# ===========================================================================
# Verbs
# ===========================================================================


class _NullProgress:
    """No-op milestone sink — the default when a verb is driven from the CLI
    (no webui op log). The broker passes a real sink (duck-typed: anything with
    a ``step(key, msg)`` method) for webui-fired ops; rscore never imports the
    broker, so the contract is structural, not a shared type."""

    def step(self, key: str, msg: str = "") -> None:  # noqa: D401
        pass


_NULL_PROGRESS = _NullProgress()


def create(req: CreateRequest, cfg: "Config" | None = None,
           progress=None) -> CreateResult:  # type: ignore[name-defined]
    """Create a project. ``req`` is already validated (no name re-check).

    Failure policy:
      • Missing prerequisites / bad inputs → die() (SystemExit), aborts.
      • A requested worker or sandbox that won't enable → aborts the whole
        create (fail-explicit; the partial project is left standing so it can
        be inspected or destroyed and retried).
      • External MCP allow-listing is best-effort: a single MCP that can't be
        granted prints a warning and creation continues (MCPs are external and
        can be transient).

    Raw progress lines keep printing to stdout (captured into the host-only
    full log). The ``progress`` sink additionally publishes ~5 allowlist-emit
    milestones at phase boundaries to the webui-visible view log — only the
    step key + a safe description, never a host path or credential.
    """
    if cfg is None:
        cfg = load_config()
    progress = progress or _NULL_PROGRESS
    project = req.name

    container_name = container_name_for(project)
    workspace_path = workspace_path_for(project, cfg)

    if container_exists(container_name):
        die(f"project {project!r} already exists (container {container_name}). "
            f"Use destroy first.")
    # Wiring left behind by an earlier project of this name belongs to nothing.
    mcp_forget_dead_project(project)
    # A same-named create reuses a leftover workspace, whose settings folder a
    # previous project's agent controlled: refuse a link there before any side
    # effect (every write below opens the folder without following a link).
    # The remedy differs from every other refusal: there is no project to go
    # inside, only the leftover an earlier one of that name left behind.
    # A workspace the earlier agent made unopenable is NOT refused here: create
    # resets the workspace's mode below (before anything reads it), as it always
    # did, while a destroy could not get into it to clear it. The check runs
    # again right after that reset, so a link inside it still gets this text.
    _refuse_leftover_settings(project, workspace_path, unopenable_ok=True)

    project_type = (PROJECT_TYPE_SANDBOX_DIND
                    if req.type is ProjectType.SANDBOX_DIND
                    else PROJECT_TYPE_RESEARCH)
    # substrate is always set by CreateRequest.from_kwargs (resolved from the
    # workflow); no derivation fallback needed here.
    substrate = req.substrate
    is_docker = substrate is Substrate.DOCKER

    # Light-path harness is the docker box's capability (WORKFLOW_TAXONOMY_S4) AND
    # the sandbox-dind flavor's (STAGE_SANDBOX_DIND_AGENT); on the research/overlay
    # workflow an effective repo/setup is noted-and-ignored, mirroring the docker-
    # side note for ignored worker/extension tokens below.
    if (not is_docker and project_type != PROJECT_TYPE_SANDBOX_DIND
            and (req.repo or req.setup)):
        print("note: --repo/--setup-script apply only to the light-path docker "
              "box / sandbox-dind; ignoring for this workflow", file=sys.stderr)
    # --agent(s) deploys an agent-dist set into the docker box (STAGE_MULTI_AGENT);
    # sandbox-dind deploys exactly that set into the supervisor's OWN ~/.local
    # (step 6 below, _dind_agent_sets). Only on the research/
    # overlay workflow is the explicit set unwired (the fleet uses the floor), so
    # it's noted-and-ignored there.
    if (not is_docker and project_type != PROJECT_TYPE_SANDBOX_DIND
            and req.agents):
        print(f"note: --agent {','.join(req.agents)} applies only to the docker "
              "box / sandbox-dind; ignoring for this workflow", file=sys.stderr)

    substrate_image = (
        MINIMAL_IMAGE if is_docker
        else SANDBOX_DIND_IMAGE if project_type == PROJECT_TYPE_SANDBOX_DIND
        else SUPERVISOR_IMAGE)

    progress.step("validate", "checking prerequisites")
    # The task cap from the host settings — read here, before anything exists,
    # so a damaged settings file refuses the create cleanly.
    pids_limit = project_pids_limit()

    # Verify prerequisites.
    if not run_quiet(["docker", "image", "inspect", substrate_image]):
        die(f"image {substrate_image} not found. Run `research setup` first.")
    # A research or sandbox-dind image from before RS's current layout would
    # write RS's files into the project's own folders at its first boot and
    # report success: refuse before anything exists. Keyed on the IMAGE (the
    # Docker substrate derives the research type too, and rs-minimal carries
    # no such label).
    if substrate_image in (SUPERVISOR_IMAGE, SANDBOX_DIND_IMAGE):
        layout = _image_instructions_layout(substrate_image)
        if layout is None:
            raise ValidationError(OLD_INSTRUCTIONS_LABEL_CREATE_ERROR)
        if layout != INSTRUCTIONS_LAYOUT_HOME:
            raise ValidationError(OLD_INSTRUCTIONS_IMAGE_CREATE_ERROR)
    if not container_running(ROUTER_CONTAINER):
        die(f"{ROUTER_CONTAINER} is not running. Run `research setup` first.")
    # A workflow that starts its own web app needs the loop baked into the
    # image; refuse before anything exists (and before any Gitea resume).
    if is_docker and req.web:
        _gate_project_web_image()

    # The `docker` substrate is a single runc container — no sysbox runtime, no
    # inner dockerd. dind_mode is meaningless there; mark it "none" so the label
    # is honest and build_supervisor_docker_args skips the runtime block.
    dind_mode = "none" if is_docker else select_dind_mode(
        (req.dind.value if req.dind is not None else None) or cfg.default_dind)

    # No inner dockerd ⇒ no inner-bridge firewall on the docker substrate.
    inner_firewall = req.inner_firewall and not is_docker

    # Egress. Sandbox flavor and the docker substrate default to `locked`;
    # research to cfg default — the shared rule the webui's create form reads too.
    egress = (req.egress.value if req.egress is not None else None) or (
        default_egress_for(project_type, substrate, cfg.default_egress))
    if egress not in ("open", "locked"):
        die(f"invalid --egress value: {egress!r} (expected open|locked)")

    # Optional host-folder bind-mounts (the CLI's --mount, or the webui's
    # `mount` field after the broker's data-folder gate — resolve_data_mount_paths
    # hands this RESOLVED absolute paths), RO inside the container, each at
    # /workspace/mnt/<basename>/. Pure host-side preparation, no container
    # yet: a refusal here leaves nothing but a directory created inside a path
    # the caller was allowed to name.
    mount_basenames, extra_mounts = _prepare_mounts(req.mount)

    # Dev lane: resolve the base branch to a CONCRETE name BEFORE any side
    # effect. It has to be concrete because the clone and the agent's CLAUDE.md
    # both name it, and a bad branch (or an empty repo) must refuse here rather
    # than ~270 lines in, where the dev step runs and would leave a half-created
    # project. Deliberate consequence: on a dev create a stopped gitea is now
    # RESUMED — and a never-enabled one dies with the enable remedy — before the
    # line below. Non-dev creates are untouched.
    effective_dev_branch = ""
    if req.dev_repo:
        effective_dev_branch = _resolve_dev_branch(req.dev_repo, req.dev_branch)
        # Same reasoning, same place: REFUSE a project name whose dev identity
        # survived a retirement. Destroy unlinks the host token file but never
        # deletes the gitea user, whose fixed-name token then blocks the re-mint
        # — which used to surface ~270 lines below as an opaque "could not mint
        # a gitea token", with the container already up and the workspace on
        # disk. Here it is a pre-side-effect ValidationError: clean envelope,
        # clean CLI die, nothing left standing to clean up.
        _refuse_retired_identity(gitea.agent_username(
            gitea.consumer_for(project)))

    # Gitea history: the claim needs the Gitea, so it is decided here — beside
    # the dev lane's retired-identity check, before any port, workspace or
    # container exists (from_kwargs already refused everything network-free).
    # The fetch surface's only gitea check runs after the container exists, so a
    # gitea held by an upgrade (or left unsettled by an interrupted one) is
    # refused HERE, before anything is built, rather than dying half-wired.
    if req.fetch:
        held = _gitea_held_reason()
        if held:
            raise ValidationError(held)
    history_claim: dict | None = None
    if req.history:
        try:
            _resume_gitea(require=True, tries=GITEA_RESUME_WAIT_TRIES)
        except SystemExit:
            # An upgrade holding gitea is not fixed by retrying in a moment.
            raise ValidationError(_gitea_held_reason()
                                  or "Gitea is not answering right now; retry in a moment")
        try:
            history_claim = gitea.project_history_claim(
                _gitea_host_port(), project, gitea.load_attachments())
        except gitea.GiteaError as e:
            raise ValidationError(str(e))

    print(f"=== Creating project: {project} ===")
    # Pre-flight (raises ValidationError, nothing standing yet): the port the
    # project owns until destroy, recorded in its marker below.
    ssh_port = allocate_ssh_port(cfg, req.ssh_port, project=project)
    ssh_pass = gen_password()

    # 1. Workspace dir (host bind-mount) + optional privileged-DIND volume.
    workspace_path.mkdir(parents=True, exist_ok=True)
    os.chmod(workspace_path, 0o2770)
    _refuse_leftover_settings(project, workspace_path, unopenable_ok=False)
    (workspace_path / "shared").mkdir(parents=True, exist_ok=True)
    # The mounted folders' mountpoints, made by the operator now so docker does
    # not create them (and mnt/) root-owned inside the workspace bind.
    _make_mount_points(workspace_path, mount_basenames)
    if dind_mode == "privileged" and not volume_exists(docker_volume_name_for(project)):
        run_check(["docker", "volume", "create", docker_volume_name_for(project)])

    # 1b. Materialize the MCP bind-mount sources (files, not dirs). dind only —
    #     the docker substrate has no mcp-proxy / worker layer.
    if not is_docker:
        ensure_mcp_files(project, cfg)

    # 1c. Project-flavor + substrate + workflow marker on the volume (survives a
    #     supervisor recreate via the bind-mount; "type" is read by the webui off
    #     /projects:ro). "workflow" is provenance — what the user selected; the
    #     derived "type"/"substrate" are what the machinery branches on.
    try:
        with orch_files.open_folder(workspace_path, create=True):
            pass
    except orch_files.Unusable as e:
        die(str(e))
    # The resolved agent set, with FOUR readers: the marker below, the docker-box
    # label+mount branch (gated `is_docker` — never fires for dind), the
    # CreateResult (surfaces in the create report), and — via the marker — the
    # recreate re-stage. Research stays []: its fleet deploy is flavor-forced
    # (fleet floor) and never consults the set.
    deployed_agents = list(req.agents) if (
        is_docker or project_type == PROJECT_TYPE_SANDBOX_DIND) else []
    # Agent model + effort (STAGE_MODEL_SELECT): all FOUR container types, frozen
    # CONCRETE and already effort-drop-resolved. `box` has no create-time field —
    # it comes straight from the defaults file — so it MUST pass through the same
    # resolver here, or an operator override of `box: {haiku, max}` would land in
    # the marker as an impossible pair and the in-supervisor `rs-sandbox create`
    # (which reads it verbatim, with no catalog to check it) would compose
    # `--model haiku --effort max`.
    model_pairs = _resolve_all_model_pairs(
        supervisor=(req.supervisor_model, req.supervisor_effort),
        worker=(req.worker_model, req.worker_effort),
        role=(req.role_model, req.role_effort))
    marker = {"type": project_type, "substrate": substrate.value,
              "workflow": req.workflow, "agents": deployed_agents,
              "models": model_pairs,
              # The project's own record of its SSH host port (allocate_ssh_port
              # keys on it across stops; start/recreate read it back).
              "ssh_port": ssh_port,
              # Whether the workflow is a dev one, resolved once here: RS's
              # instructions for the project are decided from this record, so a
              # custom workflow removed later cannot change them.
              "dev": bool(req.dev_lane),
              # A new project never had RS's old /workspace/CLAUDE.md (the
              # leftover check above refused one), so the check never runs.
              OLD_INSTRUCTIONS_FLAG: True,
              # Nor any other file RS used to write into its folders (refused
              # the same way): its folders are never checked for them.
              OLD_FILES_FLAG: True}
    if project_type == PROJECT_TYPE_SANDBOX_DIND:
        # The project container's own ~/.local gets EXACTLY the recorded agents
        # (_dind_agent_sets); a marker without this key is from before that and
        # keeps claude in it whenever it records any agent.
        marker["agents_exact"] = True
    if req.fetch:
        # Opt-in rs-fetch (any non-dev workflow; gated in from_kwargs): the
        # marker key drives the conditional re-stage of the fetch surface at
        # start/recreate (_project_has_fetch_consumers).
        marker["fetch"] = True
    # pi's starting model + thinking level, only when the create chose one
    # (from_kwargs already refused it where pi is not deployed). Every deploy
    # site reads it back from here (_read_pi_pair).
    pi_pair = ({"model": req.pi_model, "thinking": req.pi_thinking}
               if (req.pi_model or req.pi_thinking) else None)
    if pi_pair:
        marker["pi_models"] = {"agent": pi_pair}
    # The working mode and the doer/checker models, only what the create chose
    # (from_kwargs refused them outside a dev workflow). _stage_harness reads
    # them back at every deploy (_read_harness).
    if _harness_set(req):
        marker["harness"] = _harness_set(req)
    # The agent's model lives in its own settings file on an image that carries
    # the label (I33 slice 3): on Docker-in-Docker the host writes the recorded
    # Claude pair right after the deploy below (pending); the docker substrate's
    # first boot merges it itself. An older image keeps the container setting
    # and no record (a later image migrates the project once).
    model_in_settings = _label_is_set("image", substrate_image)
    if model_in_settings:
        marker["agent_settings"] = {"v": 1, "pending": [] if is_docker else ["claude"],
                                    "migrated": True}
    # Starting message (STAGE_SPAWN_GREETING) for the workflow's main shell, read
    # by the Management/Supervisor tab on first byobu new-session. Manifest-
    # derived; skip on empty so research/docker (no greeting) stage no stray file.
    try:
        orch_files.write_text(workspace_path, "project.json",
                              json.dumps(marker, indent=2) + "\n")
        if req.greeting:
            orch_files.write_text(workspace_path, "greeting", req.greeting)
    except orch_files.Unusable as e:
        die(str(e))

    # 2. Per-project network + router wiring.
    progress.step("network", "creating project network")
    network, router_ip = ensure_project_network(project, egress)
    wire_webui_to_projects()

    # 3. Build docker run argv. Peel --enable/--disable tokens into service vs
    #    worker registries before computing service flags. The docker substrate
    #    has no worker/role-mcp layer, so only service tokens (code-server) apply
    #    there — worker tokens are noted and ignored.
    enable_services, enable_workers = \
        _split_enable_tokens(",".join(req.enable))
    disable_services, disable_workers = \
        _split_disable_tokens(",".join(req.disable))
    role_mcp_explicit: dict[str, list[str]] = {}
    if is_docker:
        if enable_workers or disable_workers:
            print("note: the docker substrate has no worker layer; "
                  "ignoring those --enable/--disable tokens", file=sys.stderr)
        enable_workers = []
    else:
        _dis_w = set(disable_workers)
        if project_type == PROJECT_TYPE_SANDBOX_DIND:
            for w in enable_workers:
                print(f"note: --enable {w!r}: sandbox projects have no worker layer; "
                      f"ignoring (for a browser box use the websearcher box preset)",
                      file=sys.stderr)
            enable_workers = []
        else:
            enable_workers = [w for w in _ordered_union(defaults.enabled("worker"), enable_workers)
                              if w not in _dis_w]
        role_mcp_explicit = _parse_role_mcp_upstream(
            list(req.role_mcp_upstream), valid_roles=set(enable_workers))
        for role in enable_workers:
            try:
                role_mcp.validate_role(role)
            except ValueError as e:
                die(str(e))
    # base = per-flavor manifest defaults (STAGE_EDITOR_DIST slice 2): the sandbox
    # workflow declares code-server off so a bare box is lean; --enable flips it on.
    service_flags = _compute_service_flags(
        enable_services, disable_services, base=(req.service_defaults or None))
    docker_args = build_supervisor_docker_args(
        container_name=container_name,
        project=project,
        network=network,
        workspace_path=workspace_path,
        ssh_port=ssh_port,
        ssh_pass=ssh_pass,
        dns_servers=cfg.sandbox_dns,
        memory=req.memory or cfg.default_memory,
        cpus=req.cpus or "",
        image=substrate_image,
        dind_mode=dind_mode,
        inner_firewall=inner_firewall,
        project_type=project_type,
        substrate=substrate.value,
        service_flags=service_flags,
        agent_pair=model_pairs["supervisor"],
        model_in_settings=model_in_settings,
        agents=deployed_agents,
        # Docker substrate only: its boot installs pi's settings and merges the
        # pair from this env; a dind supervisor gets it on the host-side deploy.
        pi_pair=pi_pair if is_docker else None,
        pids_limit=pids_limit,
        # The setup is the manifest's (from_kwargs refuses any other for a
        # web-app workflow), so the env carries exactly what create runs.
        web=({"start": req.web["start"], "port": req.web["port"],
              "setup": req.setup} if is_docker and req.web else None),
    )
    if extra_mounts:
        docker_args = docker_args[:-1] + extra_mounts + [docker_args[-1]]
    # Agent dists: one RO copy-source mount per enabled agent at
    # /opt/agent-dist/<agent> + a comma-joined provenance label (STAGE_MULTI_AGENT).
    # docker-substrate only BY GATE (deployed_agents is non-empty on sandbox-dind
    # too now, where the host-cache mount would be fatal: _stage_agent_dist's
    # re-stage delete on a live mountpoint + host-uid files foreign-owned
    # under the sysbox userns — dind gets the flat staged tree instead). The
    # entrypoint loops over the mounted subdirs and cp's each into the box's OWN
    # writable ~/.local on first boot. The mounts ARE the enabled set (the
    # entrypoint reads the mounts, not the label) — empty set => no mount =>
    # /opt/agent-dist absent => the boot loop no-ops (lean box). Inserted before
    # the image (last arg).
    if is_docker and deployed_agents:
        agent_args = ["--label", f"{AGENT_LABEL}={','.join(deployed_agents)}"]
        for a in deployed_agents:
            agent_args += ["-v", f"{agent_dist_path(a)}:/opt/agent-dist/{a}:ro"]
        docker_args = docker_args[:-1] + agent_args + [docker_args[-1]]
    # Editor dist for the docker box (STAGE_EDITOR_DIST slice 2): a single runc box
    # has no inner dockerd to stage into, so it RO-mounts the HOST editor cache
    # directly (source = EDITOR_DIST_DIR, NOT the supervisor-side EDITOR_DIST_MOUNT).
    # Flag-gated like the agent mount above — a default-off sandbox mounts nothing
    # (lean); --enable code-server + a pulled dist wires it, and the entrypoint
    # dist block cp's it into the box's own ~/.local at first boot.
    # A re-download REPLACES the host cache directory, so a RUNNING docker box's
    # mount of it (editor here, node below) reads empty until the box's next
    # start or recreate, which binds the new directory. Harmless by design: the
    # box copies from these mounts only at boot (the entrypoint dist block, and
    # _deploy_node at create/recreate), never while running.
    if is_docker and service_flags.get("code-server") and editor_dist_present():
        docker_args = (docker_args[:-1]
                       + ["-v", f"{EDITOR_DIST_DIR}:{EDITOR_DIST_MOUNT}:ro"]
                       + [docker_args[-1]])
    # Node seed for the docker box (STAGE_NODE_SEED): same host-cache RO mount as the
    # editor. The mount is a copy-source; _deploy_node (D2 below) cp's it into the
    # box's own ~/.local. This mount survives a _recreate_docker_substrate as a
    # RECOVERED bind (never re-derived from the flag — _without_mount strips only
    # EDITOR_DIST_MOUNT), which is correct ONLY because node has no post-create
    # toggle; a future live-node-toggle slice must convert it to the editor's
    # _without_mount + re-derive shape.
    if is_docker and service_flags.get("node") and node_dist_present():
        docker_args = (docker_args[:-1]
                       + ["-v", f"{NODE_DIST_DIR}:{NODE_DIST_MOUNT}:ro"]
                       + [docker_args[-1]])

    # 4. Create container.
    progress.step("create-container", "creating project container")
    run_check(["docker", *docker_args])

    # 5. Inject default route via router (egress traverses iptables).
    inject_route(container_name, router_ip)

    granted: list[str] = []
    workers_enabled: list[str] = []
    history_line = ""

    clone_dir = ""
    if is_docker:
        # A re-create over a project folder an old destroy left behind can
        # still carry a root-owned mnt/ that the mountpoint step above could
        # not use; hand it back now (a no-op on every other create).
        _reclaim_mount_root(container_name, workspace_path)
        # No inner dockerd: nothing to stage, no proxy, no worker/extension cone.
        # Node seed (STAGE_NODE_SEED, D2 — the RACE FIX): deploy node HOST-SIDE and
        # SYNCHRONOUSLY, BEFORE the light-path setup runs. `docker run` returns while
        # the entrypoint is still working (agent-dist cp, the slow editor deploy), so
        # a node deploy left to the entrypoint could lose the race to a `setup` that
        # needs npm (open-knowledge's `npm install -g` is the first such setup). This
        # exec guarantees node is present first. NOTE: this runs concurrently with the
        # entrypoint's OTHER ~/.local cp's (agent/editor) — safe, they write disjoint
        # files, and _deploy_node is no-clobber — it is NOT the sole ~/.local writer
        # during boot, only the sole NODE writer. The docker box has NO entrypoint
        # node block (see D6 — none exists), so a restart never re-deploys.
        if service_flags.get("node") and node_dist_present():
            _deploy_node(container_name)
        # 6''. Optional GitHub SSH auth + git identity, BEFORE the clone (which
        #      needs the key). Like _deploy_node above this lands in the same
        #      post-`docker run` window as the still-booting entrypoint — safe,
        #      because the paths are disjoint (~/.ssh + ~/.gitconfig here vs
        #      ~/.local there) and entrypoint.minimal.sh's skel restore never
        #      fires on rs-minimal (its /home/research is image-resident).
        _stage_git_auth(container_name, req.github_ssh_key,
                        req.git_user_name, req.git_user_email, progress)
        # RS's instructions (the workflow's own, or the notice alone) and the
        # web app's tab, BEFORE the setup: a failed setup raises out of create,
        # and a start retries only the setup. A new project's old-file check
        # never runs (its marker records the flag).
        _write_project_instructions(project, container_name, workspace_path,
                                    progress=progress, has_file=False)
        if req.web:
            _register_project_web_tab(workspace_path, req.web)
        # Gitea history, in the box's order and BEFORE the setup: the setup's
        # marker lets OpenKnowledge start, which must never happen in a notes/
        # that history has not yet cloned (the pending mark holds it back).
        hist_row: dict | None = None
        if history_claim is not None:
            hist_row = _provision_project_history(project, history_claim,
                                                  container_name, cfg)
            if hist_row is not None:
                _write_marker_history(workspace_path)
                if not _run_project_history(container_name, hist_row):
                    raise HarnessError("history step failed",
                                       "the project's history status could not "
                                       "be written")
        # 6'. Light-path harness: clone the workflow repo + run setup on the box
        #     (after inject_route, so egress works). Raises HarnessError on
        #     failure (box left standing). Create-time only, except for a web-app
        #     workflow: its marker is written here, the rebuild and a start re-run
        #     the setup while the marker is missing (_rerun_project_setup).
        clone_dir = _run_light_harness(
            container_name, req.repo, req.ref, req.setup, req.github_pat, progress,
            use_ssh=bool(req.github_ssh_key))
        if req.web:
            _mark_project_setup_done(container_name)
        if history_claim is not None:
            if hist_row is None:
                history_line = _PROJECT_HISTORY_GITEA_FAILED_LINE
            else:
                code = _read_project_history_status(container_name)
                history_line = _project_history_status_line(code, hist_row["repo"])
            progress.step("note" if history_line.startswith("History: on")
                          else "warning", history_line)
        progress.step("ready", "project ready")
    else:
        # 6. Wait for inner dockerd, then stage the inner images.
        progress.step("stage-images", "staging inner images")
        wait_for_inner_dockerd(container_name)
        is_management = project_type == PROJECT_TYPE_SANDBOX_DIND
        if is_management:
            # Sandbox-dind is the docker `sandbox` flavor + DIND
            # (STAGE_SANDBOX_DIND_AGENT): the supervisor RUNS an agent itself and
            # gets the light-path harness. /opt/agent-dist is ALWAYS staged with
            # the selection plus claude (the copy-source any box's agent toggle
            # deploys from — Option C), while the supervisor's OWN ~/.local gets
            # exactly the agents ticked (_dind_agent_sets over the marker just
            # written: a pi-only project runs no claude itself); an agent-less
            # create leaves the supervisor unwired.
            staged, local = _dind_agent_sets(marker)
            _report_warnings(_stage_agent_dist(
                container_name, staged, deploy_local=bool(local),
                **_local_deploy_kwargs(staged, local),
                **({"pi_pair": pi_pair} if pi_pair else {})), progress)
            # The working-mode suite (I33): into the shared copy for the boxes,
            # and into the project container's own agents.
            _report_warnings(_stage_harness(container_name, local, workspace_path), progress)
            # RS's instructions into the agent's home (the dev text with the
            # request's resolved base branch, else the notice alone).
            _write_project_instructions(
                project, container_name, workspace_path, progress=progress,
                branch=effective_dev_branch if req.dev_repo else None,
                has_file=False)
            # The recorded Claude model into Claude's own settings (I33 slice 3).
            _apply_agent_settings_pending(container_name, workspace_path, local,
                                          claude_in_settings=model_in_settings,
                                          progress=progress)
            # Editor dist staged whenever cached so any box can RO-mount
            # /opt/editor-dist; deploy_local follows the RESOLVED code-server
            # flag (default ON since the editor-by-default slice — a
            # --disable code-server project stages the mount source but
            # deploys no supervisor editor). Staged before any box spawn.
            if editor_dist_present():
                _stage_editor_dist(container_name,
                                   deploy_local=service_flags.get("code-server", True))
            # Reader dist (STAGE_READER): staged when cached so a later live-enable is
            # deploy-only; deployed now iff the reader flag resolved ON (default off).
            # The create-time floor guaranteed a dist when reader is enabled.
            if reader_dist_present():
                _stage_reader_dist(container_name,
                                   deploy_local=service_flags.get("reader", False))
            # Node seed (STAGE_NODE_SEED): staged when cached so a later flag-on is
            # deploy-only; deployed into the supervisor's own ~/.local iff node
            # resolved ON (default off). Synchronous + ordered BEFORE _run_light_harness
            # below, so the dind side is never racy (unlike the docker box, which
            # needs the explicit host deploy D2).
            if node_dist_present():
                _stage_node_dist(container_name,
                                 deploy_local=service_flags.get("node", False))
            # Box harness (STAGE_DIND_UNIFY — a standing dind utility, no longer an
            # opt-in): stage the rs-sandbox CLI (no longer baked) + bring both box
            # images in and record them (the marker was written above). Eager for
            # sandbox-dind; research brings the image a box needs on its first
            # box_add (research create never touches boxes — frozen lane).
            _stage_rs_sandbox(container_name)
            for _host_base, _repo, _latest in _BOX_IMAGES:
                _result = _bring_box_image(container_name, network, workspace_path,
                                           _host_base)
                if _result.reason:
                    die(_result.reason)
            # Stage the resolved box-preset catalog so the in-supervisor rs-sandbox
            # can resolve presets for a directly-invoked `rs-sandbox create`
            # (box_add refreshes it live; STAGE_BOX_EXT_UX). Best-effort.
            _stage_box_catalog(workspace_path, strict=False)
            # Optional GitHub SSH auth + git identity, BEFORE the clone (which
            # needs the key). Raises HarnessError on failure.
            _stage_git_auth(container_name, req.github_ssh_key,
                            req.git_user_name, req.git_user_email, progress)
            # Light-path harness: clone repo@ref + run setup on the supervisor
            # (after inject_route; raises HarnessError on failure, box left standing).
            clone_dir = _run_light_harness(
                container_name, req.repo, req.ref, req.setup, req.github_pat, progress,
                use_ssh=bool(req.github_ssh_key))
            # Dev workflow step (STAGE_DEV_GITEA S2, create-time by PI decision:
            # the repo is mandatory on a dev workflow): attach the shared gitea
            # to the project bridge, record + stage the wiring (non-secret JSON
            # + in-supervisor token), and clone the agent fork into the
            # supervisor workspace. After inject_route + the dist staging above.
            # A clone failure raises HarnessError and leaves the project
            # standing: `research dev attach` re-stages idempotently and only
            # the clone needs a manual in-project finish (or destroy+recreate).
            if req.dev_repo:
                progress.step("dev-attach", "attaching shared gitea")
                # A dev-workflow project NEEDS gitea — resume an enabled one
                # (never create; deliberate-create model), die with the enable
                # remedy if it was never enabled.
                _resume_gitea(require=True)
                gitea_ip = _connect_gitea_to_project_network(network)
                if not gitea_ip:
                    die(f"rs-gitea did not attach to {network} (no IP); "
                        f"check docker state")
                # Per-consumer identity: the PROJECT's own dev agent gets its
                # user + fork + token here (provisioning lives at the point
                # that needs an agent, never in shared wiring).
                dev_user = gitea.agent_username(gitea.consumer_for(project))
                try:
                    gitea.provision_consumer(_gitea_host_port(), req.dev_repo,
                                             dev_user,
                                             default_branch=effective_dev_branch)
                except gitea.GiteaError as e:
                    # Mid-side-effect (mirrors the adjacent no-IP die): a raw
                    # GiteaError would escape dispatch into socketserver.
                    die(f"could not provision the project's dev identity: {e}")
                gitea.record_attachment(project, "agent", req.dev_repo,
                                        gitea_ip, box=None, user=dev_user,
                                        branch=effective_dev_branch)
                _stage_dev_gitea(project, cfg, gitea_ip=gitea_ip)
                clone_dir = _run_dev_clone(container_name, req.dev_repo,
                                           dev_user, effective_dev_branch,
                                           progress)
        else:
            stage_worker_image(container_name, ANALYSIS_IMAGE)
            # Stage the agent dist into the supervisor (its own ~/.local + the
            # /opt/agent-dist the worker/role-MCP/PI fleet RO-mounts). No bake
            # anywhere now (STAGE_AGENT_DIST slice 2). ORDER IS LOAD-BEARING: this
            # MUST stay before the worker/extension enable cone below — a role-MCP or
            # PI container brought up by that cone mounts /opt/agent-dist and would
            # boot claude-less (failing only on first send_job) if staged after.
            # Research stays claude-only in this slice (its supervisor's Stop hook
            # is a claude mechanism; the supervision gate is redesigned before
            # another agent runs research — STAGE_PI_AGENT).
            _stage_agent_dist(container_name, [DEFAULT_AGENT])
            _apply_agent_settings_pending(container_name, workspace_path, [DEFAULT_AGENT],
                                          claude_in_settings=model_in_settings,
                                          progress=progress)
            # Editor dist (STAGE_EDITOR_DIST): staged before the enable cone too so
            # interactive PI containers RO-mount a populated /opt/editor-dist.
            # deploy_local brings up the supervisor's OWN editor from the dist (no
            # bake now), gated on the resolved code-server flag so a
            # --disable code-server project deploys nothing. The create-time floor
            # already guaranteed a dist is present when the editor is enabled.
            if editor_dist_present():
                _stage_editor_dist(container_name,
                                   deploy_local=service_flags.get("code-server", True))
            # Reader dist (STAGE_READER): staged when cached (deploy-only on a later
            # live-enable); deployed now iff the reader flag resolved ON (default off).
            if reader_dist_present():
                _stage_reader_dist(container_name,
                                   deploy_local=service_flags.get("reader", False))
            # Node seed (STAGE_NODE_SEED): staged when cached; deployed into the
            # supervisor's own ~/.local iff node resolved ON (default off).
            if node_dist_present():
                _stage_node_dist(container_name,
                                 deploy_local=service_flags.get("node", False))

        # 6b/6c. The MCP proxy/reload/auto-allow cone runs for ALL dind now
        #        (STAGE_DIND_UNIFY): research AND sandbox-dind get the proxy so
        #        extensions with proxy-routed upstreams (wrangler-style) work on
        #        both. rs-sandbox-dind bakes mcp-reload + mcp_render_config.py
        #        (Dockerfile.sandbox-dind) so the reload exec resolves; the proxy
        #        image is staged just below. The guard is `not is_docker` (always
        #        true inside this dind branch) so research's executed statements stay
        #        byte-identical — only the gate widened from `not is_management`.
        if not is_docker:
            stage_worker_image(container_name, MCP_PROXY_IMAGE)

            # 6b. Re-run mcp-reload now that the proxy image is staged.
            run(["docker", "exec", container_name, "/usr/local/bin/mcp-reload"],
                capture_output=True)

            # 6c. Auto-allow MCPs per --mcp. BEST-EFFORT: external MCPs can be
            #     transient, so a single failure warns and creation continues.
            requested = _resolve_create_mcp_arg(req.mcp)
            for mcp_name in requested:
                ok, msg = _allow_mcp_for_project(project, cfg, mcp_name, do_reload=False)
                if ok:
                    granted.append(mcp_name)
                else:
                    print(f"warning: skip auto-allow {mcp_name!r}: {msg}", file=sys.stderr)
            if granted:
                _supervisor_mcp_reload(container_name)

        # 6d. worker sugar (--enable <worker>). FAIL-EXPLICIT: a worker that
        #     won't enable aborts the create (no swallow). This is the slow tail
        #     — a role-MCP like websearcher builds/starts a Chromium container —
        #     so the "wire" milestone is emitted AFTER the loop, not before: its
        #     view-log row stays pending (the UI shows it in-progress) until the
        #     enabling actually finishes, instead of checking ✓ up front while
        #     the box sits on a silent wait.
        for role in enable_workers:
            _role_mcp_enable(project, cfg, role, role_mcp_explicit.get(role))
            workers_enabled.append(role)

        progress.step("wire", "enabling workers")

    # Universal dev-lane wiring (STAGE_DEV_GITEA S3; fetch is OPT-IN now): once
    # the shared gitea exists, EVERY project's NETWORK is wired to it at create
    # and the non-secret dev-gitea.json is staged (the gitea_ip floor for dev
    # boxes + consumers). The FETCH surface (tool + operator token + global
    # wiring) does NOT ride this path anymore — it is staged per-box (box_add)
    # or per docker project (the req.fetch step below); unflagged surfaces get
    # nothing. BEST-EFFORT for non-dev workflows: a sick gitea must never fail
    # a research/sandbox create. _resume_gitea RESUMES an enabled-but-stopped
    # gitea (never creates — deliberate-create model) and returns False when it
    # was never enabled, so a gitea-less create is byte-equivalent; a
    # resume-path failure (wedged wait) die()s → SystemExit → caught, warn,
    # continue. The dev workflow wired STRICTLY above (require).
    if not req.dev_repo:
        try:
            if _resume_gitea(require=False):
                dev_ip = _connect_gitea_to_project_network(network)
                if dev_ip:
                    _stage_dev_gitea(project, cfg, gitea_ip=dev_ip)
                else:
                    print(f"warning: rs-gitea attach to {network} returned no IP; "
                          f"dev wiring skipped (heals at `research start`)",
                          file=sys.stderr)
        except SystemExit:
            print("warning: rs-gitea unavailable; dev wiring skipped "
                  "(heals at `research start`)", file=sys.stderr)
    # Opt-in rs-fetch (any non-dev workflow; from_kwargs refuses only the dev
    # workflow — on dind this wires the SUPERVISOR, boxes keep their per-box
    # toggle). STRICT, unlike the best-effort universal wiring above: the flag
    # is an explicit ask, so a sick gitea fails the create loudly (the
    # from_kwargs bootstrap floor already refused the never-enabled case;
    # _resume_gitea is the TOCTOU authority). No --add-host needed on EITHER
    # substrate: this container sits on rs-net-<project>, where rs-gitea
    # resolves via the bridge's embedded DNS.
    if req.fetch:
        _resume_gitea(require=True)
        fetch_ip = _connect_gitea_to_project_network(network)
        if not fetch_ip:
            die(f"rs-gitea did not attach to {network} (no IP); check docker state")
        _stage_dev_gitea(project, cfg, gitea_ip=fetch_ip)
        _stage_dev_fetch(container_name)
        _stage_fetch_wiring(container_name)
    # F3 Slice 1: bring up loopback forwarders for any already-registered exported
    # ports (inert on a fresh project's empty registry; self-gates on docker).
    _reconcile_loopback_bridges(project, cfg)

    # 6e. Http-service readiness gates: create reports "ready" only when each
    #     enabled http service is actually listening, so there's no post-create race
    #     where the webui probes a not-yet-up service and shows no tab. code-server
    #     (CODE_SERVER_STUB_PORT, both substrates) and reader (READER_PORT, dind-only
    #     — the docker floor rejects it) are the http services in KNOWN_SERVICES.
    #     Best-effort (warn + proceed) — a slow service must never fail an otherwise-
    #     healthy create.
    if service_flags.get("code-server"):
        progress.step("editor", "waiting for editor")
        if not _wait_for_service_ready(container_name, CODE_SERVER_STUB_PORT):
            print(f"warning: editor not listening on :{CODE_SERVER_STUB_PORT} after "
                  f"{EDITOR_READY_TIMEOUT_S}s; it should come up shortly")
    if service_flags.get("reader"):
        progress.step("reader", "waiting for reader")
        if not _wait_for_service_ready(container_name, READER_PORT):
            print(f"warning: reader not listening on :{READER_PORT} after "
                  f"{EDITOR_READY_TIMEOUT_S}s; it should come up shortly")

    # 7. Return result (the front-end formats the report from this).
    return CreateResult(
        project=project,
        container=container_name,
        workspace=str(workspace_path),
        network=network,
        egress=egress,
        dind_mode=dind_mode,
        inner_firewall=inner_firewall,
        project_type=project_type,
        substrate=substrate.value,
        workflow=req.workflow,
        ssh_port=int(ssh_port),
        ssh_password=ssh_pass,
        mounts={b: str(src) for b, src in mount_basenames.items()},
        mcps=granted,
        workers=workers_enabled,
        repo=req.repo,
        clone_dir=clone_dir,
        agents=deployed_agents,
        history_line=history_line,
    )


def destroy(req: DestroyRequest, cfg: "Config" | None = None,
            progress=None) -> None:  # type: ignore[name-defined]
    """Tear a project down: container + workspace dir + DIND volume + network,
    plus its router MCP-allow rules. Confirmation is the front-end's job — this
    verb just destroys. A project whose container is already gone (a reset
    docker store, a hand `docker rm`) is destroyed too: whatever of it remains
    is removed. die()s only when nothing of the project remains."""
    if cfg is None:
        cfg = load_config()
    progress = progress or _NULL_PROGRESS
    project = req.name
    container = container_name_for(project)
    remnants = project_remnants(project, cfg)
    if not remnants:
        die(f"project {project!r} does not exist")
    progress.step("validate", "located project")

    project_root = project_root_for(project, cfg)
    docker_volume = docker_volume_name_for(project)
    network = project_network_for(project)

    # Clean up per-project MCP rules in the router so iptables doesn't
    # accumulate orphan ACCEPTs after the project network is gone.
    progress.step("router", "removing router rules")
    if network_exists(network) and container_running(ROUTER_CONTAINER):
        try:
            subnet = get_network_subnet(network)
        except SystemExit:
            subnet = ""
        for ent in load_project_allowlist(project, cfg):
            ip = ent.get("ip")
            port = ent.get("port")
            if subnet and isinstance(ip, str) and isinstance(port, int):
                run(["docker", "exec", ROUTER_CONTAINER,
                     "/scripts/mcp-deny.sh", subnet, ip, str(port)],
                    capture_output=True)

    # The milestone is emitted in both arms: the webui's destroy checklist
    # pre-lists it, so skipping it would leave a stuck pending row.
    progress.step("remove-container", "removing container")
    if "container" in remnants:
        run(["docker", "rm", "-f", container], capture_output=True)
    else:
        progress.step("note", "its container was already gone")
    progress.step("cleanup", "removing workspace, volume and network")
    # The project folder goes only when it holds RS's workspace (or the
    # container still stood, the reach destroy always had): a stale network
    # or volume must never delete an unrelated folder that shares the name.
    # lexists, so a dangling link at the folder's name is handed over too
    # (removed as a link, reported).
    if os.path.lexists(project_root) and ("workspace" in remnants
                                          or "container" in remnants):
        # Path and parent from the one project_root, and the delete happens
        # only when it is provably this project's own folder; a refusal is
        # one warning (the leftovers walk is skipped) and the teardown goes on.
        refused = _remove_own_folder(project_root.parent, project_root.name)
        stuck = [] if refused else _project_root_leftovers(project_root)
        if refused:
            msg = _project_folder_refusal(project_root, refused)
            print(f"warning: {msg}", file=sys.stderr)
            progress.step("warning", msg)
        if stuck:
            # The rest of the project is still torn down below: what is left
            # is only files, and saying so is the honest outcome.
            msg = (f"{len(stuck)} item(s) of the project folder could not be "
                   f"removed and are left on the host under {project_root} "
                   f"(first: {stuck[0]})")
            print(f"warning: {msg}", file=sys.stderr)
            for path in stuck:
                print(f"  left: {path}", file=sys.stderr)
            progress.step("warning", msg)
    if volume_exists(docker_volume):
        run(["docker", "volume", "rm", docker_volume], capture_output=True)
    # The project's MCP wiring goes BEFORE its network: the range returns to
    # docker's pool, and no token may stay valid for it. A table that cannot
    # be changed is a warning — the dead project's tokens exist nowhere else.
    warn = _mcp_drop_rows(project)
    if warn:
        print(f"warning: {warn}", file=sys.stderr)
        progress.step("warning", warn)
    # Under the lifecycle flock when it can be had at once (the broker's inline
    # destroy already holds it): a fleet-wide gateway attach must not re-attach
    # the gateway between the disconnects and the removal.
    with _lifecycle_flock_if_free():
        remove_project_network(project)
    # Retire the project's dev-lane consumers (best-effort — a destroy must not
    # die on a corrupt record or a sick gitea): archive every consumer fork
    # (history kept, users stay inert) + delete their host token files, THEN
    # drop the ledger entries.
    try:
        entries = [e for e in gitea.project_entries(project)
                   if e.get("class") == "agent" and e.get("repo")
                   and e.get("user")]
        if entries and container_running(gitea.GITEA_CONTAINER):
            host_port = _gitea_host_port()
            for e in entries:
                gitea.archive_fork(host_port, e["user"], e["repo"])
        for e in entries:
            gitea.delete_consumer_token(e["user"])
    except Exception:
        pass
    # Gitea history boxes: archive each notes repo + delete its account and
    # token, in their own per-row arm (a dev-arm error cannot skip them, and
    # they cannot skip the prune below).
    try:
        hist_rows = [e for e in gitea.project_entries(project)
                     if e.get("class") == gitea.HISTORY_CLASS]
        if hist_rows:
            for line in _retire_history_rows(project, hist_rows, container):
                print(f"warning: {line}", file=sys.stderr)
                progress.step("warning", line)
    except Exception:
        pass
    try:
        gitea.prune_project(project)
    except Exception:
        pass
    # Preset-field env store for this project's boxes — host-only, never
    # mounted; the boxes died with the project, so their keys go too (each
    # key file by name, never a recursive delete; anything else is reported).
    for w in _remove_box_env_store(BOX_ENV_DIR, project):
        print(f"warning: {w}", file=sys.stderr)
        progress.step("warning", w)


# The one name shape _remove_own_folder deletes under: a single plain path
# component (no "", ".", "..", "/", trailing newline). MIRROR PAIR: cli/rscore.py
# and cli/rs_sandbox.py carry this pattern and the function below byte-identical
# (pytest-pinned); the box tool is baked standalone and cannot import rscore.
_OWN_FOLDER_NAME_RE = re.compile(r"\A[A-Za-z0-9][A-Za-z0-9._-]*\Z")


def _remove_own_folder(parent: Path, name: str) -> str | None:
    """Delete <parent>/<name> with one recursive delete, only when it is
    provably the caller's own folder: `name` is one plain component under the
    caller's fixed `parent`, and the entry there is a real folder. MIRROR PAIR
    (cli/rscore.py and cli/rs_sandbox.py, byte-identical, pytest-pinned).

    Returns None when the folder was removed or was not there, else the reason
    it was not deleted:
      "bad-name"      `name` is not one plain component; nothing was touched
      "link-removed"  the entry was a link: only the link was removed, never
                      what it points to (the name is free again)
      "link-kept"     the entry was a link that could not be removed
      "not-a-folder"  the entry is a file or another non-folder; left in place
      "unreadable"    the entry could not be examined; left in place

    The delete never follows a link inside the folder: shutil.rmtree removes a
    link without following it, and where shutil.rmtree.avoids_symlink_attacks
    is True (Linux) it walks by file descriptor, so a folder swapped for a link
    between this check and the delete is refused, not followed. Where it is
    False (a macOS host) rmtree still never follows a link by design, but a
    swap racing the walk is not guarded. Not covered anywhere: `parent` itself
    swapped during the delete (rmtree takes no dir_fd on Python 3.9). A partial
    delete is swallowed here; destroy reports what survived (box remove
    does not yet)."""
    if not isinstance(name, str) or not _OWN_FOLDER_NAME_RE.match(name):
        return "bad-name"
    path = Path(parent) / name
    try:
        st = os.lstat(path)
    except FileNotFoundError:
        return None
    except OSError:
        return "unreadable"
    if stat.S_ISLNK(st.st_mode):
        try:
            os.unlink(path)
        except OSError:
            return "link-kept"
        return "link-removed"
    if not stat.S_ISDIR(st.st_mode):
        return "not-a-folder"
    shutil.rmtree(path, ignore_errors=True)
    return None


def _project_folder_refusal(project_root: Path, reason: str) -> str:
    """destroy's operator line for a project folder _remove_own_folder did not
    delete (fixed text per reason code; no CLI verb)."""
    if reason == "link-removed":
        return (f"the project folder {project_root} was a link: only the link "
                f"was removed, and what it pointed to was left in place untouched")
    if reason == "not-a-folder":
        return f"{project_root} is not a folder, so destroy left it in place"
    if reason == "bad-name":
        return (f"{project_root} does not end in a plain folder name, so "
                f"destroy deleted nothing there")
    return (f"the project folder {project_root} could not be examined or "
            f"removed, so destroy left it in place")


def _remove_box_env_store(env_root: Path, project: str) -> list[str]:
    """Remove the project's preset-field key store <env_root>/<project> WITHOUT
    a recursive delete: only RS writes there, one `<box>.env` file per box, so
    each such file (or link: the link itself, never its target) is unlinked by
    name and the folder is rmdir'd. Anything else found there — a `.env` that
    is a folder, any other entry, or a store that is itself a link or a file —
    is left untouched and reported. Never raises (destroy's last step must not
    fail the op); returns the warning lines."""
    store = env_root / project
    try:
        st = os.lstat(store)
    except FileNotFoundError:
        return []
    except OSError:
        return [f"the box key store {store} could not be read, so it was left "
                f"in place"]
    if not stat.S_ISDIR(st.st_mode):
        return [f"the box key store {store} is not a plain folder (a link or "
                f"a file), so it was left in place untouched"]
    try:
        names = sorted(os.listdir(store))
    except OSError:
        return [f"the box key store {store} could not be listed, so it was left "
                f"in place"]
    kept: list[str] = []
    for n in names:
        p = store / n
        try:
            est = os.lstat(p)
        except OSError:
            kept.append(n)
            continue
        if (n.endswith(".env") and _BOX_NAME_RE.match(n[:-len(".env")])
                and (stat.S_ISREG(est.st_mode) or stat.S_ISLNK(est.st_mode))):
            try:
                os.unlink(p)
            except OSError:
                kept.append(n)
        else:
            kept.append(n)
    if kept:
        return [f"{len(kept)} item(s) in the box key store {store} are not box "
                f"keys or could not be removed, and were left in place "
                f"(first: {kept[0]})"]
    try:
        os.rmdir(store)
    except OSError:
        return [f"the box key store {store} could not be removed"]
    return []


def _project_root_leftovers(project_root: Path) -> list[str]:
    """What destroy's removal of the project folder left behind, found by a
    READ-ONLY walk after the delete (_remove_own_folder decides whether the
    folder is destroy's to delete; a refused folder is never walked). Returns
    the leaves of what survived: every file or link, every empty folder, and
    every folder whose contents cannot be listed. An empty list means the
    folder is gone."""
    if not os.path.lexists(project_root):
        return []
    if project_root.is_symlink() or not project_root.is_dir():
        return [str(project_root)]
    left: list[str] = []

    def unlistable(err: OSError) -> None:
        left.append(str(err.filename))

    for dirpath, dirnames, filenames in os.walk(project_root, onerror=unlistable):
        # os.walk lists a link to a folder under dirnames and does not follow it.
        for name in dirnames:
            if os.path.islink(os.path.join(dirpath, name)):
                left.append(os.path.join(dirpath, name))
        for name in filenames:
            left.append(os.path.join(dirpath, name))
        if not dirnames and not filenames:
            left.append(dirpath)
    return left


def start(req: StartStopRequest, cfg: "Config" | None = None,
          progress=None) -> list[ActionResult]:  # type: ignore[name-defined]
    """Start a stopped project (or all). On sysbox a plain `docker start` after
    `docker stop` fails, so dind-sysbox projects route through
    _recreate_supervisor: fresh container ID + bindings, workspace/creds/network
    preserved. A docker-substrate project is a plain runc container with no
    sysbox bindings — it uses _start_docker_substrate (docker start + route
    re-inject). Fail-explicit: a recreate/start that dies aborts (no swallow)."""
    if cfg is None:
        cfg = load_config()
    progress = progress or _NULL_PROGRESS
    if not container_running(ROUTER_CONTAINER):
        die(f"{ROUTER_CONTAINER} is not running. Run `research start` first.")
    progress.step("validate", "checking project")
    # Every start (re)applies the host task cap; a damaged settings file
    # refuses here, before the port-list sweep below touches anything.
    project_pids_limit()
    if req.all:
        containers = get_supervisor_containers()
    else:
        containers = [{"name": container_name_for(req.name), "project": req.name}]
    results: list[ActionResult] = []
    # Old instructions files met on the way: raised once, after every project
    # started, so `--all` still starts them all.
    found: list[OldInstructions] = []
    for c in containers:
        if not container_exists(c["name"]):
            results.append(ActionResult(c["name"], c.get("project"), "start", "skip:absent"))
            continue
        # A reserved entry left in the port list is dropped and said once. On a
        # running project the sweep's own reconcile reaps its forwarder; on a
        # stopped one the start's container swap reconciles from the clean file.
        if valid_project_name(c.get("project") or ""):
            _drop_reserved_port_entries(c["project"], cfg, progress)
        if container_running(c["name"]):
            results.append(ActionResult(c["name"], c.get("project"), "start", "skip:already"))
            continue
        print(f"=== Starting project: {c['project']} ===")
        if _container_substrate(c["name"]) == Substrate.DOCKER.value:
            # Folders saved in ⚙ change the container's binds, which only a
            # re-creation can do on this substrate (the agent logs in again —
            # the ⚙ warning says so).
            if _docker_folders_pending(c["project"], cfg, progress):
                progress.step("recreate", "re-creating the project with its new folders")
                _recreate_docker_substrate(
                    c["project"], cfg, service_flags=_read_service_flags(c["name"]),
                    progress=progress, heal_gitea=True, found=found)
            else:
                progress.step("start", "starting container")
                _start_docker_substrate(c["project"], cfg, progress, found=found)
        else:
            progress.step("recreate", "recreating supervisor")
            found += _recreate_supervisor(c["project"], cfg, progress=progress) or []
        results.append(ActionResult(c["name"], c["project"], "start", "ok"))
    _raise_old_instructions(found, name_project=bool(req.all))
    return results


def stop(req: StartStopRequest, cfg: "Config" | None = None,
         progress=None) -> list[ActionResult]:  # type: ignore[name-defined]
    """Stop a project (or all). Fail-explicit: a `docker stop` that fails dies."""
    progress = progress or _NULL_PROGRESS
    progress.step("validate", "checking project")
    if req.all:
        names = [c["name"] for c in get_supervisor_containers()]
    else:
        names = [container_name_for(req.name)]
    results: list[ActionResult] = []
    for name in names:
        if not container_exists(name):
            results.append(ActionResult(name, None, "stop", "skip:absent"))
            continue
        progress.step("stop", "stopping container")
        run_check(["docker", "stop", name])
        results.append(ActionResult(name, None, "stop", "ok"))
    return results


def list_projects(cfg: "Config" | None = None) -> list[ProjectSummary]:  # type: ignore[name-defined]
    """Every supervisor container with its state + SSH endpoint (if running),
    then one ORPHANED_STATE row per project that has no container but still
    has something destroy would remove (a workspace, a network, a DIND
    volume) — so the webui's Destroy reaches it. Listed orphans are exactly
    the names project_remnants() reports without a container."""
    if cfg is None:
        cfg = load_config()
    out: list[ProjectSummary] = []
    for c in get_supervisor_containers():
        ssh = None
        if c["state"] == "running":
            port = get_ssh_port(c["name"])
            ssh = f"localhost:{port}" if port else None
        out.append(ProjectSummary(project=c["project"], state=c["state"], ssh=ssh))
    have = {s.project for s in out}
    orphans: set[str] = set()
    root = Path(cfg.projects_dir).expanduser().resolve()
    if root.is_dir():
        for child in root.iterdir():
            if valid_project_name(child.name) and _has_workspace_dir(child):
                orphans.add(child.name)
    # docker's name filter is a SUBSTRING match: re-check the prefix. A failed
    # `ls` contributes nothing (the container listing above already dies on a
    # dead daemon).
    for kind, prefix in (("network", PROJECT_NETWORK_PREFIX),
                         ("volume", DOCKER_VOLUME_PREFIX)):
        r = run(["docker", kind, "ls", "--filter", f"name={prefix}",
                 "--format", "{{.Name}}"], capture_output=True)
        if r.returncode != 0:
            continue
        for line in r.stdout.splitlines():
            name = line.strip()
            if name.startswith(prefix) and valid_project_name(name[len(prefix):]):
                orphans.add(name[len(prefix):])
    for name in sorted(orphans - have):
        out.append(ProjectSummary(project=name, state=ORPHANED_STATE, ssh=None))
    return out


def status(req: StatusRequest, cfg: "Config" | None = None) -> ProjectStatus:  # type: ignore[name-defined]
    """Project state + workspace + (if running) inner-worker lines and the
    .workers/ registry count. die()s if the project doesn't exist."""
    if cfg is None:
        cfg = load_config()
    container = container_name_for(req.name)
    if not container_exists(container):
        die(f"project {req.name!r} does not exist")
    state = run_check(["docker", "inspect", "-f", "{{.State.Status}}", container]).stdout.strip()
    ssh_port = get_ssh_port(container) if state == "running" else None
    workspace = workspace_path_for(req.name, cfg)

    inner: list[str] = []
    reg_count = 0
    if state == "running":
        r = run(["docker", "exec", container, "docker", "ps", "-a",
                 "--format", "{{.Names}}\t{{.Status}}\t{{.Image}}"],
                capture_output=True)
        if r.returncode == 0 and r.stdout.strip():
            inner = r.stdout.strip().splitlines()
        reg = run(["docker", "exec", container, "sh", "-c",
                   "ls /workspace/.workers/*.json 2>/dev/null | wc -l"],
                  capture_output=True)
        if reg.returncode == 0:
            try:
                reg_count = int(reg.stdout.strip() or "0")
            except ValueError:
                reg_count = 0
    return ProjectStatus(
        project=req.name, container=container, state=state,
        workspace=str(workspace), ssh_port=ssh_port,
        inner_workers=inner, registry_count=reg_count)


def update(req: UpdateRequest, cfg: "Config" | None = None,
           progress=None) -> UpdateResult:  # type: ignore[name-defined]
    """Push edited code into a running project. Always recreates the supervisor
    (the only safe shape on sysbox): file-only mode docker-cp's edited files
    into the fresh container before first start; --rebuild rebuilds images
    first. Fail-explicit: a worker/extension enable or disable that dies aborts.
    Defaults are NOT re-folded (create-time only)."""
    if cfg is None:
        cfg = load_config()
    progress = progress or _NULL_PROGRESS
    project = req.name
    container = container_name_for(project)
    if not container_exists(container):
        die(f"project {project!r} does not exist")
    # The docker substrate has no in-container editable surface (no templates, no
    # worker/extension cone) and no sysbox store to re-stage. The ONE meaningful
    # update is toggling the editor (code-server), which recreates the plain runc
    # box; anything else is still refused (inside _update_docker_substrate).
    docker = _container_substrate(container) == Substrate.DOCKER.value
    # The agents' models, the working mode and an agent removal (I33 slice 3):
    # checked against the project before anything is written. Whether Claude's
    # model goes into its settings file is a property of the container's image
    # (older images keep the container setting); asked only when it matters.
    workspace_path = workspace_path_for(project, cfg)
    claude_asked = bool(req.supervisor_model or req.supervisor_effort
                        or set(req.reset) & {"supervisor_model", "supervisor_effort"})
    claude_in_settings = claude_asked and _label_is_set("container", container)
    plan = _agent_settings_plan(req, container, workspace_path, docker=docker,
                                claude_in_settings=claude_in_settings)
    if docker:
        return _update_docker_substrate(req, cfg, project, container, progress, plan=plan)
    # The agents' settings, adds or removals and model changes on a STOPPED
    # project: saved in the record and applied at its next start (which
    # recreates the container from the record — Claude's model included,
    # whatever the old container's image — and relaunches the role services
    # from it) — nothing is started.
    if plan.any() or req.agents is not None or req.model_changes():
        others = req.enable or req.disable or req.role_mcp_upstream or req.rebuild
        if not others and not container_running(container):
            agents_added = _validate_agents_update(req, container, workspace_path)
            if agents_added:
                _refuse_during_agent_build()
            stopped_models = req.model_changes()
            if plan.claude is not None:
                stopped_models.pop("supervisor", None)
            dropped = _apply_model_changes(workspace_path, stopped_models) if stopped_models else []
            _agent_settings_commit(plan, workspace_path)
            if agents_added:
                _write_marker_agents(workspace_path,
                                     list(_read_marker_agents(workspace_path)) + agents_added)
            progress.step("saved", "saved; applied at the project's next start")
            print(f"{project!r} is stopped: the change is saved and applied at its next start.")
            return UpdateResult(project=project, rebuilt=False,
                                effort_dropped=(["supervisor"] if plan.effort_dropped else [])
                                + dropped,
                                agents_added=agents_added)
    if not container_running(ROUTER_CONTAINER):
        die(f"{ROUTER_CONTAINER} is not running. Run `research start` first.")
    progress.step("validate", "validating update")
    # A running project's update may recreate it with the host task cap: a
    # damaged settings file refuses here, before the marker writes below.
    project_pids_limit()

    print(f"=== Updating project: {project} ===")

    # Validate --enable worker tokens up front so a typo doesn't waste a rebuild.
    enable_services, enable_workers = \
        _split_enable_tokens(",".join(req.enable))
    disable_services, disable_workers = \
        _split_disable_tokens(",".join(req.disable))
    role_mcp_explicit = _parse_role_mcp_upstream(
        list(req.role_mcp_upstream), valid_roles=set(enable_workers))
    for role in enable_workers:
        try:
            role_mcp.validate_role(role)
        except ValueError as e:
            die(str(e))

    workspace_path = workspace_path_for(project, cfg)
    # A code-server-only OR reader-only flip on a dind supervisor is deployed LIVE
    # (docker exec), skipping the multi-minute _recreate_supervisor. (Docker already
    # returned via _update_docker_substrate at the gate above.) A MIXED flip
    # ({"code-server","reader"}) falls through to the full recreate, which stages +
    # deploys per the resolved flags and clears both overrides — no live path needed.
    touched = _parse_service_list(enable_services) | _parse_service_list(disable_services)
    # Node is create-time only (STAGE_NODE_SEED, E2). It joins KNOWN_SERVICES, so
    # `project update --enable`'s help advertises it — but node has no live-toggle
    # path, so an accepted `--enable node` would fall through to the full recreate
    # whose only node guard SKIPS when no dist is cached (D5): the label + env would
    # be stamped with nothing deployed (the exact silent no-op the reader floor
    # rejects pre-side-effect). Refuse it — symmetric for --disable. MUST land BEFORE
    # _apply_model_changes below (which persists the marker), or a refused
    # `--enable node --worker-model haiku` writes the worker pair and THEN dies — a
    # side effect on a rejected request. Message names NO CLI verb (it reaches the
    # browser via the enable/disable relay) and the remedy is TRUE in the seed model:
    # node detaches after delivery, so a box can install node itself. A bare update
    # (no node token) still preserves node via label → _read_service_flags →
    # _stage_node_dist. (Docker substrate is already covered — _update_docker_substrate
    # early-returns at the gate above, so this line is dind-only.)
    if "node" in touched:
        die("node is fixed at create — a project can install node itself if it "
            "needs it later")
    # A worker enable (or an upstream change) records itself in the project's
    # settings folder only AFTER the full recreate: refuse a folder the project
    # replaced with a link now, not minutes later.
    # A disable reads the same record: without this it would refuse as "not
    # enabled", the wrong reason, while the worker keeps running.
    if enable_workers or disable_workers or req.role_mcp_upstream:
        _require_settings_folder(workspace_path)
    # Agent model/effort changes (STAGE_MODEL_SELECT). Merge them into the marker
    # FIRST — every downstream path (the live toggles, the full recreate, the
    # role-mcp restart) reads the marker, so writing it once here means each of
    # them picks the change up without its own special case.
    # Agent set (STAGE_PI_AGENT): VALIDATED before any marker write (a
    # refused combination must leave the marker untouched — the node guard's
    # rule), then written beside the model pairs so every downstream path (the
    # live stage below, a full recreate) reads the same marker. `agents_added` is
    # the delta this update owes the supervisor; an unchanged set adds nothing.
    agents_added = _validate_agents_update(req, container, workspace_path)
    # Any agent change reads the cached downloads: refuse while an agent build is
    # swapping them — BEFORE the marker below records an agent that could not be
    # staged.
    if req.agents is not None:
        _refuse_during_agent_build()
    model_changes = req.model_changes()
    # Claude's pair is the plan's (it decides the effort a model keeps, and the
    # commit records it): never through _apply_model_changes. Written into the
    # settings file below on a current container; an older container (its
    # image predates settings-file models — the container setting outranks the
    # file there) needs the recreate, which delivers it from the record.
    claude_recreate = plan.claude is not None and not plan.claude_live
    if plan.claude is not None:
        model_changes.pop("supervisor", None)
    effort_dropped: list[str] = ["supervisor"] if plan.effort_dropped else []
    if plan.any():
        enabled_roles = role_mcp.load_role_mcps(workspace_path) if disable_workers else {}
        for role in disable_workers:
            if role not in enabled_roles:
                die(f"role-mcp {role!r} is not enabled for project {project!r}")
    if plan.any() and (enable_services or disable_services):
        # The service refusals (an unknown id, an always-on service) run here,
        # before the agents' settings are written — never after (validation only).
        _compute_service_flags(enable_services, disable_services)
    if model_changes:
        effort_dropped += _apply_model_changes(workspace_path, model_changes)
    _agent_settings_commit(plan, workspace_path)
    if agents_added:
        _write_marker_agents(workspace_path,
                             list(_read_marker_agents(workspace_path)) + agents_added)
    # Old instructions files met by a writer below: raised once at the end of
    # whichever path this update takes.
    found: list[OldInstructions] = []
    wrote_instructions = False
    if plan.any():
        # Written into the agents' own files now (the container is running);
        # an agent this update adds gets it right after its install below, a
        # removal's restart re-applies whatever is still pending.
        is_research_p = _container_project_type(container) != PROJECT_TYPE_SANDBOX_DIND
        now_local = ([DEFAULT_AGENT] if is_research_p
                     else _read_dind_agent_sets(workspace_path)[1])
        if not plan.removed and not claude_recreate:
            # An agent this update adds is written after its install below.
            _apply_agent_settings_pending(container, workspace_path,
                                          [a for a in now_local if a not in agents_added],
                                          claude_in_settings=plan.claude_live,
                                          progress=progress)
            if plan.harness is not None and not is_research_p:
                _report_warnings(_stage_harness(container, now_local, workspace_path), progress)
                # A working-mode change rewrites RS's instructions too (the
                # home survives; the recreate path would write them again).
                found += _write_project_instructions(project, container, workspace_path,
                                                     progress=progress, has_file=True)
                wrote_instructions = True
        if not (touched or req.rebuild or enable_workers or disable_workers
                or req.role_mcp_upstream or model_changes or agents_added or plan.removed
                or claude_recreate):
            progress.step("agents", "applied to the project's agents")
            print(f"agent settings of {project!r} updated; each agent's next session uses them.")
            _raise_old_instructions(found)
            return UpdateResult(project=project, rebuilt=False,
                                effort_dropped=effort_dropped)
    # `live_ok` must exclude any model OR agent change: `--worker-model haiku
    # --enable code-server` would otherwise take the live-editor fast path, which
    # returns without ever applying the worker pair to anything (the pair is in
    # the marker now, but the role containers would not be re-run and a
    # supervisor change would not be recreated) — a silent half-application. The
    # same shape for `--agent <other> --enable code-server`.
    live_ok = (not req.rebuild and not enable_workers and not disable_workers
               and not req.role_mcp_upstream and not model_changes
               and not agents_added and not plan.removed and not claude_recreate
               and not plan.any())
    if live_ok and touched == {"code-server"}:
        enable = "code-server" in _parse_service_list(enable_services)
        return _live_toggle_editor(project, cfg, container, workspace_path, enable, progress)
    if live_ok and touched == {"reader"}:
        enable = "reader" in _parse_service_list(enable_services)
        return _live_toggle_reader(project, cfg, container, workspace_path, enable, progress)
    # Every validation has passed (the live toggles above sweep after their own
    # last refusal): drop a reserved entry left in the port list, said once,
    # before any of the paths below returns.
    _drop_reserved_port_entries(project, cfg, progress)
    # An agents-only update is LIVE: re-stage the merged set into the running
    # supervisor (its own ~/.local included) and return — no recreate, nothing
    # else in the project touched. Mixed with anything else it falls through to
    # the full recreate, which re-reads the marker (the model-change shape).
    # Gated on the REQUEST carrying an agent set (not on a delta): a set the
    # project already carries is an idempotent re-stage, never a recreate.
    if (req.agents is not None and not touched and not req.rebuild and not enable_workers
            and not disable_workers and not req.role_mcp_upstream and not model_changes
            and not plan.removed and not claude_recreate):
        staged, local = _read_dind_agent_sets(workspace_path)
        progress.step("agents", f"staging {'+'.join(agents_added or staged)} into the project")
        # deploy_local derived from the marker like every other call site (Option
        # C: an agent-less project's supervisor stays unwired); the validator
        # already refuses an empty set, so this is True for every real add. The
        # supervisor's own home gets the local set, the boxes the staged one.
        _report_warnings(_stage_agent_dist(container, staged, deploy_local=bool(local),
                                           **_local_deploy_kwargs(staged, local),
                                           **_pi_pair_kwargs(workspace_path)), progress)
        # The working-mode suite (I33), before the box refresh below.
        _report_warnings(_stage_harness(container, local, workspace_path), progress)
        # RS's instructions into the agent's home (it survives; boxes are not
        # rewritten at an Update).
        if not wrote_instructions:
            found += _write_project_instructions(project, container, workspace_path,
                                                 progress=progress, has_file=True)
        # The recorded models of an agent just installed (I33 slice 3).
        _apply_agent_settings_pending(
            container, workspace_path, local, progress=progress,
            claude_in_settings=_label_is_set("container", container))
        # Running boxes follow live (an Add delivers the new agent wired; a
        # request that adds nothing is an Update). The editor extension: an Add
        # installs it only where none is (a supervisor that just gained claude);
        # an Update forces the shipped version back.
        update_form = not agents_added
        if local and not _install_agent_extensions(
                ["docker", "exec", "-u", "1000", "-e", "HOME=/home/research", container],
                "/home/research", update_form):
            progress.step("agents", "the project's editor extension could not be installed")
        refreshed, not_refreshed = _refresh_running_boxes(
            container, staged, progress, force_ext=update_form)
        # RS's skills into the agents' homes after the agent copy (an agent
        # just added gets them, in the project agent and every box), once the
        # project's own folders were checked for the files RS used to write
        # there — only on a container whose image carries the current layout:
        # an older one's boot puts the files back, so a flag set now would hide
        # them after the Rebuild all (the start path gates the same way).
        image_items = _project_image_check(project, container)
        found += image_items
        if not image_items:
            found += _project_files_check(
                project, workspace_path,
                research=_container_project_type(container) != PROJECT_TYPE_SANDBOX_DIND,
                progress=progress)
        found += _box_tool_home_skills(project, container, ["--boxes"], progress)
        if agents_added:
            print(f"added {', '.join(agents_added)} to {project!r}: the supervisor tab can "
                  f"run it now; {len(refreshed)} running box(es) got it too; a stopped box "
                  f"gets it at the next add or update while it runs, or when re-created.")
        else:
            print(f"agent set unchanged; re-staged {', '.join(staged)} into {project!r} "
                  f"and {len(refreshed)} running box(es).")
        if not_refreshed:
            print(f"warning: not refreshed: {', '.join(not_refreshed)}", file=sys.stderr)
        _raise_old_instructions(found)
        return UpdateResult(project=project, rebuilt=False,
                            effort_dropped=effort_dropped, agents_added=agents_added,
                            boxes_refreshed=refreshed, boxes_not_refreshed=not_refreshed)
    # Granular model application — the point of writing the marker above. Only a
    # SUPERVISOR pair change needs the multi-minute recreate (its env is fixed at
    # docker run); the other two are far cheaper and must not pay for it:
    #   * worker  → nothing at all. `rs-worker spawn` reads the marker per spawn,
    #     so the next worker picks it up; workers already mid-run correctly keep
    #     the model they started on.
    #   * role    → re-run just the role-MCP containers (their env is also fixed
    #     at docker run), honoring the in-flight gate. The supervisor — and the
    #     researcher's session in it — is untouched.
    # A model change MIXED with anything else falls through to the full recreate
    # below, which re-reads the marker anyway (the code-server/reader precedent).
    # `not agents_added` is load-bearing: `--worker-model haiku --agent <other>`
    # would otherwise return here with the marker claiming an agent nothing staged.
    if (model_changes and not touched and not req.rebuild and not enable_workers
            and not disable_workers and not req.role_mcp_upstream and not agents_added
            and not plan.removed and not claude_recreate):
        changed = set(model_changes)
        if changed == {"worker"}:
            progress.step("models", "applying the worker model")
            print("worker model updated; the next `rs-worker spawn` picks it up "
                  "(no container touched).")
            _raise_old_instructions(found)
            return UpdateResult(project=project, rebuilt=False,
                                effort_dropped=effort_dropped)
        if changed == {"role"}:
            progress.step("models", "applying the role model")
            _restart_role_mcps_for_models(project, cfg, workspace_path)
            _raise_old_instructions(found)
            return UpdateResult(project=project, rebuilt=False,
                                effort_dropped=effort_dropped)
        # A `role` change alongside a `supervisor` change still needs the
        # recreate, which relaunches the role containers from the marker — so it
        # falls through with no extra work here.

    if req.rebuild:
        progress.step("rebuild", "rebuilding images")
        print("rebuilding images...")
        _build_images(force=True)

    hook = None
    if not req.rebuild:
        def hook(c: str) -> None:
            print(f"copying edited files into {c}...")
            for rel in _docker_cp_supervisor_files(c):
                print(f"  {rel}")

    flags_override: dict[str, bool] | None = None
    if enable_services or disable_services:
        base = _apply_service_override(_read_service_flags(container), workspace_path)
        flags_override = _compute_service_flags(
            enable_services, disable_services, base=base)

    # Disables run BEFORE the recreate (the recreate's restart loop reads
    # role-mcps.json; a removed entry must not come back up). Fail-explicit:
    # a disable that dies aborts.
    workers_disabled: list[str] = []
    if disable_workers:
        progress.step("disable", "applying disables")
    for role in disable_workers:
        _role_mcp_disable(project, cfg, role)
        workers_disabled.append(role)

    progress.step("recreate", "recreating supervisor")
    found += _recreate_supervisor(
        project, cfg,
        force_restage=req.rebuild,
        post_create_hook=hook,
        service_flags=flags_override,
        progress=progress,
    ) or []

    # The recreate wrote authoritative service labels, so a live-toggle override for
    # any EXPLICITLY-changed service is now redundant — clear it so a stale override
    # can't resurrect the just-applied value on the next recreate. A non-explicit
    # recreate (start, worker-only update) has `touched` empty → the override stays
    # and carries the live choice (it agrees with the freshly-written label).
    if touched:
        _clear_service_override(workspace_path, touched)

    # worker enables (idempotent on re-run). Fail-explicit.
    if enable_workers:
        progress.step("enable", "applying enables")
    workers_enabled: list[str] = []
    for role in enable_workers:
        _role_mcp_enable(project, cfg, role, role_mcp_explicit.get(role))
        workers_enabled.append(role)

    # After the last step, so everything above still ran.
    _raise_old_instructions(found)
    return UpdateResult(
        project=project, rebuilt=req.rebuild,
        workers_enabled=workers_enabled, workers_disabled=workers_disabled,
        effort_dropped=effort_dropped, agents_added=agents_added)


# ===========================================================================
# Relocated substrate — moved verbatim out of research.py. These lifecycle
# helpers + Config + constants back the verbs above; research.py imports them
# back via `from rscore import *`.
# ===========================================================================


# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------

SCRIPT_DIR = Path(__file__).resolve().parent.parent  # repo root (rscore lives in cli/)

# Shared per-project substrate (DIND + ssh + byobu + code-server). Both
