# ---------------------------------------------------------------------------
# MCP registry CLI (Stage 2.1)
# ---------------------------------------------------------------------------


def mcp_container_name_for(name: str) -> str:
    return f"{MCP_CONTAINER_PREFIX}{name}"


def projects_using_mcp(mcp_name: str) -> list[str]:
    """Scan per-project allowlists for projects that allow this MCP. The
    allowlist lives at ``<workspace>/.orchestrator/mcp-allow.json`` (see
    project_allowlist_path) — looking at the project root directly would
    silently miss every project."""
    cfg = load_config()
    root = Path(cfg.projects_dir).expanduser().resolve()
    if not root.is_dir():
        return []
    out: list[str] = []
    for p in sorted(root.iterdir()):
        if not p.is_dir():
            continue
        try:
            data = json.loads(orch_files.read_text(
                workspace_path_for(p.name, cfg), "mcp-allow.json"))
        except (json.JSONDecodeError, OSError):
            continue
        if not isinstance(data, list):
            continue
        for e in data:
            if isinstance(e, dict) and e.get("name") == mcp_name:
                out.append(p.name)
                break
    return out


def project_allowlist_path(project: str, cfg: "Config") -> Path:
    """Per-project MCP allowlist. Lives INSIDE the workspace (which is the
    only thing the supervisor bind-mounts) so atomic-rename writes by
    research.py are visible to the supervisor immediately. A single-file
    bind-mount would pin the original inode and silently make replacements
    invisible to the container."""
    return workspace_path_for(project, cfg) / ".orchestrator" / "mcp-allow.json"


def ensure_mcp_files(project: str, cfg: "Config") -> None:
    """Initialize the host-side mcp registry (if missing) and an empty
    per-project allowlist. The registry is host-only state; the supervisor
    never reads it directly — every datum it needs lives in the allowlist
    entry written at `project mcp allow` time."""
    if not mcp_registry.REGISTRY_PATH.is_file():
        mcp_registry.REGISTRY_DIR.mkdir(parents=True, exist_ok=True)
        mcp_registry.save_atomic(mcp_registry.empty())
    ws = workspace_path_for(project, cfg)
    try:
        orch_files.check_folder(ws)
    except orch_files.Unusable as e:
        die(str(e))
    try:
        orch_files.read_bytes(ws, "mcp-allow.json")
    except FileNotFoundError:
        try:
            orch_files.write_text(ws, "mcp-allow.json", "[]\n", create=True)
        except orch_files.Unusable as e:
            die(str(e))
    except OSError:
        # There but not usable (a link, a non-file): never written through;
        # the allowlist reads as empty and its next save replaces it.
        pass


def resolve_host_gateway() -> str:
    """Numeric IP for `host.docker.internal` from a container on the host's
    docker daemon. Used to translate `external` MCP destinations to numeric
    IPs in per-project allowlists, so the supervisor's inner-daemon proxy
    can reach them via the existing rs-router path."""
    r = run_check([
        "docker", "run", "--rm",
        "--add-host=host.docker.internal:host-gateway",
        "alpine:3.20", "getent", "hosts", "host.docker.internal",
    ])
    out = r.stdout.strip()
    if not out:
        die("could not resolve host.docker.internal via host-gateway")
    return out.split()[0]


def mcp_container_ip(name: str) -> str:
    cname = mcp_container_name_for(name)
    r = run_check([
        "docker", "inspect", cname, "-f",
        '{{(index .NetworkSettings.Networks "' + ROUTER_NETWORK + '").IPAddress}}',
    ])
    ip = r.stdout.strip()
    # A crash-looping container reports "running" between restarts but has an
    # empty IPAddress; docker's template renders that as the literal string
    # "invalid IP" rather than empty — non-empty would silently propagate to
    # iptables. Parse with ipaddress to catch both.
    try:
        ipaddress.ip_address(ip)
    except ValueError:
        die(f"could not resolve {cname}'s IP on {ROUTER_NETWORK} "
            f"(docker inspect returned {ip!r}); the container may be "
            f"crash-looping. Check `docker logs {cname}`.")
    return ip


def load_project_allowlist(project: str, cfg: "Config") -> list[dict]:
    """The project's MCP allowlist; [] when it is absent or not usable (a link
    at the file or at the settings folder, a non-regular file, bytes that are
    not UTF-8 — orch_files: never read through a link). Valid UTF-8 that is
    not a JSON array still refuses. The two corrupt cases differ on purpose:
    "not usable" reads as empty so a planted link cannot block a destroy,
    which reads this list; the project could empty its own list anyway."""
    p = project_allowlist_path(project, cfg)
    try:
        text = orch_files.read_text(workspace_path_for(project, cfg), "mcp-allow.json")
    except OSError:
        return []
    try:
        data = json.loads(text)
    except json.JSONDecodeError as e:
        die(f"allowlist {orch_files.SHOWN_FOLDER}/mcp-allow.json is invalid JSON: {e}")
    if not isinstance(data, list):
        die(f"allowlist {orch_files.SHOWN_FOLDER}/mcp-allow.json must be a JSON array")
    return [e for e in data if isinstance(e, dict)]


def save_project_allowlist(project: str, cfg: "Config", entries: list[dict]) -> None:
    """Replace the allowlist atomically through the no-follow settings folder
    (a fresh temp name — orch_files); a settings folder that is a link or not
    a folder refuses (die)."""
    try:
        orch_files.write_text(workspace_path_for(project, cfg), "mcp-allow.json",
                              json.dumps(entries, indent=2, sort_keys=True) + "\n",
                              create=True)
    except orch_files.Unusable as e:
        die(str(e))


def _parse_kv(items: list[str], flag: str) -> dict[str, str]:
    out: dict[str, str] = {}
    for item in items:
        if "=" not in item:
            die(f"{flag} entry must be K=V, got {item!r}")
        k, _, v = item.partition("=")
        if not k:
            die(f"{flag} entry has empty key: {item!r}")
        out[k] = v
    return out


def _parse_host_arg(s: str) -> tuple[str, int]:
    host, sep, port_s = s.rpartition(":")
    if not sep or not host or not port_s:
        die(f"--host must be HOST:PORT, got {s!r}")
    try:
        port = int(port_s)
    except ValueError:
        die(f"--host port must be an integer, got {port_s!r}")
    return host, port


def _build_mcp_entry(args: argparse.Namespace) -> dict:
    entry: dict = {"kind": args.kind, "transport": args.transport}
    if args.path and args.path != mcp_registry.DEFAULT_PATH:
        entry["path"] = args.path
    if args.kind == "external":
        if args.host is None:
            die("--host is required for --kind external")
        host_addr, host_port = _parse_host_arg(args.host)
        entry["host_address"] = host_addr
        entry["host_port"] = host_port
        if args.header:
            entry["headers"] = _parse_kv(args.header, "--header")
    else:  # shared
        if not args.image:
            die("--image is required for --kind shared")
        if args.port is None:
            die("--port is required for --kind shared")
        entry["image"] = args.image
        entry["port"] = args.port
        if args.env:
            entry["env"] = _parse_kv(args.env, "--env")
    desc = (getattr(args, "description", None) or "").strip()
    if desc:
        entry["description"] = desc
    roles = _parse_csv_list(getattr(args, "roles", None))
    if roles:
        entry["roles"] = roles
    return entry


def _ensure_router_running() -> None:
    if not container_running(ROUTER_CONTAINER):
        die(f"{ROUTER_CONTAINER} is not running. Run `research start` first.")


def _registry_role(name: str) -> str:
    """The role label of an existing registry container ("" when unlabelled —
    the single writable registry older versions ran — or when the container
    does not exist). `docker container inspect`, never bare inspect: the
    registry's image shares no name with its container, but the discipline is
    the same."""
    r = run(["docker", "container", "inspect", "-f",
             f'{{{{index .Config.Labels "{REGISTRY_ROLE_LABEL}"}}}}', name],
            capture_output=True)
    return r.stdout.strip() if r.returncode == 0 else ""


def _registry_instance_status(name: str) -> str:
    """`.State.Status` of a registry container ("" when absent)."""
    r = run(["docker", "container", "inspect", "-f", "{{.State.Status}}", name],
            capture_output=True)
    return r.stdout.strip() if r.returncode == 0 else ""


class RegistryUnavailable(Exception):
    """The box image registry could not be brought up. `reason` is a fixed,
    browser-safe text naming the cause (no command, no host file): the box-image
    step returns it as its reason, `research start` warns with it."""

    def __init__(self, reason: str):
        super().__init__(reason)
        self.reason = reason


def _registry_port_held(host_port: str) -> RegistryUnavailable:
    return RegistryUnavailable(f"the box image registry's port {host_port} on this "
                               f"computer is held by another program")


def _run_registry_instance(name: str, role: str, image: str, host_port: str) -> bool:
    """`docker run` one registry instance over the shared storage directory;
    True when this call created it. The read-only role gets the maintenance
    switch and no published port; the push role gets the loopback publish and
    no switch. A held loopback port is classified FIRST: docker leaves a
    `created` container behind such a failure (measured), which a later
    `docker start` would bring up WITHOUT the port — so that leftover is
    removed by name and the cause is named. A run that fails because a sibling
    caller created the same name meanwhile is accepted only when that
    container is RUNNING."""
    args = ["docker", "run", "-d", "--name", name,
            "--network", GATEWAY_NETWORK_RUN_ARG,
            "--restart", "unless-stopped",
            "--label", f"{REGISTRY_ROLE_LABEL}={role}",
            "-v", f"{REGISTRY_CACHE_DIR}:/var/lib/registry"]
    if role == REGISTRY_ROLE_READONLY:
        args += ["-e", REGISTRY_READONLY_ENV]
    else:
        args += ["-p", f"127.0.0.1:{host_port}:{REGISTRY_INNER_PORT}"]
    r = run(args + [image], capture_output=True)
    if r.returncode == 0:
        return True
    err = (r.stderr or r.stdout or "").strip()
    if "already allocated" in err or "address already in use" in err:
        if _registry_instance_status(name) == "created":
            run(["docker", "rm", name], capture_output=True)
        raise _registry_port_held(host_port)
    if _registry_instance_status(name) == "running":
        # a concurrent caller won the creation race; its container serves
        return False
    raise RegistryUnavailable(f"the box image registry ({name}) could not be started")


def _push_port_bound() -> bool:
    r = run(["docker", "port", REGISTRY_PUSH_CONTAINER], capture_output=True)
    return r.returncode == 0 and bool(r.stdout.strip())


def _check_push_port(host_port: str) -> None:
    """Raise RegistryUnavailable naming the cause when the push instance runs without its loopback
    port (a `docker start` of a container whose port was taken meanwhile
    succeeds port-less — measured); the backstop after every arm. An instance
    that is not running at all (crashed at boot) is a different failure."""
    if not container_running(REGISTRY_PUSH_CONTAINER):
        raise RegistryUnavailable(f"the box image registry ({REGISTRY_PUSH_CONTAINER}) "
                                  f"stopped right after its start")
    if not _push_port_bound():
        raise _registry_port_held(host_port)


def _attach_registry_to_all_projects() -> None:
    """Attach the read-only registry to every per-project network (idempotent;
    a re-connect exits non-zero silently). Run after the instance was
    (re)created, so no running project is left without its pull path."""
    r = run(["docker", "network", "ls",
             "--filter", f"name=^{PROJECT_NETWORK_PREFIX}",
             "--format", "{{.Name}}"],
            capture_output=True)
    for net in r.stdout.strip().splitlines():
        if net:
            run(["docker", "network", "connect", net, REGISTRY_CONTAINER],
                capture_output=True)


def _registry_image_and_port() -> tuple[str, str]:
    pins = load_versions()
    return ("registry:" + pins.get("REGISTRY_VERSION", DEFAULT_REGISTRY_VERSION),
            pins.get("REGISTRY_HOST_PORT", DEFAULT_REGISTRY_HOST_PORT))


def _pull_registry_image_if_needed(image: str) -> None:
    """A registry image pruned while both instances exist is not needed (a
    stopped container keeps its image); otherwise pull it."""
    if not run_quiet(["docker", "image", "inspect", image]) \
            and not (container_exists(REGISTRY_CONTAINER)
                     and container_exists(REGISTRY_PUSH_CONTAINER)):
        print(f"pulling {image}...")
        if run(["docker", "pull", image], capture_output=True).returncode != 0:
            raise RegistryUnavailable("the box image registry's own image could not "
                                      "be downloaded")


def _ensure_readonly_registry() -> None:
    """The READ-ONLY instance every inner daemon pulls from — the only thing a
    pull-side caller (a recreate, a box delivery) needs. Triad running ->
    no-op; exists-stopped -> docker start; absent -> docker run. An
    `rs-registry` without the role label is the single writable registry an
    older version ran: it is removed (its storage is the shared host directory,
    nothing is lost) and recreated read-only, then re-attached to EVERY project
    network — never only the caller's — so no other running project loses its
    pulls until its next delivery. The old container holds the loopback port,
    so removing it first is what lets the push instance come up later."""
    image, host_port = _registry_image_and_port()
    converted = False
    if container_exists(REGISTRY_CONTAINER) \
            and _registry_role(REGISTRY_CONTAINER) != REGISTRY_ROLE_READONLY:
        print(f"converting {REGISTRY_CONTAINER} to a read-only instance "
              f"(writes move to {REGISTRY_PUSH_CONTAINER} on the loopback port)")
        # tolerant: a concurrent first caller may have removed it already
        run(["docker", "rm", "-f", REGISTRY_CONTAINER], capture_output=True)
        converted = True
    _pull_registry_image_if_needed(image)
    REGISTRY_CACHE_DIR.mkdir(parents=True, exist_ok=True)
    created = False
    if container_running(REGISTRY_CONTAINER):
        pass
    elif container_exists(REGISTRY_CONTAINER):
        if run(["docker", "start", REGISTRY_CONTAINER],
               capture_output=True).returncode != 0:
            raise RegistryUnavailable(f"the box image registry ({REGISTRY_CONTAINER}) "
                                      f"could not be started")
    else:
        created = _run_registry_instance(REGISTRY_CONTAINER, REGISTRY_ROLE_READONLY,
                                         image, host_port)
        if created:
            print(f"started {REGISTRY_CONTAINER} ({REGISTRY_ROLE_READONLY} box-image "
                  f"registry on {ROUTER_NETWORK})")
    if converted or created:
        _attach_registry_to_all_projects()


def _ensure_push_registry() -> None:
    """The writable instance on the loopback port — what a PUSH needs (create,
    research's first box of a kind, a start that moves a project to a new box
    image build) and what
    `research start` brings up for the operator. Triad as above; a held
    loopback port is named at every arm: at the run (the cause, the `created`
    leftover removed), at a failed `docker start` of the stopped instance
    (docker refuses the bind), and after a start that succeeded without the
    port (docker lets that happen on a second attempt — measured)."""
    image, host_port = _registry_image_and_port()
    _pull_registry_image_if_needed(image)
    REGISTRY_CACHE_DIR.mkdir(parents=True, exist_ok=True)
    if container_running(REGISTRY_PUSH_CONTAINER) and not _push_port_bound():
        # docker brought it up without the port on a retry while something
        # held it (measured); it can never regain the port in place, so it is
        # recreated — the port may be free now, and if not the run names the cause
        print(f"recreating {REGISTRY_PUSH_CONTAINER}: it runs without its loopback port")
        run(["docker", "rm", "-f", REGISTRY_PUSH_CONTAINER], capture_output=True)
    if container_running(REGISTRY_PUSH_CONTAINER):
        pass
    elif container_exists(REGISTRY_PUSH_CONTAINER):
        r = run(["docker", "start", REGISTRY_PUSH_CONTAINER], capture_output=True)
        if r.returncode != 0:
            err = (r.stderr or r.stdout or "").strip()
            if "already allocated" in err or "address already in use" in err:
                raise _registry_port_held(host_port)
            raise RegistryUnavailable(f"the box image registry "
                                      f"({REGISTRY_PUSH_CONTAINER}) could not be started")
    else:
        if _run_registry_instance(REGISTRY_PUSH_CONTAINER, REGISTRY_ROLE_PUSH,
                                  image, host_port):
            print(f"started {REGISTRY_PUSH_CONTAINER} ({REGISTRY_ROLE_PUSH} box-image "
                  f"registry on {ROUTER_NETWORK})")
    _check_push_port(host_port)


def _ensure_registry_running() -> None:
    """Both instances (B155): the read-only `rs-registry` every inner daemon
    pulls from, then the writable `rs-registry-push` the host pushes through,
    over one storage directory. Order is load-bearing: the read-only instance,
    which cannot fail on a port, comes back first, so a held loopback port
    leaves every pull-only delivery working and only the host's push lane
    missing until the next attempt. Pull-side callers use
    `_ensure_readonly_registry` alone; this is for the push callers (create,
    research's lazy box delivery, a start that publishes a new box image build) and for
    `research start`."""
    _ensure_readonly_registry()
    _ensure_push_registry()


def _connect_registry_to_project_network(network: str) -> None:
    """Attach the READ-ONLY registry to a per-project network so the project's
    inner dockerd pulls rs-registry:5000 by container DNS over its OWN subnet
    (L2) — never crossing the router's RFC1918 DROP. Ensures that instance
    exists first (lazy stand-up; the push instance is not needed to pull, so a
    held loopback port never fails a pull-only delivery — a re-creation whose
    box images are current; a delivery that PUSHES needs the pair and names
    the cause).
    Idempotent (a re-connect exits non-zero silently)."""
    _ensure_readonly_registry()
    run(["docker", "network", "connect", network, REGISTRY_CONTAINER],
        capture_output=True)


# ---------------------------------------------------------------------------
# Shared rs-gitea (STAGE_DEV_GITEA S1) — the dev lane's registry-pattern sibling
# ---------------------------------------------------------------------------

# A Gitea version as it may appear in a pin: dotted digits only. It becomes part
# of an image reference and a container label, so nothing else gets through.
_GITEA_VERSION_RE = re.compile(r"\d+(?:\.\d+)*")

# The first Gitea release whose egress settings moved: `[migrations]
# ALLOWED_DOMAINS` and `[webhook] ALLOWED_HOST_LIST` became deprecated
# fallbacks, and the webhook allowlist stopped restricting PUBLIC hosts unless
# `[security] EGRESS_MODE = strict` is set (measured: a webhook to a non-GitHub
# host is blocked by 1.25.1 and delivered by 28.2.0 under the old settings).
GITEA_EGRESS_SETTINGS_VERSION = "28"

# The container label naming the gitea release it runs — set at `docker run`.
GITEA_VERSION_LABEL = "research.gitea.version"
# The restart policy every gitea container is created with, and what an upgrade's
# rollback puts back on the old container after keeping it aside with none.
GITEA_RESTART_POLICY = "unless-stopped"


def _gitea_pinned_version(pins: dict[str, str]) -> str:
    """The Gitea version the pins ask for, validated before it reaches docker."""
    version = pins.get("GITEA_VERSION", gitea.DEFAULT_GITEA_VERSION)
    if not _GITEA_VERSION_RE.fullmatch(version):
        die(f"GITEA_VERSION {version!r} is not a version number")
    return version


def _gitea_env(version: str, webui_port: str | None = None) -> dict[str, str]:
    """The environment every gitea `docker run` gets, for that gitea VERSION.

    The egress allowlists are a lockstep with the version: on a release older
    than GITEA_EGRESS_SETTINGS_VERSION the new setting names mean nothing (the
    migration restriction would silently disappear), and on a newer one the old
    names leave webhooks free to reach any public host.

    Gitea's own session and remember-me cookie names carry the webui's
    published port (``webui_port``, default the configured WEBUI_PORT): gitea
    is reached through the webui's origin ports at the operator's hostname, and
    browsers key cookies on the hostname alone, so a second RS's gitea at the
    same hostname would otherwise share — and overwrite — this one's login
    (B73). The suffix only has to DIFFER between two installs, so the value
    captured when the container is created stays correct if WEBUI_PORT later
    changes. These two are the only cookie names gitea lets a config set (its
    CSRF cookie is gone in 28.x and was a fixed name before)."""
    if webui_port is None:
        # Same fallback as `research webui start` (compose's ${WEBUI_PORT:-7777}).
        webui_port = read_env_value("WEBUI_PORT") or "7777"
    env = {
        "INSTALL_LOCK": "true",
        "GITEA__service__DISABLE_REGISTRATION": "true",
        "GITEA__service__REQUIRE_SIGNIN_VIEW": "true",
        "GITEA__server__DISABLE_SSH": "true",
        "GITEA__server__ROOT_URL": f"http://{gitea.GITEA_CONTAINER}:{gitea.GITEA_INNER_PORT}/",
        "GITEA__session__COOKIE_NAME": f"i_like_gitea_{webui_port}",
        "GITEA__security__COOKIE_REMEMBER_NAME": f"gitea_incredible_{webui_port}",
    }
    # GitHub migration hits api.github.com (metadata) + codeload.github.com
    # (archives) besides github.com (clone), so allow the apex + its
    # subdomains — still tight (SSRF-guarded to GitHub only).
    migrate_hosts = "github.com,*.github.com"
    if _version_older(version, GITEA_EGRESS_SETTINGS_VERSION):
        env["GITEA__migrations__ALLOWED_DOMAINS"] = migrate_hosts
        env["GITEA__webhook__ALLOWED_HOST_LIST"] = "github.com"
    else:
        env["GITEA__migrations__ALLOWED_HOST_LIST"] = migrate_hosts
        env["GITEA__migrations__EGRESS_MODE"] = "strict"
        env["GITEA__security__ALLOWED_HOST_LIST"] = "github.com"
        env["GITEA__security__EGRESS_MODE"] = "strict"
    return env


def _run_gitea_container(image: str, volume: str, version: str,
                         host_port: str) -> None:
    """`docker run` the shared gitea on ``volume``. The one place the container's
    shape is decided, so every creator produces the same container. The version
    label is what status reads to name the running release."""
    cmd = [
        "docker", "run", "-d",
        "--name", gitea.GITEA_CONTAINER,
        "--network", GATEWAY_NETWORK_RUN_ARG,
        "--restart", GITEA_RESTART_POLICY,
        "--label", f"{GITEA_VERSION_LABEL}={version}",
        "-p", f"127.0.0.1:{host_port}:{gitea.GITEA_INNER_PORT}",
        "-v", f"{volume}:/data",
    ]
    for k, v in _gitea_env(version).items():
        cmd += ["-e", f"{k}={v}"]
    cmd.append(image)
    r = run(cmd, capture_output=True)
    if r.returncode != 0:
        err = (r.stderr or r.stdout or "").strip()
        if "already allocated" in err or "address already in use" in err:
            die(f"host port {host_port} is already in use; set GITEA_HOST_PORT "
                f"in versions.env to a free port and retry. (docker: "
                f"{err[-200:]})")
        die(f"failed to start {gitea.GITEA_CONTAINER}: {err[-300:]}")


def _provision_gitea(progress=None) -> None:
    """Provision the shared Gitea on rs-sandbox — the DELIBERATE Enable action,
    and the SOLE creator (deliberate-create / auto-resume model). Triad: running
    -> ensure-bootstrap; exists-stopped -> docker start; absent -> pull + docker
    run. Home ROUTER_NETWORK (internet via the gateway for mirror sync); admin
    API on a 127.0.0.1 loopback port only. Stood up DELIBERATELY via
    `dev_gitea_start` (webui Sandboxes -> Infrastructure, or `research dev
    gitea-enable`) — never lazily. A stopped-but-enabled gitea is RESUMED by
    _resume_gitea, which never creates; only this function ever CREATES it.

    Stale-token guard: if the tokens exist but the container AND every copy of
    its data are gone, die with a remedy — a fresh gitea would reject the stale
    admin token silently, so surface it rather than half-work.

    Upgrade-aware: an upgrade that was cut off before its new release proved
    itself (a record short of `committed`) is finished here by putting the old
    release back — the button reads Recover in that state. A create picks its
    data volume through _gitea_data_volume, so a gitea whose container was
    removed after an upgrade comes back on the upgraded copy. The start and
    create arms hold the gitea lock SHARED, so neither can start a container
    while an upgrade or a restore is moving its data."""
    progress = progress or _NULL_PROGRESS
    pins = load_versions()
    host_port = pins.get("GITEA_HOST_PORT", gitea.DEFAULT_GITEA_HOST_PORT)
    # The record is read BEFORE the already-running shortcut: an upgrade killed
    # after its new release started leaves that unverified release running, and
    # the shortcut would bless it.
    try:
        rec = _read_upgrade_record()
    except ValidationError as e:
        die(str(e))
    if rec is not None and rec["phase"] != "committed" and gitea_upgrading():
        die(GITEA_BUSY_MSG)
    if container_running(gitea.GITEA_CONTAINER) and (
            rec is None or rec["phase"] == "committed"):
        # Already up — but a prior attempt may have started it and then FAILED
        # bootstrap (leaving no tokens). So fall through to the bootstrap-if-absent
        # step rather than early-returning; the wait+bootstrap runs at most once
        # (bootstrap_present() gates it), so a healthy re-entry is a cheap no-op.
        progress.step("bootstrap", "checking gitea accounts")
        _bootstrap_gitea_if_absent(host_port)
        return
    if rec is not None and rec["phase"] != "committed":
        progress.step("recover", "going back to Gitea " + rec["from_version"]
                      if rec["phase"] == "rolling-back"
                      else "finishing an interrupted upgrade")
        _recover_interrupted_upgrade(rec, progress)
        progress.step("bootstrap", "checking gitea accounts")
        _bootstrap_gitea_if_absent(host_port)
        return
    if (gitea.bootstrap_present()
            and not container_exists(gitea.GITEA_CONTAINER)
            and rec is None and not _gitea_data_volume_candidates()):
        die(f"stale dev-lane tokens from a removed {gitea.GITEA_CONTAINER}; "
            f"rm {gitea.ADMIN_TOKEN_PATH} and {gitea.OPERATOR_TOKEN_PATH} to "
            f"re-enable on the next `research dev gitea-enable`.")
    try:
        with _gitea_lock(exclusive=False, blocking=False):
            if container_running(gitea.GITEA_CONTAINER):
                progress.step("bootstrap", "checking gitea accounts")
                _bootstrap_gitea_if_absent(host_port)
                return
            if container_exists(gitea.GITEA_CONTAINER):
                progress.step("start", "starting gitea")
                run_check(["docker", "start", gitea.GITEA_CONTAINER])
            else:
                version = _gitea_pinned_version(pins)
                image = "gitea/gitea:" + version
                try:
                    volume = _gitea_data_volume()
                except ValidationError as e:
                    die(str(e))
                progress.step("pull", "pulling the gitea image")
                if not run_quiet(["docker", "image", "inspect", image]):
                    print(f"pulling {image}...")
                    run_check(["docker", "pull", image])
                _run_gitea_container(image, volume, version, host_port)
                print(f"started {gitea.GITEA_CONTAINER} (shared dev gitea on "
                      f"{ROUTER_NETWORK})")
            # We just started (or created) the container: its app is NOT serving
            # the instant `docker start` returns (sqlite reopen + http bind take a
            # moment). Wait for readiness BEFORE any caller touches the API — an
            # already-bootstrapped restart would otherwise race the first
            # post-restart API call (the "not private" cascade the harness
            # caught). The pure-already-running path above skips this (gitea was
            # already serving from a prior call).
            _wait_for_gitea(host_port)
            progress.step("bootstrap", "checking gitea accounts")
            _bootstrap_gitea_if_absent(host_port)
    except _GiteaLockBusy:
        die(GITEA_BUSY_MSG)


def _resume_gitea(*, require: bool, tries: int | None = None) -> bool:
    """RESUME an already-enabled gitea (the router/projects precedent) — NEVER
    creates. running -> ensure-bootstrap; exists-stopped -> docker start + wait +
    ensure-bootstrap; absent -> die with the enable remedy when `require`, else
    return False (best-effort skip for universal wiring). This is the
    'no lazy-loading' line: adding a repo, syncing, or wiring a project resumes
    an ENABLED backend but never conjures one — only _provision_gitea (the Enable
    action) creates. A stale-token/corrupt state (tokens present, container gone)
    surfaces on the eventual Enable, whose _provision_gitea guard names the real
    remedy; here the operator is simply told to enable first."""
    host_port = load_versions().get("GITEA_HOST_PORT", gitea.DEFAULT_GITEA_HOST_PORT)
    # An upgrade that has not committed owns gitea: in progress, the running
    # container may be an unverified release mid-migration; cut off, only
    # Recover may decide what runs. A file read, so the no-lock arms stay cheap
    # (and the record is absent on every host that never upgraded). A restore
    # writes no record, so its own wiring pass, run while it holds the lock,
    # is unaffected.
    try:
        rec = _read_upgrade_record()
    except ValidationError as e:
        if require:
            die(str(e))
        return False
    if rec is not None and rec["phase"] != "committed":
        if not require:
            return False
        if gitea_upgrading():
            die(GITEA_BUSY_MSG)
        die(_gitea_interrupted_msg(rec))
    # The running and absent arms take no lock and create no file: a host that
    # never enabled gitea must stay untouched by `research start`'s wiring pass.
    if container_running(gitea.GITEA_CONTAINER):
        _bootstrap_gitea_if_absent(host_port, tries=tries)
        return True
    if container_exists(gitea.GITEA_CONTAINER):
        # The stopped arm starts a container, so it holds the lock SHARED and
        # re-checks under it: an upgrade or a restore may have stopped gitea to
        # move its data, and a start now would land on a half-copied volume.
        try:
            with _gitea_lock(exclusive=False, blocking=False):
                if not container_running(gitea.GITEA_CONTAINER):
                    if not container_exists(gitea.GITEA_CONTAINER):
                        die("Gitea isn't enabled — enable it in Sandboxes → "
                            "Infrastructure first")
                    run_check(["docker", "start", gitea.GITEA_CONTAINER])
                    _wait_for_gitea(host_port, tries=tries)
                _bootstrap_gitea_if_absent(host_port, tries=tries)
        except _GiteaLockBusy:
            die(GITEA_BUSY_MSG)
        return True
    if require:
        if gitea_upgrading():
            die(GITEA_BUSY_MSG)
        # An uncommitted record was refused at the top. With a committed one
        # (or none) a missing container is what Enable fixes — the page offers
        # exactly that button, so name it.
        die("Gitea isn't enabled — enable it in Sandboxes → Infrastructure first")
    return False


def _bootstrap_gitea_if_absent(host_port: str, *, tries: int | None = None) -> None:
    """Wait for readiness + create the admin/operator accounts, ONCE. Gated on
    bootstrap_present() so a healthy re-entry is a cheap no-op; runs from both
    the just-started path AND the already-running path (a prior run that started
    the container but failed bootstrap left no tokens — this heals it)."""
    if gitea.bootstrap_present():
        return
    _wait_for_gitea(host_port, tries=tries)
    # A mint failure here raises GiteaError; die() (mid-execution infra channel)
    # so it never escapes a broker verb fn as a foreign exception (dispatch
    # catches only ValidationError/HarnessError/SystemExit).
    try:
        gitea.bootstrap_accounts(host_port, secrets.token_urlsafe(24),
                                 secrets.token_urlsafe(24))
    except gitea.GiteaError as e:
        die(str(e))
    print(f"bootstrapped {gitea.GITEA_CONTAINER} accounts "
          f"({gitea.ADMIN_USER}, {gitea.OPERATOR_USER})")


def _wait_for_gitea(host_port: str, *, tries: int | None = None) -> None:
    """Block until the gitea API answers, bounded. Named constant: gitea's first
    boot (sqlite init + migrations) is a few seconds; 60 * 1s covers a cold pull
    on a slow disk without hanging forever on a wedged container."""
    import time
    # /api/healthz is the PUBLIC readiness endpoint (DB + cache ping) — unlike
    # /api/v1/version, it is NOT gated by REQUIRE_SIGNIN_VIEW (which we set), so
    # it answers 200 without auth the moment gitea is serving.
    health = f"http://127.0.0.1:{host_port}/api/healthz"
    # `tries` overrides the budget for callers that are RESUMING rather than
    # cold-booting (see GITEA_RESUME_WAIT_TRIES); None means the full budget.
    # Worst case on the serial thread is GITEA_BOOT_WAIT_TRIES × (probe+sleep) ≈
    # 4 min against a wedged gitea — bounded, CLI-dominant today (a webui client
    # would have hit its 30s relay timeout long before, which is acceptable: the
    # daemon keeps working, only that one relayed call reports unreachable).
    for _ in range(GITEA_BOOT_WAIT_TRIES if tries is None else tries):
        # Per-probe bound so a half-up gitea can't hang the caller on urllib's
        # default (no) timeout. Stdlib only — no host-tool dependency.
        try:
            with urllib.request.urlopen(health, timeout=GITEA_PROBE_MAX_TIME_S):
                return
        except OSError:
            pass
        time.sleep(1)
    die(f"{gitea.GITEA_CONTAINER} did not become ready on 127.0.0.1:{host_port}")


# Bound on the whole encrypted instance export, which runs INLINE on the broker's
# serial accept thread (the export is deliberately not a detached lane: the
# one-resident-artifact invariant has no other serializer). rscore cannot import
# the webui's BROKER_OP_TIMEOUT_S — that constant lives in webui/server.py and the
# webui image carries no cli/ — so this is the house form: a literal whose comment
# names the value it must stay under (_UPSTREAM_RESOLVE_MAX_TIME_S here and
# gitea.API_TIMEOUT_S are the same shape).
#
# 540 = 60s UNDER the webui's 600s op window. Strictly under, not equal: at exactly
# 600 the browser's wait and the daemon's bound expire together, so the browser
# reports failure while the export is still running and still holding the daemon.
# The 60s covers writing the reply envelope and the client's own round trip.
#
# The CLI shares this bound, and its consequence differs from a migrate's: a
# migrate HEALS on re-run, so exceeding MIGRATE_TIMEOUT_S is a retry. An export
# does not heal — a kill at the ceiling is a hard failure that wrote nothing, and
# the refusal says so rather than implying a retry behaves differently.
BOARD_EXPORT_TIMEOUT_S = 540
# The floor below which starting an export is pointless. The budget above covers
# resuming gitea AND the export, and a resume can consume most of it; 60s is the
# same headroom figure used above, i.e. roughly one round trip plus the smallest
# export this code has been measured producing (a seeded fixture dumps in a few
# seconds). Below it the export is certain to be cut off, so refusing costs the
# operator nothing they would not lose anyway and tells them why.
BOARD_EXPORT_MIN_RUN_S = 60

# Bound on the restore. It is NOT BOARD_EXPORT_TIMEOUT_S: that number is reasoned
# entirely from the webui's op window, and the restore has no webui path at all
# (CLI only, by ruling — it stops gitea and replaces its data). What it does have
# is more work than an export: a verification decrypt, then a full safety export
# with its own verify, then a second decrypt that also unpacks. Three passes over
# the artifact rather than one. 1800s is that shape with headroom on a large
# instance; at the export's 540 a big restore would be killed MID-REPLACE, which
# is the one moment this code must not be interrupted. There is no client waiting
# on a clock, so a generous bound costs nothing but a longer wait on a genuinely
# wedged docker.
BOARD_IMPORT_TIMEOUT_S = 1800
# The floor for STARTING the replace, and deliberately not the export's 60s one.
# That constant is reasoned as "one round trip plus the smallest export measured"
# — a sensible gate for a read pass that can simply be re-run. The replace is the
# opposite case: being cut off part way is the one thing this code must not do,
# and it is the pass whose failure leaves a half-written database. 300s is the
# measured shape of a replace (decrypt, unpack, load, copy a repository tree)
# with room for an instance several times the size of anything measured here; if
# less than that is left, the restore refuses to start rather than begin work it
# may not finish. Below it the operator loses nothing but the wait they already
# spent, and their instance is still running.
BOARD_REPLACE_MIN_RUN_S = 300

# How much of docker's own output a failed `docker start` of gitea shows the
# operator, from the END. Measured on docker 29: a start whose published port is
# taken prints ~315 characters on two lines, "Error response from daemon: failed to
# set up container networking: driver failed programming external connectivity on
# endpoint <name> (<64-hex id>): Bind for 127.0.0.1:<port> failed: port is already
# allocated" plus a short trailer naming the container. The reason sits just
# before that trailer, so a tail keeps it: 300 keeps everything from "container
# networking" on, half of it keeps only the bind clause, and ten times it lets a
# pathological multi-KB output flood a one-line error. It is also what the enable
# path already shows for the same container's failed start.
_GITEA_START_ERR_TAIL_CHARS = 300

# Where a browser-initiated export lands. This is the ONLY definition — the
# webui is told the path rather than deriving one, because it runs in a container
# and cannot know the operator's home.
#
# It used to live under the broker's `run/` directory for one reason: that is the
# host directory the webui has mounted read-only, so it was the only place a file
# could be served to the browser from. The browser download was removed (the page
# names this path and the operator takes the file themselves), and with it that
# reason. `run/` holds the socket and the op logs — runtime state — and a backup
# is the opposite of runtime state, so it moves here where the name says what it
# is. A real consequence beyond tidiness: the artifact now sits OUTSIDE anything
# the webui container has mounted, so a compromised webui cannot read the
# instance's own signing keys off the disk.
BOARD_EXPORT_DIR = Path.home() / ".research-sandbox" / "backups"
# ONE fixed on-disk name. It is what makes "at most one resident backup" a
# checkable property, and with no sweep (see dev_board_export) the atomic replace
# onto this name IS the mechanism. It carries no date deliberately: a dated name
# would mean many resident files and therefore a sweep, which was reversed for
# good reasons. The page shows when the file was taken, and the operator dates
# their own copy if they want one.
BOARD_EXPORT_NAME = "gitea-instance.gpg"

GITEA_BOOT_WAIT_TRIES = 60       # ~1 probe/sec; covers a cold pull + sqlite init
GITEA_PROBE_MAX_TIME_S = 3       # per-probe bound (< the 1s-cadence loop's budget)
# The RESUME deadline, for `research start`'s wiring pass. The budget above is
# sized for a COLD boot — image pull, sqlite init, migrations. A resume does none
# of that: the container exists and is already bootstrapped, so it starts a
# process and binds a port. Spending the cold-boot budget here would make
# `research start` hang for minutes on a sick gitea, on the routine path after
# every `research stop` and on the very command an operator reaches for when
# things are already broken. Expiry is NOT destructive (the wiring pass catches
# it and continues with the container merely running), so this only has to cover
# a warm restart with headroom.
# The deadline bounds the WAIT; the serving flag the wiring pass carries out of
# a failed wait bounds everything AFTER it (the live fork resolutions would
# otherwise each pay gitea.API_TIMEOUT_S, per repo, per project). Neither alone
# is sufficient — a short deadline without the flag can hand back a pass that
# costs more than the wait it replaced.
# MEASURED, not chosen: a warm restart of an already-bootstrapped gitea reached
# its health endpoint in 2.4s on the acceptance run, so ten tries (~10s, since
# each is a bounded probe plus a 1s sleep) is roughly 4x headroom while staying
# an order of magnitude under the cold-boot budget. The harness re-measures and
# fails if the margin ever disappears.
GITEA_RESUME_WAIT_TRIES = 10


def _connect_gitea_to_project_network(network: str) -> str:
    """Attach rs-gitea to a per-project network (L2, dodging the router RFC1918
    DROP, exactly like the registry) and return its IP on that bridge — recorded
    in the attachment record so S2 can inject `--add-host rs-gitea:<ip>` into a
    box (inner-container DNS does not resolve outer-bridge names).

    CONNECT-ONLY: it does NOT provision or resume gitea (the caller decides its
    resume/skip posture via _resume_gitea first — deliberate-create/auto-resume).
    Returns "" if gitea isn't running, which every caller already tolerates."""
    if not container_running(gitea.GITEA_CONTAINER):
        return ""
    run(["docker", "network", "connect", network, gitea.GITEA_CONTAINER],
        capture_output=True)
    r = run(["docker", "inspect", gitea.GITEA_CONTAINER, "-f",
             '{{(index .NetworkSettings.Networks "' + network + '").IPAddress}}'],
            capture_output=True)
    return r.stdout.strip()


def wire_gitea_to_projects(progress=None) -> None:
    """Re-attach rs-gitea after a host `start`/recreate — UNIVERSAL network
    wiring, like wire_registry_to_projects (STAGE_DEV_GITEA S3: every project
    is wired once gitea exists), refreshing each record entry's gitea_ip on
    reconnect and re-staging the project-side non-secret wiring. The FETCH
    surface is OPT-IN now: its supervisor halves re-stage only for projects
    carrying rs-fetch consumers. Dev AND rs-fetch boxes get the per-box
    ExtraHosts auto-heal (_restart_dev_boxes — a strict no-op on the stable
    path); unflagged boxes carry no gitea address at all. No-op if gitea was
    never stood up."""
    # Resume an ENABLED-but-stopped gitea (never creates), on the SHORT deadline:
    # this is the routine state after a `research stop`, not a cold boot.
    # `require=False` gates ONLY the absent branch — the start, the readiness
    # wait and the bootstrap heal can each still die(), which is why the catch
    # below is load-bearing and not belt-and-braces. Do not delete it on the
    # strength of `require=False`. `except SystemExit` specifically: die() raises
    # it, and `except Exception` would sail past while looking correct.
    # An interrupted (or damaged) upgrade record means the running container
    # may be an unverified release that Recover will remove: wiring projects to
    # it would rewrite their recorded addresses and restart dev boxes against
    # it. Recover wires everything itself once it has settled the record. The
    # record alone is checked — not the lock — because a restore runs this pass
    # while holding the lock itself.
    try:
        rec = _read_upgrade_record()
    except ValidationError:
        return
    if rec is not None and rec["phase"] != "committed":
        return
    serving = True
    try:
        _resume_gitea(require=False, tries=GITEA_RESUME_WAIT_TRIES)
    except SystemExit:
        serving = False
        # A resume that could not finish must NOT abandon the wiring pass. The
        # docker-level work below needs gitea RUNNING, not SERVING —
        # _connect_gitea_to_project_network is connect-only and returns "" for a
        # non-running gitea, which every caller tolerates. The one step that
        # needs a SERVING gitea, the live active-fork resolution inside
        # _stage_dev_gitea, already degrades to the recorded row. Unwinding here
        # would instead skip every network connect, every gitea_ip refresh and
        # every dev-box heal — precisely the work this pass exists to do, and
        # the reason a shorter deadline is safe rather than risky.
        # Deliberately NOT printed here: on the failed-`docker start` arm the
        # container is not running, nothing below will wire, and promising
        # "wiring from the recorded rows" would be a lie (run_check has already
        # printed the real error). The message belongs after the running gate.
        pass
    # Absent gitea -> the resume returned False without side effects and nothing
    # is running, so there is nothing to wire. The EARLY RETURN matters: falling
    # through would print a per-project reconnect warning on every
    # `research start` on any host that never enabled the dev lane.
    if not container_running(gitea.GITEA_CONTAINER):
        return
    if not serving:
        print(f"warning: {gitea.GITEA_CONTAINER} is running but not answering; "
              f"wiring from the recorded rows and skipping the live fork "
              f"resolution", file=sys.stderr)
    r = run(["docker", "network", "ls",
             "--filter", f"name=^{PROJECT_NETWORK_PREFIX}",
             "--format", "{{.Name}}"], capture_output=True)
    nets = [n for n in r.stdout.strip().splitlines() if n]
    if not nets:
        return
    cfg = load_config()
    for network in nets:
        project = network[len(PROJECT_NETWORK_PREFIX):]
        ip = _connect_gitea_to_project_network(network)
        if not ip:
            # A reconnect whose inspect came back empty must NOT overwrite the
            # recorded IP with "" (symmetry with dev_attach's empty-IP guard);
            # leave the prior record for S2 to re-read.
            print(f"warning: rs-gitea reconnect to {network} returned no IP; "
                  f"keeping the recorded gitea_ip", file=sys.stderr)
            continue
        # Refresh gitea_ip on every entry of this project (the IP can change
        # across a disconnect/reconnect).
        # record_attachment REPLACES on the key, so every field this loop does
        # not forward is BLANKED. `branch` needs the same preserve-guard `user`
        # already has: without it one `research start` wipes the operator's
        # chosen branch off every entry, and the next supervisor recreate stages
        # a branch-less row.
        for e in gitea.project_entries(project):
            gitea.record_attachment(project, e["class"], e.get("repo"), ip,
                                    box=e.get("box"), user=e.get("user") or "",
                                    branch=e.get("branch") or "")
        # Project-side wiring: the non-secret file + agent tokens ride the
        # record; the fetch surface is OPT-IN now (universal staging RETIRED) —
        # re-stage the supervisor halves only for a project carrying rs-fetch
        # consumers, BEFORE the box reconcile below (a re-run box copies them).
        _stage_dev_gitea(project, cfg, gitea_ip=ip, serving=serving)
        if _project_has_fetch_consumers(workspace_path_for(project, cfg)):
            _stage_dev_fetch(container_name_for(project))
            _stage_fetch_wiring(container_name_for(project), serving=serving)
        # F3 Slice 1: heal loopback forwarders on the universal `research start`
        # wiring pass (self-gates on docker; no-op for non-docker projects).
        _reconcile_loopback_bridges(project, cfg)
        # UNGATED (was `if gitea.project_entries(project):`): fetch boxes mint
        # no gitea consumer, so a ledger gate would skip exactly the projects
        # the fetch half of the reconcile targets. _restart_dev_boxes
        # self-gates (gitea_ip + container_running) and its entry filter skips
        # projects with neither dev nor fetch boxes — the stable no-op.
        _restart_dev_boxes(project, cfg, ip, progress)


def _stage_dev_git_credentials(container: str, user: str, *,
                               strict: bool = False) -> str:
    """Write a dev consumer's git credential store (~/.git-credentials) in a
    RUNNING container from the HOST token file — the push/pull half of the dev
    wiring, RE-DERIVED rather than stashed (B62): _stash_git_auth_for_rebuild
    deliberately does not carry the file, so every heal path that re-stages
    ~/.dev-tokens must re-derive it or the agent can commit but never push.
    Token discipline matches the ~/.dev-tokens staging: read from
    gitea.consumer_token_path (the host bridge), stream over stdin as the
    container's own user — never argv, never the workspace. Overwrite, not
    append (the box entrypoint's every-boot rewrite is the precedent; the
    file is agent-owned on any container that has an agent row).

    Two postures. strict=True (the create path): an empty/missing/unreadable
    token die()s and a failed write raises HarnessError with the token literal
    scrubbed — the missing/unreadable arms are a DELIBERATE die where a bare
    read formerly escaped as FileNotFoundError/PermissionError, which the
    broker's verb-exception contract does not catch. strict=False (the heal
    paths — recreate, attach, wire, docker-substrate start): warn-and-return,
    because those run under `research start`/`project start` and must never
    raise. Returns the staged token ("" when nothing was staged) so the create
    path can reuse the same literal for its scrub without a second, unguarded
    read."""
    tok_path = gitea.consumer_token_path(user)
    try:
        tok = tok_path.read_text().strip()
    except OSError:
        tok = ""
    if not tok:
        if strict:
            die(f"consumer token file for {user!r} is empty or missing; "
                f"re-run the attach")
        print(f"warning: consumer token missing at {tok_path}; skipped the "
              f"git credential store re-derivation (re-attach to heal)",
              file=sys.stderr)
        return ""
    r = run(["docker", "exec", "-i", "-u", "research", container, "sh", "-c",
             'umask 077 && cat > "$HOME/.git-credentials"'],
            input=f"http://{user}:{tok}@"
                  f"{gitea.GITEA_CONTAINER}:{gitea.GITEA_INNER_PORT}\n",
            capture_output=True)
    if r.returncode != 0:
        detail = (r.stderr or r.stdout or "").replace(tok, "***").strip()
        if strict:
            raise HarnessError("dev credentials staging failed", detail)
        print(f"warning: git credential store staging for {user!r} failed: "
              f"{detail}", file=sys.stderr)
        return ""
    return tok


def _stage_dev_gitea(project: str, cfg: "Config", gitea_ip: str = "",
                     *, serving: bool = True) -> None:
    """Stage a project's dev-lane wiring (STAGE_DEV_GITEA S2/S3), split by
    secrecy:

      * ``<ws>/.orchestrator/dev-gitea.json`` — NON-secret ``{gitea_ip, repos:
        [{repo, user, agent_user, branch, token_file}]}``, host-written into the
        bind-mounted workspace (atomic tmp+rename; the parent dir is the
        mount, no inode pin). The webui's RO /projects mount can read this
        file, so a token must NEVER enter it — the writer only handles
        ip/name fields by construction. Rows are REPO-level: ``user`` is the
        repo's ACTIVE fork owner (what rs-fetch reads), ``agent_user`` /
        ``branch`` / ``token_file`` are the PROJECT consumer's identity + base
        branch (empty when the project's own agent doesn't work the repo — box
        entries never mint those fields; rs-repo-watch filters to the
        agent_user-bearing row). Written for ANY wired project (``repos`` may be
        ``[]``): the ``gitea_ip`` is load-bearing for the universal box
        ``--add-host`` injection, not just for dev boxes.
      * every project CONSUMER's token (the project's own + each dev box's),
        streamed into the RUNNING supervisor's own fs at
        ``~/.dev-tokens/<user>.token`` (0600) via ``docker exec -i … cat`` —
        stdin as the container's own user (docker cp would land a foreign-uid
        file under sysbox), never argv, never the workspace. Staging ALL
        consumers here means a supervisor recreate re-heals box tokens for
        free.

    IP source, in order: the ``gitea_ip`` param (call sites that JUST connected
    thread it), an agent-class record entry, a live inspect of rs-gitea on the
    project network. No resolvable IP (gitea genuinely unattached) ⇒ the file
    write is SKIPPED — never write an empty ``gitea_ip``.
    Silently skips the token half when the supervisor isn't running: the
    project-start path re-runs this from _recreate_supervisor, and dev_attach
    requires a running project up-front."""
    ws = workspace_path_for(project, cfg)
    if not ws.is_dir():
        return
    entries = [e for e in gitea.project_entries(project)
               if e.get("class") == "agent" and e.get("repo")]
    # Gitea-history rows: their tokens are staged below like the dev ones, but
    # they never become dev-gitea.json rows (those are the dev boxes' wiring).
    hist_entries = [e for e in gitea.project_entries(project)
                    if e.get("class") == gitea.HISTORY_CLASS and e.get("user")]
    ip = gitea_ip or next((e["gitea_ip"] for e in entries + hist_entries
                           if e.get("gitea_ip")), "")
    if not ip and container_exists(gitea.GITEA_CONTAINER):
        network = project_network_for(project)
        if network_exists(network):
            r = run(["docker", "inspect", gitea.GITEA_CONTAINER, "-f",
                     '{{(index .NetworkSettings.Networks "' + network
                     + '").IPAddress}}'],
                    capture_output=True)
            ip = r.stdout.strip() if r.returncode == 0 else ""
            if "<no value>" in ip:
                ip = ""
    if ip:
        rows = []
        for repo in sorted({e["repo"] for e in entries}):
            repo_entries = [e for e in entries if e["repo"] == repo]
            proj_user = next((e.get("user") for e in repo_entries
                              if e.get("box") is None and e.get("user")), "")
            # Active fork for the row's `user`: the explicit map first (a host
            # file — no API), a live-gitea resolution when possible, then the
            # project consumer / any box consumer (a stopped gitea at recreate
            # time must not blank the row).
            active = gitea.load_active_forks().get(repo, "")
            # `serving` is the caller's ANSWER to "is gitea actually answering",
            # which container_running cannot give: a resumed-but-not-yet-serving
            # gitea is running, so without this the call below is attempted and
            # burns gitea.API_TIMEOUT_S per repo per project against a listener
            # that is up but still migrating. Defaults True — every caller other
            # than `research start`'s wiring pass has already waited for gitea.
            if not active and serving and container_running(gitea.GITEA_CONTAINER):
                try:
                    active = gitea.active_fork_for(_gitea_host_port(), repo)
                except gitea.GiteaError:
                    active = ""
            if not active:
                active = proj_user or next((e.get("user") for e in repo_entries
                                            if e.get("user")), "")
            # The PROJECT consumer's base branch, derived exactly like proj_user
            # above (box entries are OTHER containers' wiring). rs-repo-watch
            # reads it off the agent_user-bearing row and exports GITEA_BRANCH.
            proj_branch = next((e.get("branch") for e in repo_entries
                                if e.get("box") is None and e.get("branch")), "")
            rows.append({"repo": repo, "user": active,
                         "agent_user": proj_user,
                         "branch": proj_branch,
                         "token_file": f"{proj_user}.token" if proj_user else ""})
        payload = {"gitea_ip": ip, "repos": rows}
        try:
            orch_files.write_text(ws, "dev-gitea.json",
                                  json.dumps(payload, indent=2, sort_keys=True) + "\n",
                                  create=True)
        except orch_files.Unusable as e:
            # Every caller is mid-operation; the wiring file is not written
            # through a link, and the rest of the staging goes on.
            print(f"warning: the dev wiring of project {project!r} was not "
                  f"written: {e}", file=sys.stderr)
        else:
            _rerun_inner_guard(project)
    container = container_name_for(project)
    if not (entries or hist_entries) or not container_running(container):
        return
    for user in sorted({e["user"] for e in entries + hist_entries
                        if e.get("user")}):
        tok_path = gitea.consumer_token_path(user)
        try:
            tok = tok_path.read_text().strip()
        except OSError:
            tok = ""
        if not tok:
            print(f"warning: consumer token missing at {tok_path}; skipped its "
                  f"in-supervisor staging (re-attach or re-add the box)",
                  file=sys.stderr)
            continue
        # Positional-arg sh so the (validated-name-derived) file name never
        # rides string interpolation, and the token rides ONLY stdin.
        r = run(["docker", "exec", "-i", "-u", "research", container, "sh", "-c",
                 'umask 077 && mkdir -p "$HOME/.dev-tokens" && cat > "$HOME/.dev-tokens/$1"',
                 "sh", f"{user}.token"],
                input=tok + "\n", capture_output=True)
        if r.returncode != 0:
            print(f"warning: token staging for consumer {user!r} failed: "
                  f"{(r.stderr or r.stdout).strip()}", file=sys.stderr)
    # The push/pull half (B62): the PROJECT consumer's ~/.git-credentials is
    # container-fs state a recreate wipes, so re-derive it wherever the tokens
    # re-stage. Box-None agent rows all carry the one project consumer, so
    # this is a single write; a project that only HOSTS dev boxes has no such
    # row and its supervisor stays credential-free (a human's own store there
    # is never touched — the write fires only on an agent's own container).
    proj_user = next((e.get("user") for e in entries
                      if e.get("box") is None and e.get("user")), "")
    if proj_user:
        _stage_dev_git_credentials(container, proj_user)


def _rerun_inner_guard(project: str) -> None:
    """Re-apply the inner-bridge guard inside a RUNNING dind project after the
    dev wiring was staged: the guard's gitea exception is read from that file,
    which is absent at a project's first boot and appears only when the host
    wires gitea in. Skipped for the `docker` substrate (no inner bridge, no
    guard; this staging site is reached from its start path too) and for a
    stopped container (its next boot runs the guard itself). A failure warns
    and continues — the guard's own posture; a container from before the
    guard existed warns here on every start until `project update` copies the
    script in."""
    container = container_name_for(project)
    if not container_running(container):
        return
    if _container_substrate(container) == Substrate.DOCKER.value:
        return
    r = run(["docker", "exec", container, INNER_GUARD_BIN], capture_output=True)
    if r.returncode != 0:
        print(f"warning: inner guard re-run in {container} failed: "
              f"{(r.stderr or r.stdout).strip()}", file=sys.stderr)


def _stage_dev_fetch(container: str) -> None:
    """Stage the OPT-IN fetch surface into a RUNNING rs-fetch-enabled project
    container: the rs-fetch tool at /usr/local/bin/rs-fetch (root-owned 0755 —
    the _stage_rs_sandbox single-file stdin idiom) + the READ-ONLY gitea
    operator token at ~/.dev-tokens/operator.token (0600, the agent-token
    stdin pattern — never argv, never the workspace). Called only for fetch
    consumers now (the universal every-container staging is RETIRED): the
    crown jewels (the human's push credential, review verdicts) never ride
    this surface, and unflagged containers get NOTHING. SILENT skip when the
    operator token doesn't exist (dev lane never bootstrapped) or the
    container isn't running — callers gate on the explicit ask, and the
    bootstrap floor already refused the never-enabled case on those paths. A
    staging failure WARNS and continues: the container is fine without
    fetch."""
    try:
        tok = gitea.OPERATOR_TOKEN_PATH.read_text().strip()
    except OSError:
        return
    if not tok or not container_running(container):
        return
    src = Path(__file__).resolve().parent / "rs_fetch.py"
    if not src.is_file():
        print(f"warning: rs_fetch.py not found at {src}; fetch tool not "
              f"staged into {container}", file=sys.stderr)
        return
    install = "cat > /usr/local/bin/rs-fetch && chmod 755 /usr/local/bin/rs-fetch"
    proc = subprocess.Popen(
        ["docker", "exec", "-i", "-u", "0", container, "sh", "-c", install],
        stdin=subprocess.PIPE, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
    _, err = proc.communicate(input=src.read_bytes())
    if proc.returncode != 0:
        detail = (err.decode(errors="replace") if err else "").strip()
        print(f"warning: staging rs-fetch into {container} failed: "
              f"{detail or 'cat returned non-zero'}", file=sys.stderr)
    r = run(["docker", "exec", "-i", "-u", "research", container, "sh", "-c",
             'umask 077 && mkdir -p "$HOME/.dev-tokens" && '
             'cat > "$HOME/.dev-tokens/operator.token"'],
            input=tok + "\n", capture_output=True)
    if r.returncode != 0:
        print(f"warning: operator-token staging into {container} failed: "
              f"{(r.stderr or r.stdout).strip()}", file=sys.stderr)


def _stage_fetch_wiring(container: str, *, serving: bool = True) -> None:
    """Stage the GLOBAL fetch wiring into a RUNNING rs-fetch-enabled container:
    every mirrored dev repo -> its ACTIVE consumer fork owner, written to
    ~/.dev-tokens/fetch-wiring.json (rs_fetch.BOX_WIRING_JSON — a mirror-pair
    path lockstep; the staged rs-fetch cannot import this module). NON-SECRET
    by construction: the writer only emits repo/owner NAME fields. Cross-
    project on purpose (fork F3): a project's own dev-gitea.json rows cover
    only that project's consumers, while a fetch surface may pull any dev-lane
    repo — the read-only operator token already reads every consumer fork, so
    the row list adds reach, never privilege. Owner resolution mirrors
    _stage_dev_gitea's: the explicit active-fork map, then a live-gitea
    resolution (guarded on a RUNNING gitea), then any ledger consumer;
    unresolvable repos are SKIPPED (a fork-less mirror is not fetchable —
    never die). Staleness (a later active-fork change / new repo) heals at
    box/project restart — the re-run re-copies (the ExtraHosts-heal posture,
    fork F5). Best-effort: a failure warns and leaves the container usable
    without fetch."""
    try:
        mirrors = sorted(p.name for p in gitea.MIRRORS_DIR.iterdir()
                         if p.is_file())
    except OSError:
        mirrors = []
    active_map = gitea.load_active_forks()
    ledger = gitea.load_attachments()
    rows = []
    for repo in mirrors:
        owner = active_map.get(repo, "")
        # Same bound as _stage_dev_gitea's: skip the live resolution outright
        # when the caller already knows gitea is not answering, and fall through
        # to the ledger owner below (a repo with no owner anywhere is omitted
        # from `rows`, exactly as for a stopped gitea).
        if not owner and serving and container_running(gitea.GITEA_CONTAINER):
            try:
                owner = gitea.active_fork_for(_gitea_host_port(), repo)
            except gitea.GiteaError:
                owner = ""
        if not owner:
            owner = next((e.get("user") for e in ledger
                          if e.get("repo") == repo and e.get("user")
                          and e.get("class") != gitea.HISTORY_CLASS), "")
        if owner:
            rows.append({"repo": repo, "user": owner})
    if not container_running(container):
        return
    payload = json.dumps({"repos": rows}, indent=2, sort_keys=True) + "\n"
    r = run(["docker", "exec", "-i", "-u", "research", container, "sh", "-c",
             'umask 077 && mkdir -p "$HOME/.dev-tokens" && '
             'cat > "$HOME/.dev-tokens/fetch-wiring.json"'],
            input=payload, capture_output=True)
    if r.returncode != 0:
        print(f"warning: fetch-wiring staging into {container} failed: "
              f"{(r.stderr or r.stdout).strip()}", file=sys.stderr)


# --- F3 loopback->bridge forwarder (Slice 1, docker substrate) --------------
# A 127.0.0.1-bound in-box service is unreachable from outside the container's
# netns (that invisibility is the boundary). For an operator-registered exported
# port we stand up a tiny in-box forwarder (cli/rs_loopback_fwd.py) that binds the
# box's bridge IP at the SAME port and relays to 127.0.0.1:<port>, so the webui
# reaches it at rs-project-<name>:<port> with no resolver change. Docker substrate
# only (the box container IS rs-project-<name>); dind inner boxes are Slice 2. The
# forwarder + its pidfiles live at these fixed in-box paths and the host reconcile
# is the ONLY thing that launches/reaps them.
_LOOPBACK_FWD_BIN = "/usr/local/bin/rs-loopback-fwd"
_LOOPBACK_PIDFILE_DIR = "/tmp/rs-loopback-fwd"
# Reap bound for a killed forwarder GROUP (one process may serve several ports):
# SIGTERM ends the handler-less asyncio process in milliseconds, so the poll
# normally passes on its first iteration; the 5s bound caps a pathologically
# wedged process to one tolerable port_remove latency (the reconcile runs on the
# broker's serial thread — at 10x this would push a single remove past the
# webui's 30s relay window), after which SIGKILL guarantees the listeners are
# gone before survivors relaunch. At half (2.5s) the normal case is unchanged.
_LOOPBACK_REAP_WAIT_S = 5.0
_LOOPBACK_REAP_POLL_S = 0.1


def _stage_loopback_fwd(container: str) -> None:
    """Stage the F3 loopback forwarder into a RUNNING container at
    /usr/local/bin/rs-loopback-fwd (root-owned 0755 — the _stage_dev_fetch
    single-file stdin idiom, never docker cp). Idempotent (overwrites);
    best-effort — a staging failure warns and continues (the box is fine without
    it). Callers gate on docker substrate + container_running (see
    _reconcile_loopback_bridges)."""
    src = Path(__file__).resolve().parent / "rs_loopback_fwd.py"
    if not src.is_file():
        print(f"warning: rs_loopback_fwd.py not found at {src}; loopback forwarder "
              f"not staged into {container}", file=sys.stderr)
        return
    install = ("cat > /usr/local/bin/rs-loopback-fwd && "
               "chmod 755 /usr/local/bin/rs-loopback-fwd")
    proc = subprocess.Popen(
        ["docker", "exec", "-i", "-u", "0", container, "sh", "-c", install],
        stdin=subprocess.PIPE, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
    _, err = proc.communicate(input=src.read_bytes())
    if proc.returncode != 0:
        detail = (err.decode(errors="replace") if err else "").strip()
        print(f"warning: staging rs-loopback-fwd into {container} failed: "
              f"{detail or 'cat returned non-zero'}", file=sys.stderr)


def _reconcile_loopback_bridges(project: str, cfg: "Config") -> None:  # type: ignore[name-defined]
    """Make the running set of in-box loopback forwarders match a project's
    exported-port registry, for the TOP-LEVEL `rs-project-<name>` container of
    ANY substrate — a docker box (F3 Slice 1) OR a research/sandbox-dind
    supervisor (Slice 2a, Fork-B). The forwarder binds that container's own bridge
    IP at each registered port and relays to 127.0.0.1, so a loopback app is
    reachable at rs-project-<name>:<port>. Inner boxes (rs-box-<name>) are NOT
    reached here — they live one netns down and are published/forwarded by
    rs-sandbox (Slice 2b); this only ever exec's the top-level container.
    Host-orchestrated: the launches are host `docker exec -d` (the container has
    no docker CLI reachable this way), only liveness + teardown run as in-box
    `sh`. Best-effort throughout — the registry write is the source of truth and
    the forwarders reconcile toward it; a hiccup warns and continues. Called live
    from port_add/port_remove and after each container-swap re-stage site (docker
    start/recreate + the sysbox supervisor recreate).

    GROUP semantics (STAGE_PASSTHROUGH_PORTS): all non-live desired ports launch
    as ONE forwarder process (a 66-wide span as 66 python processes would cost
    ~0.5-1 GB RSS), one pidfile per port all holding that pid. Removing one port
    therefore kills its whole group — BY CONSTRUCTION, not timing: the teardown
    reaps the killed pid (bounded wait, then SIGKILL) and unlinks every sibling
    pidfile holding it, so the survivors read dead in THIS call's liveness pass
    and relaunch together as one new group before this function returns."""
    container = container_name_for(project)
    if not container_running(container):
        return
    # Only the TOP-LEVEL entries (no `box` field) are ours — an inner-box entry
    # (F3 Slice 2b) is published + forwarded by rs-sandbox inside the box; binding
    # its pub_super on the supervisor's eth0 here would double-bind against the -p
    # publish (N2). A pass-through claim expands to its whole project-side span —
    # the forwarder bridges every port the webui relay dials. The registry is
    # container-writable, so the spans are MERGED as intervals before anything
    # is expanded: many overlapping rows cost one sort, never rows x count, and
    # each port is produced once. A claim's span is bounded to 1-65535 by
    # read_exported_ports, so the merged expansion is too. Same result as the
    # sorted set of every row's ports.
    intervals: list[tuple[int, int]] = []
    for e in read_exported_ports(workspace_path_for(project, cfg)):
        if e.get("box"):
            continue
        span = int(e.get("count", 1)) if e.get("passthrough") else 1
        first = int(e["port"])
        intervals.append((first, first + span - 1))
    intervals.sort()
    desired: list[int] = []
    cur_lo = cur_hi = None
    for lo, hi in intervals:
        if cur_hi is not None and lo <= cur_hi + 1:
            cur_hi = max(cur_hi, hi)
            continue
        if cur_hi is not None:
            desired.extend(range(cur_lo, cur_hi + 1))
        cur_lo, cur_hi = lo, hi
    if cur_hi is not None:
        desired.extend(range(cur_lo, cur_hi + 1))
    # Teardown ALWAYS runs first (even when desired is empty) so a removed port's
    # forwarder is reaped. The kill is GUARDED by a /proc/<pid>/cmdline content
    # check — identical to the liveness probe (F1): a bare `kill $(cat pidfile)`
    # would SIGTERM a recycled PID after a restart (/tmp is not tmpfs, so pidfiles
    # persist). The pidfile is removed unconditionally (a stale file must always
    # clear; only the kill is guarded). glob-no-match + empty pidfile are guarded
    # (F2); the bin path + port token are NUL-exact matched via `grep -z` so 80
    # never matches 808 (F3). After a kill: bounded reap (poll /proc, then
    # SIGKILL, then poll again) + unlink of EVERY sibling pidfile holding that
    # pid — a group process serves several ports, and without the reap+unlink a
    # survivor's liveness probe could still read the dying pid as live and skip
    # its own relaunch (silent unbridged port). The mid-loop sibling unlink is
    # safe ONLY because the glob expanded once and `[ -e "$f" ] || continue`
    # skips already-unlinked siblings on their own iteration — that guard is
    # load-bearing here, not just for the no-match glob.
    keep = (" " + " ".join(str(p) for p in desired) + " ") if desired else "  "
    reap_iters = int(_LOOPBACK_REAP_WAIT_S / _LOOPBACK_REAP_POLL_S)
    teardown = f'''set -u
DIR={_LOOPBACK_PIDFILE_DIR}
KEEP="{keep}"
for f in "$DIR"/*.pid; do
  [ -e "$f" ] || continue
  port=$(basename "$f" .pid)
  case "$KEEP" in *" $port "*) continue ;; esac
  pid=$(cat "$f" 2>/dev/null)
  if [ -n "$pid" ] && [ -r "/proc/$pid/cmdline" ] \
     && grep -zFxq "{_LOOPBACK_FWD_BIN}" "/proc/$pid/cmdline" \
     && grep -zFxq "$port" "/proc/$pid/cmdline"; then
    kill "$pid" 2>/dev/null || true
    i=0
    while [ -d "/proc/$pid" ] && [ "$i" -lt {reap_iters} ]; do
      sleep {_LOOPBACK_REAP_POLL_S}; i=$((i+1))
    done
    if [ -d "/proc/$pid" ]; then
      kill -9 "$pid" 2>/dev/null || true
      i=0
      while [ -d "/proc/$pid" ] && [ "$i" -lt {reap_iters} ]; do
        sleep {_LOOPBACK_REAP_POLL_S}; i=$((i+1))
      done
    fi
    grep -lFx "$pid" "$DIR"/*.pid 2>/dev/null | xargs -r rm -f --
  fi
  rm -f "$f"
done'''
    r = run(["docker", "exec", "-u", "0", container, "sh", "-c", teardown],
            capture_output=True)
    if r.returncode != 0:
        print(f"warning: loopback-bridge teardown in {container} failed: "
              f"{(r.stderr or r.stdout).strip()}", file=sys.stderr)
    if not desired:
        return
    _stage_loopback_fwd(container)
    to_launch: list[int] = []
    for port in desired:
        # Liveness: is a genuine rs-loopback-fwd for THIS exact port already
        # running? Content-check /proc/<pid>/cmdline (NOT kill -0, which mis-reads
        # a recycled PID after a restart). glob/empty guarded; bin path + port
        # NUL-exact matched.
        probe = f'''set -u
f={_LOOPBACK_PIDFILE_DIR}/{port}.pid
[ -e "$f" ] || exit 1
pid=$(cat "$f" 2>/dev/null)
[ -n "$pid" ] || exit 1
[ -r "/proc/$pid/cmdline" ] || exit 1
grep -zFxq "{_LOOPBACK_FWD_BIN}" "/proc/$pid/cmdline" || exit 1
grep -zFxq "{port}" "/proc/$pid/cmdline" || exit 1
exit 0'''
        live = run(["docker", "exec", "-u", "0", container, "sh", "-c", probe],
                   capture_output=True)
        if live.returncode == 0:
            continue
        to_launch.append(port)
    if not to_launch:
        return
    # Launch ALL non-live ports as ONE detached root group process (binds any
    # validated port >= 1; writes a pidfile per port it actually binds, skips a
    # port already held by a 0.0.0.0 app). Argv shape is load-bearing:
    # [..., _LOOPBACK_FWD_BIN, p1, p2, ...] with nothing between the bin and the
    # port tokens — the teardown/liveness greps match tokens NUL-exactly, and
    # archived pins assert the single-port tail.
    launched = run(["docker", "exec", "-d", "-u", "0", container,
                    _LOOPBACK_FWD_BIN, *(str(p) for p in to_launch)],
                   capture_output=True)
    if launched.returncode != 0:
        print(f"warning: launching loopback forwarder for port(s) "
              f"{', '.join(str(p) for p in to_launch)} in {container} failed: "
              f"{(launched.stderr or launched.stdout).strip()}",
              file=sys.stderr)


def _restart_dev_boxes(project: str, cfg: "Config", gitea_ip: str,
                       progress=None) -> None:
    """F1 auto-heal (STAGE_DEV_GITEA S2): re-run any RUNNING dev OR
    rs-fetch-enabled box whose baked /etc/hosts entry does not match the
    CURRENTLY staged gitea address (both kinds bake the same rs-gitea
    --add-host at docker run; a fetch box's re-run also re-copies the fetch
    halves via _stage_box_fetch).
    The change check is against the box container's ACTUAL ExtraHosts —
    --add-host is fixed at docker run, and only a re-run (rs-sandbox restart →
    _rerun_box → rm+run, re-reading the fresh staging) refreshes it — NOT
    against record history: the primary address-changing flow (detach →
    re-attach) deletes the record in between, so a prior-record comparison can
    never fire there (the acceptance harness caught exactly that). A matching
    box is skipped — the stable-path no-op; a deliberately-parked (stopped)
    box is left parked — rs-sandbox's own start path reconciles it. Dev boxes
    are enumerated HOST-side from the bind-mounted extensions.json. Best-
    effort: a failure warns and leaves the box to a manual
    `rs-sandbox restart <name>`. A box that reports RS's old instructions file
    is a warning on stderr and on `progress` when given (the browser's Gitea
    Recover follows only progress steps): every caller is an operation about
    something else, so it never fails."""
    container = container_name_for(project)
    if not gitea_ip or not container_running(container):
        return
    ws = workspace_path_for(project, cfg)
    for name, e in sorted(extension.load(ws).items()):
        # Gitea-history boxes: the address is rewritten IN PLACE (no re-run —
        # OpenKnowledge and the agent keep running), unconditionally on every
        # pass (idempotent; a box keeps no host-visible address to compare).
        if (isinstance(e, dict) and e.get("kind") == extension.SANDBOX_KIND
                and isinstance(e.get("history"), dict) and not e.get("dev")):
            r = run(["docker", "exec", container, "rs-sandbox", "history-heal",
                     name], capture_output=True)
            if r.returncode != 0:
                print(f"warning: history box {name!r} could not take the new "
                      f"Gitea address: {(r.stderr or r.stdout).strip()}",
                      file=sys.stderr)
            continue
        if not (isinstance(e, dict) and e.get("kind") == extension.SANDBOX_KIND
                and (e.get("dev") or e.get("fetch"))):
            continue
        cname = e.get("container") or f"rs-box-{name}"
        ins = run(["docker", "exec", container, "docker", "inspect", "-f",
                   "{{.State.Running}} {{json .HostConfig.ExtraHosts}}", cname],
                  capture_output=True)
        state = ins.stdout.strip() if ins.returncode == 0 else ""
        if not state.startswith("true"):
            continue                    # absent or parked — not ours to start
        # Match the QUOTED JSON form: a bare substring would false-match a
        # prefix ip ("…:172.20.0.9" is a substring of "…:172.20.0.90") and
        # skip a genuinely stale box.
        if f'"rs-gitea:{gitea_ip}"' in state:
            continue                    # already current — the stable no-op
        r = run(["docker", "exec", container, "rs-sandbox", "restart", name],
                capture_output=True)
        if r.returncode != 0:
            print(f"warning: dev/fetch box {name!r} re-run after the gitea "
                  f"address change failed: {(r.stderr or r.stdout).strip()}",
                  file=sys.stderr)
        else:
            print(f"dev/fetch box {name!r} re-run against the new gitea address")
            # A fetch box may carry read-only folders: report any it lacks.
            _report_box_restart_warnings(name, r.stdout, progress)
            # A side effect of a shared dev-lane operation: RS's old files in
            # the box's folder are a WARNING here, never this operation's
            # failure; the project's next start fails with the error.
            for item in _box_old_items(project, name,
                                       _parse_box_tool_json(r.stdout).get("warnings")):
                if item.kind == "box":
                    _report_warnings([OLD_INSTRUCTIONS_BOX_SIDE_WARNING.format(
                        box=_shown_box(name), project=project)], progress)
                else:
                    _report_warnings([OLD_FILES_BOX_SIDE_WARNING.format(
                        box=_shown_box(name), project=project,
                        paths=_shown_old_paths(name, item.paths))], progress)


def _resolve_dev_branch(repo: str, branch: str) -> str:
    """Resolve a dev container's base branch to a CONCRETE name, pre-side-effect.

    ONE home for the resolution and all four refusals — box_add and create both
    call this and must refuse identically; a second copy is where they drift.
    Returns the caller's branch (validated to exist) or the mirror's default.

    Every arm raises ValidationError, so the browser gets a clean envelope and
    the CLI a clean die. GiteaError text is safe to surface: it carries only
    method/path/status, never a body. No message names a CLI verb."""
    # The reads below need gitea RUNNING. Enabled-but-stopped is a routine state
    # (any host reboot leaves it there), and the pure-file mirror_present stamp
    # the callers check beside this is NOT a liveness signal. Idempotent with
    # the callers' own later resume.
    _resume_gitea(require=True)
    hp = _gitea_host_port()
    try:
        state = gitea.mirror_state(hp, repo)
    except gitea.GiteaError as e:
        raise ValidationError(f"could not read {repo!r} from Gitea: {e}")
    # ORDER IS LOAD-BEARING: an empty repo has no branches at all and 404s the
    # branch route, so checking it AFTER the branch query would report "no such
    # branch" for a repo whose real problem is that it has no commits.
    if state["empty"]:
        raise ValidationError(
            f"repo {repo!r} has no commits yet — push an initial commit to "
            f"GitHub and retry (a dev container starts from a branch of your "
            f"existing work)")
    if branch:
        try:
            found = gitea.mirror_has_branch(hp, repo, branch)
        except gitea.GiteaError as e:
            raise ValidationError(
                f"could not verify branch {branch!r} against Gitea: {e}")
        if not found:
            raise ValidationError(
                f"branch {branch!r} does not exist in {repo!r}")
        return branch
    default = state["default_branch"]
    if not default:
        raise ValidationError(
            f"could not determine the default branch of {repo!r}; name a "
            f"branch explicitly")
    return default


def _refuse_retired_identity(user: str) -> None:
    """Refuse to re-provision a consumer identity that survived a retirement.

    Shared by ALL THREE provision_consumer callers (create, box_add,
    dev_attach) so the refusal reads the same everywhere and no path is left
    surfacing gitea's raw text. Call it BEFORE the caller's first side effect —
    it raises ValidationError, whose whole value here is that nothing has been
    built yet.

    The message is BROWSER-REACHABLE (ValidationError text reaches the op tail
    verbatim), so: no CLI verb anywhere in it. It classifies the identity by
    what it OWNS (user_repos — the same strict read the purge gate uses),
    because the Development page lists a retired identity ONLY through an
    archived fork it owns. Four states, four remedies, none of them a lie:
      * archived fork(s) only — the page shows a Purge row under each of those
        repos: point at them by name.
      * a LIVE fork — the create-crashed-after-fork orphan (B52): no row (the
        page lists archived forks only) and the purge verb refuses a live
        fork, so the honest route is archive-in-the-Gitea-tab, THEN the page.
      * nothing at all — the create-crashed-before-fork orphan (B52): no row
        anywhere; the browser route is Site Administration in the Gitea tab.
      * a copy of a history box's notes — the account of an earlier box that
        kept history on Gitea (same `agent-<project>.<box>` name), whose
        deletion Gitea refused after the box user had forked its own notes
        repo (forks bypass its repo-creation cap). The page lists consumer
        forks per MIRROR, and a fork of `notes/...` has no mirror, so no row
        ever appears; Gitea refuses a plain delete of a user that still owns
        a repo, so the remedy is Site Administration with the purge option
        (or delete the copy first, then the user). Any notes copy wins over a
        mixed set: the purge verb refuses a live fork, and Site Administration
        is the one route that works for every mix.
    A classification failure falls back to the generic text: the refusal is
    still correct, only the pointer degrades. 'A different name' is an equal
    remedy in every arm, never a fallback, and no arm implies purging is
    immediate for a STILL-ATTACHED project (there the sequence is detach,
    purge, attach, and the purge verb's ledger gate refuses until then).

    A FOURTH state hides behind the first two reads: Gitea resolves a user
    name ignoring letter case, so for project `foo` the existence probe and
    the ownership read both answer for an account stored as `agent-Foo` —
    while the token-file probe is exact-case and finds nothing. The stored
    spelling (gitea.stored_login, read only in the retired arm) tells the
    variant apart. A variant claimed by a ledger row or holding its token file
    is ANOTHER live project or box: the refusal says the name is in use and
    offers only a different name — never archive or purge, which would
    destroy that project's live work. A variant with neither is genuinely
    retired: the four arms above apply to it, under its stored name."""
    host_port = _gitea_host_port()
    try:
        retired = gitea.retired_identity(host_port, user)
    except gitea.GiteaError as e:
        # Could not VERIFY — never silently proceed into the opaque mint
        # failure this exists to replace.
        raise ValidationError(
            f"could not check the dev identity {user!r} against Gitea: {e}")
    if not retired:
        return
    try:
        login = gitea.stored_login(host_port, user)
    except gitea.GiteaError as e:
        raise ValidationError(
            f"could not check the dev identity {user!r} against Gitea: {e}")
    if login is None:
        login = user                 # deleted between the two reads
    if login == user:
        head = (f"the dev identity {user!r} still exists in Gitea from an "
                f"earlier project or box of this name, and its access token "
                f"cannot be reissued. ")
    else:
        lowered = login.lower()
        claimed = any(str(e.get("user") or "").lower() == lowered
                      for e in gitea.load_attachments())
        if claimed or gitea.consumer_token_path(login).is_file():
            raise ValidationError(
                f"the Gitea account {login!r} is in use by another project or "
                f"box, and it also answers for {user!r} (Gitea ignores letter "
                f"case, so a project whose name differs only in case counts); "
                f"use a different name")
        head = (f"the retired dev identity {login!r} still exists in Gitea "
                f"from an earlier project or box, and it blocks {user!r} "
                f"because Gitea ignores letter case. ")
    try:
        owned = gitea.user_repos(host_port, login, detail=True)
    except gitea.GiteaError:
        owned = None
    if owned is None:
        raise ValidationError(
            head + "Purge that retired identity from the Development page (it "
            "is listed under its repo while it still has a fork), or use a "
            "different name")
    # A fork whose parent is in the history ORG (`notes/`, with the slash: a
    # project's history user is `notes-<project>`, a different owner).
    notes_prefix = gitea.HISTORY_ORG + "/"
    notes = sorted(r["parent"] for r in owned
                   if r.get("fork") and str(r.get("parent") or "").lower()
                   .startswith(notes_prefix))
    if notes:
        raise ValidationError(
            head + f"It is the account of an earlier box that kept history on "
            f"Gitea, and it holds a copy of that box's notes "
            f"({', '.join(notes)}), so it is not shown on the Development page. "
            f"Gitea refuses to delete a user that still owns a repository: "
            f"delete the user under Site Administration in the Gitea tab with "
            f"its purge option ticked (that removes its copy too; the notes "
            f"repo itself is not affected), or delete its copy first and then "
            f"the user; or use a different name")
    # A malformed row carries an empty name (user_repos emits `name or ""`);
    # never print "listed under , X".
    live = sorted(r["repo"] for r in owned
                  if r.get("repo") and not r.get("archived"))
    archived = sorted(r["repo"] for r in owned
                      if r.get("repo") and r.get("archived"))
    if live:
        raise ValidationError(
            head + f"It still holds a live fork of {', '.join(live)} — archive "
            f"that fork in the Gitea tab (if no project is still working it), "
            f"then purge the identity from the Development page, where it "
            f"appears once archived; or use a different name")
    if archived:
        raise ValidationError(
            head + f"Purge that retired identity from the Development page — "
            f"it is listed under {', '.join(archived)} — or use a different "
            f"name")
    raise ValidationError(
        head + "It holds no fork, so it is not shown on the Development page; "
        "delete the user under Site Administration in the Gitea tab, or use a "
        "different name")


def _run_dev_clone(container: str, repo: str, user: str, branch: str,
                   progress) -> str:
    """Clone the agent fork into the supervisor workspace (the dev workflow's
    create-time step, STAGE_DEV_GITEA S2): credential-helper store +
    clone-if-absent + the agent's repo-local git identity + the read-only
    mirror as ``upstream`` — the same contract as the box entrypoint's dev
    block, executed host-side as the unprivileged research user.
    Deliberately NOT _run_light_harness (that path is https://-only +
    GitHub-PAT-shaped). Secret discipline: the credentials line
    reaches the container via STDIN (never exec argv); the clone script itself
    carries NO token (the helper file supplies auth); failures raise
    HarnessError with the token literal scrubbed (via _light_exec).
    ``branch`` is the CONCRETE name the host already resolved
    (_resolve_dev_branch) — never empty. Returns the clone dir."""
    base = f"http://{gitea.GITEA_CONTAINER}:{gitea.GITEA_INNER_PORT}"
    progress.step("dev-clone", "cloning the dev fork")
    token = _stage_dev_git_credentials(container, user, strict=True)
    workdir = f"/workspace/{repo}"
    q = shlex.quote
    script = (
        "git config --global credential.helper store && "
        # The clone carries TWO remotes (origin=fork, upstream=mirror) holding
        # the same branch names, which makes `git checkout <branch>` ambiguous
        # for every branch but the cloned one ("matched multiple (2) remote
        # tracking branches"). defaultRemote restores the DWIM against the
        # fork. --global is correct, not sloppy: one repo per container is a
        # structural invariant, so there is nothing else here to affect.
        "git config --global checkout.defaultRemote origin && "
        f"if [ ! -d {q(workdir)}/.git ]; then rm -rf {q(workdir)} && "
        f"git clone --branch {q(branch)} "
        f"{q(base + '/' + user + '/' + repo + '.git')} {q(workdir)}; fi && "
        f"cd {q(workdir)} && "
        # The agent's git identity, pinned repo-LOCAL (B36): the consumer's
        # gitea account name + that account's email (gitea.consumer_email —
        # the address create_user minted, so the fork's commits resolve to the
        # account that owns the fork). LOCAL, not --global, because it scopes
        # the identity to the fork clone and its worktrees (linked worktrees
        # share this .git/config) and nothing else in the container; it cannot
        # collide with an operator identity _stage_git_auth may have written
        # globally (that runs before this clone); and it lives on the workspace
        # bind mount, so no heal path has to re-derive it. Survival is NOT the
        # reason — a global identity would also ride the creds stash across a
        # recreate (~/.gitconfig is stashed + restored). Idempotent: a re-run
        # writes the same values.
        f"git config user.name {q(user)} && "
        f"git config user.email {q(gitea.consumer_email(user))} && "
        "(git remote get-url upstream >/dev/null 2>&1 || "
        f"git remote add upstream {q(base + '/' + gitea.ADMIN_USER + '/' + repo + '.git')}) && "
        "git fetch upstream --quiet"
    )
    # _light_exec's scrub parameter is generic "replace this literal" — here the
    # literal is the gitea agent token, not a GitHub PAT.
    _light_exec(container, script, step="dev fork clone", github_pat=token)
    # The dev instructions are RS's home-folder file now
    # (_write_project_instructions); nothing is written into the workspace.
    return workdir


# The two blank-box images, in build order (browser FROMs the plain box). Each:
# (host image base, registry repo, the :latest tag the in-supervisor rs-sandbox
# `docker run`s — see cli/rs_sandbox.py BOX_IMAGE).
_BOX_IMAGES = [
    ("rs-sandbox-box", "sandbox-box", SANDBOX_BOX_IMAGE),
    ("rs-sandbox-box-browser", "sandbox-box-browser", SANDBOX_BOX_BROWSER_IMAGE),
]

# The project record of the box images it holds: {repo: {"id", "digest"}} —
# the HOST image id that was published and the digest the registry served for
# it. The id decides whether the project's image is the current one; the digest
# is what the project pulls.
BOX_IMAGES_KEY = "box_images"

# How each box image is named to the operator.
_BOX_IMAGE_SHOWN = {"sandbox-box": "the box image",
                    "sandbox-box-browser": "the browser box image"}

# The reasons the step gives (browser-reachable: no host command, no path).
BOX_IMAGE_NOT_BUILT = ("the box images are not built on this computer: Rebuild "
                       "all on Sandboxes → Software, then retry")
# The host's box image is from before RS's current layout (or its labels
# cannot be read): only a Rebuild all brings the new one.
BOX_IMAGE_OLD_LAYOUT = ("the box images on this computer are out of date: Rebuild "
                        "all on Sandboxes → Software, then retry")
BOX_IMAGE_PUBLISH_FAILED = "publishing {image} into the box image registry failed"
BOX_IMAGE_CONFIRM_FAILED = ("the box image registry did not confirm what it holds "
                            "for {image}")
BOX_IMAGE_PULL_FAILED = "the project could not pull {image} from the box image registry"
BOX_IMAGE_RECORD_FAILED = ("the project's record of {image} could not be written: "
                           "its settings file " + orch_files.SHOWN_FOLDER +
                           "/project.json could not be read or written; repair it "
                           "from the project's terminal, then restart the project")


@dataclass(frozen=True)
class BoxImageResult:
    """One run of _bring_box_image: `reason` empty = the image is in the
    project and recorded; otherwise why not. `in_project` says whether the
    project now holds the current image anyway (only a record write failed),
    so its boxes keep running."""
    reason: str = ""
    in_project: bool = False


def _registry_served_digest(host_port: str, repo: str, tag: str) -> str:
    """The digest the registry SERVES for a tag — a HEAD of the manifest on the
    loopback push port with the manifest media types offered — never the local
    daemon's `RepoDigests`, which can carry the local index digest while the
    registry holds a different single-platform manifest (measured): a recorded
    digest the registry cannot serve would make every later pull fail. "" when
    the registry does not answer with one (a missing tag, repo or Accept
    header answers 404)."""
    url = f"http://127.0.0.1:{host_port}/v2/{repo}/manifests/{tag}"
    req = urllib.request.Request(url, method="HEAD",
                                 headers={"Accept": REGISTRY_MANIFEST_ACCEPT})
    # loopback, never through an http_proxy the environment may name (the
    # push itself went over the docker socket, untouched by that proxy)
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
    try:
        with opener.open(req, timeout=REGISTRY_MANIFEST_HEAD_TIMEOUT_S) as resp:
            digest = resp.headers.get("Docker-Content-Digest", "")
    except (urllib.error.HTTPError, urllib.error.URLError, OSError):
        return ""
    return digest if _is_sha256_ref(digest) else ""


def _is_sha256_ref(value: Any) -> bool:
    return (isinstance(value, str) and value.startswith("sha256:")
            and re.fullmatch(r"[0-9a-f]{64}", value[len("sha256:"):]) is not None)


def _host_box_image_id(host_base: str) -> str:
    """The id of the host's current `rs-<base>:latest` (what Rebuild all built),
    "" when the host has none."""
    r = run(["docker", "image", "inspect", "-f", "{{.Id}}", f"{host_base}:latest"],
            capture_output=True)
    value = (r.stdout or "").strip() if r.returncode == 0 else ""
    return value if _is_sha256_ref(value) else ""


def _read_box_image_record(workspace_path: "Path") -> dict[str, dict[str, str]]:
    """The project's box-image record, valid entries only ({} when the marker
    is absent or unreadable, a link included — orch_files). An entry without
    a valid id AND digest is no entry: that image is published again."""
    try:
        data = json.loads(_read_marker_text(workspace_path))
    except (OSError, json.JSONDecodeError):
        return {}
    record = data.get(BOX_IMAGES_KEY) if isinstance(data, dict) else None
    if not isinstance(record, dict):
        return {}
    return {repo: {"id": e["id"], "digest": e["digest"]}
            for repo, e in record.items()
            if isinstance(repo, str) and isinstance(e, dict)
            and _is_sha256_ref(e.get("id")) and _is_sha256_ref(e.get("digest"))}


def _write_box_image_record(workspace_path: "Path", repo: str, image_id: str,
                            digest: str) -> bool:
    """Record one image's id and digest, merged into the marker in one temp +
    rename write; every other key is kept. False, and nothing written, when
    the marker is absent, unreadable or not an object: it is never written
    fresh (that would leave a project record without its type)."""
    try:
        data = json.loads(_read_marker_text(workspace_path))
    except (OSError, json.JSONDecodeError):
        return False
    if not isinstance(data, dict):
        return False
    current = data.get(BOX_IMAGES_KEY)
    record = dict(current) if isinstance(current, dict) else {}
    record[repo] = {"id": image_id, "digest": digest}
    data[BOX_IMAGES_KEY] = record
    try:
        _write_marker_text(workspace_path, data)
    except OSError:          # orch_files.Unusable included
        return False
    return True


def _bring_box_image(container: str, network: str, workspace_path: "Path",
                     host_base: str) -> BoxImageResult:
    """Bring ONE box image into a project: the only way a box image enters a
    project (create, a box add that finds it absent, every re-creation).

    The host's `rs-<base>:latest` is the current image. When the project's
    record holds that same id, it is pulled by the recorded digest and retagged
    `:latest` inside (a fresh inner store needs it; a kept one gets back a
    `:latest` it lost); a registry that no longer serves that digest (its
    storage was lost) is treated like no record. Otherwise that exact id is
    tagged under a name used by this call alone, published, the digest the
    registry serves for that name read back, pulled by that digest, retagged,
    and recorded — so what is recorded is what was published, whatever another
    build or delivery does meanwhile. Each step fails with a fixed reason (no
    reason is taken from a command's output) and no step prints a command
    line."""
    _, repo, latest_tag = next(t for t in _BOX_IMAGES if t[0] == host_base)
    shown = _BOX_IMAGE_SHOWN[repo]
    host_id = _host_box_image_id(host_base)
    if not host_id:
        return BoxImageResult(BOX_IMAGE_NOT_BUILT)
    # An image from before RS's current layout boots into writing RS's files
    # into the box's own folders: refused before anything is published or
    # pulled. Read from that exact id, so a concurrent rebuild cannot move it.
    if _image_instructions_layout(host_id) != INSTRUCTIONS_LAYOUT_HOME:
        return BoxImageResult(BOX_IMAGE_OLD_LAYOUT)
    try:
        _connect_registry_to_project_network(network)
    except RegistryUnavailable as e:
        return BoxImageResult(e.reason)

    def pull(digest: str) -> bool:
        ref = f"{extension.EXT_REGISTRY}/{repo}@{digest}"
        return (run_quiet(["docker", "exec", container, "docker", "pull", ref])
                and run_quiet(["docker", "exec", container, "docker", "tag", ref,
                               latest_tag]))

    recorded = _read_box_image_record(workspace_path).get(repo)
    current = recorded is not None and recorded["id"] == host_id
    if current and pull(recorded["digest"]):
        return BoxImageResult()
    # Not current, or current but its pull failed (the registry may have lost
    # it): publish. When that pull failed, a publish that fails before its own
    # pull reports the pull, the first cause.
    pull_failed = BOX_IMAGE_PULL_FAILED.format(image=shown) if current else ""
    try:
        _ensure_registry_running()
    except RegistryUnavailable as e:
        return BoxImageResult(pull_failed or e.reason)
    host_port = load_versions().get("REGISTRY_HOST_PORT", DEFAULT_REGISTRY_HOST_PORT)
    tag = f"{host_id[len('sha256:'):][:12]}-{secrets.token_hex(4)}"
    push_ref = f"127.0.0.1:{host_port}/{repo}:{tag}"
    if not run_quiet(["docker", "tag", host_id, push_ref]):
        return BoxImageResult(pull_failed or BOX_IMAGE_PUBLISH_FAILED.format(image=shown))
    pushed = run_quiet(["docker", "push", push_ref])
    # the host keeps no tag per delivery (it would hold every old build)
    run_quiet(["docker", "image", "rm", push_ref])
    if not pushed:
        return BoxImageResult(pull_failed or BOX_IMAGE_PUBLISH_FAILED.format(image=shown))
    digest = _registry_served_digest(host_port, repo, tag)
    if not digest:
        return BoxImageResult(pull_failed or BOX_IMAGE_CONFIRM_FAILED.format(image=shown))
    if not pull(digest):
        return BoxImageResult(BOX_IMAGE_PULL_FAILED.format(image=shown))
    print(f"published {shown} into the project ({digest})")
    if not _write_box_image_record(workspace_path, repo, host_id, digest):
        return BoxImageResult(BOX_IMAGE_RECORD_FAILED.format(image=shown),
                              in_project=True)
    return BoxImageResult()


def _inner_box_images_present(container: str) -> set[str]:
    """The host bases whose `:latest` the project's inner store holds now."""
    return {host_base for host_base, _repo, latest in _BOX_IMAGES
            if run_quiet(["docker", "exec", container, "docker", "image",
                          "inspect", latest])}


def _box_image_of(entry: dict) -> str:
    """The host base a box entry runs (its persisted, resolved `browser`)."""
    return _BOX_IMAGES[1][0] if entry.get("browser") is True else _BOX_IMAGES[0][0]


def _bring_box_images_at_start(project: str, container: str, network: str,
                               workspace_path: "Path", boxes: dict[str, dict],
                               found: list) -> set[str]:
    """At a re-creation, before any box is relaunched: bring every box image the
    project holds or a box needs up to the host's current one. For an image
    that fails, its boxes are stopped (a privileged host's inner daemon has
    restarted them on their own), its `:latest` is removed inside so nothing
    re-runs them on the old image, and the reason is added to `found` for the
    end of the operation. Returns the host bases whose boxes must not be
    relaunched."""
    wanted = _inner_box_images_present(container) | {
        _box_image_of(e) for e in boxes.values()}
    failed: set[str] = set()
    for host_base, repo, latest in _BOX_IMAGES:
        if host_base not in wanted:
            continue
        result = _bring_box_image(container, network, workspace_path, host_base)
        if not result.reason:
            continue
        if result.in_project:
            found.append(OldInstructions("box-image", project, reason=result.reason))
            continue
        failed.add(host_base)
        stop_failed = False
        users = [name for name, entry in sorted(boxes.items())
                 if _box_image_of(entry) == host_base]
        for name in users:
            cname = extension.container_name(name)
            if not run_quiet(["docker", "exec", container, "docker",
                              "container", "inspect", cname]):
                continue
            if not run_quiet(["docker", "exec", container, "docker", "stop", cname]):
                stop_failed = True
        run_quiet(["docker", "exec", container, "docker", "image", "rm", "-f", latest])
        kept = run_quiet(["docker", "exec", container, "docker", "image", "inspect",
                          latest])
        shown = _BOX_IMAGE_SHOWN[repo]
        parts = []
        if users:
            parts.append("the boxes that use it could not all be stopped" if stop_failed
                         else "the boxes that use it are stopped")
        if kept:
            parts.append("its old copy could not be removed from the project")
        tail = ("; " + ", and ".join(parts)) if parts else ""
        found.append(OldInstructions("box-image", project, reason=(
            f"{shown} could not be brought up to date ({result.reason}){tail}")))
    return failed


def _ensure_box_harness(container: str, network: str, workspace_path: "Path",
                        want_browser: bool) -> None:
    """Make the box harness usable in a RUNNING dind project for a box add:
    stage the rs-sandbox CLI if absent, and bring the ONE box image this box
    needs (base, or browser when ``want_browser``) into the project when its
    inner store does not hold it (research delivers lazily; a sandbox-dind
    project whose start could not bring it up to date lost it). An image the
    project holds is reused: it was brought up to date at the last start."""
    if not run_quiet(["docker", "exec", container, "test", "-e",
                      "/usr/local/bin/rs-sandbox"]):
        _stage_rs_sandbox(container)
    host_base, _repo, latest_tag = _BOX_IMAGES[1] if want_browser else _BOX_IMAGES[0]
    if not run_quiet(["docker", "exec", container, "docker", "image", "inspect",
                      latest_tag]):
        result = _bring_box_image(container, network, workspace_path, host_base)
        if result.reason:
            raise ValidationError(result.reason)


def _project_has_fetch_consumers(workspace_path: "Path") -> bool:
    """True when this project carries any opt-in rs-fetch surface: the docker
    substrate's marker `fetch` key, or any rs-fetch-enabled box entry in
    extensions.json. Drives the conditional re-stage of the supervisor-side
    fetch halves at start/recreate/wire (the universal staging is retired).
    Tolerant reads — missing/corrupt ⇒ False: an unflagged project must never
    grow the surface from a bad file (or one read through a link)."""
    try:
        if json.loads(_read_marker_text(workspace_path)).get("fetch") is True:
            return True
    except (OSError, json.JSONDecodeError, AttributeError):
        pass
    try:
        entries = extension.load(workspace_path)
    except Exception:
        return False
    return any(isinstance(e, dict) and e.get("fetch") for e in entries.values())


def _agents_from_mounts(extra_mounts: list[str]) -> list[str]:
    """Agent names out of a docker box's recovered `-v …:/opt/agent-dist/<a>:ro`
    binds (create() mounts one per enabled agent). Tolerant: anything that is not
    such a bind is skipped."""
    out: list[str] = []
    for m in extra_mounts:
        if not isinstance(m, str) or ":" not in m:
            continue
        parts = m.split(":")
        dest = parts[1] if len(parts) > 1 else ""
        prefix = f"{AGENT_DIST_MOUNT}/"
        if dest.startswith(prefix):
            a = dest[len(prefix):]
            if a in KNOWN_AGENTS and a not in out:
                out.append(a)
    return out


def _read_marker_agents(workspace_path: "Path") -> list[str]:
    """The agent set stamped into .orchestrator/project.json at create (drives the
    sandbox-dind recreate's deploy_local). Tolerant read, the _read_box_image_record shape:
    a missing/unreadable marker or key reads as [] — the recreate then comes back
    UNWIRED (accepted B31-family caveat; greenfield posture — pre-change non-docker
    markers already carry []). A link reads as unreadable (orch_files)."""
    try:
        data = json.loads(_read_marker_text(workspace_path))
    except (OSError, json.JSONDecodeError):
        return []
    agents = data.get("agents")
    return agents if isinstance(agents, list) else []


def _write_marker_agents(workspace_path: "Path", agents: list[str]) -> None:
    """Write the agent set into project.json, keeping every other key intact —
    and REFUSING on an unreadable marker rather than clobbering it, like every
    read-modify-write writer of the marker: `type`, `substrate`, `workflow`,
    `models`, `box_images`, `ssh_port` would all vanish, and the recreate +
    the webui flavor gate read every one of them. A link at the marker or at
    the settings folder is unreadable (orch_files), never followed."""
    f = workspace_path / ".orchestrator" / "project.json"
    try:
        data = json.loads(_read_marker_text(workspace_path))
    except orch_files.Unusable as e:
        # Its own text names the folder as the project sees it; the host path
        # never reaches the browser.
        raise ValidationError(f"cannot update the agent set: {e}")
    except (OSError, json.JSONDecodeError) as e:
        raise ValidationError(
            f"cannot update the agent set: the project marker {orch_files.SHOWN_FOLDER}/project.json is unreadable "
            f"({e}); repair it before changing agents")
    if not isinstance(data, dict):
        raise ValidationError(
            f"cannot update the agent set: the project marker {orch_files.SHOWN_FOLDER}/project.json is not a JSON object")
    new = list(dict.fromkeys(agents))
    # A project recorded with an EMPTY set has no claude in its own container to
    # preserve, so its first agent add makes it exact (_dind_agent_sets): adding
    # pi gives exactly pi. Only a PRESENT, empty list: a marker with no `agents`
    # key at all may still carry claude from its original create.
    current = data.get("agents")
    if isinstance(current, list) and not current and new:
        data["agents_exact"] = True
    data["agents"] = new
    _write_marker(workspace_path, data, "update the agent set")


def _validate_agents_update(req: "UpdateRequest", container: str,
                            workspace_path: "Path") -> list[str]:
    """The agents an update ADDS to the record, or [] when the request carries no
    agent change / an already-complete set. Raises ValidationError
    (pre-side-effect, a clean browser refusal) on a research project (Claude
    only) or a missing marker. A removal is checked by _agent_settings_plan."""
    if req.agents is None:
        return []
    if _container_project_type(container) != PROJECT_TYPE_SANDBOX_DIND:
        raise ValidationError(
            "the agent set can only change on a sandbox-dind (dev / sandbox) project; "
            "a research-workflow project runs claude")
    f = workspace_path / ".orchestrator" / "project.json"
    try:
        _read_marker_text(workspace_path)
    except FileNotFoundError:
        raise ValidationError(
            f"cannot update the agent set: the project marker {orch_files.SHOWN_FOLDER}/project.json is missing")
    except OSError as e:
        raise ValidationError(f"cannot update the agent set: {e}")
    # Additions are judged against what runs in the project's own container
    # (an older record runs Claude without listing it), like removals in
    # _agent_settings_plan, which update() runs before any write.
    running = _project_running_agents(workspace_path)
    return [a for a in req.agents if a not in running]


# ---------------------------------------------------------------------------
# The agent's model and effort live in the agent's own settings file (I33
# slice 3). Claude Code keeps its default model in ~/.claude/settings.json
# (`model`, where its own /model saves) and its effort there too (`effortLevel`,
# and per model under `modelSettings`, where /effort saves); pi keeps its own
# in its settings (`defaultProvider`/`defaultModel`/`defaultThinkingLevel`). RS
# writes the project's choice into those files — a merge into the existing
# file, never a new file — and the ⚙ panel reads them back, so a model picked
# inside the agent shows up and a change needs no container restart.
# Measured on the pinned Claude Code 2.1.258 (zero tokens, a fake API): the
# container's ANTHROPIC_MODEL / CLAUDE_CODE_EFFORT_LEVEL outrank the file's
# keys; the file's own `env` block outranks the container's; an empty entry
# there neutralises the container's; `effortLevel` takes low..xhigh only (`max`
# only through the environment); the per-model entry outranks the top-level
# one; a running session keeps its model until its next start.
# ---------------------------------------------------------------------------

# A Claude model as Claude's own picker writes it: a tier (`opus`), a variant
# (`opus[1m]`, `opusplan`) or a full id (`claude-sonnet-5`).
CLAUDE_MODEL_RE = re.compile(r"\A[A-Za-z0-9][A-Za-z0-9._\[\]-]*\Z")
# The levels Claude's own `effortLevel` setting accepts (its settings schema in
# 2.1.258); any other catalog level (`max`) rides the file's `env` block.
CLAUDE_SETTINGS_EFFORTS = ("low", "medium", "high", "xhigh")
# What a worker's or role service's copy of the supervisor's Claude settings
# drops: the hooks (supervisor-only) and the supervisor agent's own model and
# effort, which would override the copy's --model/--effort (an `env` effort
# entry beats the flag — measured). MIRROR of rs_worker.AGENT_MODEL_KEYS /
# AGENT_MODEL_ENV_KEYS (pinned).
AGENT_MODEL_SETTINGS_JQ = ('del(.hooks, .model, .effortLevel, .modelSettings)'
                           ' | if (.env | type) == "object"'
                           ' then .env |= del(.ANTHROPIC_MODEL, .CLAUDE_CODE_EFFORT_LEVEL)'
                           ' else . end')
# The fields an update can set back to the default (UpdateRequest.reset).
UPDATE_RESETTABLE = ("supervisor_model", "supervisor_effort", "pi_model", "pi_thinking",
                     *HARNESS_FIELDS)
# Images built with this label carry the settings-file delivery (the research
# worker/role settings copy strips the model keys; the docker entrypoint merges
# the create-time choice). A project on an older image keeps the container
# setting (ANTHROPIC_MODEL) exactly as before.
AGENT_SETTINGS_LABEL = "research.agent-settings"
CLAUDE_EXT_ID = "anthropic.claude-code"
AGENT_SETTINGS_ABSENT = "RS_AGENT_SETTINGS_ABSENT"
AGENT_SETTINGS_FAILED = "RS_AGENT_SETTINGS_NOT_APPLIED"
# Bounds on one agent's settings file, which the agent (or anything in the
# container) can rewrite. Real files are a few KB; the cap only stops a file
# replaced with something huge from being streamed and parsed — 1 MiB is two
# orders of magnitude above any real one and still trivial to hold.
AGENT_SETTINGS_MAX_BYTES = 1024 * 1024
# A `docker exec` of `head`/`jq` on that file answers in well under a second;
# the bound only stops a wedged exec from freezing the serial broker (the read
# is a broker verb). Same class and value as HISTORY_STATUS_READ_TIMEOUT_S.
AGENT_SETTINGS_EXEC_TIMEOUT_S = 5
_AGENT_SETTINGS_WARNING = ("the {agent} model could not be written into its settings in the "
                           "project; it is saved and applied at the project's next start")

# Set or clear Claude's model and effort. $mo/$eo are "set", "clear" or "keep".
# Any model or effort write also empties the matching `env` entry, which
# neutralises a container setting left by a project created before this; `max`
# is written there instead, the only place Claude accepts it. Mirrored (the
# set-only half) by agent/entrypoint.minimal.sh — pinned.
CLAUDE_SETTINGS_JQ = (
    '(.model // "") as $old'
    ' | (if $mo == "set" then $m else $old end) as $k'
    ' | if $mo == "set" then .model = $m elif $mo == "clear" then del(.model) else . end'
    ' | if $mo == "keep" then . else .env = ((.env // {}) + {"ANTHROPIC_MODEL": ""}) end'
    ' | if $eo == "set" and $e == "max"'
    ' then .env = ((.env // {}) + {"CLAUDE_CODE_EFFORT_LEVEL": "max"}) | del(.effortLevel)'
    ' | if $k == "" or ((.modelSettings // {}) | has($k) | not) then .'
    ' else .modelSettings[$k] |= del(.effortLevel) end'
    ' elif $eo == "set"'
    ' then .env = ((.env // {}) + {"CLAUDE_CODE_EFFORT_LEVEL": ""}) | .effortLevel = $e'
    ' | if $k == "" then . else .modelSettings = ((.modelSettings // {})'
    ' | .[$k] = ((.[$k] // {}) + {"effortLevel": $e})) end'
    ' elif $eo == "clear"'
    ' then .env = ((.env // {}) + {"CLAUDE_CODE_EFFORT_LEVEL": ""}) | del(.effortLevel)'
    ' | if $k == "" or ((.modelSettings // {}) | has($k) | not) then .'
    ' else .modelSettings[$k] |= del(.effortLevel) end'
    ' else . end')
# Set or clear pi's starting model and thinking level ($mo/$to as above).
PI_SETTINGS_JQ = (
    'if $mo == "set" then .defaultProvider = $p | .defaultModel = $m'
    ' elif $mo == "clear" then del(.defaultProvider, .defaultModel) else . end'
    ' | if $to == "set" then .defaultThinkingLevel = $t'
    ' elif $to == "clear" then del(.defaultThinkingLevel) else . end')
# Merge into an EXISTING file only (RS's own settings file carries the bypass,
# attribution and other keys; creating one would skip them for good): temp
# file + rename beside it. The values reach jq as argv words ("$@"), never as
# shell text. Prints a sentinel instead of failing; the host reads it back.
_AGENT_SETTINGS_SCRIPT = (
    'f="$1"; shift\n'
    f'[ -f "$f" ] || {{ echo {AGENT_SETTINGS_ABSENT}; exit 0; }}\n'
    f'[ "$(wc -c < "$f")" -le {AGENT_SETTINGS_MAX_BYTES} ] || '
    f'{{ echo {AGENT_SETTINGS_FAILED}; exit 0; }}\n'
    # an empty result (jq on a file caught mid-write by its creator) is never
    # moved in: it would replace the agent's settings with nothing
    'if jq "$@" "$f" > "$f.rs-tmp" && [ -s "$f.rs-tmp" ] && mv "$f.rs-tmp" "$f"; then exit 0; fi\n'
    f'rm -f "$f.rs-tmp"; echo {AGENT_SETTINGS_FAILED}\n')
_AGENT_HOME = "/home/research"


def _agent_settings_path(agent: str, home: str = _AGENT_HOME) -> str:
    """The settings file RS writes for `agent` in a container with `home`."""
    if agent == "pi":
        return f"{home}/{PI_AGENT_DIR_REL}/settings.json"
    return f"{home}/.claude/settings.json"


def _claude_effort_ok(model: str, effort: str, catalog: dict) -> bool:
    """Whether `effort` may go with `model`: a catalog tier answers from the
    catalog (haiku takes none); any other id (a full id, `opus[1m]`) takes any
    catalog level — Claude decides what to send for it."""
    if not effort:
        return True
    if effort not in catalog.get("efforts", ()):
        return False
    if model in model_catalog.aliases(catalog):
        return model_catalog.supports_effort(model, effort, catalog)
    return True


def _label_is_set(kind: str, ref: str) -> bool:
    """Whether the image or container `ref` carries AGENT_SETTINGS_LABEL=1.
    Anything else (an older image, a failed inspect) reads as no."""
    try:
        r = run(["docker", kind, "inspect", "-f",
                 '{{index .Config.Labels "' + AGENT_SETTINGS_LABEL + '"}}', ref],
                capture_output=True, timeout=AGENT_SETTINGS_EXEC_TIMEOUT_S)
    except (OSError, subprocess.TimeoutExpired):
        return False
    return r.returncode == 0 and (r.stdout or "").strip() == "1"


def _claude_ops_from_pair(pair: "dict | None",
                          fields: "Sequence[str] | None" = None) -> tuple[str, str, str, str]:
    """(mo, m, eo, e) setting the file to the recorded pair: an empty half is
    cleared (Claude's own default). `fields` names the halves to write
    ("model", "effort"); the others are kept as the file has them (None: both)."""
    pair = pair if isinstance(pair, dict) else {}
    m = pair.get("model") if isinstance(pair.get("model"), str) else ""
    e = pair.get("effort") if isinstance(pair.get("effort"), str) else ""
    if m and not CLAUDE_MODEL_RE.match(m):
        m = ""
    if e and e not in CLAUDE_SETTINGS_EFFORTS and e != "max":
        e = ""
    mo = ("set" if m else "clear") if fields is None or "model" in fields else "keep"
    eo = ("set" if e else "clear") if fields is None or "effort" in fields else "keep"
    return (mo, m, eo, e)


def _pi_ops_from_pair(pair: "dict | None",
                      fields: "Sequence[str] | None" = None) -> tuple[str, str, str, str, str]:
    """(mo, provider, model, to, thinking) setting pi's file to the pair;
    `fields` ("model", "thinking") as for Claude."""
    pair = pair if isinstance(pair, dict) else {}
    m = pair.get("model") if isinstance(pair.get("model"), str) else ""
    t = pair.get("thinking") if isinstance(pair.get("thinking"), str) else ""
    if m and not PI_MODEL_RE.match(m):
        m = ""
    if t not in PI_THINKING_LEVELS:
        t = ""
    p, _, rest = m.partition("/")
    mo = ("set" if m else "clear") if fields is None or "model" in fields else "keep"
    to = ("set" if t else "clear") if fields is None or "thinking" in fields else "keep"
    return (mo, p, rest, to, t)


def _write_agent_settings(container: str, agent: str, pair: "dict | None",
                          home: str = _AGENT_HOME,
                          fields: "Sequence[str] | None" = None) -> str:
    """Write the recorded pair into `agent`'s settings file in a RUNNING
    container, as the agent user. "ok", "absent" (no settings file yet — the
    agent was never installed there) or "failed". Never raises."""
    if agent == "pi":
        mo, p, m, to, t = _pi_ops_from_pair(pair, fields)
        args = ["--arg", "mo", mo, "--arg", "p", p, "--arg", "m", m,
                "--arg", "to", to, "--arg", "t", t, PI_SETTINGS_JQ]
    else:
        mo, m, eo, e = _claude_ops_from_pair(pair, fields)
        args = ["--arg", "mo", mo, "--arg", "m", m, "--arg", "eo", eo, "--arg", "e", e,
                CLAUDE_SETTINGS_JQ]
    try:
        r = run(["docker", "exec", "-u", "1000", "-e", f"HOME={home}", container,
                 "sh", "-c", _AGENT_SETTINGS_SCRIPT, "sh", _agent_settings_path(agent, home),
                 *args], capture_output=True, timeout=AGENT_SETTINGS_EXEC_TIMEOUT_S)
    except (OSError, subprocess.TimeoutExpired, UnicodeDecodeError):
        return "failed"
    out = r.stdout or ""
    if r.returncode != 0 or AGENT_SETTINGS_FAILED in out:
        return "failed"
    if AGENT_SETTINGS_ABSENT in out:
        return "absent"
    return "ok"


def _read_agent_settings(container: str, agent: str,
                         home: str = _AGENT_HOME) -> "dict | None":
    """`agent`'s settings file in a RUNNING container as a dict, or None (no
    file, unreadable, not an object)."""
    # A regular file only (a FIFO would block `cat` forever), and at most the
    # cap (one byte over reads as unreadable).
    try:
        r = run(["docker", "exec", "-u", "1000", container, "sh", "-c",
                 '[ -f "$1" ] && head -c "$2" "$1" 2>/dev/null', "sh",
                 _agent_settings_path(agent, home), str(AGENT_SETTINGS_MAX_BYTES + 1)],
                capture_output=True, timeout=AGENT_SETTINGS_EXEC_TIMEOUT_S)
    except (OSError, subprocess.TimeoutExpired, UnicodeDecodeError):
        return None
    if len(r.stdout or "") > AGENT_SETTINGS_MAX_BYTES:
        return None
    if r.returncode != 0 or not (r.stdout or "").strip():
        return None
    try:
        data = json.loads(r.stdout)
    except json.JSONDecodeError:
        return None
    return data if isinstance(data, dict) else None


def _marker_rmw(workspace_path: "Path", mutate, what: str) -> None:
    """Read-modify-write the project marker: `mutate(data)` edits the dict in
    place. Refuses an unreadable or non-object marker (never clobbers it), temp
    file + rename. `what` names the change in the refusal. A link at the
    marker or at the settings folder is refused, never followed (orch_files)."""
    f = workspace_path / ".orchestrator" / "project.json"
    try:
        data = json.loads(_read_marker_text(workspace_path))
    except orch_files.Unusable as e:
        raise ValidationError(f"cannot {what}: {e}")
    except (OSError, json.JSONDecodeError) as e:
        raise ValidationError(f"cannot {what}: the project marker {orch_files.SHOWN_FOLDER}/project.json is unreadable ({e}); "
                              f"repair it first")
    if not isinstance(data, dict):
        raise ValidationError(f"cannot {what}: the project marker {orch_files.SHOWN_FOLDER}/project.json is not a JSON object")
    mutate(data)
    _write_marker(workspace_path, data, what)


# ---------------------------------------------------------------------------
# RS's instructions in the agent's home rules folder
# ---------------------------------------------------------------------------
# RS's text for each kind of container lives in ONE file outside the
# workspace, `~/.claude/rules/rs-instructions.md` in the agent user's home:
# Claude Code loads every rule file there in every session and subagent, and
# RS's pi extension loads the same folder into pi. The file is owned by the
# agent user with mode 0444 (read-only by MODE: RS's own steps re-own the home
# to the agent user and never change modes); the folder stays an ordinary
# writable folder. The notice at the top says RS replaces the file. The user's
# own instructions live in /workspace/.claude/ and /workspace/.pi/, which RS
# never writes. RS used to write /workspace/CLAUDE.md; where an old one is
# still there, RS writes nothing new and the operation fails with an error
# saying what to do (it never renames, moves or deletes the file).
RS_INSTRUCTIONS_NOTICE_FILE = SCRIPT_DIR / "container" / "rs-instructions-notice.md"
RS_INSTRUCTIONS_REL = ".claude/rules/rs-instructions.md"
# The marker / box-record flag set after the first successful write: from then
# on a /workspace/CLAUDE.md is the user's own file and never checked again.
OLD_INSTRUCTIONS_FLAG = "old_instructions_cleared"
# The sentence a dev text carries when no base branch is recorded (`<base>`
# stands where the name would be). MIRROR PAIR with rs_sandbox.NO_BRANCH_SENTENCE
# (the box tool is staged standalone) — pinned equal.
NO_BRANCH_PLACEHOLDER = "<base>"
NO_BRANCH_SENTENCE = (
    "RS had no base branch recorded for this container when it wrote this file, "
    "so `<base>` below stands for it: it is the default branch of the `upstream` "
    "remote (`git remote show upstream`, the `HEAD branch` line) unless the "
    "maintainer names another.")
RS_INSTR_WRITTEN = "RS_INSTRUCTIONS_WRITTEN"
RS_INSTR_FAILED = "RS_INSTRUCTIONS_NOT_WRITTEN"
RS_INSTR_OLD = "RS_INSTRUCTIONS_OLD_FILE"
RS_INSTR_KEPT = "RS_INSTRUCTIONS_KEPT"
# One `docker exec` writing a few KB into the container's home answers in well
# under a second; the bound only stops a wedged exec from holding a start (and
# the serial broker) forever. Generous on purpose: a timeout here costs a
# warning and leaves the file to the next start, so it must not fire on a box
# that is merely slow under a parallel image build.
RS_INSTR_EXEC_TIMEOUT_S = 30
# The write, as the agent user (uid 1000, HOME set by the caller). $1 is the
# byte count the host sent, $2 is 1 when the container's old
# /workspace/CLAUDE.md must be checked first (a file or a link — a dangling
# link fails -e), $3 is 1 when a file already in place is kept (a dev text
# written without its branch never replaces one written with it). ONE `&&` chain with ONE failure branch: on the left of `||`
# the shell ignores `set -e`, so a `;`-list would install a cut-short file and
# report success. The temp name never ends in `.md` (the agents load only
# `*.md`), `mktemp` creates it exclusively, the count catches a host that died
# mid-stream (`cat` then sees end-of-file and exits 0), and `mv -T` makes a
# folder planted at the target fail instead of receiving the file; a link at
# the target is replaced, never followed. MIRROR PAIR with
# rs_sandbox.RS_INSTR_SCRIPT — pinned equal.
RS_INSTR_SCRIPT = (
    'if [ "$2" = 1 ] && { [ -L /workspace/CLAUDE.md ] || [ -e /workspace/CLAUDE.md ]; }; '
    f'then echo {RS_INSTR_OLD}; exit 0; fi\n'
    'if [ "$3" = 1 ] && [ -e "$HOME/.claude/rules/rs-instructions.md" ]; '
    f'then echo {RS_INSTR_KEPT}; exit 0; fi\n'
    'tmp=; mkdir -p "$HOME/.claude/rules" && '
    'tmp=$(mktemp "$HOME/.claude/rules/.rs-instructions.XXXXXX") && '
    'cat >"$tmp" && [ "$(wc -c <"$tmp")" -eq "$1" ] && chmod 0444 "$tmp" && '
    'mv -fT "$tmp" "$HOME/.claude/rules/rs-instructions.md" && '
    f'echo {RS_INSTR_WRITTEN} || '
    f'{{ [ -z "$tmp" ] || rm -f "$tmp" || :; echo {RS_INSTR_FAILED} || :; }}\n')
# A failed read of a workflow catalog, the built-ins or the custom-workflow
# registry (UnicodeDecodeError is a ValueError).
_CATALOG_READ_ERRORS = (workflow.WorkflowError, OSError, ValueError, RecursionError)
# What _marker_rmw lets escape besides its own ValidationError.
_MARKER_WRITE_ERRORS = (ValidationError, OSError, ValueError, RecursionError)

# Operator lines (browser-visible: project terms, never a host path or a CLI
# verb, never a reader's exception text).
_INSTR_UNKNOWN_KEEP = ("RS's instructions for this project were not refreshed "
                       "because {what} could not be read; a copy from an earlier "
                       "start, if there is one, stays in place until a start can "
                       "read it")
_INSTR_UNKNOWN_NONE = ("RS's instructions for this project were not written "
                       "because {what} could not be read; the agent runs without "
                       "them until a start can read it")
_INSTR_WRITE_FAILED = ("RS's instructions could not be written into the "
                       "project's agent home; the next start writes them again")
_INSTR_FLAG_FAILED = ("RS's instructions were written, but the project's "
                      "settings could not record it; the next start checks the "
                      "project's old instructions file again")
_INSTR_NO_LEDGER = ("RS's instructions for this project were written without its "
                    "base branch because the dev record could not be read; the "
                    "next start that can read it fills the branch in")
_INSTR_LABELS_UNKNOWN = ("RS could not read this project's container labels, so "
                         "its instructions were not refreshed; the next start "
                         "tries again")
OLD_INSTRUCTIONS_PROJECT_ERROR = (
    "`/workspace/CLAUDE.md` is the instructions file RS used to write here. RS's "
    "instructions now live in the agent's home folder and are no longer written "
    "while this file exists, so the agent still reads the old one. Remove or "
    "rename `/workspace/CLAUDE.md` from this project's terminal or editor, then "
    "stop the project and start it again.")
OLD_INSTRUCTIONS_BOX_ERROR = (
    "`/workspace/boxes/{box}/CLAUDE.md` is the instructions file RS used to write "
    "for box '{box}'. RS's instructions now live in the box's home folder and are "
    "no longer written while this file exists, so the box's agent still reads the "
    "old one. Remove or rename `/workspace/boxes/{box}/CLAUDE.md` from this "
    "project's terminal or editor, then stop the project and start it again.")
OLD_INSTRUCTIONS_BOX_SIDE_WARNING = (
    "box '{box}' of project '{project}' was re-run without its new instructions: "
    "`/workspace/boxes/{box}/CLAUDE.md` is the instructions file RS used to write "
    "there and is still there, so the box's agent reads the old one. Remove or "
    "rename it from the project's terminal or editor; until then the project's "
    "next start fails")
OLD_INSTRUCTIONS_RESEARCH_ERROR = (
    "`/workspace/CLAUDE.md` is a link to `.claude/CLAUDE.md`, where RS used to put "
    "the research instructions. RS's instructions now live in the agent's home "
    "folder and are not written while this link exists, so the agent still reads "
    "the old copy. Remove the link `/workspace/CLAUDE.md` from this project's "
    "terminal or editor. `/workspace/.claude/CLAUDE.md` is still loaded as the "
    "project's own instructions: remove or rename it too, unless you keep it as "
    "your own. Then stop the project and start it again.")
OLD_INSTRUCTIONS_IMAGE_ERROR = (
    "this project type's image is out of date: rebuild RS's images with Rebuild "
    "all on Sandboxes → Software, then stop the project and start it again")
OLD_INSTRUCTIONS_UNCHECKED_ERROR = (
    "RS could not check this project for its old instructions link; stop the "
    "project and start it again")
OLD_INSTRUCTIONS_IMAGE_CREATE_ERROR = (
    "this project type's image is out of date: rebuild RS's images with Rebuild "
    "all on Sandboxes → Software, then create the project again")
OLD_INSTRUCTIONS_LABEL_CREATE_ERROR = (
    "RS could not read this project type's image labels, so it could not check "
    "that the image is up to date; create the project again")
OLD_INSTRUCTIONS_LABEL_ERROR = (
    "RS could not read this project's image labels, so it could not check its "
    "instructions layout; stop the project and start it again")
# The image label marking the layout where RS's files live in the agents'
# homes: the boot script writes nothing into the workspace's .claude/ or .pi/
# (and the research one writes ~/.claude/rules/rs-instructions.md and never
# re-creates the old /workspace/CLAUDE.md link). Set by
# agent/Dockerfile.supervisor, agent/Dockerfile.sandbox-dind and
# agent/Dockerfile.sandbox-box (the browser box image inherits it). A new value
# whenever an image's own boot stops writing into those folders: an image built
# before it would put the files back after every removal.
INSTRUCTIONS_LAYOUT_LABEL = "research.instructions-layout"
INSTRUCTIONS_LAYOUT_HOME = "home-2"
# The project record's flag (the marker; a box's is its record's) set once a
# check found none of the files RS used to write into the project's own
# folders: from then on such a file is the user's and never checked again.
OLD_FILES_FLAG = "old_files_cleared"
# The paths RS used to write into a project's folders, per kind (only where it
# wrote them): the project agent of a sandbox-dind or research project, the
# research supervisor besides, and every box (MIRROR of rs_sandbox's pair —
# pinned equal). Dev and plain Docker projects: none.
PROJECT_OLD_PATHS = (".claude/skills/ok", ".pi/skills/ok")
RESEARCH_OLD_PATHS = (".claude/settings.json", ".claude/commands/log.md",
                      ".claude/logbook_supervisor_template.md",
                      ".claude/logbook_pi_template.md", ".claude/logbook_template.md")
# The credential stash of the retired PI containers, .pi/<role>/.creds/<file>
# (any role folder), and the one-time upgrade tool's `*.before-upgrade`
# copies in .claude/.
RESEARCH_OLD_CREDS = (".credentials.json", "settings.json", "home_claude.json")
OLD_UPGRADE_SUFFIX = ".before-upgrade"
BOX_OLD_PATHS = (".claude/skills/ok", ".pi/skills/ok", ".claude/settings.json",
                 ".pi/mcp.json")
OK_BOX_OLD_PATHS = (".claude/skills/ok-ingest", "notes/.claude/skills/ok-ingest")
OLD_FILES_PROJECT_ERROR = (
    "this project still holds files RS used to write into its folders: {paths}. "
    "RS keeps these in the agents' home folders now and writes no new copies "
    "while they exist, so the agents still read the old ones. Remove or rename "
    "them from this project's terminal or editor, then stop the project and "
    "start it again.")
OLD_FILES_BOX_ERROR = (
    "box '{box}' still holds files RS used to write into its folder: {paths}. RS "
    "keeps these in the box agents' home folders now and writes no new copies "
    "while they exist. Remove or rename them from this project's terminal or "
    "editor, then stop the project and start it again.")
OLD_FILES_BOX_SIDE_WARNING = (
    "box '{box}' of project '{project}' was re-run without RS's new copies of the "
    "files it used to write into the box's folder: {paths} are still there. Remove "
    "or rename them from the project's terminal or editor; until then the "
    "project's next start fails")
_FILES_UNKNOWN = ("RS could not read the project's settings, so it did not check "
                  "the project's folders for the files it used to write there or "
                  "refresh the project agent's skills; the next start tries again")
_FILES_FLAG_FAILED = ("the project's folders hold none of the files RS used to "
                      "write there, but the project's settings could not record "
                      "it; the next start checks them again")
_RESEARCH_STAGING_FAILED = ("the project's box tool or box catalog could not be "
                            "staged at this start; the project agent's skills and "
                            "its boxes keep what they had until the next start")
_FILES_SKILLS_FAILED = ("RS's skills could not be refreshed in the agents' home "
                        "folders; the next start writes them again")


@dataclass(frozen=True)
class OldInstructions:
    """An operation met an old instructions file (or an old research image)
    and wrote nothing new: raised ONCE at the end of the top-level verb."""
    kind: str          # "project" | "box" | "research" | "image" | "labels" | "unchecked"
                       # | "box-image" (a box image could not be brought up to
                       # date at a re-creation; `reason` is its fixed text)
                       # | "files" / "box-files" (files RS used to write into
                       # the project's / a box's folder; `paths` lists them)
    project: str
    box: str = ""
    reason: str = ""
    paths: "tuple[str, ...]" = ()

    def text(self) -> str:
        if self.kind == "box":
            return OLD_INSTRUCTIONS_BOX_ERROR.format(box=_shown_box(self.box))
        if self.kind == "box-image":
            return self.reason
        if self.kind == "files":
            return OLD_FILES_PROJECT_ERROR.format(paths=_shown_old_paths("", self.paths))
        if self.kind == "box-files":
            return OLD_FILES_BOX_ERROR.format(
                box=_shown_box(self.box), paths=_shown_old_paths(self.box, self.paths))
        return {"project": OLD_INSTRUCTIONS_PROJECT_ERROR,
                "research": OLD_INSTRUCTIONS_RESEARCH_ERROR,
                "image": OLD_INSTRUCTIONS_IMAGE_ERROR,
                "labels": OLD_INSTRUCTIONS_LABEL_ERROR,
                "unchecked": OLD_INSTRUCTIONS_UNCHECKED_ERROR}[self.kind]


def _shown_box(name: Any) -> str:
    """A box name for operator text: the record is project-writable, so a
    name that is not a valid box name is shown as `…`."""
    return name if isinstance(name, str) and _BOX_NAME_RE.match(name) else "…"


def _known_old_rel(rel: Any, box: bool) -> bool:
    """Whether `rel` is one of the paths RS wrote (the box tool's report is
    project-controlled: anything else is never shown)."""
    if not isinstance(rel, str):
        return False
    if box:
        return rel in BOX_OLD_PATHS + OK_BOX_OLD_PATHS
    if rel in PROJECT_OLD_PATHS + RESEARCH_OLD_PATHS:
        return True
    parts = rel.split("/")
    if (len(parts) == 4 and parts[0] == ".pi" and parts[2] == ".creds"
            and parts[3] in RESEARCH_OLD_CREDS and _OLD_NAME_RE.match(parts[1])):
        return True
    return (len(parts) == 2 and parts[0] == ".claude" and parts[1].endswith(OLD_UPGRADE_SUFFIX)
            and _OLD_NAME_RE.match(parts[1]) is not None)


# A folder or file name shown back to the operator (the role folders and
# upgrade copies are listed from the project's own folders).
_OLD_NAME_RE = re.compile(r"\A[A-Za-z0-9._-]{1,128}\Z")


def _shown_old_paths(box: str, paths: "Sequence[str]") -> str:
    """The old paths as the project sees them, each re-validated; "" names
    the files generically when none survives."""
    base = f"/workspace/boxes/{_shown_box(box)}/" if box else "/workspace/"
    shown = [f"`{base}{p}`" for p in paths if _known_old_rel(p, bool(box))]
    return ", ".join(shown) or "files RS wrote there"


def _raise_old_instructions(found: "Sequence[OldInstructions]", *,
                            name_project: bool = False) -> None:
    """Raise the collected old-instructions errors as ONE ValidationError (the
    broker prints its text exactly); nothing when there are none. Each text
    once; `name_project` prefixes the project (start --all)."""
    lines: list[str] = []
    for f in found:
        if not isinstance(f, OldInstructions):
            continue
        t = f.text()
        if name_project:
            t = f"project {f.project!r}: {t}"
        if t not in lines:
            lines.append(t)
    if lines:
        raise ValidationError("\n".join(lines))


@dataclass
class _InstrPlan:
    """What the writer does for one project container. `text` None = unknown
    (an input could not be read; `what` names it in project terms)."""
    text: "str | None" = None
    what: str = ""
    check_old: bool = False
    keep_existing: bool = False
    cleared: bool = False
    backfill: dict = field(default_factory=dict)


def _rs_notice() -> str:
    return RS_INSTRUCTIONS_NOTICE_FILE.read_text(encoding="utf-8")


def _compose_rs_text(body: str) -> str:
    """The notice, then the container's text (the notice alone for none)."""
    notice = _rs_notice().rstrip("\n") + "\n"
    body = (body or "").strip()
    return notice + ("\n" + body + "\n" if body else "")


def _dev_text(branch: str) -> str:
    """The dev template with the base branch filled in; with none recorded,
    `<base>` in its place plus the sentence saying how to find it."""
    text = (box_catalog.BUILTIN_DIR / "dev.instructions.md").read_text(encoding="utf-8")
    if branch:
        return text.replace(BASE_BRANCH_TOKEN, branch)
    return NO_BRANCH_SENTENCE + "\n\n" + text.replace(BASE_BRANCH_TOKEN,
                                                      NO_BRANCH_PLACEHOLDER)


def _read_marker_three_way(workspace_path: "Path") -> "tuple[str, dict]":
    """("absent"|"unreadable"|"ok", data). PR 0's file reader under it: a link,
    invalid UTF-8 and any other OSError are unreadable; so are invalid or too
    deeply nested JSON and a non-object."""
    try:
        text = _read_marker_text(workspace_path)
    except FileNotFoundError:
        return "absent", {}
    except OSError:
        return "unreadable", {}
    try:
        data = json.loads(text)
    except (ValueError, RecursionError):
        return "unreadable", {}
    if not isinstance(data, dict):
        return "unreadable", {}
    return "ok", data


def _resolve_workflow_three_way(wf: str) -> "tuple[str, dict]":
    """("found", manifest) | ("missing", {}) | ("unknown", {}). The full
    catalog first; when it cannot be read, the built-ins decide only if the
    custom-workflow registry reads cleanly and lacks the name (a built-in that
    later took a custom workflow's name must never decide it)."""
    try:
        catalog = {m["name"]: m for m in workflow.load_catalog()}
    except _CATALOG_READ_ERRORS:
        pass
    else:
        return ("found", catalog[wf]) if wf in catalog else ("missing", {})
    try:
        registry = workflow.load_registry()
    except _CATALOG_READ_ERRORS:
        return "unknown", {}
    if wf in registry:
        return "unknown", {}
    try:
        builtins = workflow.load_builtins()
    except _CATALOG_READ_ERRORS:
        return "unknown", {}
    if wf in builtins:
        return "found", builtins[wf]
    return "unknown", {}


def _read_attachments_three_way() -> "tuple[bool, list]":
    """(readable, rows) of the dev lane's attachment ledger: a missing file is
    readable and empty; anything unreadable is (False, [])."""
    path = gitea.ATTACHMENTS_PATH
    try:
        text = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        return True, []
    except (OSError, ValueError):
        return False, []
    try:
        data = json.loads(text)
    except (ValueError, RecursionError):
        return False, []
    return (True, data) if isinstance(data, list) else (False, [])


def _ledger_branch(project: str, rows: list) -> str:
    """The project agent's recorded base branch: its `agent` row with no box
    (history rows excluded); "" when none is recorded."""
    for e in rows:
        if (isinstance(e, dict) and e.get("project") == project
                and e.get("class") == "agent" and e.get("box") is None):
            b = e.get("branch")
            return b if isinstance(b, str) else ""
    return ""


def _plan_project_instructions(project: str, workspace_path: "Path", *,
                               branch: "str | None" = None) -> _InstrPlan:
    """Decide the text for a project container from its marker (never from a
    tolerant reader that folds unreadable into a default). `branch` (create)
    is the request's resolved base branch, used instead of the ledger."""
    state, data = _read_marker_three_way(workspace_path)
    what = f"the project's settings ({orch_files.SHOWN_FOLDER}/project.json)"
    if state != "ok" or not isinstance(data.get("type"), str):
        # A marker without `type` is not one RS writes (older versions'
        # box-pin backfill could synthesize one): read as unknown, never as
        # "not dev".
        return _InstrPlan(what=what)
    plan = _InstrPlan(cleared=data.get(OLD_INSTRUCTIONS_FLAG) is True)
    wf = data.get("workflow") if isinstance(data.get("workflow"), str) and data.get("workflow") else ""
    docker = data.get("substrate") == Substrate.DOCKER.value
    resolved: "tuple[str, dict] | None" = None

    def resolve() -> "tuple[str, dict]":
        nonlocal resolved
        if resolved is None:
            resolved = _resolve_workflow_three_way(wf)
        return resolved

    if docker:
        body, covered = "", False
        if wf:
            st, m = resolve()
            if st == "unknown":
                return _InstrPlan(what="the custom-workflow list")
            if st == "found":
                instr = m.get("instructions") if m.get("source", "builtin") == "builtin" else None
                if isinstance(instr, str) and instr.strip():
                    body, covered = instr, True
            else:
                covered = True        # gone from a readable catalog (F-L1)
        plan.text = _compose_rs_text(body)
        plan.check_old = covered and not plan.cleared
        return plan

    dev = data.get("dev")
    if not isinstance(dev, bool):
        if not wf:
            dev = False
        else:
            st, m = resolve()
            if st == "unknown":
                return _InstrPlan(what="the custom-workflow list")
            dev = bool(m.get("dev")) if st == "found" else False
        plan.backfill["dev"] = dev
    if dev:
        if branch is None:
            ok, rows = _read_attachments_three_way()
            if not ok:
                # A file already there is kept; with none, the `<base>` text.
                plan.keep_existing, plan.what = True, "the dev record"
                rows = []
            branch = _ledger_branch(project, rows)
        plan.text = _compose_rs_text(_dev_text(branch))
        plan.check_old = not plan.cleared
        return plan
    plan.text = _compose_rs_text("")
    if not plan.cleared and wf:
        st, _m = resolve()
        if st == "unknown":
            return _InstrPlan(what="the custom-workflow list")
        plan.check_old = st == "missing"     # F-L1: RS cannot tell what it wrote
    return plan


def _exec_rs_instructions(container: str, home: str, text: str, *,
                          check_old: bool, keep_existing: bool = False) -> str:
    """Write `text` as `<home>/.claude/rules/rs-instructions.md` in a RUNNING
    container, as uid 1000: "written", "old" (the old /workspace/CLAUDE.md is
    there and nothing was written), "kept" (`keep_existing` and a file is
    there) or "failed". Sends UTF-8 BYTES in binary
    mode (the host's locale must not re-encode the text) and passes their
    count. Never raises."""
    data = text.encode("utf-8")
    try:
        r = subprocess.run(
            ["docker", "exec", "-i", "-u", "1000", "-e", f"HOME={home}", container,
             "sh", "-c", RS_INSTR_SCRIPT, "sh", str(len(data)),
             "1" if check_old else "0", "1" if keep_existing else "0"],
            input=data, capture_output=True, timeout=RS_INSTR_EXEC_TIMEOUT_S)
    except (OSError, subprocess.TimeoutExpired):
        return "failed"
    out = (r.stdout or b"").decode("utf-8", "replace")
    if RS_INSTR_OLD in out:
        return "old"
    if RS_INSTR_KEPT in out and r.returncode == 0:
        return "kept"
    if r.returncode == 0 and RS_INSTR_WRITTEN in out and RS_INSTR_FAILED not in out:
        return "written"
    return "failed"


def _image_instructions_layout(image: str) -> "str | None":
    """The image's INSTRUCTIONS_LAYOUT_LABEL value ("" when it has none);
    None when the inspect fails — an unknown, never "no label"."""
    try:
        r = run(["docker", "image", "inspect", "-f", '{{json .Config.Labels}}', image],
                capture_output=True, timeout=RS_INSTR_EXEC_TIMEOUT_S)
    except (OSError, subprocess.TimeoutExpired, UnicodeDecodeError):
        return None
    if r.returncode != 0:
        return None
    try:
        labels = json.loads(r.stdout or "null")
    except (ValueError, RecursionError):
        return None
    if labels is None:
        return ""
    if not isinstance(labels, dict):
        return None
    v = labels.get(INSTRUCTIONS_LAYOUT_LABEL)
    return v if isinstance(v, str) else ""


def _container_layout_labels(container: str) -> "tuple[str, str] | None":
    """(substrate, project type) from ONE inspect of the container's labels;
    None when the inspect fails (never a default: the existing readers fall
    back to research/dind-sysbox, which would read as "skip" in silence)."""
    try:
        r = run(["docker", "container", "inspect", "-f",
                 '{{json .Config.Labels}}', container],
                capture_output=True, timeout=RS_INSTR_EXEC_TIMEOUT_S)
    except (OSError, subprocess.TimeoutExpired, UnicodeDecodeError):
        return None
    if r.returncode != 0:
        return None
    try:
        labels = json.loads(r.stdout or "null")
    except (ValueError, RecursionError):
        return None
    if labels is None:
        labels = {}
    if not isinstance(labels, dict):
        return None
    sub = labels.get(SUBSTRATE_LABEL)
    typ = labels.get(PROJECT_TYPE_LABEL)
    return (sub if isinstance(sub, str) else "", typ if isinstance(typ, str) else "")


def _project_image_check(project: str, container: str) -> "list[OldInstructions]":
    """After a sandbox-dind re-creation, and before a live agent change checks
    a project's folders (either kind): the container's image must carry
    the current layout label (an image label rides into the container's;
    never the image tag, which a concurrent rebuild can move). A failed read
    is its own error, never "no label"."""
    labels = _container_labels(container)
    if labels is None:
        return [OldInstructions("labels", project)]
    if labels.get(INSTRUCTIONS_LAYOUT_LABEL) != INSTRUCTIONS_LAYOUT_HOME:
        return [OldInstructions("image", project)]
    return []


def _container_labels(container: str) -> "dict | None":
    """The container's labels ({} for none); None when they cannot be read."""
    try:
        r = run(["docker", "container", "inspect", "-f", '{{json .Config.Labels}}',
                 container], capture_output=True, timeout=RS_INSTR_EXEC_TIMEOUT_S)
        if r.returncode != 0:
            return None
        labels = json.loads(r.stdout or "null")
    except (OSError, subprocess.TimeoutExpired, UnicodeDecodeError, ValueError,
            RecursionError):
        return None
    return labels if isinstance(labels, dict) else {}


def _research_instructions_check(project: str, container: str) -> "list[OldInstructions]":
    """After a research recreate: the boot script writes RS's instructions
    itself, unless the container's image is from before that layout (its old
    boot script puts RS's text back into the project's folders: rebuild first)
    or RS's old link /workspace/CLAUDE.md -> .claude/CLAUDE.md still stands.
    Read from the NEW container's labels (an image label rides into them),
    never the image tag, which a concurrent rebuild can move. A failed read is
    its own error, never "no label"."""
    try:
        r = run(["docker", "container", "inspect", "-f", '{{json .Config.Labels}}',
                 container], capture_output=True, timeout=RS_INSTR_EXEC_TIMEOUT_S)
        labels = json.loads(r.stdout or "null") if r.returncode == 0 else ...
    except (OSError, subprocess.TimeoutExpired, UnicodeDecodeError, ValueError,
            RecursionError):
        labels = ...
    if labels is ...:
        return [OldInstructions("labels", project)]
    labels = labels if isinstance(labels, dict) else {}
    if labels.get(INSTRUCTIONS_LAYOUT_LABEL) != INSTRUCTIONS_LAYOUT_HOME:
        return [OldInstructions("image", project)]
    try:
        r = run(["docker", "exec", "-u", "1000", container, "sh", "-c",
                 'if [ -L /workspace/CLAUDE.md ]; then '
                 'printf "LINK:%s\\n" "$(readlink /workspace/CLAUDE.md)"; '
                 'else echo NOLINK; fi'],
                capture_output=True, timeout=RS_INSTR_EXEC_TIMEOUT_S)
    except (OSError, subprocess.TimeoutExpired, UnicodeDecodeError):
        return [OldInstructions("unchecked", project)]
    out = (r.stdout or "").strip() if r.returncode == 0 else ""
    # Only the script's own tokens decide: `docker exec` exits 1 for its own
    # failures too, which must never read as "no link".
    if out == "LINK:.claude/CLAUDE.md":
        return [OldInstructions("research", project)]
    if out == "NOLINK" or out.startswith("LINK:"):
        return []
    return [OldInstructions("unchecked", project)]


def _write_project_instructions(project: str, container: str, workspace_path: "Path",
                                *, progress=None, branch: "str | None" = None,
                                home: str = _AGENT_HOME,
                                has_file: bool = True) -> "list[OldInstructions]":
    """Write RS's instructions into a RUNNING project container (every host
    site: create, recreate, the plain Docker start and recreate, the
    agents-only Update, the live working-mode change, the Config box's agents
    Update). Research is skipped (its boot script writes them), decided from
    the container's labels. Every failure is a warning; an old
    /workspace/CLAUDE.md is RETURNED, never raised here — the operation's
    later steps must still run, and the verb raises once at its end."""
    # Every site that calls this is a project coming up or gaining an agent:
    # the same moment its agents need their wired MCP servers (a no-op, with
    # no docker call, for a project that has no wiring). A research recreate
    # does not come through here; _recreate_supervisor calls it itself.
    mcp_sync_project(project, container, progress=progress)
    labels = _container_layout_labels(container)
    if labels is None:
        _report_warnings([_INSTR_LABELS_UNKNOWN], progress)
        return []
    sub, typ = labels
    if not sub and not typ:
        return []                       # a pre-label research project
    if sub != Substrate.DOCKER.value and typ in ("", PROJECT_TYPE_RESEARCH):
        return []                       # research: its boot script writes it
    try:
        plan = _plan_project_instructions(project, workspace_path, branch=branch)
    except (OSError, ValueError):
        # RS's own text (the notice, the dev template) could not be read: a
        # broken install, never a reason to fail the operation around it.
        _report_warnings([_INSTR_WRITE_FAILED], progress)
        return []
    if plan.text is None:
        tmpl = _INSTR_UNKNOWN_KEEP if has_file else _INSTR_UNKNOWN_NONE
        _report_warnings([tmpl.format(what=plan.what)], progress)
        return []
    outcome = _exec_rs_instructions(container, home, plan.text, check_old=plan.check_old,
                                    keep_existing=plan.keep_existing)
    if outcome == "old":
        return [OldInstructions("project", project)]
    if outcome == "kept":
        _report_warnings([_INSTR_UNKNOWN_KEEP.format(what=plan.what)], progress)
        return []
    if outcome != "written":
        _report_warnings([_INSTR_WRITE_FAILED], progress)
        return []
    if plan.keep_existing:
        _report_warnings([_INSTR_NO_LEDGER], progress)
    if plan.backfill or not plan.cleared:
        def mutate(d: dict) -> None:
            for k, v in plan.backfill.items():
                if k not in d:
                    d[k] = v
            d[OLD_INSTRUCTIONS_FLAG] = True
        try:
            _marker_rmw(workspace_path, mutate, "record RS's instructions")
        except _MARKER_WRITE_ERRORS:
            _report_warnings([_INSTR_FLAG_FAILED], progress)
    return []


def _old_path_present(root: "Path", rel: str) -> bool:
    """Whether `rel` is there below `root`, walked without following anything
    (the folders are the project's own): absent → False; a link at any
    component → True (a link counts as present, whatever it points to); the
    final component in any form → True; a component that is not a folder →
    False (nothing can be below it); any other error → True (never read as
    "absent"). The box tool walks a box's folder the same way."""
    parts = rel.split("/")
    try:
        fd = os.open(root, os.O_PATH | os.O_DIRECTORY | os.O_NOFOLLOW)
    except FileNotFoundError:
        return False
    except OSError:
        return True
    try:
        for i, part in enumerate(parts):
            try:
                st = os.stat(part, dir_fd=fd, follow_symlinks=False)
            except (FileNotFoundError, NotADirectoryError):
                return False
            except OSError:
                return True
            if stat.S_ISLNK(st.st_mode) or i == len(parts) - 1:
                return True
            if not stat.S_ISDIR(st.st_mode):
                return False
            try:
                nfd = os.open(part, os.O_PATH | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=fd)
            except OSError:
                return True
            os.close(fd)
            fd = nfd
        return False
    finally:
        os.close(fd)


def _listed_names(root: "Path", rel: str) -> "list[tuple[str, bool]]":
    """[(name, is a real folder)] in root/rel, opened without following a
    link (a link at rel lists nothing: its paths are reported by the fixed
    probes); names that are not plain file names are skipped."""
    out: list[tuple[str, bool]] = []
    try:
        fd = os.open(root, os.O_PATH | os.O_DIRECTORY | os.O_NOFOLLOW)
    except OSError:
        return out
    try:
        try:
            dfd = os.open(rel, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=fd)
        except OSError:
            return out
        try:
            for name in sorted(os.listdir(dfd)):
                if not _OLD_NAME_RE.match(name) or name in (".", ".."):
                    continue
                try:
                    st = os.stat(name, dir_fd=dfd, follow_symlinks=False)
                except OSError:
                    continue
                out.append((name, stat.S_ISDIR(st.st_mode)))
        finally:
            os.close(dfd)
    finally:
        os.close(fd)
    return out


def _project_old_files(workspace_path: "Path", *, research: bool) -> list[str]:
    """The paths RS used to write into a project's own folders that are still
    there: the project agent's /ok copies, and for a research project its
    settings, /log command, logbook templates, the retired PI containers'
    credential stash and the upgrade tool's copies. Host-side, never
    following a link."""
    rels = PROJECT_OLD_PATHS + (RESEARCH_OLD_PATHS if research else ())
    found = [r for r in rels if _old_path_present(workspace_path, r)]
    if research:
        for role, is_dir in _listed_names(workspace_path, ".pi"):
            if is_dir:
                found += [f".pi/{role}/.creds/{f}" for f in RESEARCH_OLD_CREDS
                          if _old_path_present(workspace_path, f".pi/{role}/.creds/{f}")]
        found += [f".claude/{n}" for n, _d in _listed_names(workspace_path, ".claude")
                  if n.endswith(OLD_UPGRADE_SUFFIX)]
    return found


def _project_files_check(project: str, workspace_path: "Path", *, research: bool,
                         progress=None) -> "list[OldInstructions]":
    """Check a sandbox-dind or research project's own folders for the files RS
    used to write there, until the record's flag says none was left. Found →
    RETURNED (the verb raises once at its end; RS writes no new copy, the box
    tool reads the flag before writing the project agent's home skills); none
    → the flag is set. An unreadable record checks nothing (a warning)."""
    state, data = _read_marker_three_way(workspace_path)
    if state != "ok":
        _report_warnings([_FILES_UNKNOWN], progress)
        return []
    if data.get(OLD_FILES_FLAG) is True:
        return []
    found = _project_old_files(workspace_path, research=research)
    if found:
        return [OldInstructions("files", project, paths=tuple(found))]

    def mutate(d: dict) -> None:
        d[OLD_FILES_FLAG] = True
    try:
        _marker_rmw(workspace_path, mutate, "record the project's folders as checked")
    except _MARKER_WRITE_ERRORS:
        _report_warnings([_FILES_FLAG_FAILED], progress)
    return []


def _box_tool_home_skills(project: str, container: str, args: "Sequence[str]" = (),
                          progress=None) -> "list[OldInstructions]":
    """Run `rs-sandbox home-skills` in the project: RS's skills into the
    project agent's home (and with --boxes / --box, into the boxes' homes).
    Its warnings become warning steps; a box's old files come back as items
    the verb raises at its end. An older box tool, or one that cannot run, is
    a warning: never this operation's failure."""
    try:
        r = run(["docker", "exec", container, "rs-sandbox", "home-skills", *args],
                capture_output=True)
    except (OSError, UnicodeDecodeError):
        _report_warnings([_FILES_SKILLS_FAILED], progress)
        return []
    if _is_old_box_tool(r):
        _report_warnings([_OLD_BOX_TOOL_FILES_MSG], progress)
        return []
    if r.returncode != 0:
        _report_warnings([_FILES_SKILLS_FAILED], progress)
        return []
    raw = _parse_box_tool_json(r.stdout).get("warnings")
    found: list[OldInstructions] = []
    lines: list[str] = []
    for w in raw if isinstance(raw, list) else []:
        if not isinstance(w, dict):
            continue
        if w.get("kind") == "old-files":
            found.append(OldInstructions("box-files", project, str(w.get("box") or ""),
                                         paths=_box_old_paths_of(w)))
            continue
        lines += _box_folder_warnings([w], w.get("box"))
    _report_warnings(lines, progress)
    return found


def _agent_settings_block(data: dict) -> "dict | None":
    blk = data.get("agent_settings")
    return blk if isinstance(blk, dict) else None


def _pending_fields(blk: "dict | None") -> dict:
    """{agent: [halves]} of the pending agents that owe only some halves (an
    agent pending without an entry owes its whole pair)."""
    f = (blk or {}).get("fields")
    if not isinstance(f, dict):
        return {}
    return {a: [x for x in v if isinstance(x, str)] for a, v in f.items()
            if a in ("claude", "pi") and isinstance(v, list)}


def _add_pending(data: dict, owed: "dict[str, Sequence[str] | None]") -> None:
    """Mark the agents in `owed` as owing a settings write at the next deploy;
    each maps to the halves it owes (None: the whole pair). Marks merge: an
    agent already owing its whole pair keeps owing it."""
    blk = _agent_settings_block(data) or {}
    pending = [a for a in blk.get("pending", []) if a in ("claude", "pi")] \
        if isinstance(blk.get("pending"), list) else []
    fields = _pending_fields(blk)
    for a, halves in owed.items():
        whole = a in pending and a not in fields
        if a not in pending:
            pending.append(a)
        if halves is None or whole:
            fields.pop(a, None)
        else:
            fields[a] = sorted(set(fields.get(a, [])) | set(halves))
    out = {"v": 1, "pending": pending, "migrated": bool(blk.get("migrated"))}
    if fields:
        out["fields"] = fields
    data["agent_settings"] = out


def _apply_agent_settings_pending(container: str, workspace_path: "Path",
                                  local: "Sequence[str]", *, claude_in_settings: bool,
                                  progress=None, home: str = _AGENT_HOME) -> None:
    """Write the recorded model of every agent marked pending into its settings
    file in the running `container` — called right after the agents are
    deployed (create, every start, an add) and after a live change. `local`:
    the agents installed in this container. A project created before this
    (its record not yet `migrated`) is migrated once: its recorded Claude pair
    is written only where Claude's file has no model yet, so a choice made
    inside Claude is kept. Never raises — it runs in the middle of a start."""
    try:
        data = _read_marker_dict(workspace_path)
        if not data:
            return
        blk = _agent_settings_block(data)
        pending = set(a for a in (blk or {}).get("pending", []) if a in ("claude", "pi")) \
            if isinstance((blk or {}).get("pending"), list) else set()
        models = data.get("models") if isinstance(data.get("models"), dict) else {}
        claude_pair = models.get("supervisor") if isinstance(models.get("supervisor"), dict) else None
        pi_blk = data.get("pi_models") if isinstance(data.get("pi_models"), dict) else {}
        pi_pair = pi_blk.get("agent") if isinstance(pi_blk.get("agent"), dict) else None
        done: set[str] = set()
        fields = _pending_fields(blk)
        migrate_now = (claude_in_settings and DEFAULT_AGENT in local
                       and not (blk or {}).get("migrated"))
        migrated = False
        for agent in ("claude", "pi"):
            if agent not in local or (agent == "claude" and not claude_in_settings):
                continue
            pair = claude_pair if agent == "claude" else pi_pair
            if agent not in pending:
                # The one-time migration of an older project's Claude pair:
                # written only where Claude's file has no model yet. Counted
                # as done only once the file was read (a failed read retries
                # at the next deploy).
                if not (agent == "claude" and migrate_now):
                    continue
                cur = _read_agent_settings(container, "claude", home)
                if cur is None:
                    continue
                # Migrate exactly what the old container setting delivered: the
                # model when one is recorded (kept as the file has it when a
                # /model choice is already there), the effort only alongside a
                # recorded model with a recorded effort (_model_env_args emits
                # nothing else) — never a clear of something it never set.
                rec_m = (claude_pair or {}).get("model") or ""
                rec_e = (claude_pair or {}).get("effort") or ""
                halves = []
                if rec_m and "model" not in cur:
                    halves.append("model")
                if rec_m and rec_e:
                    halves.append("effort")
                if not halves or _write_agent_settings(container, agent, pair, home,
                                                       halves) == "ok":
                    migrated = True
                continue
            res = _write_agent_settings(container, agent, pair, home, fields.get(agent))
            if res == "ok":
                done.add(agent)
                if agent == "claude":
                    migrated = True     # the record's pair is in the file now
            else:
                _report_warnings([_AGENT_SETTINGS_WARNING.format(agent=agent)], progress)
        if not done and not migrated:
            return

        def mutate(d: dict) -> None:
            b = _agent_settings_block(d) or {}
            left = [a for a in (b.get("pending") or []) if a in ("claude", "pi") and a not in done] \
                if isinstance(b.get("pending"), list) else []
            f = {a: v for a, v in _pending_fields(b).items() if a in left}
            out = {"v": 1, "pending": left, "migrated": bool(b.get("migrated")) or migrated}
            if f:
                out["fields"] = f
            d["agent_settings"] = out
        _marker_rmw(workspace_path, mutate, "record the applied agent settings")
    except Exception as e:     # never stop a start over a settings write
        _report_warnings([f"the agents' recorded models could not be applied ({e})"], progress)


def _clear_pending(workspace_path: "Path", agents: "Sequence[str]",
                   mark_migrated: bool = False) -> None:
    """Drop `agents` from the pending marks (their record is in the files
    already); `mark_migrated` also records the one-time migration as done (a
    fresh home whose first boot merged the whole record). Never raises."""
    def mutate(d: dict) -> None:
        b = _agent_settings_block(d) or {}
        left = [a for a in (b.get("pending") or []) if a not in agents] \
            if isinstance(b.get("pending"), list) else []
        f = {a: v for a, v in _pending_fields(b).items() if a in left}
        out = {"v": 1, "pending": left, "migrated": bool(b.get("migrated")) or mark_migrated}
        if f:
            out["fields"] = f
        d["agent_settings"] = out
    try:
        data = _read_marker_dict(workspace_path)
        if data and (_agent_settings_block(data) is not None or mark_migrated):
            _marker_rmw(workspace_path, mutate, "record the applied agent settings")
    except Exception:
        pass


def _agent_settings_owed(workspace_path: "Path") -> bool:
    """Whether the record owes a settings write (a pending agent, or the
    one-time migration of a recorded Claude model) — read from the file alone,
    so a start with nothing owed makes no container call."""
    data = _read_marker_dict(workspace_path)
    blk = _agent_settings_block(data)
    if blk and isinstance(blk.get("pending"), list) and blk["pending"]:
        return True
    models = data.get("models") if isinstance(data.get("models"), dict) else {}
    sup = models.get("supervisor") if isinstance(models.get("supervisor"), dict) else {}
    return not (blk or {}).get("migrated") and bool(sup.get("model"))


def _uninstall_claude_extension(container: str, home: str = _AGENT_HOME) -> None:
    """Remove Claude Code's editor extension from the project's editor when the
    project's own container no longer runs Claude (its extensions live in the
    workspace and survive a restart). A no-op without an editor or the
    extension; never raises."""
    script = (f'cs="{home}/.local/bin/code-server"; [ -x "$cs" ] || exit 0\n'
              f'U="{_CS_USER_DIR}"; E="$U/extensions"\n'
              f'set -- "$E/{CLAUDE_EXT_ID}-"[0-9]*; [ -e "$1" ] || exit 0\n'
              f'"$cs" --uninstall-extension {CLAUDE_EXT_ID} --extensions-dir "$E" '
              f'--user-data-dir "$U" >/dev/null 2>&1 || true\n')
    try:
        run(["docker", "exec", "-u", "1000", "-e", f"HOME={home}", container, "sh", "-c", script],
            capture_output=True)
    except OSError:
        pass


@dataclass
class _AgentSettingsPlan:
    """What an update changes in the agents' settings (built and checked before
    any write; see _agent_settings_plan)."""
    claude: "dict | None" = None        # the new recorded Claude pair, or None
    claude_live: bool = False           # written into the settings file (not via a recreate)
    claude_fields: "list[str]" = field(default_factory=list)   # the halves asked ("model", "effort")
    pi_fields: "list[str]" = field(default_factory=list)       # ("model", "thinking")
    pi: "dict | None" = None            # the new pi pair ({} = cleared), or None
    harness: "dict | None" = None       # the new harness map, or None
    agents_new: "list[str] | None" = None
    removed: list[str] = field(default_factory=list)
    effort_dropped: bool = False

    def any(self) -> bool:
        return (self.claude is not None or self.pi is not None or self.harness is not None
                or bool(self.removed))


def _project_running_agents(workspace_path: "Path") -> list[str]:
    """The agents in the project's own container, from its record: the docker
    substrate runs exactly its record, research runs Claude, Docker-in-Docker
    runs _dind_agent_sets' local set — which, for a record from before the
    exact sets, includes Claude whenever any agent is recorded. A removal is
    judged against this (never the bare record), and the CLI builds its
    request from it, so the two agree with the panel (`agents_local`)."""
    data = _read_marker_dict(workspace_path)
    if data.get("substrate") == Substrate.DOCKER.value:
        return list(_read_marker_agents(workspace_path))
    if data.get("type") != PROJECT_TYPE_SANDBOX_DIND:
        return [DEFAULT_AGENT]
    return _dind_agent_sets(data)[1]


def _workflow_is_dev(data: dict) -> bool:
    """The project's workflow carries the `dev` flag (tolerant: an unknown
    workflow reads as no)."""
    wf = data.get("workflow")
    if not isinstance(wf, str) or not wf:
        return False
    try:
        manifest, _pt, _sub = _resolve_workflow(wf)
    except (ValidationError, SystemExit, OSError, ValueError):
        return False
    return bool(manifest.get("dev"))


def _agent_settings_plan(req: "UpdateRequest", container: str, workspace_path: "Path",
                         *, docker: bool, claude_in_settings: bool) -> _AgentSettingsPlan:
    """Check an update's agent-settings half against the project (its marker,
    workflow, agents and boxes) and return what it changes. Raises
    ValidationError before anything is written. Texts reach the browser
    verbatim: they name the panel's fields, never a command."""
    plan = _AgentSettingsPlan()
    reset = set(req.reset)
    claude_asked = bool(req.supervisor_model or req.supervisor_effort
                        or reset & {"supervisor_model", "supervisor_effort"})
    pi_asked = bool(req.pi_model or req.pi_thinking or reset & {"pi_model", "pi_thinking"})
    harness_asked = any(getattr(req, f) for f in HARNESS_FIELDS) or bool(reset & set(HARNESS_FIELDS))
    if not (claude_asked or pi_asked or harness_asked or req.agents is not None):
        return plan
    data = _read_marker_dict(workspace_path)
    if not data:
        why = ""
        try:
            _read_marker_text(workspace_path)
        except orch_files.Unusable as e:
            why = f" ({e})"         # a link: name the settings folder
        except (OSError, ValueError):
            pass
        raise ValidationError("cannot change the agents: the project's record is missing "
                              f"or unreadable{why}")
    is_research = (not docker) and data.get("type") != PROJECT_TYPE_SANDBOX_DIND
    current = list(_read_marker_agents(workspace_path))
    new_agents = list(req.agents) if req.agents is not None else current
    # What runs in the project's own container now (see _project_running_agents).
    running_now = _project_running_agents(workspace_path)
    # Removal (I33 slice 3).
    removed = ([a for a in running_now if a not in new_agents]
               if req.agents is not None else [])
    if docker:
        local = new_agents
    elif is_research:
        local = [DEFAULT_AGENT]
    else:
        hypo = dict(data)
        hypo["agents"] = new_agents
        if removed:
            hypo["agents_exact"] = True
        _staged, local = _dind_agent_sets(hypo)
    dev = _workflow_is_dev(data)
    if removed:
        if docker or is_research:
            raise ValidationError("this project's agents are fixed when it is created")
        if dev and not new_agents:
            raise ValidationError("a dev project needs at least one agent")
        if "pi" in removed:
            try:
                boxes = sorted(n for n, e in extension.load(workspace_path).items()
                               if isinstance(e, dict) and e.get("agent") == "pi")
            except Exception:
                boxes = []
            if boxes:
                raise ValidationError(
                    f"pi cannot be removed while these boxes run it: {', '.join(boxes)}; "
                    f"remove those boxes first")
        plan.removed = removed
        plan.agents_new = new_agents
    # Claude's model and effort.
    if claude_asked:
        if DEFAULT_AGENT not in local:
            raise ValidationError("the project's own terminal does not run Claude")
        models = _read_models(workspace_path)
        old = dict(models.get("supervisor") or {}) if isinstance(models.get("supervisor"), dict) else {}
        m = req.supervisor_model or ("" if "supervisor_model" in reset else old.get("model", ""))
        e = req.supervisor_effort or ("" if "supervisor_effort" in reset else old.get("effort", ""))
        catalog = _model_catalog_checked()
        if e and not _claude_effort_ok(m, e, catalog):
            if req.supervisor_effort:
                raise ValidationError(f"model {m!r} does not accept an effort level")
            e = ""
            plan.effort_dropped = True
        plan.claude = {"model": m, "effort": e}
        plan.claude_live = claude_in_settings
        plan.claude_fields = [h for h, asked in (
            ("model", req.supervisor_model or "supervisor_model" in reset),
            ("effort", req.supervisor_effort or "supervisor_effort" in reset
             or plan.effort_dropped)) if asked]
    # pi's starting model.
    if pi_asked:
        if is_research:
            raise ValidationError("a research project runs Claude only")
        if "pi" not in local:
            raise ValidationError("the project's own terminal does not run pi")
        blk = data.get("pi_models") if isinstance(data.get("pi_models"), dict) else {}
        old = dict(blk.get("agent") or {}) if isinstance(blk.get("agent"), dict) else {}
        m = req.pi_model or ("" if "pi_model" in reset else old.get("model", ""))
        t = req.pi_thinking or ("" if "pi_thinking" in reset else old.get("thinking", ""))
        plan.pi = {"model": m, "thinking": t} if (m or t) else {}
        plan.pi_fields = [h for h, asked in (
            ("model", req.pi_model or "pi_model" in reset),
            ("thinking", req.pi_thinking or "pi_thinking" in reset)) if asked]
    # The working mode and the doer/checker models.
    if harness_asked or removed:
        old_h = _read_harness(workspace_path)
        new_h = dict(old_h)
        for f in HARNESS_FIELDS:
            v = getattr(req, f)
            if v:
                new_h[f] = v
            elif f in reset:
                new_h.pop(f, None)
        # A removed agent's doer/checker models go with it.
        if DEFAULT_AGENT in removed:
            for f in _HARNESS_CLAUDE:
                new_h.pop(f, None)
        if "pi" in removed:
            for f in _HARNESS_PI:
                new_h.pop(f, None)
        if harness_asked:
            if is_research:
                raise ValidationError("the working mode and the Doer and Checker models are "
                                      "for dev projects and dev boxes")
            set_now = {f: getattr(req, f) for f in HARNESS_FIELDS}
            _validated_harness(set_now, dev=dev, agents=local)
        if new_h != old_h:
            plan.harness = new_h
    if "pi" in removed and plan.pi is None:
        blk = data.get("pi_models")
        if isinstance(blk, dict) and blk.get("agent"):
            plan.pi = {}
    return plan


def _agent_settings_commit(plan: _AgentSettingsPlan, workspace_path: "Path") -> None:
    """Write the plan into the project's record (one read-modify-write), with
    every changed agent marked pending: the live apply, the add or the next
    start writes it into the agent's own file and clears the mark."""
    if not plan.any():
        return

    def mutate(d: dict) -> None:
        owed: dict = {}
        if plan.claude is not None:
            models = d.get("models") if isinstance(d.get("models"), dict) else {}
            models = dict(models)
            models["supervisor"] = dict(plan.claude)
            d["models"] = models
            # Owed even when this container cannot take it (an older image):
            # the mark is consumed only where the file is the channel, so it
            # waits for the first start on a current image — and is never
            # lost to the one-time migration.
            # A project not yet migrated owes the WHOLE pair: its container
            # delivered both halves until now, and the first start on a
            # current image drops that container setting.
            migrated = bool((_agent_settings_block(d) or {}).get("migrated"))
            owed["claude"] = (plan.claude_fields or None) if migrated else None
        if plan.pi is not None:
            blk = dict(d.get("pi_models")) if isinstance(d.get("pi_models"), dict) else {}
            if plan.pi:
                blk["agent"] = dict(plan.pi)
            else:
                blk.pop("agent", None)
            if blk:
                d["pi_models"] = blk
            else:
                d.pop("pi_models", None)
            if "pi" not in plan.removed:
                owed["pi"] = plan.pi_fields or None
        if plan.harness is not None:
            if plan.harness:
                d["harness"] = dict(plan.harness)
            else:
                d.pop("harness", None)
        if plan.agents_new is not None:
            d["agents"] = list(dict.fromkeys(plan.agents_new))
            d["agents_exact"] = True
        if owed:
            _add_pending(d, owed)
    _marker_rmw(workspace_path, mutate, "change the agents")


@dataclass(frozen=True)
class ProjectAgentsRequest:
    """Read what a project's agents run, for the ⚙ Agents box."""
    project: str

    @classmethod
    def from_kwargs(cls, **kw: Any) -> "ProjectAgentsRequest":
        return cls(project=_require_name(kw.get("project")))


def _clean_claude_model(v: Any) -> tuple[str, bool]:
    """(value, unrecognised): a string held to CLAUDE_MODEL_RE, else ("", True)."""
    if not isinstance(v, str) or not v:
        return "", False
    return (v, False) if CLAUDE_MODEL_RE.match(v) else ("", True)


def _claude_effective(settings: "dict | None", env: dict) -> dict:
    """What Claude will run, in Claude's own order (measured, 2.1.258): the
    settings file's `env` entries, then the container's environment, then the
    file's `model`; for effort the same two environments, then the per-model
    level `/effort` saves, then the file's `effortLevel`. A present but empty
    `env` entry in the file hides the container's (a project migrated by a
    panel write). Values failing the character set read as unrecognised."""
    st = settings if isinstance(settings, dict) else {}
    senv = st.get("env") if isinstance(st.get("env"), dict) else {}

    def layered(key: str, file_value: Any) -> Any:
        if key in senv:
            return senv[key] or file_value
        return env.get(key) or file_value
    model, bad_m = _clean_claude_model(layered("ANTHROPIC_MODEL", st.get("model")))
    ms = st.get("modelSettings") if isinstance(st.get("modelSettings"), dict) else {}
    per = ms.get(model) if model and isinstance(ms.get(model), dict) else {}
    file_effort = per.get("effortLevel") or st.get("effortLevel")
    effort = layered("CLAUDE_CODE_EFFORT_LEVEL", file_effort)
    bad_e = False
    if not isinstance(effort, str) or (effort and effort not in (*CLAUDE_SETTINGS_EFFORTS, "max")):
        bad_e, effort = bool(effort), ""
    return {"model": model, "effort": effort, "unrecognised": bad_m or bad_e}


def _pi_effective(settings: "dict | None") -> dict:
    """pi's starting model and thinking level from its settings file."""
    st = settings if isinstance(settings, dict) else {}
    p, m, t = st.get("defaultProvider"), st.get("defaultModel"), st.get("defaultThinkingLevel")
    model = f"{p}/{m}" if isinstance(p, str) and isinstance(m, str) and p and m else ""
    bad = False
    if model and not PI_MODEL_RE.match(model):
        model, bad = "", True
    if not isinstance(t, str) or t not in PI_THINKING_LEVELS:
        bad, t = bad or bool(t), ""
    return {"model": model, "thinking": t, "unrecognised": bad}


def _container_env(container: str) -> dict:
    """The container's own environment (KEY → value), or {}."""
    try:
        r = run(["docker", "container", "inspect", "-f", "{{json .Config.Env}}", container],
                capture_output=True, timeout=AGENT_SETTINGS_EXEC_TIMEOUT_S)
    except (OSError, subprocess.TimeoutExpired):
        return {}
    if r.returncode != 0:
        return {}
    try:
        items = json.loads(r.stdout)
    except json.JSONDecodeError:
        return {}
    out = {}
    for it in items if isinstance(items, list) else []:
        if isinstance(it, str) and "=" in it:
            k, _, v = it.partition("=")
            out[k] = v
    return out


def project_agents(req: ProjectAgentsRequest, _progress=None) -> dict:
    """The ⚙ Agents box's read: the project's kind, its agents (recorded,
    in its own container, in the copy its boxes use), and what each agent
    runs. A running project's models are read from the agents' own settings
    files — so a model picked inside the agent shows up — and a stopped one's
    from the record. Values are held to the panel's character sets."""
    cfg = load_config()
    container = container_name_for(req.project)
    if not container_exists(container):
        raise ValidationError(f"no project named {req.project!r}")
    ws = workspace_path_for(req.project, cfg)
    data = _read_marker_dict(ws)
    docker = data.get("substrate") == Substrate.DOCKER.value
    research = not docker and data.get("type") != PROJECT_TYPE_SANDBOX_DIND
    agents = [a for a in _read_marker_agents(ws) if a in KNOWN_AGENTS]
    if docker:
        staged, local = list(agents), list(agents)
    elif research:
        staged, local = [DEFAULT_AGENT], [DEFAULT_AGENT]
    else:
        staged, local = _dind_agent_sets(data)
    running = container_running(container)
    models = data.get("models") if isinstance(data.get("models"), dict) else {}
    out: dict = {
        "project": req.project, "running": running,
        "kind": "docker" if docker else ("research" if research else "dind"),
        "dev": _workflow_is_dev(data), "agents": agents,
        "agents_local": local, "agents_staged": staged,
        "model_in_settings": _label_is_set("container", container),
        "harness": _read_harness(ws),
    }
    env = _container_env(container) if running else {}
    if DEFAULT_AGENT in local:
        rec = models.get("supervisor") if isinstance(models.get("supervisor"), dict) else {}
        if running and out["model_in_settings"]:
            out["claude"] = {**_claude_effective(_read_agent_settings(container, "claude"), env),
                             "source": "settings"}
        elif running:
            out["claude"] = {**_claude_effective(None, env), "source": "container"}
        else:
            out["claude"] = {**_claude_effective({"model": rec.get("model"),
                                                  "effortLevel": rec.get("effort")}, {}),
                             "source": "saved"}
    if "pi" in local:
        rec = (data.get("pi_models") or {}).get("agent") if isinstance(data.get("pi_models"), dict) else None
        if running:
            out["pi"] = {**_pi_effective(_read_agent_settings(container, "pi")), "source": "settings"}
        else:
            m = rec.get("model", "") if isinstance(rec, dict) else ""
            p, _, rest = m.partition("/") if isinstance(m, str) else ("", "", "")
            out["pi"] = {**_pi_effective({"defaultProvider": p, "defaultModel": rest,
                                          "defaultThinkingLevel": (rec or {}).get("thinking")}),
                         "source": "saved"}
    if research:
        out["research_models"] = {t: {"model": (models.get(t) or {}).get("model", ""),
                                      "effort": (models.get(t) or {}).get("effort", "")}
                                  for t in ("worker", "role") if isinstance(models.get(t), dict)}
    out["boxes"], out["boxes_state"] = ([], "none") if docker else \
        _project_agent_boxes(container, running, research, ws)
    return out


def _project_agent_boxes(container: str, running: bool, research: bool,
                         ws: "Path") -> tuple[list, str]:
    """The project's boxes that run an agent, for the ⚙ Box agents section:
    (rows, state) — state "ok", "stopped" (the project is), "old-tool" (a box
    tool from before this) or "unavailable". Each row: name, agent, dev,
    running, whether its working mode can change, its Claude model/effort
    (what the box runs — its settings file under its container variables, the
    entry when it is not running) and its working-mode fields (re-checked; the
    record is writable from inside the project). A project with no agent box
    (its record says so — a box-less research project has no box tool at all)
    reads as "ok" with no rows and costs no call. Never raises."""
    try:
        recorded = extension.load(ws)
    except (OSError, ValueError, RecursionError):
        recorded = {}
    n = sum(1 for e in (recorded.values() if isinstance(recorded, dict) else [])
            if isinstance(e, dict) and e.get("kind") == extension.SANDBOX_KIND
            and e.get("agent", "none") != "none")
    if not n:
        return [], "ok"
    if not running:
        return [], "stopped"
    # The box tool makes two bounded execs per agent box (its state + its
    # settings file); one more bound covers its own start and record read.
    try:
        r = run(["docker", "exec", container, "rs-sandbox", "agents"],
                capture_output=True, timeout=AGENT_SETTINGS_EXEC_TIMEOUT_S * (2 * n + 1))
    except (OSError, subprocess.TimeoutExpired, UnicodeDecodeError):
        return [], "unavailable"
    if r.returncode != 0:
        return [], ("old-tool" if _is_old_box_tool(r) else "unavailable")
    try:
        raw = json.loads(r.stdout or "[]")
    except (ValueError, RecursionError):
        return [], "unavailable"
    rows = []
    for b in raw if isinstance(raw, list) else []:
        if not isinstance(b, dict):
            continue
        name, agent = b.get("name"), b.get("agent")
        if not (isinstance(name, str) and _BOX_NAME_RE.match(name)) or agent not in KNOWN_AGENTS:
            continue
        h = b.get("harness") if isinstance(b.get("harness"), dict) else {}
        harness = {}
        for f in HARNESS_FIELDS:
            v = h.get(f)
            if isinstance(v, str) and v and not (f == "harness_mode" and v == "none"):
                try:
                    _harness_shape({f: v})
                    harness[f] = v
                except Exception:
                    pass
        row = {"name": name, "agent": agent, "dev": b.get("dev") is True,
               "running": b.get("running") is True,
               "mode_editable": b.get("dev") is True and not research,
               "harness": harness}
        if agent == "claude":
            env = b.get("env") if isinstance(b.get("env"), dict) else {}
            env = {k: v for k, v in env.items() if isinstance(v, str)}
            settings = None
            text = b.get("settings")
            if row["running"] and isinstance(text, str) and len(text) <= AGENT_SETTINGS_MAX_BYTES:
                try:
                    settings = json.loads(text)
                except (ValueError, RecursionError):
                    settings = None
            if row["running"]:
                row["claude"] = {**_claude_effective(settings, env), "source": "settings"}
            else:
                row["claude"] = {**_claude_effective({"model": b.get("model"),
                                                      "effortLevel": b.get("effort")}, {}),
                                 "source": "saved"}
        rows.append(row)
    return rows, "ok"


def _read_marker_substrate(workspace_path: "Path") -> str:
    """The substrate stamped into .orchestrator/project.json at create. Tolerant
    (the _read_marker_agents shape): a missing/unreadable marker or key reads as
    dind-sysbox, the substrate every pre-docker marker meant (a link reads as
    unreadable — orch_files)."""
    try:
        data = json.loads(_read_marker_text(workspace_path))
    except (OSError, json.JSONDecodeError):
        return Substrate.DIND_SYSBOX.value
    sub = data.get("substrate") if isinstance(data, dict) else None
    return sub if isinstance(sub, str) else Substrate.DIND_SYSBOX.value


def project_add_agents(project: str, agents: "Sequence[str]",
                       cfg: "Config" | None = None, progress=None) -> "UpdateResult":  # type: ignore[name-defined]
    """`project update-agent [--agent X]` (CLI) and the browser's Update: bring a
    RUNNING project's agents level with the host's cached downloads, live — no
    recreate. An invocation that ADDS an agent is an Add, routed through
    update()'s live agents-only branch; one that adds nothing (no agent, or only
    agents the project carries) is an Update: re-stage the project's set, deploy
    it into the supervisor's own home, refresh every running agent-bearing box,
    and force the editor extension back to the shipped version.
    The docker substrate (a plain runc box, its set fixed at create) takes the
    streamed transfer (its agent mounts go stale after a Pull) and has no boxes.
    The substrate and the agent set come from the project MARKER (the container's
    agent label does not survive an editor-toggle recreate)."""
    progress = progress or _NULL_PROGRESS
    if cfg is None:
        cfg = load_config()
    container = container_name_for(project)
    if not container_exists(container):
        die(f"project {project!r} does not exist")
    if not container_running(container):
        die(f"project {project!r} is not running — start it first")
    workspace_path = workspace_path_for(project, cfg)
    marker_agents = list(_read_marker_agents(workspace_path))
    if _read_marker_substrate(workspace_path) == Substrate.DOCKER.value:
        if any(a not in marker_agents for a in agents):
            die("the agent set is fixed at create on the docker substrate "
                "(a plain runc box); recreate the project to change it; to update its "
                "agents to the cached versions, use Update in the project's Config box")
        if not marker_agents:
            die("this project has no agents to update")
        _refuse_during_agent_build()
        progress.step("agents", f"deploying {'+'.join(marker_agents)} into the project")
        _report_warnings(_stage_agent_dist(container, marker_agents, docker=True,
                                           **_pi_pair_kwargs(workspace_path)), progress)
        # RS's instructions into the agent's home (it survives this Update).
        found = _write_project_instructions(project, container, workspace_path,
                                            progress=progress, has_file=True)
        if not _install_agent_extensions(
                ["docker", "exec", "-u", "1000", "-e", "HOME=/home/research", container],
                "/home/research", True):
            progress.step("agents", "the project's editor extension could not be installed")
        _raise_old_instructions(found)
        return UpdateResult(project=project, rebuilt=False)
    is_research = _container_project_type(container) != PROJECT_TYPE_SANDBOX_DIND
    # Membership is against the MARKER (research: claude by construction), not
    # the floored stage set — else `--agent claude` on an agent-less sandbox-dind
    # project would read as "already carried" and never wire the supervisor.
    carried = [DEFAULT_AGENT] if is_research else marker_agents
    if agents and not all(a in carried for a in agents):
        req = UpdateRequest.from_kwargs(name=project, agents=marker_agents + list(agents))
        return update(req, cfg, progress=progress)
    _refuse_during_agent_build()
    # The staged set feeds the shared copy and the boxes; the local set is what
    # the supervisor's own home gets (research: claude, both).
    staged, local = (([DEFAULT_AGENT], [DEFAULT_AGENT]) if is_research
                     else _read_dind_agent_sets(workspace_path))
    deploy_local = bool(local)
    progress.step("agents", f"staging {'+'.join(staged)} into the project")
    _report_warnings(_stage_agent_dist(container, staged, deploy_local=deploy_local,
                                       **_local_deploy_kwargs(staged, local),
                                       **_pi_pair_kwargs(workspace_path)), progress)
    if not is_research:
        # The working-mode suite (I33), before the box refresh below runs its
        # installer in each box. Never research (its boxes must find none).
        _report_warnings(_stage_harness(container, local, workspace_path), progress)
    # RS's instructions into the agent's home (it survives this Update;
    # research is skipped inside — its boot script writes them).
    found = _write_project_instructions(project, container, workspace_path,
                                        progress=progress, has_file=True)
    if deploy_local and not _install_agent_extensions(
            ["docker", "exec", "-u", "1000", "-e", "HOME=/home/research", container],
            "/home/research", True):
        progress.step("agents", "the project's editor extension could not be installed")
    refreshed, not_refreshed = _refresh_running_boxes(container, staged, progress, force_ext=True)
    # RS's skills into the agents' homes after the agent copy (pi just added
    # gets them, in the project agent and every box), once the project's own
    # folders were checked for the files RS used to write there — only on a
    # container whose image carries the current layout (an older one's boot
    # puts the files back; the start path gates the same way).
    image_items = _project_image_check(project, container)
    found += image_items
    if not image_items:
        found += _project_files_check(project, workspace_path, research=is_research,
                                      progress=progress)
    found += _box_tool_home_skills(project, container, ["--boxes"], progress)
    _raise_old_instructions(found)
    return UpdateResult(project=project, rebuilt=False,
                        boxes_refreshed=refreshed, boxes_not_refreshed=not_refreshed)


def _read_models(workspace_path: "Path") -> dict[str, dict[str, str]]:
    """The project's frozen per-type (model, effort) pairs from
    .orchestrator/project.json, or {} for a pre-STAGE_MODEL_SELECT project.

    {} means EMIT NO FLAGS — it deliberately does NOT fall back to the catalog
    defaults, so an existing project keeps behaving exactly as it does today on
    its next recreate instead of silently acquiring a model it never had
    (greenfield: old projects are disposable, but they must not change under you).

    Every pair in here is already RESOLVED and mutually valid (see
    _resolve_all_model_pairs) — that is the contract the in-supervisor readers
    (rs-worker, rs-sandbox) depend on, since they read it verbatim and have no
    catalog to validate against. A link at the marker or at the settings
    folder reads as unreadable (orch_files)."""
    try:
        data = json.loads(_read_marker_text(workspace_path))
    except (OSError, json.JSONDecodeError):
        return {}
    models = data.get("models")
    return models if isinstance(models, dict) else {}


def _write_models(workspace_path: "Path", models: dict[str, dict[str, str]]) -> None:
    """Write the per-type model pairs into project.json, KEEPING EVERY OTHER MARKER
    KEY INTACT. A naive whole-file rewrite would silently drop `type`, `substrate`,
    `workflow`, `agents`, and `box_images` — which the webui's flavor gate and
    every box recreate read — and the damage would surface far from its cause. So
    an ABSENT marker is written fresh, but an existing unreadable (or non-object)
    one raises ValidationError and is left untouched: this runs inside `update`
    before any side effect, so the refusal reaches the operator cleanly (the
    _write_marker_agents posture). Temp + rename, so a concurrent reader never sees
    a torn file. A link at the marker or at the settings folder is
    unreadable (orch_files), never followed."""
    f = workspace_path / ".orchestrator" / "project.json"
    try:
        data = json.loads(_read_marker_text(workspace_path))
    except FileNotFoundError:
        data = {}
    except orch_files.Unusable as e:
        raise ValidationError(f"cannot change the agent models: {e}")
    except (OSError, json.JSONDecodeError) as e:
        raise ValidationError(
            f"cannot change the agent models: the project marker {orch_files.SHOWN_FOLDER}/project.json is unreadable "
            f"({e}); repair it before changing models")
    if not isinstance(data, dict):
        raise ValidationError(
            f"cannot change the agent models: the project marker {orch_files.SHOWN_FOLDER}/project.json is not a "
            f"JSON object; repair it before changing models")
    data["models"] = models
    _write_marker(workspace_path, data, "change the agent models")


def _apply_model_changes(workspace_path: "Path",
                         changes: dict[str, dict[str, str]]) -> list[str]:
    """Merge per-type model/effort changes into the project marker and return the
    types whose stored effort had to be DROPPED.

    A model change can invalidate an effort that is already stored: `--worker-model
    haiku` against a stored `max` cannot stand, because haiku accepts no effort
    level. The researcher explicitly asked for haiku, so the model wins and the
    effort is dropped — reported on the result, never silent. (An effort supplied
    TOGETHER with an incompatible model already died in UpdateRequest.from_kwargs.)

    Writes through _write_models, which is read-modify-write: the marker's other
    keys (`type`, `substrate`, `workflow`, `agents`, `box_images`) survive."""
    catalog = _model_catalog_checked()
    current = _read_models(workspace_path)
    if not current:
        # A pre-STAGE_MODEL_SELECT project has no block at all. Seed the missing
        # types from the defaults so the merge lands on a complete marker rather
        # than a partial one that would emit flags for some containers only.
        current = _resolve_all_model_pairs()
    merged = {t: dict(p) for t, p in current.items() if isinstance(p, dict)}
    dropped: list[str] = []
    for ctype, blk in changes.items():
        pair = dict(merged.get(ctype) or {})
        pair.update(blk)
        model, effort = pair.get("model", ""), pair.get("effort", "")
        if model and effort and not model_catalog.supports_effort(model, effort, catalog):
            pair["effort"] = ""
            dropped.append(ctype)
        merged[ctype] = pair
    _write_models(workspace_path, merged)
    return dropped


def _restart_role_mcps_for_models(project: str, cfg: "Config",
                                  workspace_path: "Path") -> None:
    """Re-run the project's ENABLED role-MCP containers so they pick up a changed
    model pair. Their env is fixed at `docker run` (a plain restart does not
    re-evaluate it), and _role_mcp_start is an idempotent rm+run — so this is the
    whole of it. The supervisor is deliberately NOT touched: only the role
    containers changed, and recreating the supervisor would kill the researcher's
    session for no reason.

    Refuses while a send_job is in flight rather than killing a live call (the
    same gate `_role_mcp_stop` honors)."""
    supervisor = container_name_for(project)
    entries = role_mcp.load_role_mcps(workspace_path)
    for role in sorted(entries):
        running = _role_mcp_in_flight(workspace_path, role)
        if running:
            die(f"role-mcp {role!r} has {len(running)} call(s) in flight; "
                f"retry once they finish (a model change re-runs its container)")
    for role in sorted(entries):
        print(f"re-running role-mcp {role!r} with the new model...")
        _role_mcp_start(supervisor, project, cfg, role)


def _model_env_args(pair: dict[str, str] | None) -> list[str]:
    """`docker run` -e args for a HUMAN-launched agent (supervisor tab, box tab):
    the tab runs a login shell, not the agent, so there is no argv to inject and
    the pair rides the environment the agent CLI reads. Empty/absent pair → no
    args at all (a pre-STAGE_MODEL_SELECT project is untouched). The effort half
    is conditional: an effort-less tier (haiku) emits no effort var."""
    if not pair or not pair.get("model"):
        return []
    args = ["-e", f"ANTHROPIC_MODEL={pair['model']}"]
    if pair.get("effort"):
        args += ["-e", f"CLAUDE_CODE_EFFORT_LEVEL={pair['effort']}"]
    return args


def _claude_boot_env_args(pair: dict[str, str] | None) -> list[str]:
    """`-e` args carrying the Claude pair to the docker substrate's first boot,
    which merges them into the settings it installs (entrypoint.minimal.sh).
    Empty halves emit nothing."""
    if not pair:
        return []
    args: list[str] = []
    if pair.get("model"):
        args += ["-e", f"RS_CLAUDE_MODEL={pair['model']}"]
    if pair.get("effort"):
        args += ["-e", f"RS_CLAUDE_EFFORT={pair['effort']}"]
    return args


def _agent_flag_env_args(pair: dict[str, str] | None) -> list[str]:
    """`docker run` -e args for an agent WE spawn (analysis worker, role-MCP): the
    entrypoint turns these into explicit `--model` / `--effort` flags on the agent
    command line. RS-namespaced on purpose — one active channel per container, so
    a container never silently falls back to ANTHROPIC_MODEL if the flag-building
    code is skipped."""
    if not pair or not pair.get("model"):
        return []
    args = ["-e", f"RS_AGENT_MODEL={pair['model']}"]
    if pair.get("effort"):
        args += ["-e", f"RS_AGENT_EFFORT={pair['effort']}"]
    return args


# ---------------------------------------------------------------------------
# pi's starting model + thinking level (the create dialog's pi tab).
#
# Delivered into pi's SETTINGS, never as a launch flag: measured on pi 1.5.0, a
# `--model provider/id` on a provider nobody has logged into yet stops pi from
# starting at all ("No API key found"), which is every fresh project, whereas a
# settings default naming a model the provider lacks is skipped silently. The
# pair is merged ONLY where pi's canonical settings were just installed (a
# no-clobber install), so it is a starting default: what the researcher picks in
# pi later is theirs. Three install sites carry the merge: the docker-substrate
# boot (agent/entrypoint.minimal.sh, from RS_PI_* env set at docker run), the
# dind deploy and the docker Update deploy (_stage_agent_dist, from the same env
# on its docker exec). The values never enter a shell line: jq reads them from
# the environment, and PI_MODEL_RE holds the model to a strict charset first.
# ---------------------------------------------------------------------------

# One stderr line the merge prints when it could not apply the pair; the deploy
# reads it back and reports a warning (a failed merge is never fatal: pi starts
# on its own default).
PI_DEFAULTS_SENTINEL = "RS_PI_DEFAULTS_NOT_APPLIED"
_PI_DEFAULTS_WARNING = ("pi's chosen model and thinking level could not be written into "
                        "its settings; pi starts on its own default (choose inside pi "
                        "with /model)")
# The jq program: the provider/model half only when a model was given, the
# thinking level only when one was. No parentheses (the dind command's grouped
# pi fragment is parenthesis-free by pin).
PI_DEFAULTS_JQ = ('if $p == "" then . else .defaultProvider = $p | .defaultModel = $m end'
                  ' | if $t == "" then . else .defaultThinkingLevel = $t end')


def _pi_defaults_merge(settings: str) -> str:
    """A POSIX sh fragment merging RS_PI_MODEL / RS_PI_THINKING (environment)
    into the pi settings file at `settings`, keeping every other key (temp file
    + rename). Exits 0 always: with neither variable set it does nothing; a
    failed merge removes the temp file and prints PI_DEFAULTS_SENTINEL on
    stderr. `settings` is an RS-built path, never user text."""
    tmp = f"{settings}.rs-tmp"
    return (f'{{ [ -z "${{RS_PI_MODEL:-}}${{RS_PI_THINKING:-}}" ] || '
            f'{{ jq --arg p "${{RS_PI_MODEL%%/*}}" --arg m "${{RS_PI_MODEL#*/}}" '
            f'--arg t "${{RS_PI_THINKING:-}}" \'{PI_DEFAULTS_JQ}\' {settings} > {tmp} '
            f'&& mv {tmp} {settings}; }} || '
            f'{{ rm -f {tmp}; echo {PI_DEFAULTS_SENTINEL} >&2; }}; }}')


def _pi_env_args(pair: dict[str, str] | None) -> list[str]:
    """`-e` args carrying pi's starting pair (docker run / docker exec). Absent
    or empty values emit nothing, so a project without a pi choice is
    byte-identical to one created before the pi tab existed."""
    if not pair:
        return []
    args: list[str] = []
    if pair.get("model"):
        args += ["-e", f"RS_PI_MODEL={pair['model']}"]
    if pair.get("thinking"):
        args += ["-e", f"RS_PI_THINKING={pair['thinking']}"]
    return args


def _read_pi_pair(workspace_path: "Path") -> dict[str, str] | None:
    """The marker's `pi_models.agent` pair, or None when the project chose
    none (or predates the pi tab). Tolerant: an unreadable marker reads as no
    choice, and only well-formed string values pass (the marker is
    container-writable; the values still reach pi only through the merge,
    which reads them from the environment)."""
    try:
        data = json.loads(_read_marker_text(workspace_path))
    except (OSError, json.JSONDecodeError):
        return None
    blk = data.get("pi_models") if isinstance(data, dict) else None
    pair = blk.get("agent") if isinstance(blk, dict) else None
    if not isinstance(pair, dict):
        return None
    model = pair.get("model") if isinstance(pair.get("model"), str) else ""
    thinking = pair.get("thinking") if isinstance(pair.get("thinking"), str) else ""
    if model and not PI_MODEL_RE.match(model):
        model = ""
    if thinking not in PI_THINKING_LEVELS:
        thinking = ""
    return {"model": model, "thinking": thinking} if (model or thinking) else None


def _pi_pair_kwargs(workspace_path: "Path") -> dict:
    """`_stage_agent_dist` keyword args for the marker's pi pair: empty when the
    project has none, so those calls keep their exact arguments."""
    pair = _read_pi_pair(workspace_path)
    return {"pi_pair": pair} if pair else {}


def _report_warnings(lines: "Sequence[str]", progress=None) -> None:
    """Operator-facing warnings from a deploy step: stderr for the CLI, a
    `warning` progress line for the webui (`progress` may be None). `lines`
    may be None (a stubbed deploy in a test returns nothing)."""
    for line in lines or ():
        print(f"warning: {line}", file=sys.stderr)
        if progress is not None:
            progress.step("warning", line)


def _stage_box_catalog(workspace_path: "Path", *, strict: bool) -> list[dict]:
    """Stage the resolved box-preset catalog into .orchestrator/box-catalog.json
    (STAGE_BOX_EXT_UX) so the in-supervisor rs-sandbox resolves presets offline,
    and RETURN it so a caller can gate against the same bytes without a second
    load (closing the unguarded-second-load-site gap). Host-side write into the
    bind-mounted workspace dir (atomic-rename → visible to the supervisor
    immediately; a parent-dir mount, not a single-file mount). Q1→live: box_add
    refreshes it (strict=True → BoxCatalogError surfaces, the caller maps it to
    ValidationError); create/recreate stage it best-effort (strict=False → a
    malformed or unreadable box-registry.json leaves the catalog staged before
    as it is, warns and returns the built-ins; nothing blocks the lifecycle
    verb)."""
    # Best-effort (strict=False) means NO read or write failure escapes: the
    # registry read can also fail as an OSError, a UnicodeDecodeError
    # (ValueError) or a RecursionError, and the write as any OSError — each
    # would otherwise end a start half-way through its recreate.
    try:
        catalog = box_catalog.load_catalog()
    except (box_catalog.BoxCatalogError, OSError, ValueError, RecursionError):
        if strict:
            raise
        # The box types are an INPUT that could not be read: leave the catalog
        # staged before (box add stages it strictly) exactly as it is. Staging
        # the built-ins alone would read as complete in the box tool and tell
        # every custom-type box its type is gone. Returned for callers that
        # want the built-ins (none of the non-strict callers gates on it).
        print("warning: box-registry.json is malformed or unreadable; the box "
              "types staged before are kept until it is fixed", file=sys.stderr)
        try:
            return [{**m, "source": "builtin"}
                    for m in box_catalog.load_builtins().values()]
        except (box_catalog.BoxCatalogError, OSError, ValueError, RecursionError):
            return []
    # Through the no-follow settings folder (orch_files): a folder that is a
    # link refuses a box add (strict) and only warns at create/recreate.
    try:
        orch_files.write_text(workspace_path, "box-catalog.json",
                              json.dumps(catalog, indent=2, sort_keys=True) + "\n",
                              create=True)
    except orch_files.Unusable as e:
        if strict:
            raise ValidationError(str(e))
        print(f"warning: the box types were not staged: {e}", file=sys.stderr)
    except OSError:
        if strict:
            raise
        print("warning: the box types could not be written into the project's "
              "settings folder; its boxes keep the ones staged before",
              file=sys.stderr)
    return catalog


def _spawn_shared_mcp(name: str, entry: dict) -> None:
    """Run the shared MCP container on rs-sandbox. Idempotent: skips if running."""
    cname = mcp_container_name_for(name)
    if container_running(cname):
        return
    if container_exists(cname):
        run(["docker", "rm", "-f", cname], capture_output=True)
    if not run_quiet(["docker", "image", "inspect", entry["image"]]):
        print(f"pulling {entry['image']}...")
        run_check(["docker", "pull", entry["image"]])
    cmd = [
        "docker", "run", "-d",
        "--name", cname,
        "--network", ROUTER_NETWORK,
        "--restart", "unless-stopped",
        "--label", f"{MCP_LABEL}=1",
        "--label", f"{MCP_NAME_LABEL}={name}",
    ]
    for k, v in entry.get("env", {}).items():
        cmd += ["-e", f"{k}={v}"]
    cmd += [entry["image"]]
    run_check(cmd)
    print(f"started {cname}")


def _set_enabled(name: str, value: bool) -> dict:
    with mcp_registry.lock():
        try:
            data = mcp_registry.load(expand=False)
        except mcp_registry.RegistryError as e:
            die(str(e))
        entry = data["mcps"].get(name)
        if entry is None:
            die(f"no MCP named {name!r}")
        entry["enabled"] = value
        try:
            mcp_registry.save_atomic(data)
        except mcp_registry.RegistryError as e:
            die(str(e))
    return entry


def _shared_mcps(only_enabled: bool = False) -> list[tuple[str, dict]]:
    try:
        data = mcp_registry.load()
    except mcp_registry.RegistryError as e:
        die(str(e))
    out = []
    for name, entry in sorted(data["mcps"].items()):
        if entry["kind"] != "shared":
            continue
        if only_enabled and not entry.get("enabled", False):
            continue
        out.append((name, entry))
    return out


def _resolve_mcp_host(host_addr: str) -> str:
    """An external MCP's `--host` as one IPv4 address: a literal passes through,
    a name is resolved on the host (the same machine the router and the
    project's proxy reach it from). Raises OSError when it does not resolve
    and UnicodeError when the name itself is malformed."""
    try:
        return str(ipaddress.IPv4Address(host_addr))
    except ValueError:
        pass
    return socket.gethostbyname(host_addr)


def _probe_mcp(name: str, entry: dict) -> tuple[bool, str]:
    if entry["kind"] == "external":
        host = entry.get("host_address", "host.docker.internal")
        port = entry["host_port"]
        cmd = [
            "docker", "run", "--rm",
            "--network", ROUTER_NETWORK,
            "--add-host", "host.docker.internal:host-gateway",
            PROBE_IMAGE,
            "nc", "-z", "-w", "5", host, str(port),
        ]
    else:
        cname = mcp_container_name_for(name)
        if not container_running(cname):
            return False, (f"shared MCP container {cname} not running "
                           f"(try: research mcp start {name})")
        cmd = [
            "docker", "run", "--rm",
            "--network", ROUTER_NETWORK,
            PROBE_IMAGE,
            "nc", "-z", "-w", "5", cname, str(entry["port"]),
        ]
    r = run(cmd, capture_output=True)
    if r.returncode == 0:
        return True, ""
    return False, (r.stderr or r.stdout).strip()


# ---------------------------------------------------------------------------
# The shared MCP gateway (rs-mcpgw) and its server list
# ---------------------------------------------------------------------------
# One container beside the router and Gitea that holds the registered MCP
# servers' addresses and secret headers (cli/mcp_servers.py). It is separate
# from the older per-project machinery (mcp_registry + the in-project proxy),
# which it does not read or touch. Named outside the `rs-mcp-<name>` namespace
# of the older shared servers, and carrying no MCP_LABEL (their sweep keys on it).
MCP_GATEWAY_CONTAINER = "rs-mcpgw"
MCP_GATEWAY_IMAGE = "rs-mcpgw:latest"
MCP_GATEWAY_PROGRAM = "/opt/mcp-gateway/gateway.py"
# How long one Test may take, enforced INSIDE the probe as a total deadline.
# Half the webui's 30 s bound on a broker call (webui/server.py
# BROKER_CALL_TIMEOUT_S), so a probe plus the exec around it always answers
# inside one relay; the _UPSTREAM_RESOLVE_MAX_TIME_S precedent. Shorter fails a
# hosted server's cold start; longer cannot fit the relay.
MCP_PROBE_TIMEOUT_S = 15
# Backstop on the host's `docker exec` only: the probe ends itself at
# MCP_PROBE_TIMEOUT_S, and 5 s covers the exec's own start and exit.
MCP_PROBE_EXEC_TIMEOUT_S = 20
# ONE deadline per inline verb: every docker call inside it gets the time left,
# so no verb on the broker's accept thread can outlast the 30 s relay however
# many calls it makes (5 s of margin for the relay's own queueing).
MCP_INLINE_DEADLINE_S = 25

MCP_GATEWAY_IMAGE_MISSING = "the MCP gateway's image is not built yet"
_MCP_HOST_SLOW = "the host's container service did not answer in time"
_MCP_HOST_DOWN = "the host's container service could not be reached"
_MCP_PROBE_OUTCOMES = frozenset({"mcp", "refused", "not_mcp", "unreachable", "unknown"})
# The gateway's own `detail` is a fixed vocabulary; the cap only bounds what a
# replaced program could print (the longest real one is under 80 characters).
_MCP_PROBE_DETAIL_MAX = 200


def _mcp_deadline() -> float:
    return time.monotonic() + MCP_INLINE_DEADLINE_S


def _mcp_docker(cmd: list[str], deadline: float | None) -> subprocess.CompletedProcess:
    """One docker call that takes what is left of the verb's deadline (None =
    unbounded: the host command and the build-lane child). Never run_check:
    its refusal carries the command line."""
    try:
        if deadline is None:
            return run(cmd, capture_output=True)
        left = deadline - time.monotonic()
        if left <= 0:
            raise ValidationError(_MCP_HOST_SLOW)
        return run(cmd, capture_output=True, timeout=left)
    except subprocess.TimeoutExpired:
        raise ValidationError(_MCP_HOST_SLOW) from None
    except OSError:
        raise ValidationError(_MCP_HOST_DOWN) from None


def _mcp_gateway_image_id(deadline: float | None) -> str:
    r = _mcp_docker(["docker", "image", "inspect", "-f", "{{.Id}}",
                     MCP_GATEWAY_IMAGE], deadline)
    return r.stdout.strip() if r.returncode == 0 else ""


def _mcp_gateway_container(deadline: float | None) -> tuple[str, str]:
    """(state, image id) of the gateway CONTAINER: state is running | stopped |
    absent. `docker container inspect`: the image shares the name."""
    r = _mcp_docker(["docker", "container", "inspect", "-f",
                     "{{.State.Running}} {{.Image}}", MCP_GATEWAY_CONTAINER], deadline)
    if r.returncode != 0:
        return "absent", ""
    running, _, image = r.stdout.strip().partition(" ")
    return ("running" if running == "true" else "stopped"), image


def mcp_gateway_state(deadline: float | None = None) -> str:
    """running | stopped | absent | image_missing (the last only when it is not
    running: a running gateway is running whatever became of the tag)."""
    state, _image = _mcp_gateway_container(deadline)
    if state == "running":
        return state
    return state if _mcp_gateway_image_id(deadline) else "image_missing"


def _mcp_gateway_up(deadline: float | None = None) -> tuple[bool, str]:
    """Render the list and make the gateway running on the built image.
    (ok, message); never raises for a state it can name. Refuses on a damaged
    or newer-version list: the gateway never starts on a stale rendering."""
    try:
        with mcp_servers.lock():
            mcp_servers.render(mcp_servers.load())
    except mcp_servers.ServerListError as e:
        return False, str(e)
    want = _mcp_gateway_image_id(deadline)
    if not want:
        return False, MCP_GATEWAY_IMAGE_MISSING
    state, image = _mcp_gateway_container(deadline)
    if state != "absent" and image != want:
        # A rebuild replaced the image: the old container goes, by its fixed name.
        r = _mcp_docker(["docker", "rm", "-f", MCP_GATEWAY_CONTAINER], deadline)
        if r.returncode != 0:
            return False, "the old MCP gateway container could not be removed"
        state = "absent"
    if state == "running":
        _mcp_docker(["docker", "kill", "-s", "HUP", MCP_GATEWAY_CONTAINER], deadline)
        return True, "the MCP gateway is running"
    if state == "stopped":
        r = _mcp_docker(["docker", "start", MCP_GATEWAY_CONTAINER], deadline)
    else:
        r = _mcp_docker([
            "docker", "run", "-d",
            "--name", MCP_GATEWAY_CONTAINER,
            "--network", GATEWAY_NETWORK_RUN_ARG,
            # The operator's uid: the rendered list is 0600 in a 0700 folder.
            "--user", f"{os.getuid()}:{os.getgid()}",
            "--add-host", "host.docker.internal:host-gateway",
            # It sits on every project's network: it must never pass packets
            # between them (a container forwards by default; measured).
            "--sysctl", "net.ipv4.ip_forward=0",
            "--restart", "unless-stopped",
            # The DIRECTORY: the rendered file is replaced by rename.
            "-v", f"{mcp_servers.GATEWAY_DIR}:/etc/mcp-gateway:ro",
            MCP_GATEWAY_IMAGE,
        ], deadline)
    if r.returncode != 0:
        # The FIRST line is the cause; the last is often the client's help pointer.
        err = [l for l in (r.stderr or r.stdout or "").splitlines() if l.strip()]
        return False, ("the MCP gateway could not be started"
                       + (f" ({err[0].strip()[:200]})" if err else ""))
    # A created gateway is on rs-sandbox only: put it back into every project
    # (deadline None = the CLI or a build-lane child, which may wait for the
    # lifecycle flock; no inline verb reaches this branch).
    if state == "absent" and deadline is None:
        mcp_gateway_attach_all()
    return True, "the MCP gateway was started"


def _mcp_gateway_build() -> bool:
    """Build the gateway's one image from this tree (cached: seconds). Its
    output goes to the caller's stdout. It is NOT in _image_build_specs: like
    the router and the webui it is a host-daemon image built where it is
    started, and a failed build must not stop the fleet."""
    try:
        r = run(["docker", "build",
                 "-f", str(SCRIPT_DIR / "agent" / "Dockerfile.mcp-gateway"),
                 "-t", MCP_GATEWAY_IMAGE, str(SCRIPT_DIR)])
    except OSError:
        return False
    return r.returncode == 0


def start_mcp_gateway_with_fleet(rebuild: bool = False) -> None:
    """`research start`'s step: build the gateway's image and bring the gateway
    up — or WARN and carry on: nothing else in the fleet depends on it. The
    image is built at EVERY start (cached: seconds), as the router's is: the
    host's wiring code and the gateway's program must be the same version, and
    a start after an upgrade would otherwise keep running the old program.
    `rebuild` is accepted for the caller's symmetry; the build is the same."""
    try:
        if True:
            print(f"building {MCP_GATEWAY_IMAGE}...")
            if not _mcp_gateway_build():
                if not _mcp_gateway_image_id(None):
                    raise ValidationError("the MCP gateway's image could not be built")
                print(f"warning: {MCP_GATEWAY_IMAGE} could not be rebuilt; the "
                      "gateway keeps its previous image, which may be older "
                      "than this version of RS: wired MCP servers can be "
                      "refused until a start builds it", file=sys.stderr)
        ok, msg = _mcp_gateway_up()
    except ValidationError as e:
        ok, msg = False, str(e)
    if ok:
        print(msg)
        # Always, at every fleet start: a gateway that was already running (a
        # host reboot restarts it by itself) is attached and its ranges
        # recorded too. Idempotent.
        mcp_gateway_attach_all()
    else:
        print(f"warning: {msg}; MCP servers are unavailable until it runs",
              file=sys.stderr)


def mcp_gateway_start(progress=None) -> dict:
    """The page's Start (a build-lane verb: it may build). Builds the gateway's
    one image when it is absent, then brings the container up. Every refusal
    is a die(): the build lane shows the full log, where die's line lands (a
    ValidationError would end there as a bare "invalid request")."""
    progress = progress or _NULL_PROGRESS
    try:
        if not _mcp_gateway_image_id(None):
            progress.step("build", f"building {MCP_GATEWAY_IMAGE}")
            if not _mcp_gateway_build():
                die("the MCP gateway's image could not be built (output above)")
        progress.step("start", "starting the MCP gateway")
        ok, msg = _mcp_gateway_up()
    except ValidationError as e:
        die(str(e))
    if not ok:
        die(msg)
    print(msg)
    return {"gateway": "running"}


def _mcp_gateway_hup(deadline: float | None) -> None:
    """Tell a RUNNING gateway to re-read the list. Never creates or starts it:
    a stopped fleet stays stopped (the failure of the signal is that case)."""
    _mcp_docker(["docker", "kill", "-s", "HUP", MCP_GATEWAY_CONTAINER], deadline)


def _mcp_list_error(e: "mcp_servers.ServerListError") -> ValidationError:
    return ValidationError(str(e))


def _mcp_change(change: Callable[[dict], None], *, blocking: bool,
                deadline: float | None) -> None:
    """Read, change, save and render the list under its lock (file work only),
    then signal the gateway. `blocking=False` is the broker's form."""
    try:
        with mcp_servers.lock(blocking=blocking):
            data = mcp_servers.load()
            change(data)
            mcp_servers.save(data)
            mcp_servers.render(data)
    except mcp_servers.ServerListError as e:
        raise _mcp_list_error(e) from None
    _mcp_gateway_hup(deadline)


def _mcp_name(value: Any) -> str:
    if not isinstance(value, str) or not mcp_servers.NAME_RE.match(value):
        raise ValidationError(
            "a server name starts with a lowercase letter and holds only "
            "lowercase letters, digits and dashes")
    return value


def _mcp_headers(value: Any) -> dict:
    if value is None:
        return {}
    if not isinstance(value, dict):
        raise ValidationError("the secret headers must be given as name and value pairs")
    for hn, hv in value.items():
        problem = mcp_servers.header_problem(hn, hv)
        if problem:
            raise ValidationError(problem)
    return dict(value)


def _mcp_description(value: Any) -> str:
    if value is None:
        return ""
    if not isinstance(value, str) or any(c in value for c in "\r\n\0"):
        raise ValidationError("a description must be a single line of text")
    return value.strip()


def _mcp_url(value: Any) -> str:
    try:
        return mcp_servers.normalize_url(value)
    except mcp_servers.ServerListError as e:
        raise ValidationError(str(e)) from None


@dataclass(frozen=True)
class McpServerNameRequest:
    name: str

    @classmethod
    def from_kwargs(cls, **kw: Any) -> "McpServerNameRequest":
        return cls(name=_mcp_name(kw.get("name")))


@dataclass(frozen=True)
class McpServerAddRequest:
    name: str
    url: str
    description: str = ""
    headers: dict = field(default_factory=dict)

    @classmethod
    def from_kwargs(cls, **kw: Any) -> "McpServerAddRequest":
        return cls(name=_mcp_name(kw.get("name")), url=_mcp_url(kw.get("url")),
                   description=_mcp_description(kw.get("description")),
                   headers=_mcp_headers(kw.get("headers")))


@dataclass(frozen=True)
class McpServerEditRequest:
    """An absent field is left as it is. `headers_set` adds or replaces secret
    headers; `headers_remove` names the ones to drop. A secret is never read
    back, so there is no "unchanged" value to send."""
    name: str
    url: str | None = None
    description: str | None = None
    headers_set: dict = field(default_factory=dict)
    headers_remove: tuple = ()

    @classmethod
    def from_kwargs(cls, **kw: Any) -> "McpServerEditRequest":
        remove = kw.get("headers_remove")
        if remove is None:
            remove = []
        if not isinstance(remove, (list, tuple)) or not all(
                isinstance(h, str) and mcp_servers.HEADER_NAME_RE.match(h)
                for h in remove):
            raise ValidationError("the headers to remove must be a list of header names")
        headers_set = _mcp_headers(kw.get("headers_set"))
        lowered = {h.lower() for h in headers_set}
        if any(h.lower() in lowered for h in remove):
            raise ValidationError("a header cannot be both set and removed")
        return cls(
            name=_mcp_name(kw.get("name")),
            url=None if kw.get("url") is None else _mcp_url(kw.get("url")),
            description=(None if kw.get("description") is None
                         else _mcp_description(kw.get("description"))),
            headers_set=headers_set, headers_remove=tuple(remove))


def _mcp_servers_with_wiring(rows: list) -> list:
    """Each server row plus who is wired to it ([[project, consumer], ...])."""
    state, grants, _why = mcp_servers.read_grants()
    for row in rows:
        row["wired"] = ([list(pair) for pair in mcp_servers.wired_to(grants, row["name"])]
                        if state == mcp_servers.OK else [])
    return rows


def mcp_server_list(deadline: float | None = None) -> dict:
    """The MCP page's payload: the servers (header NAMES only), the gateway's
    state, and what is wrong with the list when it cannot be used. Never raises
    for a damaged or newer list — the page must still render its remedy."""
    state, data, why = mcp_servers.read()
    error = None
    if state == mcp_servers.DAMAGED:
        error = mcp_servers.DAMAGED_TEXT.format(why=why)
    elif state == mcp_servers.NEWER:
        error = mcp_servers.NEWER_TEXT
    return {
        "servers": _mcp_servers_with_wiring(mcp_servers.public_view(data)),
        "gateway": mcp_gateway_state(deadline),
        "list": state,
        "error": error,
        "probe_timeout_s": MCP_PROBE_TIMEOUT_S,
    }


def mcp_server_add(req: McpServerAddRequest, *, blocking: bool = True,
                   deadline: float | None = None) -> dict:
    def change(data: dict) -> None:
        if req.name in data["servers"]:
            raise mcp_servers.ServerListError(
                f"a server named {req.name} is already on the list")
        entry: dict = {"url": req.url}
        if req.description:
            entry["description"] = req.description
        if req.headers:
            entry["headers"] = dict(req.headers)
        data["servers"][req.name] = entry
    _mcp_change(change, blocking=blocking, deadline=deadline)
    return mcp_server_list(deadline)


def mcp_server_edit(req: McpServerEditRequest, *, blocking: bool = True,
                    deadline: float | None = None) -> dict:
    def change(data: dict) -> None:
        entry = data["servers"].get(req.name)
        if entry is None:
            raise mcp_servers.ServerListError(f"no server named {req.name} is on the list")
        if req.url is not None:
            entry["url"] = req.url
        if req.description is not None:
            if req.description:
                entry["description"] = req.description
            else:
                entry.pop("description", None)
        headers = dict(entry.get("headers", {}))
        # Header names compare without case (HTTP), so a replacement under
        # another spelling replaces instead of sending the header twice.
        drop = {h.lower() for h in req.headers_remove} | {h.lower() for h in req.headers_set}
        headers = {h: v for h, v in headers.items() if h.lower() not in drop}
        headers.update(req.headers_set)
        if headers:
            entry["headers"] = headers
        else:
            entry.pop("headers", None)
    _mcp_change(change, blocking=blocking, deadline=deadline)
    return mcp_server_list(deadline)


def mcp_server_remove(req: McpServerNameRequest, *, blocking: bool = True,
                      deadline: float | None = None) -> dict:
    """Take a server off the list and unwire it everywhere — in the table
    only: the gateway refuses it at once, and each agent's leftover entry goes
    at that container's next start or wiring change. A wiring table that
    cannot be used refuses the removal before anything is written; the list is
    saved first, so a failure in between leaves a table naming a server that
    is gone (refused by the gateway), never a listed server that lost its
    wiring."""
    try:
        with mcp_servers.lock(blocking=blocking):
            data = mcp_servers.load()
            if req.name not in data["servers"]:
                raise mcp_servers.ServerListError(
                    f"no server named {req.name} is on the list")
            grants = mcp_servers.load_grants()
            del data["servers"][req.name]
            mcp_servers.save(data)
            mcp_servers.render(data)
            touched = False
            for row in grants["projects"].values():
                for consumer in row["consumers"].values():
                    if req.name in consumer["servers"]:
                        consumer["servers"].remove(req.name)
                        touched = True
            if touched:
                mcp_servers.save_grants(grants)
                mcp_servers.render_grants(grants)
    except mcp_servers.ServerListError as e:
        raise _mcp_list_error(e) from None
    _mcp_gateway_hup(deadline)
    return mcp_server_list(deadline)


def mcp_server_list_reset(*, blocking: bool = True,
                          deadline: float | None = None) -> dict:
    """Replace a DAMAGED list with an empty one — the page's explicit remedy.
    Refuses a readable list and a newer-version one (nothing is discarded on a
    guess). Check and write under one lock."""
    try:
        with mcp_servers.lock(blocking=blocking):
            state, _data, _why = mcp_servers.read()
            if state == mcp_servers.NEWER:
                raise mcp_servers.ServerListError(mcp_servers.NEWER_TEXT)
            if state != mcp_servers.DAMAGED:
                raise mcp_servers.ServerListError(
                    "the MCP server list is readable; nothing was replaced")
            # Nobody stays wired to a name on the discarded list (a server
            # added later under an old name must not inherit its consumers).
            # A wiring table that cannot be used is left for its own remedy.
            # The TABLE first: if its save fails the list is still damaged and
            # this reset can be run again; the other order would leave a
            # readable list (no reset any more) with everyone still wired.
            gstate, grants, _gwhy = mcp_servers.read_grants()
            if gstate == mcp_servers.OK and any(
                    c["servers"] for row in grants["projects"].values()
                    for c in row["consumers"].values()):
                for row in grants["projects"].values():
                    for c in row["consumers"].values():
                        c["servers"] = []
                mcp_servers.save_grants(grants)
                mcp_servers.render_grants(grants)
            mcp_servers.save(mcp_servers.empty())
            mcp_servers.render(mcp_servers.empty())
    except mcp_servers.ServerListError as e:
        raise _mcp_list_error(e) from None
    _mcp_gateway_hup(deadline)
    return mcp_server_list(deadline)


def mcp_server_test(req: McpServerNameRequest) -> dict:
    """Ask one server, from the gateway, to introduce itself. Always returns a
    result row ({name, outcome, http_status, detail}); the outcomes are mcp |
    refused | not_mcp | unreachable | unknown | gateway_down (the broker turns
    the last into gateway_restarting while a rebuild or a Start runs). "Gateway not
    running" is read from the exec's own failure — no inspect first."""
    def row(outcome: str, detail: str = "", status: Any = None) -> dict:
        return {"name": req.name, "outcome": outcome, "http_status": status,
                "detail": detail}
    try:
        r = run(["docker", "exec", MCP_GATEWAY_CONTAINER, "python3",
                 MCP_GATEWAY_PROGRAM, "--probe", req.name,
                 "--timeout", str(MCP_PROBE_TIMEOUT_S)],
                capture_output=True, timeout=MCP_PROBE_EXEC_TIMEOUT_S)
    except subprocess.TimeoutExpired:
        return row("unreachable", "the MCP gateway did not answer in time")
    except OSError:
        return row("gateway_down", _MCP_HOST_DOWN)
    if r.returncode != 0:
        return row("gateway_down", "the MCP gateway is not running")
    try:
        out = json.loads((r.stdout or "").strip().splitlines()[-1])
        outcome = out["outcome"]
        status = out.get("http_status")
        detail = out.get("detail") or ""
        if outcome not in _MCP_PROBE_OUTCOMES or not isinstance(detail, str) \
                or not (status is None or (isinstance(status, int)
                                           and not isinstance(status, bool))):
            raise ValueError("unexpected probe result")
    except (ValueError, KeyError, IndexError, TypeError, RecursionError):
        return row("unreachable", "the MCP gateway gave an answer that could not be read")
    return row(outcome, detail[:_MCP_PROBE_DETAIL_MAX], status)


# --- wiring: the gateway in each project, and what each consumer may use ------
# The gateway is attached to every project network at ONE fixed address — the
# last usable host address of that network's range — so the project container
# and its boxes all reach it at the same place and nothing has to be healed
# when the gateway is re-created. Attaching at a chosen address on a network
# docker picked the range for needs Engine 29.0 (28.x refuses; measured), which
# is why ENGINE_VERSION_FLOOR is what it is.
MCP_GATEWAY_PORT = 8888
# Set on both dind images: their inner guard lets a box reach the gateway.
MCP_GUARD_LABEL = "research.mcp-gateway-guard"
MCP_SYNC_SCRIPT = SCRIPT_DIR / "agent" / "rs-mcp-sync.py"
MCP_SYNC_HOME_DIR = ".rs-mcp"
MCP_APPLIED_FILE = "mcp-applied.json"
# The project marker says what was applied; it is written inside the project,
# so the host reads it bounded and maps every value to this vocabulary.
MCP_APPLIED_MAX_BYTES = 256 * 1024     # a few hundred consumers' worth of short lines
_MCP_APPLIED_STATES = frozenset({"applied", "pending", "no agent", "failed"})
_MCP_APPLIED_OUTCOMES = frozenset({"added", "kept", "removed", "conflict", "failed"})
# The host-wide lifecycle flock (the broker's lane lock lives here so the host
# verbs can take it too: a fleet-wide gateway attach and a destroy removing a
# network must not interleave).
LIFECYCLE_LOCK_PATH = Path.home() / ".research-sandbox" / "lifecycle.lock"
# Networks that ALWAYS exist inside a Docker-in-Docker project: its inner
# docker0 and the pinned inner bridges (rs-inner .99, the dev bridges .100-.111).
# A project whose own network range overlaps one of them cannot reach its last
# address, so wiring it is refused. LOCKSTEP with agent/Dockerfile.substrate-base
# (bip) and cli/rs_sandbox.py (the pinned bridges); pytest-pinned.
_MCP_INNER_FIXED_RANGES = ("172.17.0.0/16",) + tuple(
    f"192.168.{n}.0/24" for n in range(99, 112))
MCP_OLD_IMAGE_BOX = ("this project was made before boxes could reach the MCP "
                     "gateway; Stop and Start it (after Rebuild all under "
                     "Sandboxes → Software) and wire its boxes then")
MCP_GATEWAY_ABSENT = ("the MCP gateway has not been started yet; use Start on "
                      "this page first")


def _mcp_project_subnet(project: str, deadline: float | None) -> str:
    r = _mcp_docker(["docker", "network", "inspect", project_network_for(project),
                     "-f", "{{(index .IPAM.Config 0).Subnet}}"], deadline)
    subnet = r.stdout.strip() if r.returncode == 0 else ""
    try:
        if ipaddress.ip_network(subnet).version != 4:
            raise ValueError
    except ValueError:
        raise ValidationError(
            f"the network of project {project} could not be read") from None
    return subnet


def _mcp_gateway_attach(project: str, deadline: float | None, *,
                        dind: bool) -> str:
    """Attach the gateway to one project's network at its fixed address.
    Returns the network's range. Idempotent; every refusal is a sentence."""
    subnet = _mcp_project_subnet(project, deadline)
    net = ipaddress.ip_network(subnet)
    if dind and any(net.overlaps(ipaddress.ip_network(r)) for r in _MCP_INNER_FIXED_RANGES):
        raise ValidationError(
            f"project {project}'s network uses an address range ({subnet}) that "
            "the networks inside the project also use, so nothing in it could "
            "reach the MCP gateway; it cannot be wired")
    try:
        address = mcp_servers.gateway_address(subnet)
    except ValueError:
        raise ValidationError(
            f"project {project}'s network has no room for the MCP gateway") from None
    network = project_network_for(project)
    r = _mcp_docker(["docker", "network", "connect", "--ip", address, network,
                     MCP_GATEWAY_CONTAINER], deadline)
    if r.returncode != 0:
        # Already attached is success only at the fixed address.
        # A RUNNING gateway must hold the address live. A stopped one reports
        # no live address, so its configured one counts — but only then: a
        # connect that failed because the address is taken also leaves the
        # configured address behind on a running gateway (measured).
        at = _mcp_docker(["docker", "container", "inspect", "-f",
                          '{{.State.Running}}|{{with index .NetworkSettings.Networks "'
                          + network + '"}}{{.IPAddress}}|{{with .IPAMConfig}}'
                          '{{.IPv4Address}}{{end}}{{end}}',
                          MCP_GATEWAY_CONTAINER], deadline)
        running, live, configured = (at.stdout.strip().split("|") + ["", ""])[:3]
        held = live if running == "true" else configured
        if at.returncode != 0 or held != address:
            raise ValidationError(
                f"the MCP gateway could not be given its address in project "
                f"{project}'s network (the address is in use, or the host's "
                "container service refuses a chosen address)")
    return subnet


def _mcp_note_subnets(subnets: dict) -> None:
    """Record each wired project's network range (file work only) and re-render
    when one changed. A table that cannot be used is left alone."""
    try:
        with mcp_servers.lock():
            state, data, _why = mcp_servers.read_grants()
            if state != mcp_servers.OK:
                return
            changed = False
            for project, subnet in subnets.items():
                row = data["projects"].get(project)
                if row is not None and row["subnet"] != subnet:
                    row["subnet"] = subnet
                    changed = True
            if changed:
                mcp_servers.save_grants(data)
                mcp_servers.render_grants(data)
    except mcp_servers.ServerListError as e:
        print(f"warning: {e}", file=sys.stderr)
        return
    if changed:
        _mcp_gateway_hup(None)


def _project_networks() -> list[str]:
    try:
        r = run(["docker", "network", "ls", "--format", "{{.Name}}",
                 "--filter", f"name=^{PROJECT_NETWORK_PREFIX}"], capture_output=True)
    except OSError:
        return []
    return sorted(n for n in (r.stdout or "").split() if n.startswith(PROJECT_NETWORK_PREFIX))


def mcp_gateway_attach_all() -> None:
    """Attach the gateway to EVERY project network (after it was created, and at
    every `research start`). Never on the broker's accept thread: it waits for
    the lifecycle flock, so it cannot interleave with a destroy removing a
    network. Every failure is a warning."""
    subnets: dict = {}
    try:
        LIFECYCLE_LOCK_PATH.parent.mkdir(parents=True, exist_ok=True)
        with open(LIFECYCLE_LOCK_PATH, "a") as lock_f:
            fcntl.flock(lock_f, fcntl.LOCK_EX)
            for network in _project_networks():
                project = network[len(PROJECT_NETWORK_PREFIX):]
                container = container_name_for(project)
                labels = _container_layout_labels(container)
                dind = labels is not None and labels[0] != Substrate.DOCKER.value
                try:
                    subnets[project] = _mcp_gateway_attach(project, None, dind=dind)
                except ValidationError as e:
                    # A network that vanished mid-loop is a destroyed project.
                    if network in _project_networks():
                        print(f"warning: {e}", file=sys.stderr)
    except OSError as e:
        print(f"warning: the MCP gateway could not be attached to the projects "
              f"({e.strerror or 'lock failed'})", file=sys.stderr)
        return
    _mcp_note_subnets(subnets)


def _mcp_wanted(row: dict | None) -> dict:
    """What a project's sync tool is told: names and tokens per consumer (a
    secret: it goes to the project container's home, never to .orchestrator)."""
    wanted: dict = {"agent": {"servers": {}}, "boxes": {}}
    for key, c in ((row or {}).get("consumers") or {}).items():
        servers = {name: c["token"] for name in c["servers"]}
        if key == mcp_servers.AGENT_CONSUMER:
            wanted["agent"] = {"servers": servers}
        else:
            wanted["boxes"][key[len(mcp_servers.BOX_CONSUMER_PREFIX):]] = {"servers": servers}
    return wanted


# Writes the two files from one JSON document on stdin: the tool (0700) and the
# wanted sets (0600), each through a temp + rename in a 0700 folder.
_MCP_STAGE_SNIPPET = (
    "import json, os, sys\n"
    "d = json.loads(sys.stdin.buffer.read())\n"
    "base = os.path.join(os.path.expanduser('~'), sys.argv[1])\n"
    "os.makedirs(base, mode=0o700, exist_ok=True)\n"
    "os.chmod(base, 0o700)\n"
    "for name, mode, text in (('sync.py', 0o700, d['sync']),\n"
    "                         ('wanted.json', 0o600, json.dumps(d['wanted']))):\n"
    "    tmp = os.path.join(base, '.' + name + '.new')\n"
    "    fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, mode)\n"
    "    with os.fdopen(fd, 'w') as f:\n"
    "        f.write(text)\n"
    "    os.chmod(tmp, mode)\n"
    "    os.replace(tmp, os.path.join(base, name))\n"
)


def _mcp_stage(container: str, wanted: dict, deadline: float | None) -> bool:
    """Put the sync tool and the wanted sets into a RUNNING project container's
    home (as its user, over stdin). False when it could not be done."""
    try:
        payload = json.dumps({"sync": MCP_SYNC_SCRIPT.read_text(), "wanted": wanted})
        left = None if deadline is None else deadline - time.monotonic()
        if left is not None and left <= 0:
            return False
        r = run(["docker", "exec", "-i", "-u", "1000", "-e", f"HOME={_AGENT_HOME}",
                 container, "python3", "-c", _MCP_STAGE_SNIPPET, MCP_SYNC_HOME_DIR],
                input=payload, capture_output=True, timeout=left)
    except (OSError, subprocess.TimeoutExpired):
        return False
    return r.returncode == 0


def _mcp_sync_cmd(container: str, scope: list[str], detach: bool) -> list[str]:
    return ["docker", "exec", *(["-d"] if detach else []), "-u", "1000",
            "-e", f"HOME={_AGENT_HOME}", container, "python3",
            f"{_AGENT_HOME}/{MCP_SYNC_HOME_DIR}/sync.py", *scope]


def mcp_sync_project(project: str, container: str, *, progress=None) -> None:
    """A project came up (or gained an agent): attach the gateway, stage the
    tool and the wanted sets, and let the project apply its own agents' wiring
    in the background. Boxes apply theirs when they start (rs-sandbox runs the
    staged tool). Does nothing — no docker call — for a project with no wiring;
    every failure is a warning."""
    try:
        state, data, _why = mcp_servers.read_grants()
    except OSError:
        return
    row = data["projects"].get(project) if state == mcp_servers.OK else None
    if not row or not row["consumers"]:
        return
    labels = _container_layout_labels(container)
    dind = labels is not None and labels[0] != Substrate.DOCKER.value
    try:
        if _mcp_gateway_container(None)[0] != "absent":
            _mcp_note_subnets({project: _mcp_gateway_attach(project, None, dind=dind)})
        if not _mcp_stage(container, _mcp_wanted(row), None):
            raise ValidationError("the project's MCP servers could not be staged")
        run(_mcp_sync_cmd(container, ["--agent"], detach=True), capture_output=True)
    except (ValidationError, OSError) as e:
        _report_warnings([f"{e}; its agents get their MCP servers at the next "
                          "start or wiring change"], progress)


def _mcp_read_applied(project: str) -> dict:
    """What the project says it applied, per consumer — read without any exec,
    bounded, and mapped to the fixed vocabulary (the file is the project's)."""
    try:
        # Bounded AT the read: the file is the project's to write.
        raw = orch_files.read_bytes(workspace_path_for(project, load_config()),
                                    MCP_APPLIED_FILE, max_bytes=MCP_APPLIED_MAX_BYTES)
    except (OSError, orch_files.Unusable, orch_files.WorkspaceUnopenable):
        return {}
    try:
        data = json.loads(raw)
    except (ValueError, RecursionError):
        return {}
    out: dict = {}
    if not isinstance(data, dict):
        return out
    for key, entry in data.items():
        if mcp_servers.consumer_problem(key) or not isinstance(entry, dict) \
                or entry.get("state") not in _MCP_APPLIED_STATES:
            continue
        agents: dict = {}
        raw_agents = entry.get("agents")
        for agent in ("claude", "pi"):
            servers = raw_agents.get(agent) if isinstance(raw_agents, dict) else None
            if isinstance(servers, dict):
                agents[agent] = {n: o for n, o in servers.items()
                                 if isinstance(n, str) and mcp_servers.NAME_RE.match(n)
                                 and o in _MCP_APPLIED_OUTCOMES}
        out[key] = {"state": entry["state"], "agents": agents}
    return out


def mcp_wiring(project: str | None = None) -> dict:
    """The wiring as the page shows it: per project and consumer, the servers
    and what the project last reported applying. No exec, no docker call."""
    state, data, why = mcp_servers.read_grants()
    error = None
    if state == mcp_servers.DAMAGED:
        error = mcp_servers.GRANTS_DAMAGED_TEXT.format(why=why)
    elif state == mcp_servers.NEWER:
        error = mcp_servers.GRANTS_NEWER_TEXT
    projects: dict = {}
    for name, row in sorted(data["projects"].items()):
        if project is not None and name != project:
            continue
        applied = _mcp_read_applied(name)
        projects[name] = {
            key: {"servers": sorted(c["servers"]), "applied": applied.get(key)}
            for key, c in sorted(row["consumers"].items())}
    return {"table": state, "error": error, "projects": projects}


def mcp_targets(deadline: float | None = None) -> list:
    """What the page can offer to wire: each project, whether its own agent
    can be wired, and its boxes. ONE bounded container listing; the boxes come
    from each project's own record (a host file read)."""
    fmt = ("{{.Names}}\t{{.State}}\t{{.Label \"" + SUBSTRATE_LABEL + "\"}}\t{{.Label \""
           + PROJECT_TYPE_LABEL + "\"}}\t{{.Label \"" + MCP_GUARD_LABEL + "\"}}")
    r = _mcp_docker(["docker", "ps", "-a", "--filter", f"label={PROJECT_LABEL}",
                     "--format", fmt], deadline)
    prefix = container_name_for("")
    cfg = load_config()
    out = []
    for line in (r.stdout or "").splitlines() if r.returncode == 0 else []:
        parts = (line.split("\t") + [""] * 5)[:5]
        cname, state, substrate, ptype, guard = parts
        if not cname.startswith(prefix) or not _PROJECT_NAME_RE.match(cname[len(prefix):]):
            continue
        project = cname[len(prefix):]
        dind = (substrate or Substrate.DIND_SYSBOX.value) != Substrate.DOCKER.value
        research = dind and ptype in ("", PROJECT_TYPE_RESEARCH)
        boxes: list = []
        if dind:
            try:
                boxes = sorted(n for n in extension.load(workspace_path_for(project, cfg))
                               if isinstance(n, str) and not mcp_servers.consumer_problem("box:" + n))
            except Exception:  # noqa: BLE001 — an unreadable record offers no boxes
                boxes = []
        out.append({"project": project, "running": state == "running",
                    "agent": not research, "boxes": boxes,
                    "boxes_wirable": guard == "1"})
    return sorted(out, key=lambda t: t["project"])


@dataclass(frozen=True)
class McpWireRequest:
    """Set the servers one consumer has: a project's own agents (no box) or one
    of its boxes. An empty list unwires it."""
    project: str
    box: str | None
    servers: tuple

    @classmethod
    def from_kwargs(cls, **kw: Any) -> "McpWireRequest":
        project = kw.get("project")
        if not isinstance(project, str) or not _PROJECT_NAME_RE.match(project):
            raise ValidationError("a project name is required")
        box = kw.get("box")
        if box is not None and (not isinstance(box, str)
                                or mcp_servers.consumer_problem("box:" + box)):
            raise ValidationError("the box name is not valid")
        servers = kw.get("servers")
        if not isinstance(servers, (list, tuple)) or not all(
                isinstance(n, str) and mcp_servers.NAME_RE.match(n) for n in servers):
            raise ValidationError("the servers must be a list of server names")
        if len(set(servers)) != len(servers):
            raise ValidationError("a server is named twice")
        return cls(project=project, box=box, servers=tuple(sorted(servers)))


def mcp_wire(req: McpWireRequest, *, blocking: bool = True,
             deadline: float | None = None) -> dict:
    """Wire one consumer. Order: refuse what cannot work → the gateway into
    the project's network (a refusal there writes nothing) → the table (the
    gateway's truth) → the project applies it to its agents. Returns the
    project's wiring and what was applied ({"state": "pending"} for a stopped
    project or box)."""
    container = container_name_for(req.project)
    r = _mcp_docker(["docker", "container", "inspect", "-f",
                     "{{.State.Running}} {{json .Config.Labels}}", container], deadline)
    if r.returncode != 0:
        raise ValidationError(f"there is no project named {req.project}")
    running_s, _, labels_s = r.stdout.strip().partition(" ")
    try:
        labels = json.loads(labels_s) or {}
    except (ValueError, RecursionError):
        labels = {}
    running = running_s == "true"
    dind = labels.get(SUBSTRATE_LABEL, Substrate.DIND_SYSBOX.value) != Substrate.DOCKER.value
    research = dind and labels.get(PROJECT_TYPE_LABEL, PROJECT_TYPE_RESEARCH) \
        in ("", PROJECT_TYPE_RESEARCH)
    if req.box is None and research:
        raise ValidationError(
            "a research project's own agent plans and delegates; MCP servers "
            "there are for its workers and its boxes, so it cannot be wired")
    if req.box is not None:
        if not dind:
            raise ValidationError(f"project {req.project} has no boxes")
        try:
            boxes = extension.load(workspace_path_for(req.project, load_config()))
        except Exception:  # noqa: BLE001 — a record that cannot be read has no boxes
            boxes = {}
        if req.box not in boxes:
            raise ValidationError(f"project {req.project} has no box named {req.box}")
        if req.servers and labels.get(MCP_GUARD_LABEL) != "1":
            raise ValidationError(MCP_OLD_IMAGE_BOX)
    if _mcp_gateway_container(deadline)[0] == "absent":
        raise ValidationError(MCP_GATEWAY_ABSENT)
    subnet = _mcp_gateway_attach(req.project, deadline, dind=dind)
    key = mcp_servers.consumer_key(req.box)
    try:
        with mcp_servers.lock(blocking=blocking):
            known = mcp_servers.load()["servers"]
            unknown = [n for n in req.servers if n not in known]
            if unknown:
                raise mcp_servers.ServerListError(
                    f"no server named {unknown[0]} is on the list")
            data = mcp_servers.load_grants()
            known_row = data["projects"].get(req.project)
            if not req.servers and (known_row is None or key not in known_row["consumers"]):
                # Unwiring what was never wired: nothing to write, nothing to tell.
                return {"wiring": mcp_wiring(req.project), "consumer": key,
                        "applied": {"state": "pending"}}
            row = data["projects"].setdefault(
                req.project, {"subnet": subnet, "consumers": {}})
            row["subnet"] = subnet
            consumer = row["consumers"].get(key)
            if req.servers:
                if consumer is None:
                    consumer = row["consumers"][key] = {
                        "token": mcp_servers.new_token(), "servers": []}
                consumer["servers"] = list(req.servers)
            elif consumer is not None:
                # Kept with an empty list (not dropped): the project still
                # needs to be told to remove the entries it added.
                consumer["servers"] = []
            mcp_servers.save_grants(data)
            mcp_servers.render_grants(data)
            wanted = _mcp_wanted(row)
    except mcp_servers.ServerListError as e:
        raise _mcp_list_error(e) from None
    _mcp_gateway_hup(deadline)
    applied: dict = {"state": "pending"}
    if running and _mcp_stage(container, wanted, deadline):
        scope = ["--agent"] if req.box is None else ["--box", req.box]
        try:
            left = None if deadline is None else deadline - time.monotonic()
            if left is not None and left <= 0:
                # Nothing left of the deadline: let the project apply it in
                # the background rather than start an exec only to abandon it.
                run(_mcp_sync_cmd(container, scope, detach=True), capture_output=True)
                raise subprocess.TimeoutExpired("sync", 0)
            out = run(_mcp_sync_cmd(container, scope, detach=False),
                      capture_output=True, timeout=left)
            got = json.loads(out.stdout or "null") if out.returncode == 0 else None
            if isinstance(got, dict):
                applied = _mcp_read_applied(req.project).get(key) or {"state": "pending"}
        except subprocess.TimeoutExpired:
            applied = {"state": "applying"}     # the tool finishes on its own
        except (OSError, ValueError, RecursionError):
            pass
    return {"wiring": mcp_wiring(req.project), "consumer": key, "applied": applied}


def mcp_grants_reset(*, blocking: bool = True, deadline: float | None = None) -> dict:
    """Replace a DAMAGED wiring table with an empty one — the page's explicit
    remedy. Refuses a readable table and a newer-version one."""
    try:
        with mcp_servers.lock(blocking=blocking):
            state, _data, _why = mcp_servers.read_grants()
            if state == mcp_servers.NEWER:
                raise mcp_servers.ServerListError(mcp_servers.GRANTS_NEWER_TEXT)
            if state != mcp_servers.DAMAGED:
                raise mcp_servers.ServerListError(
                    "the MCP wiring table is readable; nothing was replaced")
            mcp_servers.save_grants(mcp_servers.grants_empty())
            mcp_servers.render_grants(mcp_servers.grants_empty())
    except mcp_servers.ServerListError as e:
        raise _mcp_list_error(e) from None
    _mcp_gateway_hup(deadline)
    return mcp_wiring()


def _mcp_drop_rows(project: str, box: str | None = None) -> str | None:
    """Forget a destroyed project's wiring, or a removed box's. Returns a
    warning sentence when the table could not be changed, else None."""
    try:
        with mcp_servers.lock():
            state, data, _why = mcp_servers.read_grants()
            if state != mcp_servers.OK:
                return ("the MCP wiring table could not be read, so this "
                        "wiring was not removed from it")
            row = data["projects"].get(project)
            if row is None:
                return None
            if box is None:
                del data["projects"][project]
            elif row["consumers"].pop(mcp_servers.consumer_key(box), None) is None:
                return None
            mcp_servers.save_grants(data)
            mcp_servers.render_grants(data)
    except mcp_servers.ServerListError as e:
        return str(e)
    try:
        _mcp_gateway_hup(None)
    except ValidationError:
        pass
    return None


def mcp_forget_dead_project(project: str) -> None:
    """A project is about to be CREATED under this name: wiring recorded for an
    earlier project of the same name (a destroy that could not drop it) belongs
    to nothing — that project's containers, and with them its tokens, are gone.
    It is dropped here, so the new project starts with none. Rows that are
    there and cannot be removed (the table cannot be saved) refuse the create,
    with the page's own remedy. A table that cannot be READ is not a reason to
    refuse every create: the new project simply starts unwired, and the page
    shows that table's own error and remedy. (The list lock is taken blocking
    here and in destroy, on the broker's accept thread: an accepted exception
    to the one-attempt rule — holders do file work only, so the wait is the
    length of one small file write.)"""
    if not mcp_project_has_rows(project):
        return
    warn = _mcp_drop_rows(project)
    if warn:
        raise ValidationError(
            f"MCP wiring from an earlier project named {project} is still "
            f"recorded and could not be removed ({warn}); repair the wiring "
            "under Sandboxes → MCP, then create this project")


def mcp_project_has_rows(project: str) -> bool:
    try:
        state, data, _why = mcp_servers.read_grants()
    except OSError:
        return False
    return state == mcp_servers.OK and project in data["projects"]


def _supervisor_mcp_reload(container_name: str) -> None:
    """Re-render the supervisor's proxy config and SIGHUP the proxy."""
    if not container_running(container_name):
        return
    r = run(["docker", "exec", container_name, "/usr/local/bin/mcp-reload"],
            capture_output=True)
    if r.returncode != 0:
        msg = (r.stderr or r.stdout).strip()
        print(f"warning: mcp-reload in {container_name} failed: {msg}",
              file=sys.stderr)


def _allow_mcp_for_project(project: str, cfg: "Config", mcp_name: str,
                           *, do_reload: bool = True) -> tuple[bool, str]:
    """Open the router hole, append (or replace) the per-project allowlist
    entry, and optionally reload the supervisor's mcp-proxy. Returns
    ``(ok, message)`` so callers can iterate batches without aborting.
    The caller owns project-existence checks; this helper validates
    router + registry + (shared) container state."""
    container_name = container_name_for(project)

    if not container_running(ROUTER_CONTAINER):
        return False, f"{ROUTER_CONTAINER} is not running"

    try:
        entry = mcp_registry.entry_for(mcp_name)
    except mcp_registry.RegistryError as e:
        return False, str(e)
    if entry is None:
        return False, f"no MCP named {mcp_name!r}"
    if not entry.get("enabled", False):
        return False, f"MCP {mcp_name!r} is not enabled"

    if entry["kind"] == "external":
        host_addr = entry.get("host_address", "host.docker.internal")
        if host_addr == "host.docker.internal":
            ip = resolve_host_gateway()
        else:
            # The allowlist carries one ADDRESS every consumer keys on — the
            # router's allow rule, the proxy's upstream dial and the inner
            # guard's exception pair. A name registered with `--host` is
            # resolved here, once, like host.docker.internal is; a name that
            # does not resolve refuses the allow instead of writing a value
            # the guard would have to skip (and the proxy then be dropped on).
            try:
                ip = _resolve_mcp_host(host_addr)
            except (OSError, UnicodeError) as e:
                # gaierror for an unknown name; UnicodeError from the idna
                # codec for a malformed label (empty, or over 63 characters)
                return False, f"external MCP host {host_addr!r} does not resolve: {e}"
        port = entry["host_port"]
    else:  # shared
        cname = mcp_container_name_for(mcp_name)
        if not container_running(cname):
            return False, f"shared MCP container {cname} not running"
        ip = mcp_container_ip(mcp_name)
        port = entry["port"]

    # The allowlist is written below: a settings folder that is a link refuses
    # before the router opens anything.
    refusal = _settings_folder_refusal(workspace_path_for(project, cfg))
    if refusal:
        return False, refusal

    network = project_network_for(project)
    subnet = get_network_subnet(network)
    r = run(["docker", "exec", ROUTER_CONTAINER,
             "/scripts/mcp-allow.sh", subnet, ip, str(port)],
            capture_output=True)
    if r.returncode != 0:
        return False, (r.stderr or r.stdout).strip() or "mcp-allow.sh failed"

    allowlist = load_project_allowlist(project, cfg)
    allowlist = [e for e in allowlist if e.get("name") != mcp_name]
    new_entry = {
        "name": mcp_name,
        "kind": entry["kind"],
        "transport": entry.get("transport", "http"),
        "ip": ip,
        "port": port,
        "path": entry.get("path", mcp_registry.DEFAULT_PATH),
    }
    if entry.get("headers"):
        new_entry["headers"] = entry["headers"]
    if entry.get("description"):
        new_entry["description"] = entry["description"]
    allowlist.append(new_entry)
    save_project_allowlist(project, cfg, allowlist)

    if do_reload:
        _supervisor_mcp_reload(container_name)
    return True, f"-> {ip}:{port}"


def _deny_mcp_for_project(project: str, cfg: "Config", mcp_name: str,
                          *, do_reload: bool = True) -> tuple[bool, str]:
    """Close the router hole, drop the entry from the per-project
    allowlist, optionally reload the supervisor's mcp-proxy. Returns
    ``(ok, message)``. Tolerates a torn-down project network / stopped
    router (skips the firewall step in that case)."""
    container_name = container_name_for(project)

    allowlist = load_project_allowlist(project, cfg)
    target = next((e for e in allowlist if e.get("name") == mcp_name), None)
    if target is None:
        return False, f"{mcp_name!r} is not currently allowed"

    network = project_network_for(project)
    if network_exists(network) and container_running(ROUTER_CONTAINER):
        subnet = get_network_subnet(network)
        run(["docker", "exec", ROUTER_CONTAINER,
             "/scripts/mcp-deny.sh", subnet,
             str(target.get("ip", "")), str(target.get("port", ""))],
            capture_output=True)

    allowlist = [e for e in allowlist if e.get("name") != mcp_name]
    save_project_allowlist(project, cfg, allowlist)

    if do_reload:
        _supervisor_mcp_reload(container_name)
    return True, ""


def _require_project(project: str) -> str:
    container_name = container_name_for(project)
    if not container_exists(container_name):
        die(f"project {project!r} does not exist")
    return container_name


def _batch_apply(project: str, cfg: "Config", names: list[str],
                 helper, action: str) -> tuple[list[str], list[str]]:
    """Run ``helper`` (allow or deny) for each name with reload deferred.
    Returns ``(succeeded, failed)`` lists. Caller is responsible for the
    one-shot reload at the end."""
    succeeded: list[str] = []
    failed: list[str] = []
    for name in names:
        ok, msg = helper(project, cfg, name, do_reload=False)
        if ok:
            succeeded.append(name)
            print(f"{action} {name!r}{(' ' + msg) if msg else ''}")
        else:
            failed.append(name)
            print(f"warning: {action} {name!r} skipped: {msg}",
                  file=sys.stderr)
    return succeeded, failed


# ---------------------------------------------------------------------------
# Per-project role-MCP lifecycle (B.0)
# ---------------------------------------------------------------------------


def _role_mcp_stage_creds(supervisor: str, role: str) -> None:
    """Snapshot the supervisor's current Claude credentials into the
    per-role daemon-state dir so the role-MCP container can stage them at
    boot. Idempotent: overwrites any previous snapshot.

    Tolerant of an un-authed supervisor: if the supervisor has no
    `.credentials.json` yet, this stages nothing and returns cleanly — it
    does NOT fail. Enablement is independent of auth (the worker-side twin
    of the PI auth-ownership model): the daemon boots idle and the
    supervisor's claude copies its own creds in later via
    `rs-role-mcp sync-creds`, prompted by the `needs_credentials` send_job
    envelope. The `mkdir -p` below is kept unconditionally — it is the
    load-bearing root-owned-bind-source guard, needed whether or not creds
    exist.

    Path note: creds land under .role-mcps/<role>/.creds/ (the daemon-state
    location), NOT under shared/<role>/ which is reserved for the role's
    public publish surface. Mixing them would expose creds to any future
    cross-role RO consumer of shared/<role>/."""
    # mkdir -p does double duty: stages creds, AND pre-creates the publish
    # source dir (/workspace/shared/{role}) and daemon-state dir
    # (/workspace/.role-mcps/{role}) with the supervisor user's ownership
    # (uid 1000) BEFORE docker tries to bind-mount them. If we don't,
    # docker auto-creates missing bind-mount sources as root-owned 755,
    # and the role-MCP container's worker user (also uid 1000 but
    # different namespace) can't write to them. Failure mode is
    # silent until the daemon tries its first write.
    #
    # Role-MCPs only spawn headless `claude -p`, which works from
    # `.credentials.json` alone — no `~/.claude.json` propagation here.
    script = f"""
        set -e
        mkdir -p /workspace/.role-mcps/{role}/.creds
        mkdir -p /workspace/shared/{role}
        if [ ! -f /home/research/.claude/.credentials.json ]; then
            echo "supervisor not yet authenticated; role-mcp {role} will boot idle (run rs-role-mcp sync-creds after /login)" >&2
            exit 0
        fi
        cp /home/research/.claude/.credentials.json \
           /workspace/.role-mcps/{role}/.creds/.credentials.json
        chmod 600 /workspace/.role-mcps/{role}/.creds/.credentials.json
        if [ -f /home/research/.claude/settings.json ]; then
            # Strip the `hooks` key — the supervisor's Stop hook calls
            # /usr/local/bin/rs-audit-stop, which is baked into the
            # supervisor image only. Propagating it would break every
            # claude session in the role-MCP container with a "command
            # not found" error on every Stop event.
            # …and the supervisor agent's own model and effort, which live in
            # this file and would override the role's own (I33 slice 3).
            jq '{AGENT_MODEL_SETTINGS_JQ}' /home/research/.claude/settings.json \
               > /workspace/.role-mcps/{role}/.creds/settings.json
            chmod 600 /workspace/.role-mcps/{role}/.creds/settings.json
        fi
    """
    r = run(["docker", "exec", supervisor, "bash", "-eu", "-c", script],
            capture_output=True)
    if r.returncode != 0:
        die((r.stderr or r.stdout).strip()
            or f"failed to stage creds for role-mcp {role!r}")


def _role_mcp_migrate_state(supervisor: str, role: str) -> None:
    """One-shot move of daemon-state subdirs from the B.0 layout
    (/workspace/shared/<role>/{jobs,memories,...}) to the B.3 layout
    (/workspace/.role-mcps/<role>/{jobs,memories,...}).

    Idempotent: only moves entries when the source exists and the
    destination doesn't. Safe to call on every role-mcp start; on
    already-migrated workspaces every check short-circuits.

    The publish surface at /workspace/shared/<role>/ is preserved (the
    non-daemon-state files there, if any, stay put — they're the role's
    public artifact dir going forward). Daemon-state names are explicit
    (no glob) so we don't accidentally sweep a future publish artifact
    a user dropped in there."""
    daemon_state_names = [
        "jobs", "memories", ".calls", ".creds",
        "global.md", ".summarize-watermark",
    ]
    moves = " ".join(daemon_state_names)
    script = f"""
        set -e
        src=/workspace/shared/{role}
        dst=/workspace/.role-mcps/{role}
        mkdir -p "$dst"
        for name in {moves}; do
            if [ -e "$src/$name" ] && [ ! -e "$dst/$name" ]; then
                mv "$src/$name" "$dst/$name"
                echo "migrated $src/$name -> $dst/$name" >&2
            fi
        done
    """
    run(["docker", "exec", supervisor, "bash", "-eu", "-c", script],
        capture_output=True)


def _role_mcp_inner_exists(supervisor: str, role: str) -> bool:
    cname = role_mcp.role_container_name(role)
    r = run(["docker", "exec", supervisor,
             "docker", "inspect", cname], capture_output=True)
    return r.returncode == 0


def _role_mcp_inner_running(supervisor: str, role: str) -> bool:
    cname = role_mcp.role_container_name(role)
    r = run(["docker", "exec", supervisor,
             "docker", "inspect", "-f", "{{.State.Running}}", cname],
            capture_output=True)
    return r.returncode == 0 and r.stdout.strip() == "true"


def _role_mcp_start(supervisor: str, project: str, cfg: "Config",
                    role: str, *, force_restage: bool = False) -> None:
    """Run the role-MCP container in the supervisor's inner dockerd.
    Idempotent: tears down any prior instance with the same name first so
    a stale crashed container doesn't block start. Lazy-stages the
    per-role image into the inner dockerd on first use; project create
    doesn't pre-stage role-MCP images (most projects won't use them).
    Pass force_restage=True after a host-side image rebuild to push the
    new content through."""
    workspace_path = workspace_path_for(project, cfg)
    entries = role_mcp.load_role_mcps(workspace_path)
    entry = entries.get(role)
    if entry is None:
        die(f"no role-mcps.json entry for role {role!r}; call enable first")

    role_mcp.validate_role(role)

    cname = role_mcp.role_container_name(role)
    # rm any prior container BEFORE migrating state, so the move can't race
    # a running daemon that's still writing into /workspace/shared/<role>/.
    run(["docker", "exec", supervisor, "docker", "rm", "-f", cname],
        capture_output=True)
    _role_mcp_migrate_state(supervisor, role)
    _role_mcp_stage_creds(supervisor, role)

    image = entry.get("image") or role_mcp.ROLE_IMAGES[role]
    stage_worker_image(supervisor, image, force=force_restage)

    # Bind-mount layout:
    #   /workspace                  ← <supervisor>/workspace/.role-mcps/<role>
    #     RW. Daemon-private state: jobs/, memories/, global.md, .calls/,
    #     .creds/, .summarize-watermark, .tools-inventory.md. Hidden under
    #     a leading-dot dir on the project volume so casual `ls /shared/`
    #     doesn't surface internals.
    #   /workspace/published        ← <supervisor>/workspace/shared/<role>
    #     RW from this role-MCP. The role's PUBLIC artifact surface —
    #     intended to be cross-role-RO-consumable later. Wrangler writes
    #     extracts/<topic>/<slug>.{parquet,sql,metadata.json} here;
    #     librarian (B.2) will write refs/<topic>/; echo and (likely)
    #     websearcher leave it empty.
    #   /etc/orchestrator           ← <supervisor>/workspace/.orchestrator (RO)
    #     Parent-dir bind-mount so atomic-rename writes by the host stay
    #     visible (single-file-bind-mount rule); entrypoint reads
    #     role-mcps.json and mcp-allow.json from here.
    ip = entry["ip"]
    # Substrate (B.1-substrate) resource flags + concurrency env. Persisted
    # in role-mcps.json so they survive _recreate_supervisor without
    # re-consulting Config (operator's enable-time intent is captured).
    memory = entry.get("memory") or cfg.default_role_mcp_memory
    mcc = entry.get("max_concurrent_calls")
    if mcc is None:
        mcc = cfg.default_role_mcp_max_concurrent_calls
    docker_args = [
        "docker", "exec", supervisor,
        "docker", "run", "-d",
        "--name", cname,
        "--network", INNER_NETWORK,
        "--ip", ip,
        "--restart", "unless-stopped",
        # No --init: the role image's own ENTRYPOINT tini is PID 1 and reaps
        # zombies, including the grandchildren of a `dumb-init`-wrapped stdio
        # MCP that dies uncleanly (they reparent to PID 1). Adding --init
        # would put docker-init at PID 1 and push that tini to PID 2, where
        # it warns at every boot that it is not running as PID 1.
        # Blast-radius backstop. OOM-killer takes the role container,
        # not the supervisor. See Config.default_role_mcp_memory comment
        # for the size reasoning.
        f"--memory={memory}",
        "-v", f"/workspace/.role-mcps/{role}:/workspace",
        "-v", f"/workspace/shared/{role}:/workspace/published",
        "-v", "/workspace/.orchestrator:/etc/orchestrator:ro",
        *AGENT_DIST_MOUNT_ARGS,   # claude copy-source (no bake; slice 2)
        # Agent model + effort for the per-call `claude -p` this daemon spawns
        # (STAGE_MODEL_SELECT). RS-namespaced: spawn.sh turns these into explicit
        # --model / --effort flags — we own that argv, so we use it rather than
        # ANTHROPIC_MODEL, and there is exactly one active channel per container.
        # Read verbatim from the marker (already resolved + effort-drop-checked).
        # A model change re-runs this container (update's granular role path).
        *_agent_flag_env_args(_read_models(workspace_path).get("role")),
        "-e", f"RS_ROLE_NAME={role}",
        "-e", f"RS_ROLE_MCP_PORT={role_mcp.ROLE_MCP_PORT}",
        # Daemon reads this to enforce the cap on send_job. 0 = uncapped.
        "-e", f"RS_ROLE_MAX_CONCURRENT_CALLS={int(mcc)}",
        "--label", f"research.role_mcp={role}",
        "--label", f"research.project={project}",
        # The project's mounted folders (/workspace/mnt/<name>, --mount), RO at
        # the same path the supervisor and the workers see them at: one bind
        # of the parent, which the supervisor entrypoint guarantees exists;
        # the host binds inside it ride along (a recursive bind), so a folder
        # set at create is visible here without per-folder harvesting.
        "-v", "/workspace/mnt:/workspace/mnt:ro",
        image,
    ]
    run_check(docker_args)
    print(f"role-mcp {role!r}: running at {ip}:{role_mcp.ROLE_MCP_PORT}")


def _role_mcp_stop(supervisor: str, role: str) -> None:
    """Hard stop + remove the role-MCP container (`docker rm -f` = SIGKILL,
    no grace, no drain). This is `disable`'s teardown — it pairs with
    dropping the role-mcps.json entry, so abruptness is acceptable: the role
    is leaving the project. For a *graceful park that keeps the entry*, use
    `_role_mcp_park` instead. Tolerates absence — caller may have already
    removed it via _recreate_supervisor."""
    cname = role_mcp.role_container_name(role)
    run(["docker", "exec", supervisor, "docker", "rm", "-f", cname],
        capture_output=True)


def _role_mcp_in_flight(workspace_path: Path, role: str) -> list[dict]:
    """Read-only, host-side count of in-flight send_job calls, straight off
    the project volume (`<workspace>/.role-mcps/<role>/jobs/*.json` — the same
    files the daemon writes; see daemon.py JobStore). A job still in status
    `running` is a live `claude -p` call (or a daemon-restart orphan the
    daemon would reap on its next boot; from the host the file state is the
    conservative signal — we'd rather refuse a stop than kill a real call).
    Returns the running entries so the caller can name them in a refusal.
    Pure read — no docker, no mutation, safe to call as a gate."""
    jobs_dir = workspace_path / ".role-mcps" / role / "jobs"
    if not jobs_dir.is_dir():
        return []
    running: list[dict] = []
    for p in sorted(jobs_dir.glob("*.json")):
        try:
            entry = json.loads(p.read_text())
        except (json.JSONDecodeError, OSError):
            continue
        if isinstance(entry, dict) and entry.get("status") == "running":
            running.append(entry)
    return running


def _role_mcp_park(supervisor: str, role: str) -> None:
    """Graceful stop of the role-MCP container WITHOUT removing it and
    WITHOUT touching role-mcps.json — the role stays registered, just parked.
    Uses `docker stop` (SIGTERM + grace), not the `rm -f` (SIGKILL) that
    `disable` uses. The daemon has no SIGTERM drain handler, so gracefulness
    here comes from *quiescence*, not from the signal: callers gate on
    `_role_mcp_in_flight` == 0 first, so the daemon is idle (no `claude -p`
    child, no memory write mid-flight) when the signal lands and a
    handler-less SIGTERM terminates a process with nothing to tear. The
    container is left `exited` (name preserved, visible in `docker ps -a`);
    `_role_mcp_start` rm's and replaces it on unpark, and
    `_recreate_supervisor` skips parked entries entirely. The
    `--restart unless-stopped` policy honors a manual stop, so the parked
    container won't auto-restart within the supervisor's lifetime."""
    cname = role_mcp.role_container_name(role)
    run(["docker", "exec", supervisor, "docker", "stop", cname],
        capture_output=True)


def _derive_auto_upstreams(role: str, project: str, cfg: "Config") -> list[str]:
    """Auto-wired upstream set for ``role``: every registered MCP whose
    ``roles`` field lists ``role`` AND that is currently allowed for the
    project. Sorted alphabetically so role-mcps.json diffs across sync
    runs are minimal."""
    try:
        registry = mcp_registry.load(expand=False)
    except mcp_registry.RegistryError as e:
        die(str(e))
    allowed = {e.get("name") for e in load_project_allowlist(project, cfg)
               if e.get("name")}
    return sorted(
        name for name, entry in registry["mcps"].items()
        if role in (entry.get("roles") or [])
        and name in allowed
    )


def _role_mcp_enable(project: str, cfg: "Config", role: str,
                     upstreams: list[str] | None,
                     *, force_auto: bool = False,
                     memory: str | None = None,
                     max_concurrent_calls: int | None = None) -> None:
    """Validate + write the per-project role-mcps.json entry + start the
    container + reload the supervisor's mcp-proxy so its config includes
    the role-MCP route. Idempotent. Enables the worker-facing service only;
    nothing else is started or enabled alongside it.

    Upstream-source state machine:
      - ``upstreams=list, force_auto=False``: explicit pin. Survives sync.
      - ``upstreams=None, force_auto=True``: re-derive from registry × allow,
        write ``upstream_source=auto``. The re-mark path.
      - ``upstreams=None, force_auto=False``:
          - if no existing entry: first-time enable — auto-derive, write
            ``upstream_source=auto``. Empty result warns, unless the role
            ships image-baked tools (``role_mcp.ROLE_BAKED_MCPS``).
          - if an entry exists: idempotent re-run — preserve current
            ``upstream_source`` and ``upstream_mcps``. No silent flips."""
    role_mcp.validate_role(role)
    supervisor = container_name_for(project)
    if not container_running(supervisor):
        die(f"project {project!r} is not running; bring it up first")

    workspace_path = workspace_path_for(project, cfg)
    entries = role_mcp.load_role_mcps(workspace_path)
    existing = entries.get(role)

    if upstreams is not None:
        chosen_upstreams = list(upstreams)
        chosen_source = "explicit"
    elif force_auto or existing is None:
        chosen_upstreams = _derive_auto_upstreams(role, project, cfg)
        chosen_source = "auto"
        # An image-baked role (websearcher) has tools of its own: no
        # proxy-routed upstream is its normal state, so say nothing. For
        # any other role it means the worker has no MCP tools at all. The
        # text names only verbs that parse, and carries no "error: " —
        # the broker relays stderr to the browser only after the first
        # "error: ", so this line stays CLI / host-log only.
        if not chosen_upstreams and role not in role_mcp.ROLE_BAKED_MCPS:
            print(
                f"warning: worker {role!r} has no MCP tools: no MCP allowed "
                f"for project {project!r} claims role {role!r}, and its "
                f"image bakes none. To wire one, register it with "
                f"`research mcp add <name> --kind external --host "
                f"<host:port> --roles {role}` (skip if already registered "
                f"with that role), enable it with `research mcp enable "
                f"<name>`, then allow it and re-wire the worker with "
                f"`research project mcp sync {project}`; or pin MCPs "
                f"already allowed for the project with `research project "
                f"worker enable {project} {role} --upstream <csv>`.",
                file=sys.stderr,
            )
    else:
        # Preserve-on-reenable: idempotent re-run, no silent flips.
        chosen_upstreams = list(existing.get("upstream_mcps") or [])
        chosen_source = existing.get("upstream_source") or "explicit"

    allow_entries = load_project_allowlist(project, cfg)
    try:
        role_mcp.validate_upstreams(chosen_upstreams, allow_entries)
    except ValueError as e:
        die(str(e))

    # Resource caps: explicit flag > existing entry > cfg default. The
    # entry always carries a concrete value so _recreate_supervisor and
    # `role-mcp status` reads don't need access to Config — the persisted
    # state is the source of truth. A bump to DEFAULT_ROLE_MCP_* only
    # affects NEW enables; existing entries keep their captured values
    # until disable+enable (predictable across recreates).
    if memory is not None:
        chosen_memory = memory
    elif existing is not None and existing.get("memory"):
        chosen_memory = str(existing["memory"])
    else:
        chosen_memory = cfg.default_role_mcp_memory

    if max_concurrent_calls is not None:
        chosen_mcc = max_concurrent_calls
    elif existing is not None and existing.get("max_concurrent_calls") is not None:
        chosen_mcc = int(existing["max_concurrent_calls"])
    else:
        chosen_mcc = cfg.default_role_mcp_max_concurrent_calls

    new_entry = role_mcp.build_entry(
        role, chosen_upstreams, upstream_source=chosen_source,
        memory=chosen_memory, max_concurrent_calls=chosen_mcc,
    )
    # Preserve parked state across re-enable / sync re-derive: a worker the
    # operator deliberately stopped (`project worker stop`) stays parked
    # until an explicit `project worker start`. build_entry always renders a
    # running entry, so without this carry-forward a `project mcp sync`
    # re-derive would silently resurrect a stopped worker.
    parked = bool(existing is not None and existing.get("stopped"))
    if parked:
        new_entry["stopped"] = True
    entries[role] = new_entry
    role_mcp.save_role_mcps(workspace_path, entries)

    if parked:
        print(
            f"worker {role!r}: entry updated but left parked — start it with "
            f"`research project worker start {project} {role}`",
            file=sys.stderr,
        )
    else:
        _role_mcp_start(supervisor, project, cfg, role)
        _supervisor_mcp_reload(supervisor)


def _role_mcp_disable(project: str, cfg: "Config", role: str) -> None:
    """Stop the container, drop the role-mcps.json entry, reload the
    proxy. Workspace state under /workspace/.role-mcps/<role>/ (daemon
    state: jobs, memories, global.md, creds) and under
    /workspace/shared/<role>/ (publish surface) both survive — the
    bind-mounts are on the project volume and unaffected by docker rm."""
    supervisor = container_name_for(project)
    workspace_path = workspace_path_for(project, cfg)
    entries = role_mcp.load_role_mcps(workspace_path)
    if role not in entries:
        die(f"role-mcp {role!r} is not enabled for project {project!r}")
    if container_running(supervisor):
        _role_mcp_stop(supervisor, role)
    del entries[role]
    role_mcp.save_role_mcps(workspace_path, entries)
    if container_running(supervisor):
        _supervisor_mcp_reload(supervisor)


def _parse_csv_list(value: str | None) -> list[str]:
    if not value:
        return []
    return [t.strip() for t in value.split(",") if t.strip()]


# ---------------------------------------------------------------------------
# Inner-container state (shared helper)
# ---------------------------------------------------------------------------


def _inner_container_states(supervisor: str) -> dict[str, str]:
    """Map inner-container name → docker state (running/exited/created/dead/…)
    via a single ``docker ps -a``. Empty dict when the supervisor is down, so
    callers fall back to config-only listings (the comprehensive-list rule:
    every subcontainer visible, supervisor up *or* down)."""
    if not container_running(supervisor):
        return {}
    r = run(["docker", "exec", supervisor, "docker", "ps", "-a",
             "--format", "{{.Names}}\t{{.State}}"], capture_output=True)
    if r.returncode != 0:
        return {}
    out: dict[str, str] = {}
    for line in r.stdout.splitlines():
        if "\t" in line:
            n, _, s = line.partition("\t")
            out[n.strip()] = s.strip()
    return out


def _split_enable_tokens(
    enable_arg: str | None,
) -> tuple[str | None, list[str]]:
    """Split ``--enable`` value into (service_csv, worker_roles).

    Tokens are matched by canonical name:
      - a key in ``role_mcp.ROLE_IMAGES`` (e.g. ``wrangler``, ``websearcher``,
        ``echo-mcp``) peels into the worker list,
      - anything else stays for ``_compute_service_flags`` as a service id.

    Empty service set returns None to keep the default intact."""
    if not enable_arg:
        return None, []
    services: list[str] = []
    workers: list[str] = []
    for tok in enable_arg.split(","):
        tok = tok.strip()
        if not tok:
            continue
        if tok in role_mcp.ROLE_IMAGES:
            workers.append(tok)
        else:
            services.append(tok)
    svc_csv = ",".join(services) if services else None
    return svc_csv, workers


def _parse_role_mcp_upstream(
    raw: list[str], *, valid_roles: set[str],
) -> dict[str, list[str]]:
    """Parse repeated ``--role-mcp-upstream <role>=<csv>`` flags into
    ``{role: [mcp_name, ...]}``. Each role must appear in the same
    ``--enable`` set as a role-MCP token, so a typo or stray role-mcp
    surfaces here rather than as an orphan upstream override.

    An entry with empty CSV (``--role-mcp-upstream wrangler=``) means
    'explicit empty' — daemon comes up with no upstreams — distinct from
    the absence of the flag entirely (which falls through to auto-derive)."""
    out: dict[str, list[str]] = {}
    for item in raw:
        if "=" not in item:
            die(f"--role-mcp-upstream value must be 'role=csv', got {item!r}")
        role, _, csv = item.partition("=")
        role = role.strip()
        if not role:
            die(f"--role-mcp-upstream missing role name in {item!r}")
        if role not in valid_roles:
            die(f"--role-mcp-upstream {role!r} not in --enable role-mcp "
                f"set {sorted(valid_roles)}")
        out[role] = _parse_csv_list(csv)
    return out


def _ordered_union(*lists: list[str]) -> list[str]:
    """Concatenate lists preserving first-seen order, dropping duplicates."""
    seen: set[str] = set()
    out: list[str] = []
    for lst in lists:
        for x in lst:
            if x not in seen:
                seen.add(x)
                out.append(x)
    return out


def _split_disable_tokens(
    disable_arg: str | None,
) -> tuple[str | None, list[str]]:
    """Mirror of `_split_enable_tokens` for the disable side: (service_csv,
    workers). `--disable` overrules the default-enable set at `project create`,
    and disables an enabled worker at `project update`."""
    if not disable_arg:
        return None, []
    services: list[str] = []
    workers: list[str] = []
    for tok in disable_arg.split(","):
        tok = tok.strip()
        if not tok:
            continue
        if tok in role_mcp.ROLE_IMAGES:
            workers.append(tok)
        else:
            services.append(tok)
    svc_csv = ",".join(services) if services else None
    return svc_csv, workers


# ---------------------------------------------------------------------------
# Per-supervisor service flags
# ---------------------------------------------------------------------------


def _parse_service_list(s: str | None) -> set[str]:
    if not s:
        return set()
    return {tok for tok in (t.strip() for t in s.split(",")) if tok}


def _compute_service_flags(
    enable_arg: str | None,
    disable_arg: str | None,
    base: dict[str, bool] | None = None,
) -> dict[str, bool]:
    """Resolve per-service enabled flags from --enable / --disable args.

    Default = every known service enabled (or `base` if updating, so missing
    flags inherit the supervisor's prior choices). `supervisor` (the
    SSH + byobu substrate) is always-on and cannot be disabled. Unknown
    service ids are a hard error."""
    enable = _parse_service_list(enable_arg)
    disable = _parse_service_list(disable_arg)
    unknown = (enable | disable) - set(KNOWN_SERVICES)
    if unknown:
        die(f"unknown service id(s): {sorted(unknown)} "
            f"(known: {KNOWN_SERVICES})")
    bad = disable & ALWAYS_ON_SERVICES
    if bad:
        die(f"cannot disable always-on service(s): {sorted(bad)}")

    flags: dict[str, bool] = dict(base) if base else {}
    for sid in KNOWN_SERVICES:
        flags.setdefault(sid, _service_default(sid))
    for sid in disable:
        flags[sid] = False
    for sid in enable:
        flags[sid] = True
    for sid in ALWAYS_ON_SERVICES:
        flags[sid] = True
    return flags


def _read_service_flags(container: str) -> dict[str, bool]:
    """Recover per-service flags from a supervisor's existing labels.
    A missing label (legacy projects, or a service that didn't exist when the
    container was created) falls back to the service's create-time default via
    `_service_default` — ON for most, OFF for DEFAULT_OFF_SERVICES (reader) — so
    the "missing == on-create default" invariant holds for default-off services
    too. Used by `_recreate_supervisor` so a bare `project update` preserves prior
    --enable/--disable choices."""
    if not container_exists(container):
        return {sid: _service_default(sid) for sid in KNOWN_SERVICES}
    r = run(["docker", "inspect", container, "-f",
             "{{json .Config.Labels}}"], capture_output=True)
    try:
        labels = json.loads(r.stdout) or {}
    except json.JSONDecodeError:
        labels = {}
    out: dict[str, bool] = {}
    for sid in KNOWN_SERVICES:
        v = labels.get(f"{SERVICE_LABEL_PREFIX}{sid}")
        # "enabled"/"disabled" are authoritative; a missing label → the default.
        out[sid] = _service_default(sid) if v is None else (v != "disabled")
    for sid in ALWAYS_ON_SERVICES:
        out[sid] = True
    return out


# Live-toggle service-flag overrides. A dind editor toggle (STAGE live-editor)
# deploys/removes code-server via `docker exec` WITHOUT recreating — but a docker
# label is immutable on a running container, so the live choice is recorded here
# and overlaid onto the label-derived flags at the recreate/start paths, so the
# editor survives a restart. update()'s recreate path clears the override for an
# explicitly-changed service afterwards (the fresh label is then authoritative).
def _service_override_path(workspace_path: Path) -> Path:
    return workspace_path / ".orchestrator" / "service-overrides.json"


def _read_service_override(workspace_path: Path) -> dict[str, bool]:
    """{} when absent, unparseable or not usable (a link — orch_files)."""
    try:
        d = json.loads(orch_files.read_text(workspace_path, "service-overrides.json"))
    except (OSError, json.JSONDecodeError):
        return {}
    return {k: bool(v) for k, v in d.items()} if isinstance(d, dict) else {}


def _write_service_override(workspace_path: Path, sid: str, value: bool) -> None:
    """Record a live toggle; a settings folder that is a link refuses (die —
    the live toggles check it before their first side effect)."""
    cur = _read_service_override(workspace_path)
    cur[sid] = bool(value)
    try:
        orch_files.write_text(workspace_path, "service-overrides.json",
                              json.dumps(cur, indent=2, sort_keys=True) + "\n",
                              create=True)
    except orch_files.Unusable as e:
        die(str(e))


def _clear_service_override(workspace_path: Path, sids) -> None:
    cur = _read_service_override(workspace_path)
    if not any(sid in cur for sid in sids):
        return
    for sid in sids:
        cur.pop(sid, None)
    # Runs after a recreate: a settings folder that turned into a link only
    # warns (nothing is written or removed through it).
    try:
        if cur:
            orch_files.write_text(workspace_path, "service-overrides.json",
                                  json.dumps(cur, indent=2, sort_keys=True) + "\n")
        else:
            try:
                orch_files.unlink(workspace_path, "service-overrides.json")
            except FileNotFoundError:
                pass
    except orch_files.Unusable as e:
        print(f"warning: the editor/reader choice was not cleared: {e}",
              file=sys.stderr)


def _apply_service_override(base: dict[str, bool], workspace_path: Path) -> dict[str, bool]:
    """Overlay live-toggle overrides onto a label-derived flag set. ALWAYS_ON
    services are re-forced so a malformed/stale override can't disable the
    supervisor substrate."""
    out = dict(base)
    out.update(_read_service_override(workspace_path))
    for sid in ALWAYS_ON_SERVICES:
        out[sid] = True
    return out


# ---------------------------------------------------------------------------
# webui (browser SSH multiplexer + service-aware proxy host)
# ---------------------------------------------------------------------------


def _supervisor_ssh_pass(container: str) -> str | None:
    """Read SSH_PASSWORD from a supervisor container's env. Returns None
    when the container is missing or the password isn't published."""
    if not container_exists(container):
        return None
    r = run(["docker", "inspect", container, "-f",
             "{{range .Config.Env}}{{println .}}{{end}}"],
            capture_output=True)
    if r.returncode != 0:
        return None
    for line in r.stdout.splitlines():
        if line.startswith("SSH_PASSWORD="):
            return line.split("=", 1)[1]
    return None


def _webui_import_string(project: str, ssh_pass: str) -> str:
    """Build the base64 import string for the webui SPA. Webui reaches the
    supervisor via container DNS on the per-project network (rs-webui is
    `docker network connect`'d to every rs-net-<proj>), not via the
    published host SSH port."""
    return base64.b64encode(json.dumps({
        "name": project,
        "host": container_name_for(project),
        "port": 22,
        "username": "research",
        "password": ssh_pass,
    }).encode()).decode()


def webui_attach_info(req: "AttachRequest", cfg: "Config" | None = None) -> AttachInfo:  # type: ignore[name-defined]
    """The JIT keyring: resolve a project's SSH coordinates so the webui can
    attach without a host-side `research webui import`. Same target shape as
    `_webui_import_string` (container DNS + internal sshd port 22 — the webui
    reaches supervisors over the per-project bridge, not the published host
    port), but structured rather than base64'd because this is a broker→webui
    machine path, not a human paste.

    Returns the password in-memory; NEVER prints/logs it (the broker serialises
    the result over the socket, the audit line records principal/verb/outcome
    only). die()s if the project is absent or not running — a stopped
    supervisor has no bridge endpoint to attach to."""
    if cfg is None:
        cfg = load_config()
    container = container_name_for(req.name)
    if not container_exists(container):
        die(f"project {req.name!r} does not exist")
    if not container_running(container):
        die(f"project {req.name!r} is not running; start it before attaching")
    ssh_pass = _supervisor_ssh_pass(container)
    if not ssh_pass:
        die(f"could not read SSH password for {req.name!r}")
    # port 22 + user 'research' mirror _webui_import_string above; keep the two
    # in lockstep (both describe the same per-project-bridge endpoint).
    return AttachInfo(name=req.name, host=container, port=22,
                      username="research", password=ssh_pass)


def _running_dind_supervisor(project: str) -> str:
    """Resolve + validate a RUNNING dind supervisor (research OR sandbox-dind) for
    the box_* AND ext_* verbs, returning its container name. die()s (→ the broker's
    `failed` envelope) if the project is absent, stopped, or the docker containment
    substrate (no inner dockerd → no boxes/extensions). The box harness and
    extensions are a standing dind utility on BOTH flavors now (STAGE_DIND_UNIFY),
    so flavor is no longer rejected here — only the substrate is. The substrate
    die() makes the webui's Boxes/Extensions surfaces self-hide on a docker box,
    mirroring how those sections gate."""
    container = container_name_for(project)
    if not container_exists(container):
        die(f"project {project!r} does not exist")
    if not container_running(container):
        die(f"project {project!r} is not running; start it before managing "
            f"boxes or extensions")
    if _container_substrate(container) == Substrate.DOCKER.value:
        die(f"project {project!r} uses the docker containment substrate (no inner "
            f"dockerd); boxes and extensions are unavailable")
    return container


# Host store for preset-field env files: ~/.research-sandbox/box-env/<project>/
# <box>.env — HOST-ONLY (never mounted anywhere; same tier as the dev consumer
# tokens), 0700 dirs / 0600 files. The durable root that survives supervisor
# recreates: _recreate_supervisor re-streams it into the supervisor's
# ~/.rs-box-env/, which rs-sandbox's create→cp→start reads. Swept at box remove
# (its file) and project destroy (the project dir).
BOX_ENV_DIR = Path.home() / ".research-sandbox" / "box-env"


def _render_box_env(values: dict) -> str:
    """The box env file: `export K=V` lines, shell-quoted, sorted for a stable
    diffable file. Pure — the single place field VALUES are serialized, so the
    quoting is testable without any I/O. Sourced by the box entrypoint and by
    every login shell; never expanded host-side."""
    lines = [f"export {k}={shlex.quote(v)}" for k, v in sorted(values.items())]
    return "\n".join(lines) + "\n"


def _stage_box_env_files(project: str, container: str) -> None:
    """Re-stream every host-stored box env file into the supervisor's
    ~/.rs-box-env/ (a recreate wiped that copy; _rerun_box's create→cp→start
    reads it). Best-effort per file: a failed restage degrades to a box whose
    preset MCP errors visibly in-session — never a failed recreate."""
    env_dir = BOX_ENV_DIR / project
    if not env_dir.is_dir():
        return
    for f in sorted(env_dir.glob("*.env")):
        try:
            content = f.read_text()
        except OSError:
            continue
        r = run(["docker", "exec", "-i", "-u", "research", container, "sh", "-c",
                 'umask 077 && mkdir -p "$HOME/.rs-box-env" && cat > "$HOME/.rs-box-env/$1"',
                 "sh", f.name], input=content, capture_output=True)
        if r.returncode != 0:
            print(f"warning: failed to restage box env file {f.name!r}; that "
                  f"box's preset MCP lacks its field values until a later "
                  f"restage", file=sys.stderr)


# --- Gitea history for a box (OK_BOX slice 3) --------------------------------

# The in-box status file is a box-controlled path read on the serial thread:
# `-f` refuses a FIFO, and the read itself is bounded (a few bytes, a few
# seconds — a healthy read is instant; at expiry the outcome reads unknown).
HISTORY_STATUS_READ_TIMEOUT_S = 5
_HISTORY_CODE_RE = re.compile(r"\A[a-z]+(?::[a-z-]+)?\Z")
_HISTORY_GITEA_FAILED_LINE = ("History: off — the Gitea side could not be set "
                              "up; the box was created without history. Remove "
                              "the box and add it again to retry.")
_OLD_BOX_TOOL_HISTORY_MSG = ("this project's box tool predates Gitea history — "
                             "restart the project, then retry")


def _history_status_line(code: str, repo: str) -> str:
    """A box's history outcome code → one fixed operator line (unknown → a
    generic one). Every "off" line names a browser-only remedy."""
    where = f"notes/{repo}"
    return {
        "on": (f"History: on — the notes are kept in the Gitea repo {where} "
               f"(the box's (GIT) tab). Pull-and-push sync is turned on when "
               f"OpenKnowledge first starts there."),
        "off:no-address": ("History: off — the box started without its Gitea "
                           "address; restart the project to restore it."),
        "off:no-token": ("History: off — the box started without its Gitea "
                         "access; restart the project to restore it."),
        "off:clone-failed": ("History: off — the notes repo could not be "
                             "cloned; restart the project before writing notes "
                             "(a fresh box retries the clone)."),
        "off:not-a-clone": ("History: off — the box's notes folder already "
                            "holds files that are not a clone of its notes repo; "
                            "move the whole notes folder aside in the box, then "
                            "restart the project."),
        "off:push-failed": ("History: off for now — the first push failed; it is "
                            "retried at the box's next fresh start (a project "
                            "restart)."),
    }.get(code, "History: off — the box's history setup did not report back; "
                "check the box's terminal message.")


def _read_history_status(container: str, box_container: str) -> str:
    r = run(["docker", "exec", container, "docker", "exec", box_container,
             "timeout", str(HISTORY_STATUS_READ_TIMEOUT_S), "sh", "-c",
             'f="$HOME/.rs-history-status"; [ -f "$f" ] && [ ! -L "$f" ] && head -c 64 "$f"'],
            capture_output=True)
    code = (r.stdout or "").strip() if r.returncode == 0 else ""
    return code if _HISTORY_CODE_RE.match(code) else ""


def _box_entry_saved(workspace_path: "Path", name: str | None) -> bool:
    """Did the box tool save this box's record? Unreadable → treated as saved
    (everything is kept; the box's Remove cleans up)."""
    try:
        return bool(name) and name in extension.load(workspace_path)
    except (OSError, ValueError, RecursionError):
        return True


def _retire_history_rows(project: str, rows: list[dict], container: str) -> list[str]:
    """Retire each history row: resume the Gitea (short budget, SystemExit
    caught), archive the repo, delete the account and token (host + staged),
    prune the row. Per-row, never raising; returns operator lines."""
    out: list[str] = []
    serving = True
    try:
        _resume_gitea(require=True, tries=GITEA_RESUME_WAIT_TRIES)
    except SystemExit:
        serving = False
    for e in rows:
        user, repo = e.get("user") or "", e.get("repo") or ""
        try:
            if serving and user and repo:
                out += gitea.retire_history(
                    _gitea_host_port(), user, repo,
                    replaced_by=("the next box of this name" if e.get("box")
                                 else "a project re-created under this name"))
            else:
                if user:
                    gitea.delete_consumer_token(user)
                why = ("Gitea is not answering" if not serving
                       else "its record is incomplete")
                out.append(f"the notes repo {gitea.HISTORY_ORG}/{repo} could not "
                           f"be archived ({why}); archive it from the Gitea tab")
        except Exception:                    # never let one row stop the rest
            out.append(f"the notes repo {gitea.HISTORY_ORG}/{repo} could not be "
                       f"retired cleanly")
        try:
            gitea.prune_entry(project, repo, box=e.get("box"),
                              klass=gitea.HISTORY_CLASS)
        except Exception:
            pass
        if user and container_running(container):
            run(["docker", "exec", "-u", "research", container, "sh", "-c",
                 'rm -f "$HOME/.dev-tokens/$1"', "sh", f"{user}.token"],
                capture_output=True)
    return out


# The one refusal for a box type with its own web app on a project whose box
# tool or box images predate web apps. A restart fixes it: it re-stages the box
# tool and moves the project's boxes to the host's current box images.
_WEB_BOX_TOO_OLD_MSG = ("this project's boxes predate box types that start "
                        "their own web app — restart the project, then retry")
# The in-image path of the web-app loop: its presence tells a current box
# image from an older one. LOCKSTEP with agent/Dockerfile.sandbox-box's COPY.
BOX_WEB_LOOP_PATH = "/usr/local/bin/rs-web-loop"


# --- A docker project's own web app (a workflow manifest's `web`) -----------
# The project runs the box's mechanism: rs-web-loop/rs-web-set/rs-web-restart
# are baked into rs-minimal at the same paths, its entrypoint starts the loop
# when WEB_ENV_START is set, and the host hands it the tab's address. The env
# names are the box's own (rs_sandbox passes them to a web box), so the scripts
# stay one set. The setup text rides the env too, because the host re-runs it
# after every rebuild (the rebuild resets the image-resident home).
WEB_ENV_START = "RS_BOX_WEB_START"
WEB_ENV_PORT = "RS_BOX_WEB_PORT"
WEB_ENV_SETUP = "RS_BOX_SETUP"
# The setup marker, in the project user's home: rs-web-loop starts nothing and
# rs-web-set reports not-ready until it exists. LOCKSTEP with both scripts.
WEB_SETUP_DONE = ".rs-box-setup-done"
# MIRROR of rs_sandbox's WEB_READY_WAIT_S / WEB_PROBE_TIMEOUT_S /
# WEB_SET_MARGIN_S (pinned — rscore cannot import that tool): the bound on one
# in-project rs-web-set call, which holds the serial broker.
_WEB_READY_WAIT_S = 4
_WEB_PROBE_TIMEOUT_S = 1
_WEB_SET_MARGIN_S = 3
WEB_SET_TIMEOUT_S = _WEB_READY_WAIT_S + _WEB_PROBE_TIMEOUT_S + _WEB_SET_MARGIN_S

_WEB_IMAGE_TOO_OLD_MSG = (
    "the project image predates workflows that start their own app; rebuild "
    "the images under Sandboxes → Software → Rebuild all, then create the "
    "project again")
_WEB_SETUP_FAILED_LINE = (
    "The project's web app could not be installed, so it stays stopped; stop "
    "the project and start it again to retry.")
_WEB_NOT_RUNNING_MSG = "the project is not running; start it to open this tab"


def _web_from_env(env: dict) -> dict | None:
    """A docker project's web app from its container env ({start, port,
    setup}), or None when the project has none (or the three are not all
    there, which create never writes)."""
    start, setup = env.get(WEB_ENV_START), env.get(WEB_ENV_SETUP)
    try:
        port = int(env.get(WEB_ENV_PORT, ""))
    except ValueError:
        return None
    if not start or not setup:
        return None
    return {"start": start, "port": port, "setup": setup}


def _project_web(container: str) -> dict | None:
    """The web app a docker project's container was created with — read from
    its own env, which works on a stopped container too. None ⇒ none."""
    r = run(["docker", "container", "inspect", "-f", "{{json .Config.Env}}",
             container], capture_output=True)
    if r.returncode != 0:
        return None
    try:
        entries = json.loads(r.stdout)
    except ValueError:
        return None
    env: dict[str, str] = {}
    for entry in entries if isinstance(entries, list) else []:
        if isinstance(entry, str) and "=" in entry:
            k, v = entry.split("=", 1)
            env[k] = v
    return _web_from_env(env)


def _gate_project_web_image() -> None:
    """Refuse a web-app project on an rs-minimal image built before the web
    scripts were baked: its tab would wait for an app nothing starts. One short
    offline container run; before anything is created."""
    r = run(["docker", "run", "--rm", "--network", "none", "--entrypoint",
             "test", MINIMAL_IMAGE, "-x", BOX_WEB_LOOP_PATH], capture_output=True)
    if r.returncode != 0:
        raise ValidationError(_WEB_IMAGE_TOO_OLD_MSG)


def _register_project_web_tab(workspace_path: "Path", web: dict) -> None:
    """The top-level tab entry {port, label, web: true} for the project's own
    web app (port_add's plain-branch dedupe + sort). Written right after the
    container is up, before the setup, so a failed setup never leaves the
    project without the tab."""
    ports = [e for e in read_exported_ports(workspace_path)
             if not (e.get("port") == web["port"] and not e.get("passthrough"))]
    ports.append({"port": web["port"], "label": web["label"], "web": True})
    ports.sort(key=lambda e: e["port"])
    _write_exported_ports(workspace_path, ports)


def _mark_project_setup_done(container: str) -> None:
    """Write the setup marker and wake the loop (rs-web-restart signals it
    only after checking the pid file names the loop), so the app starts now
    rather than at the loop's next recheck. HarnessError on failure."""
    _light_exec(container,
                f'touch "$HOME/{WEB_SETUP_DONE}" && rs-web-restart >/dev/null',
                step="workflow setup marker", github_pat="")


def _project_setup_done(container: str) -> bool:
    return run(["docker", "exec", "-u", "research", container, "sh", "-c",
                f'test -e "$HOME/{WEB_SETUP_DONE}"'],
               capture_output=True).returncode == 0


def _rerun_project_setup(container: str, web: dict, progress) -> None:
    """Re-run a web-app project's setup in /workspace (the rebuild or an
    earlier failure left it unfinished), then mark it done. Warn and continue
    on failure: the rebuild or start itself took effect, the app stays
    stopped, and the next start retries. The only two callers are the
    editor-toggle rebuild and a plain start."""
    print("running the workflow setup (it installs the project's web app)...")
    try:
        _light_exec(container, web["setup"], step="workflow setup",
                    github_pat="", workdir="/workspace")
        _mark_project_setup_done(container)
    except HarnessError as e:
        print(f"warning: {e.log_msg}: {e.client_detail}", file=sys.stderr)
        progress.step("warning", _WEB_SETUP_FAILED_LINE)


def _gate_box_web(container: str, want_browser: bool) -> None:
    """Refuse a web-app box on a project whose box tool or box image predates
    web apps. A missing tool passes (a research project stages it later), and
    so does a missing image (its lazy delivery then brings the current one)."""
    r = run(["docker", "exec", container, "rs-sandbox", "--help"],
            capture_output=True)
    if r.returncode == 0 and "web-address" not in (r.stdout or ""):
        raise ValidationError(_WEB_BOX_TOO_OLD_MSG)
    image = SANDBOX_BOX_BROWSER_IMAGE if want_browser else SANDBOX_BOX_IMAGE
    if run(["docker", "exec", container, "docker", "image", "inspect", image],
           capture_output=True).returncode != 0:
        return
    r = run(["docker", "exec", container, "docker", "run", "--rm",
             "--network", "none", "--entrypoint", "test", image,
             "-x", BOX_WEB_LOOP_PATH], capture_output=True)
    if r.returncode != 0:
        raise ValidationError(_WEB_BOX_TOO_OLD_MSG)


def _browser_image_trust(container: str) -> str:
    """The project's browser box image vs trusted browsers: "yes" (it carries
    the label), "no" (it exists without it) or "absent" (not in the project —
    research delivers it lazily)."""
    r = run(["docker", "exec", container, "docker", "image", "inspect", "-f",
             "{{index .Config.Labels \"" + BROWSER_TRUST_LABEL + "\"}}",
             SANDBOX_BOX_BROWSER_IMAGE], capture_output=True)
    if r.returncode != 0:
        return "absent"
    return "yes" if (r.stdout or "").strip() == "1" else "no"


def _gate_box_trusted_browser(container: str) -> None:
    """Refuse a trusted browser box, before any side effect, when the project's
    box tool or browser image predates trusted browsers. An absent tool or
    image passes here (research stages and delivers them next); box_add asks
    the image again after that delivery."""
    r = run(["docker", "exec", container, "rs-sandbox", "create", "--help"],
            capture_output=True)
    if r.returncode == 0 and "--trusted-browser" not in (r.stdout or ""):
        raise ValidationError(_OLD_BOX_TOOL_TRUSTED_MSG)
    if _browser_image_trust(container) == "no":
        raise ValidationError(_TRUSTED_BROWSER_TOO_OLD_MSG)


# --- A docker project's Gitea history (a workflow's `gitea_history`) -----------
# The box's in-box history step, run host-side in the project container as its
# user. rscore cannot import the box tool, so it keeps a BYTE-PINNED copy of
# rs_sandbox._HISTORY_SCRIPT (template + the same two substitutions, from
# mirrored constants) and derives the project's variant from it by a fixed list
# of exact replacements, each of which must match once — the box's bytes never
# change. The project's account and repo come from gitea.project_history_names.
# MIRROR of rs_sandbox.HISTORY_GITEA_PORT / HISTORY_PUSH_TIMEOUT_S (pinned).
_HISTORY_GITEA_PORT = "3000"
_HISTORY_PUSH_TIMEOUT_S = 60
_BOX_HISTORY_SCRIPT = r"""
T="$HOME/.rs-history.token"; S="$HOME/.rs-history-status"; N=/workspace/notes
INC="$HOME/.rs-history.gitconfig"
URL="http://rs-gitea:@@PORT@@/notes/$RS_HISTORY_REPO.git"
_rs_hist_text() {
  case "$1" in
    on) printf '%s\n' "History: on. These notes are kept in the Gitea repo notes/$RS_HISTORY_REPO (this box's (GIT) tab in the webui)." "Pull-and-push sync is turned on when OpenKnowledge first starts here, so edits are pushed.";;
    off:no-address|off:no-token) printf '%s\n' "History: off. This box started without its Gitea access; restart the project to restore it.";;
    off:clone-failed) printf '%s\n' "History: off. The notes repo could not be cloned; restart the project before writing notes (a fresh box retries the clone).";;
    off:not-a-clone) printf '%s\n' "History: off. /workspace/notes already holds files that are not a clone of the notes repo; move the whole notes folder aside in this box (mv /workspace/notes /workspace/notes.old), then restart the project.";;
    off:push-failed) printf '%s\n' "History: off for now. The first push to the notes repo failed; it is retried at the next fresh start of this box.";;
    *) printf '%s\n' "History: off.";;
  esac
}
_rs_hist_greet() {
  G=/workspace/.rs-greeting
  [ -f "$G" ] && [ ! -L "$G" ] || return 0
  tmp=$(mktemp /workspace/.rs-greeting.XXXXXX) || return 0
  awk '/^--- Gitea history ---$/{skip=1} !skip{print} /^--- end of Gitea history ---$/{skip=0}' "$G" > "$tmp" 2>/dev/null
  { printf '%s\n' "--- Gitea history ---"; _rs_hist_text "$1"; printf '%s\n' "--- end of Gitea history ---"; } >> "$tmp"
  mv -f "$tmp" "$G"
}
_rs_hist_status() { printf '%s\n' "$1" > "$S"; _rs_hist_greet "$1"; }
[ -n "$RS_HISTORY_GITEA" ] || { _rs_hist_status off:no-address; exit 0; }
[ -s "$T" ] || { _rs_hist_status off:no-token; exit 0; }
if [ "$RS_HIST_MODE" = heal ] || [ ! -e "$INC" ]; then
  tmp=$(mktemp "$INC.XXXXXX") || { _rs_hist_status off:no-token; exit 0; }
  chmod 600 "$tmp"
  printf '[url "http://%s:%s@%s:@@PORT@@/"]\n\tinsteadOf = http://rs-gitea:@@PORT@@/\n' "$RS_HISTORY_USER" "$(cat "$T")" "$RS_HISTORY_GITEA" > "$tmp"
  mv -f "$tmp" "$INC"
fi
git config --global --get-all include.path 2>/dev/null | grep -qxF "$INC" || git config --global --add include.path "$INC"
git config --global user.name "$RS_HISTORY_USER"
git config --global user.email "$RS_HISTORY_USER@rs.invalid"
# A heal before the box's own setup finished touches only the address: the
# setup is still cloning/pushing and owns the status.
if [ "$RS_HIST_MODE" = heal ] && [ ! -f "$HOME/.rs-box-setup-done" ]; then exit 0; fi
# Clone only into NOTHING or a real empty folder — never over a file or a link
# named notes (anything else falls to the not-a-clone check below).
if [ "$RS_HIST_MODE" != heal ] && { { [ ! -e "$N" ] && [ ! -L "$N" ]; } || { [ -d "$N" ] && [ ! -L "$N" ] && [ -z "$(ls -A "$N" 2>/dev/null)" ]; }; }; then
  # Clone under a FRESH hidden name, then move it into place with one rename
  # (`mv -T`): the rename lands only onto an absent path or a still-empty
  # folder and refuses if anything was written into notes/ meanwhile, so the
  # operator's files are never touched. git cleans up only the folder it
  # created itself on a failure; a clone killed outright stays under its hidden
  # name (nothing here deletes anything) and the next fresh start clones anew.
  TC=$(mktemp -u /workspace/.rs-notes-clone.XXXXXX) || { _rs_hist_status off:clone-failed; exit 0; }
  GIT_TERMINAL_PROMPT=0 timeout @@PUSH@@ git clone -q "$URL" "$TC" >/dev/null 2>&1 || { _rs_hist_status off:clone-failed; exit 0; }
  git -C "$TC" rev-parse --verify -q HEAD >/dev/null 2>&1 || git -C "$TC" symbolic-ref HEAD refs/heads/main
  mv -T "$TC" "$N" 2>/dev/null || { _rs_hist_status off:not-a-clone; exit 0; }
fi
# A heal never clones: an empty notes/ without a clone stays clone-failed (the
# setup's verdict), never relabelled as "not a clone".
if [ "$RS_HIST_MODE" = heal ] && [ ! -d "$N/.git" ] && [ -z "$(ls -A "$N" 2>/dev/null)" ]; then
  _rs_hist_status off:clone-failed; exit 0
fi
[ "$(git -C "$N" config --get remote.origin.url 2>/dev/null)" = "$URL" ] || { _rs_hist_status off:not-a-clone; exit 0; }
PUSHED=
if ! git -C "$N" rev-parse -q --verify main@{u} >/dev/null 2>&1; then
  git -C "$N" rev-parse --verify -q HEAD >/dev/null 2>&1 || git -C "$N" commit -q --allow-empty -m "Start the notes" >/dev/null 2>&1
  GIT_TERMINAL_PROMPT=0 timeout @@PUSH@@ git -C "$N" push -q -u origin main >/dev/null 2>&1 || { _rs_hist_status off:push-failed; exit 0; }
  PUSHED=1
fi
_rs_hist_status on
# A heal that just completed the first push turned history on under a running
# web app that started while it was still off: restart that app so it starts
# with history on (OpenKnowledge then turns on its sync). Only on this change —
# every other heal leaves the app running.
if [ "$RS_HIST_MODE" = heal ] && [ -n "$PUSHED" ] && [ -x /usr/local/bin/rs-web-restart ]; then
  /usr/local/bin/rs-web-restart >/dev/null 2>&1 || true
fi
""".replace("@@PORT@@", _HISTORY_GITEA_PORT).replace(
    "@@PUSH@@", str(_HISTORY_PUSH_TIMEOUT_S))

# The project variant's text table (the terminal greeting's history paragraph).
_PROJECT_HISTORY_TEXT = r"""_rs_hist_text() {
  case "$1" in
    on) printf '%s\n' "History: on. These notes are kept in the Gitea repo notes/$RS_HISTORY_REPO (this project's (GIT) tab in the webui)." "Pull-and-push sync is turned on when OpenKnowledge first starts here, so edits are pushed.";;
    off:no-address|off:no-token) printf '%s\n' "History: off. This project started without its Gitea access; stop the project and start it again to restore it.";;
    off:clone-failed) printf '%s\n' "History: off. The notes repo could not be cloned; stop the project and start it again before writing notes (the start retries the clone).";;
    off:not-a-clone) printf '%s\n' "History: off. /workspace/notes already holds files that are not a clone of the notes repo; move the whole notes folder aside (mv /workspace/notes /workspace/notes.old), then stop the project and start it again.";;
    off:push-failed) printf '%s\n' "History: off for now. The first push to the notes repo failed; it is retried when the project is next started.";;
    *) printf '%s\n' "History: off.";;
  esac
}
"""
_REMOTE_CHECK_LINE = ('[ "$(git -C "$N" config --get remote.origin.url 2>/dev/null)" '
                      '= "$URL" ] || { _rs_hist_status off:not-a-clone; exit 0; }\n')


def _derive_project_history_script(box: str) -> str:
    """The box's history step, made the project's: the token the project
    stages (no second copy), its greeting file, its text table, and the
    commit identity set in the notes repo only (the project keeps the human's
    own global identity), after the remote check — so a fresh clone and an
    existing one both get it before the first commit."""
    t0 = box.index("_rs_hist_text() {")
    t1 = box.index("esac\n}\n", t0) + len("esac\n}\n")
    swaps = [
        ('T="$HOME/.rs-history.token"', 'T="$HOME/.dev-tokens/$RS_HISTORY_USER.token"'),
        ("G=/workspace/.rs-greeting\n", "G=/workspace/.orchestrator/greeting\n"),
        ("mktemp /workspace/.rs-greeting.XXXXXX", "mktemp /workspace/.orchestrator/.greeting.XXXXXX"),
        ('git config --global user.name "$RS_HISTORY_USER"\n', ""),
        ('git config --global user.email "$RS_HISTORY_USER@rs.invalid"\n', ""),
        (_REMOTE_CHECK_LINE, _REMOTE_CHECK_LINE
         + 'git -C "$N" config user.name "$RS_HISTORY_USER"\n'
         + 'git -C "$N" config user.email "$RS_HISTORY_USER@rs.invalid"\n'),
        (box[t0:t1], _PROJECT_HISTORY_TEXT),
    ]
    out = box
    for old, new in swaps:
        if out.count(old) != 1:
            raise RuntimeError(f"history script anchor not unique: {old[:40]!r}")
        out = out.replace(old, new)
    return out


PROJECT_HISTORY_SCRIPT = _derive_project_history_script(_BOX_HISTORY_SCRIPT)
# The host waits for one run of it at most this long: the script bounds its
# clone and its first push by _HISTORY_PUSH_TIMEOUT_S each and does nothing
# else slow; the margin covers the exec itself. Past it the run is cut and the
# status stays `off:pending` (OpenKnowledge waits; the next start retries).
PROJECT_HISTORY_RUN_TIMEOUT_S = 2 * _HISTORY_PUSH_TIMEOUT_S + _WEB_SET_MARGIN_S
# What the host writes into the status file before each run (and when it skips
# one): OpenKnowledge's start script waits on any `off` it does not know, so
# it can never start in an un-cloned notes/ while history is undecided.
HISTORY_PENDING = "off:pending"
# How long a rebuild waits for the entrypoint's own home restore before the
# history step (it writes global git settings the restore would overwrite).
# ~/.rs-role is written right after the restore and the agent dists' copy —
# local file copies, seconds — and BEFORE the editor deploy that create gives
# EDITOR_READY_TIMEOUT_S, so the same budget is ample by construction. At
# expiry the step is skipped (status `off:pending`) and the next start runs it.
HOME_RESTORE_WAIT_S = EDITOR_READY_TIMEOUT_S

_PROJECT_HISTORY_GITEA_FAILED_LINE = (
    "History: off — the Gitea side could not be set up; the project was created "
    "without history. Destroy the project and create it again to retry.")


def _project_history_status_line(code: str, repo: str) -> str:
    """A project's history outcome code → one fixed operator line (unknown →
    a generic one). Every "off" line names a browser-only remedy."""
    return {
        "on": (f"History: on — the notes are kept in the Gitea repo "
               f"{gitea.HISTORY_ORG}/{repo} (the project's (GIT) tab). "
               f"Pull-and-push sync is turned on when OpenKnowledge first "
               f"starts there."),
        "off:no-address": ("History: off — the project started without its "
                           "Gitea address; stop the project and start it again "
                           "to restore it."),
        "off:no-token": ("History: off — the project started without its Gitea "
                         "access; stop the project and start it again to "
                         "restore it."),
        "off:clone-failed": ("History: off — the notes repo could not be "
                             "cloned; stop the project and start it again before "
                             "writing notes (the start retries the clone)."),
        "off:not-a-clone": ("History: off — the project's notes folder already "
                            "holds files that are not a clone of its notes "
                            "repo; move the whole notes folder aside in the "
                            "project's terminal, then stop the project and start "
                            "it again."),
        "off:push-failed": ("History: off for now — the first push failed; it "
                            "is retried when the project is next started."),
        HISTORY_PENDING: ("History: off — the history setup did not finish; "
                          "stop the project and start it again."),
    }.get(code, "History: off — the project's history setup did not report "
                "back; stop the project and start it again.")


def _project_history_row(project: str) -> dict | None:
    """The project's own history ledger row (class history, no box) with its
    account and repo names, or None."""
    try:
        rows = gitea.project_entries(project)
    except Exception:
        return None
    return next((e for e in rows
                 if e.get("class") == gitea.HISTORY_CLASS and e.get("box") is None
                 and isinstance(e.get("user"), str) and e.get("user")
                 and isinstance(e.get("repo"), str) and e.get("repo")), None)


def _read_project_history_status(container: str) -> str:
    """The project's history status code (the box read's guards: a regular
    file only, a few bytes, bounded), or "" when unreadable."""
    r = run(["docker", "exec", "-u", "research", container,
             "timeout", str(HISTORY_STATUS_READ_TIMEOUT_S), "sh", "-c",
             'f="$HOME/.rs-history-status"; [ -f "$f" ] && [ ! -L "$f" ] && head -c 64 "$f"'],
            capture_output=True)
    code = (r.stdout or "").strip() if r.returncode == 0 else ""
    return code if _HISTORY_CODE_RE.match(code) else ""


def _write_history_pending(container: str) -> bool:
    """Mark history undecided, by a fresh file renamed over the status file —
    never by opening it (a FIFO there would hang the host) — under the status
    read's bound (a few bytes; anything slower is a planted obstacle)."""
    r = run(["docker", "exec", "-u", "research", container,
             "timeout", str(HISTORY_STATUS_READ_TIMEOUT_S), "sh", "-c",
             't=$(mktemp "$HOME/.rs-history-status.XXXXXX") || exit 1; '
             'if printf "%s\\n" "$1" > "$t" && mv -T "$t" "$HOME/.rs-history-status"; '
             'then exit 0; fi; rm -f -- "$t"; exit 1',
             "sh", HISTORY_PENDING], capture_output=True)
    return r.returncode == 0


def _run_project_history(container: str, row: dict) -> bool:
    """Mark history pending, then run the history step once (bounded). False
    only when the pending mark could not be written — the caller then holds
    the setup back too, so OpenKnowledge cannot start in an un-cloned notes/.
    The step's own outcome is read from the status file, never from here."""
    if not _write_history_pending(container):
        return False
    run(["docker", "exec", "-u", "research",
         "-e", "RS_HIST_MODE=setup",
         "-e", f"RS_HISTORY_GITEA={gitea.GITEA_CONTAINER}",
         "-e", f"RS_HISTORY_USER={row['user']}",
         "-e", f"RS_HISTORY_REPO={row['repo']}",
         container, "timeout", str(PROJECT_HISTORY_RUN_TIMEOUT_S),
         "bash", "-c", PROJECT_HISTORY_SCRIPT], capture_output=True)
    return True


def _wait_for_home_restore(container: str) -> bool:
    deadline = time.monotonic() + HOME_RESTORE_WAIT_S
    while True:
        if run(["docker", "exec", "-u", "research", container,
                "timeout", str(HISTORY_STATUS_READ_TIMEOUT_S), "sh", "-c",
                'test -e "$HOME/.rs-role"'], capture_output=True).returncode == 0:
            return True
        if time.monotonic() >= deadline:
            return False
        time.sleep(1)


def _provision_project_history(project: str, claim: dict, container: str,
                               cfg: "Config") -> dict | None:  # type: ignore[name-defined]
    """The box's provisioning order for a project: connect the Gitea, create
    or reuse the repo and the account, record the row (no box), stage the
    token. Any failure cleans up the record and token and returns None."""
    user, repo = claim["user"], claim["repo"]
    try:
        ip = _connect_gitea_to_project_network(project_network_for(project))
        if not ip:
            raise gitea.GiteaError("the Gitea has no address on this project")
        gitea.provision_history(_gitea_host_port(), user, repo,
                                leftover=bool(claim.get("leftover")))
        gitea.record_attachment(project, gitea.HISTORY_CLASS, repo, ip,
                                box=None, user=user)
        _stage_dev_gitea(project, cfg, gitea_ip=ip)
        return {"user": user, "repo": repo}
    except (gitea.GiteaError, SystemExit, OSError) as e:
        print(f"warning: Gitea history setup for project {project!r} failed: {e}",
              file=sys.stderr)
        _cleanup_box_history(project, None, user, repo, container)
        return None


def _warn_history_not_on(container: str, row: dict, progress) -> bool:
    """After a history run on a rebuild or start: a `warning` row (the only
    step those tails draw) unless history is on. True when it is on."""
    code = _read_project_history_status(container)
    if code != "on":
        progress.step("warning", _project_history_status_line(code, row["repo"]))
    return code == "on"


def _rebuild_project_steps(project: str, container: str, web: dict,
                           cfg: "Config", progress) -> None:  # type: ignore[name-defined]
    """After an editor-toggle rebuild of a web-app project: history (when the
    project keeps it), then the setup. The token is re-staged first — a host
    file streamed in, using the ledger's Gitea address, so a stopped Gitea
    costs nothing here. History waits for the entrypoint's own home restore;
    past HOME_RESTORE_WAIT_S it is skipped (pending, retried at the next
    start). A pending mark that cannot be written holds the setup back too."""
    row = _project_history_row(project)
    if row is not None:
        _stage_dev_gitea(project, cfg, serving=False)
        if _wait_for_home_restore(container):
            held = not _run_project_history(container, row)
        else:
            print("warning: the project's home was not ready in time; history is "
                  "left to the next start", file=sys.stderr)
            held = not _write_history_pending(container)
        if held:
            progress.step("warning", _project_history_status_line(HISTORY_PENDING,
                                                                  row["repo"]))
            return
        _warn_history_not_on(container, row, progress)
    _rerun_project_setup(container, web, progress)


def _retry_project_steps(project: str, container: str, web: dict, progress) -> None:
    """A plain start of a web-app project retries what did not finish: history
    when the project keeps it and it is not on, then the setup when its marker
    is absent. One wake from the host at most: the setup's marker step
    already restarts the app; otherwise a history that just turned on
    restarts it here, so OpenKnowledge starts with history on (its sync
    setting). The loop may also start an app that was waiting for history by
    itself once history is on; a second start is harmless."""
    row = _project_history_row(project)
    turned_on = False
    if row is not None and _read_project_history_status(container) != "on":
        if not _run_project_history(container, row):
            progress.step("warning", _project_history_status_line(HISTORY_PENDING,
                                                                  row["repo"]))
            return
        turned_on = _warn_history_not_on(container, row, progress)
    if not _project_setup_done(container):
        _rerun_project_setup(container, web, progress)
    elif turned_on:
        run(["docker", "exec", "-u", "research", container, "rs-web-restart"],
            capture_output=True)


def _write_marker_history(workspace_path: "Path") -> None:
    """Record `history: true` in project.json, keeping every other key — the
    webui's only signal for the project's (GIT) tab (it reads nothing else
    of history; the repo name is derived from the project name). Best effort:
    an unreadable marker (a link included — orch_files) is left as it is."""
    try:
        data = json.loads(_read_marker_text(workspace_path))
    except (OSError, ValueError):
        return
    if not isinstance(data, dict):
        return
    data["history"] = True
    try:
        _write_marker_text(workspace_path, data)
    except orch_files.Unusable:
        return


_WEB_TAB_MISSING_LINE = ("The box was added without its {label} tab; remove "
                         "the box and add it again.")


def _register_box_web_tab(workspace_path: "Path", info: dict, web_spec: dict,
                          progress, want_name: str | None = None) -> None:
    """Write the exported-port entry {port: pub_super, label, box, app_port,
    web: true} for a just-created web-app box (port_add's box-branch dedupe +
    sort). An output without a usable publish port keeps the box, untabbed,
    with a warning step."""
    label = str(web_spec.get("label") or "")
    app_port = web_spec.get("port")
    web = info.get("web")
    pub = web.get("pub_super") if isinstance(web, dict) else None
    if (not isinstance(pub, int) or isinstance(pub, bool)
            or not _EXPORT_BOX_LOOPBACK_PORT_LO <= pub <= _EXPORT_BOX_LOOPBACK_PORT_HI
            or not isinstance(app_port, int) or isinstance(app_port, bool)):
        progress.step("warning", _WEB_TAB_MISSING_LINE.format(label=label))
        return
    box = info.get("name")
    # The tool's output is data: the name must be a box name, and this add's.
    if not (isinstance(box, str) and _BOX_NAME_RE.match(box)) \
            or (want_name and box != want_name):
        progress.step("warning", _WEB_TAB_MISSING_LINE.format(label=label))
        return
    ports = [e for e in read_exported_ports(workspace_path)
             if not (e.get("box") == box and e.get("app_port") == app_port)]
    ports.append({"port": pub, "label": label, "box": box,
                  "app_port": app_port, "web": True})
    ports.sort(key=lambda e: e["port"])
    _write_exported_ports(workspace_path, ports)


def _require_share_aware_box_tool(container: str, help_out=None) -> None:
    """Refuse, before any Gitea work, when the project's box tool predates
    file sharing: every add passes --share/--no-share, so an older tool would
    take a dev box's or a history box's Gitea provisioning and only then
    refuse the create (which cleans none of it up). A tool that cannot be
    asked (absent, a failed exec) is not judged here — the create reports."""
    r = help_out if help_out is not None else run(
        ["docker", "exec", container, "rs-sandbox", "create", "--help"],
        capture_output=True)
    if r.returncode == 0 and "--share" not in (r.stdout or ""):
        raise ValidationError(_OLD_BOX_TOOL_SHARE_MSG)


def _require_home_skills_box_tool(container: str) -> None:
    """Refuse an add when the project's box tool predates RS keeping its files
    in the agents' homes (a project not restarted since): its answer to the
    home-skills command is the older parser's refusal."""
    r = run(["docker", "exec", container, "rs-sandbox", "home-skills", "--help"],
            capture_output=True)
    if _is_old_box_tool(r):
        raise ValidationError(_OLD_BOX_TOOL_FILES_MSG)


def _require_harness_aware_box_tool(container: str) -> None:
    """Refuse, before any Gitea work, when the project's box tool predates the
    working-mode flags (a project not restarted since RS gained them): the add
    would otherwise take a dev box's Gitea provisioning and only then refuse
    the create. A tool that cannot be asked is not judged here."""
    r = run(["docker", "exec", container, "rs-sandbox", "create", "--help"],
            capture_output=True)
    if r.returncode == 0 and "--harness-mode" not in (r.stdout or ""):
        raise ValidationError(_OLD_BOX_TOOL_HARNESS_MSG)


def _refuse_harness_on_research(container: str) -> None:
    """A research project never stages the working-mode suite, so a box there
    cannot take a mode or doer/checker models."""
    if _container_project_type(container) != PROJECT_TYPE_SANDBOX_DIND:
        raise ValidationError(
            "a box in a research project has no working mode or doer and checker agents")


def _gate_box_history(req: "BoxAddRequest", catalog: dict, container: str,
                      workspace_path: "Path") -> dict:
    """Every Gitea-history refusal, before any side effect; the Gitea-touching
    claims last. Returns the claim (names + leftover) for the provisioning."""
    if not catalog.get(req.preset, {}).get("gitea_history"):
        raise ValidationError(
            f"box type {req.preset!r} does not keep history on Gitea")
    if req.fetch:
        raise ValidationError(
            "a box keeping history on Gitea cannot also take rs-fetch (the "
            "fetch wiring re-creates the box when the Gitea moves)")
    if not gitea.bootstrap_present():
        raise ValidationError(
            "this box keeps history on Gitea, but Gitea is not enabled on this "
            "host yet — enable it from the Sandboxes page, then retry")
    if not req.name:
        raise ValidationError(
            "a box keeping history on Gitea needs a name (its Gitea account "
            "and notes repo are named after it)")
    problem = gitea.history_name_problem(req.project, req.name)
    if problem:
        raise ValidationError(problem)
    try:
        existing = extension.load(workspace_path)
    except (OSError, ValueError, RecursionError):
        raise ValidationError("could not read this project's boxes")
    if req.name in existing:
        raise ValidationError(
            f"a box named {req.name!r} already exists in this project")
    # An older box tool would answer the history options with usage text after
    # the Gitea work; probe it first. Absent → the harness step stages the
    # current one.
    r = run(["docker", "exec", container, "rs-sandbox", "create", "--help"],
            capture_output=True)
    if r.returncode == 0 and "--history-user" not in (r.stdout or ""):
        raise ValidationError(_OLD_BOX_TOOL_HISTORY_MSG)
    # A tool with history but older than file sharing would take the Gitea
    # work and then refuse the always-passed --share/--no-share.
    _require_share_aware_box_tool(container, help_out=r)
    try:
        _resume_gitea(require=True, tries=GITEA_RESUME_WAIT_TRIES)
    except SystemExit:
        raise ValidationError("Gitea is not answering right now; retry in a moment")
    try:
        return gitea.history_claim(_gitea_host_port(), req.project, req.name,
                                   gitea.load_attachments())
    except gitea.GiteaError as e:
        raise ValidationError(str(e))


def _provision_box_history(req: "BoxAddRequest", claim: dict, container: str,
                           cfg: "Config") -> bool:
    """Connect the Gitea to the project's network, create/reuse the repo and the
    account, record the row, stage the token into the project container. Any
    failure cleans up the record and token and returns False."""
    user, repo = claim["user"], claim["repo"]
    try:
        ip = _connect_gitea_to_project_network(project_network_for(req.project))
        if not ip:
            raise gitea.GiteaError("the Gitea has no address on this project")
        gitea.provision_history(_gitea_host_port(), user, repo,
                                leftover=bool(claim.get("leftover")))
        gitea.record_attachment(req.project, gitea.HISTORY_CLASS, repo, ip,
                                box=req.name, user=user)
        _stage_dev_gitea(req.project, cfg, gitea_ip=ip)
        return True
    except (gitea.GiteaError, SystemExit, OSError) as e:
        print(f"warning: Gitea history setup for box {req.name!r} failed: {e}",
              file=sys.stderr)
        _cleanup_box_history(req.project, req.name, user, repo, container)
        return False


def _cleanup_box_history(project: str, box: str | None, user: str, repo: str,
                         container: str) -> None:
    """Drop a history row and its token (host + staged); the account stays
    (the next add of this name treats it as a leftover)."""
    gitea.prune_entry(project, repo, box=box, klass=gitea.HISTORY_CLASS)
    gitea.delete_consumer_token(user)
    if container_running(container):
        run(["docker", "exec", "-u", "research", container, "sh", "-c",
             'rm -f "$HOME/.dev-tokens/$1"', "sh", f"{user}.token"],
            capture_output=True)


def _mailbox_name_clash(name: str, workspace_path: "Path") -> str:
    """Why a box of this name cannot own a mailbox, or "". Reads the worker
    registry files directly (<workspace>/.workers/<name>.json, tombstones
    included); an unreadable registry reads as no workers. Wording names only
    the validated box name."""
    folded = name.casefold()
    if folded in {r.casefold() for r in RESERVED_MAILBOX_NAMES}:
        return (f"{name!r} is a reserved name (the project agent's mailbox or a "
                f"role service's folder under shared/); pick another")
    try:
        stems = [p.stem for p in (workspace_path / ".workers").iterdir()
                 if p.suffix == ".json"]
    except OSError:
        stems = []
    if any(w.casefold() == folded for w in stems):
        return (f"{name!r} is a worker's name in this project (workers keep "
                f"their names for good); pick another")
    return ""


BOX_LEFTOVER_INSTRUCTIONS_ERROR = (
    "the folder kept from an earlier box named {box} holds `CLAUDE.md`, that box's "
    "instructions file. Remove or rename `/workspace/boxes/{box}/CLAUDE.md` from the "
    "project's terminal or editor, then add the box again.")


BOX_LEFTOVER_FILES_ERROR = (
    "the folder kept from an earlier box named {box} holds files RS used to write "
    "there: {paths}. Remove or rename them from the project's terminal or editor, "
    "then add the box again.")


def _box_leftover_instructions(workspace_path: "Path", name: str) -> "bool | None":
    """Whether the box's kept folder holds a CLAUDE.md (a file or a link, a
    dangling one included): True / False, or None when it cannot be told.
    Every component below the workspace is opened without following a link
    (the folders are the project's own), so nothing outside it is probed."""
    try:
        bfd = os.open(workspace_path / "boxes", os.O_PATH | os.O_DIRECTORY | os.O_NOFOLLOW)
    except FileNotFoundError:
        return False
    except OSError:
        return None
    try:
        try:
            dfd = os.open(name, os.O_PATH | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=bfd)
        except FileNotFoundError:
            return False
        except OSError:
            return None
        try:
            os.stat("CLAUDE.md", dir_fd=dfd, follow_symlinks=False)
            return True
        except FileNotFoundError:
            return False
        except OSError:
            return None
        finally:
            os.close(dfd)
    finally:
        os.close(bfd)


def _refuse_box_leftover_instructions(workspace_path: "Path", name: str) -> None:
    """ValidationError when the box's kept folder holds RS's old CLAUDE.md, or
    when that cannot be told (never read as "absent")."""
    found = _box_leftover_instructions(workspace_path, name)
    if found is False:
        # Every other file RS used to write into a box's folder (every kind's
        # paths: the earlier box's type is not known), walked from the
        # project's folder without following a link.
        old = [r for r in BOX_OLD_PATHS + OK_BOX_OLD_PATHS
               if _old_path_present(workspace_path, f"boxes/{name}/{r}")]
        if old:
            raise ValidationError(BOX_LEFTOVER_FILES_ERROR.format(
                box=name, paths=_shown_old_paths(name, old)))
        return
    if found:
        raise ValidationError(BOX_LEFTOVER_INSTRUCTIONS_ERROR.format(box=name))
    raise ValidationError(f"could not check the folder of box {name!r} in the "
                          f"project; check that /workspace/boxes/{name} is a folder")


def box_add(req: "BoxAddRequest", progress=None) -> BoxAddResult:  # type: ignore[name-defined]
    """Create a sandbox box in a running sandbox-dind supervisor by driving its
    in-box `rs-sandbox create`. Validated fields only reach the list-form argv
    (no shell); the box itself is the security boundary (locked egress, no
    creds). Returns the box's recorded coordinates."""
    progress = progress or _NULL_PROGRESS
    progress.step("validate", "checking the project")
    cfg = load_config()
    container = _running_dind_supervisor(req.project)
    workspace_path = workspace_path_for(req.project, cfg)
    # A reserved entry left in the port list is dropped and said here, before
    # the web-app tab write below would drop it silently.
    _drop_reserved_port_entries(req.project, cfg, progress)
    # An agent this project never staged cannot reach the box (the merged
    # copy-source holds the project's set + claude, even where the project's own
    # container runs fewer) — refuse by name, before any side effect, rather
    # than mint a box whose tab says "command not found" (STAGE_PI_AGENT; the
    # docker-substrate update takes the same posture).
    if req.agent not in (None, "none"):
        carried = _read_dind_agent_sets(workspace_path)[0]
        if req.agent not in carried:
            raise ValidationError(
                f"this project carries {', '.join(carried)} — add {req.agent!r} to "
                f"the project (Config → Agents) before giving a box to it")
    # One mailbox namespace with the workers and the project agent: a reserved
    # name or a worker's name (live or tombstoned — .workers/*.json, project-
    # permanent), compared case-folded. Host half of the two-gate lockstep with
    # rs-sandbox create (which also gates an auto-named box). Before the
    # catalog staging below, so a refusal writes nothing.
    if req.name is not None:
        clash = _mailbox_name_clash(req.name, workspace_path)
        if clash:
            raise ValidationError(clash)
        # A folder kept from an earlier box of this name that still holds RS's
        # old instructions file belongs to that box: refuse before ANY side
        # effect (the Gitea consumer, fork and attachment of a dev box, the
        # env file, the history account). The box tool repeats the check as
        # its own first gate (it also sees auto-named boxes).
        _refuse_box_leftover_instructions(workspace_path, req.name)
    # Refresh the staged box-preset catalog (Q1→live: an operator-registered type in
    # box-registry.json becomes usable on this already-created project). strict=True
    # → a malformed registry surfaces as ValidationError, not a half-built box.
    try:
        staged = _stage_box_catalog(workspace_path, strict=True)
    except box_catalog.BoxCatalogError as e:
        raise ValidationError(str(e))
    # Semantic gating against the JUST-STAGED catalog (reuse the returned bytes —
    # no second load_catalog(), so no unguarded BoxCatalogError escape past
    # dispatch) + the project allowlist. The in-box rs-sandbox re-gates too; this
    # yields a clean pre-exec ValidationError.
    catalog = {e["name"]: e for e in staged}
    if req.preset != "empty" and req.preset not in catalog:
        raise ValidationError(
            f"unknown box preset {req.preset!r} "
            f"(available: {sorted({'empty', *catalog})})")
    # Image tri-state resolved HERE, in the gate block — pure data over
    # catalog + req — so ALL gating (the collision pre-flight below needs it)
    # precedes ALL side effects (harness/image delivery, editor staging, gitea
    # wiring). `catalog.get(...,{})` degrades correctly for `empty` (absent ⇒
    # base unless the request overrides).
    want_browser = (req.browser if req.browser is not None
                    else catalog.get(req.preset, {}).get("image") == "browser")
    # A trusted browser needs the browser on — a pure check, so here, before
    # every side effect (a dev preset resolves to the base image, so this
    # refuses a trusted dev box before the dev block touches the Gitea).
    if req.trusted_browser and not want_browser:
        raise ValidationError("a trusted browser needs the browser on")
    # Sharing files with the project, resolved the same way (the box type's
    # share_default when the caller did not say) and ALWAYS passed explicitly
    # below: a box tool older than sharing then refuses the add instead of
    # giving every box the old mailbox mounts.
    want_share = (req.share if req.share is not None
                  else catalog.get(req.preset, {}).get("share_default") is True)
    # Collision pre-flight: the box entrypoint's .mcp.json merge REFUSES on a
    # name collision, and under --restart unless-stopped that is a silent
    # crash-loop (box_add reports success; the tab never comes up; the signal
    # lives in inner docker logs). Both collision classes are statically known
    # here, so refuse at the form. Names are schema tokens — safe to echo.
    preset_mcp_names = set(catalog.get(req.preset, {}).get("mcp_servers") or {})
    if want_browser:
        clash = sorted(preset_mcp_names & set(box_catalog.BAKED_BROWSER_MCPS))
        if clash:
            raise ValidationError(
                f"preset MCP server name(s) {', '.join(clash)} collide with "
                f"the browser image's baked tools; rename them in the preset "
                f"or run this box without the browser")
    clash = sorted(preset_mcp_names & set(req.mcps))
    if clash:
        raise ValidationError(
            f"preset MCP server name(s) {', '.join(clash)} collide with "
            f"selected project MCP(s); deselect or rename them")
    allowed = {e["name"] for e in load_project_allowlist(req.project, cfg)
               if e.get("name")}
    bad = [m for m in req.mcps if m not in allowed]
    if bad:
        raise ValidationError(
            f"MCP(s) {bad} are not allowed for project {req.project!r}; allow them "
            f"first (`research project mcp allow ...`) or omit them")
    # The working mode and doer/checker models: a dev box with an agent, in a
    # project that stages the suite (never research), the pairs following the
    # box's EFFECTIVE agent — all pure checks (one docker inspect for the
    # project type, one box-tool probe), before any Gitea work and the box
    # tool / image staging.
    harness = _harness_set(req)
    if harness:
        harness_agent = req.agent if req.agent is not None else (
            DEFAULT_AGENT if catalog.get(req.preset, {}).get("agent_default") else "none")
        if not catalog.get(req.preset, {}).get("dev"):
            raise ValidationError(
                "the working mode and the Doer and Checker models are for dev boxes")
        _refuse_harness_on_research(container)
        if harness_agent == "none":
            raise ValidationError("a box without an agent has no working mode")
        _validated_harness({f: harness.get(f, "") for f in HARNESS_FIELDS}, dev=True,
                           agents=[harness_agent])
        _require_harness_aware_box_tool(container)
    # Dev preset (STAGE_DEV_GITEA S2): mirror the in-supervisor rs-sandbox gates
    # host-side for a clean pre-exec ValidationError (the two-gate lockstep).
    # `repo` carries NAME semantics here (an attached gitea repo), not the byo
    # clone URL; ref/setup/mcps are rejected — the dev clone is the authed gitea
    # lane, and the box's dedicated bridge has no path to mcp-proxy.
    is_dev_preset = bool(catalog.get(req.preset, {}).get("dev"))
    if req.branch and not is_dev_preset:
        raise ValidationError(
            "branch is only valid for a dev box; a byo box pins its clone with "
            "'ref' (which also accepts a tag or commit)")
    effective_branch = ""
    if is_dev_preset:
        # First in the block: refuse before any mirror/gitea work below.
        if req.folders:
            raise ValidationError("a dev box does not take read-only folders")
        if req.history:
            raise ValidationError("a dev box cannot keep notes history on Gitea")
        if req.mcps:
            raise ValidationError(
                "a dev box cannot take MCPs (its dedicated bridge has no path "
                "to mcp-proxy)")
        if req.ref or req.setup:
            raise ValidationError("ref/setup are not valid for a dev box")
        # Base-image only, by catalog rule (dev:true requires image:'base').
        # Placed HERE — before any mirror/gitea/identity work — so a refusable
        # request refuses without a dev lane even existing.
        if req.browser is True:
            raise ValidationError(
                "a dev box cannot take the browser image (dev presets are "
                "base-image only)")
        if req.field_values:
            raise ValidationError(
                "a dev box does not take preset input fields (the catalog "
                "forbids fields on dev presets)")
        if req.fetch:
            raise ValidationError(
                "a dev box does not take the rs-fetch option (it works its "
                "own fork; the read-only fetch surface is for non-dev boxes)")
        if not _valid_dev_repo_name(req.repo):
            raise ValidationError(
                "a dev box requires 'repo': the NAME of an added dev repo")
        # Mirror-stamp floor (per-consumer forks: no attachment prerequisite —
        # the box mints its OWN consumer below, 4c-a).
        if not gitea.mirror_present(req.repo):
            raise ValidationError(
                f"repo {req.repo!r} not added yet — add it first (the dev "
                f"workflow card and the dev box dialog take its GitHub URL)")
        # The box's gitea identity (agent-<project>.<name>) and its token must
        # exist BEFORE `rs-sandbox create` runs the container, so the name
        # cannot be auto-assigned in-box for a dev box.
        if not req.name:
            raise ValidationError(
                "a dev box requires an explicit name (its gitea identity is "
                "minted from <project>.<name> before the box runs)")
        # Base branch: resolve to a CONCRETE name here — the box's clone AND its
        # CLAUDE.md both need a real name, and a bad one must refuse BEFORE any
        # harness/image work below (byo's nonexistent-ref crash-loop is the
        # failure mode this exists to avoid). Needs the mirror, which the stamp
        # floor above just established.
        effective_branch = _resolve_dev_branch(req.repo, req.branch)
        # ...and refuse a BOX name whose dev identity survived an earlier box's
        # removal, for the same reason and with the same timing: inside the dev
        # block (gitea is up — the fetch floor below is outside it and runs with
        # gitea possibly stopped), and before any harness/image work.
        _refuse_retired_identity(gitea.agent_username(
            gitea.consumer_for(req.project, req.name)))
    # Fail-early rs-fetch floor (the dev-lane bootstrap_present precedent): an
    # explicit fetch ask on a host whose dev lane was never enabled refuses
    # BEFORE any harness/image/editor work below — and AFTER the dev-preset
    # gate above, so a dev+fetch request gets the correct dev refusal, never a
    # misleading Gitea remedy. _resume_gitea(require=True) in the fetch branch
    # below stays the TOCTOU authority. Webui-safe wording (no CLI verbs).
    if req.fetch and not gitea.bootstrap_present():
        raise ValidationError(
            "this box requests rs-fetch, but the dev lane (Gitea) is not "
            "enabled on this host yet — enable Gitea from the Sandboxes "
            "page, then retry")
    # Node gate: a node box copies the project's staged node seed at boot. Both
    # probes run ONLY for a node preset (no other box add gains a docker exec).
    # Refuse when neither the project nor the host has the seed; the host-has-it
    # case is staged after the harness step below.
    needs_node = bool(catalog.get(req.preset, {}).get("node"))
    node_staged = needs_node and _node_dist_staged_in(container)
    if needs_node and not node_staged and not node_dist_present():
        raise ValidationError(
            "this box type needs node, but node is not installed on this host "
            "yet — pull node under Sandboxes → Software, then retry")
    # Fields gate (after the dev gate, so dev+fields gets the dev refusal):
    # provided names must EQUAL the preset's declared set — every declared
    # field is required, undeclared ones refused. Messages name KEYS only;
    # the values can be API keys and must never enter an error string.
    declared = {f["name"]
                for f in (catalog.get(req.preset, {}).get("fields") or [])}
    provided = set(req.field_values)
    if provided != declared:
        parts = []
        missing = sorted(declared - provided)
        extra = sorted(provided - declared)
        if missing:
            parts.append(f"missing required field(s): {', '.join(missing)}")
        if extra:
            parts.append(f"field(s) not declared by this preset: "
                         f"{', '.join(extra)}")
        raise ValidationError("; ".join(parts))
    # Read-only folders: every level of each path must be a real folder right
    # now, and the project's box tool must take nested paths (after the dev
    # gate, so dev+folders gets the dev refusal; before every side effect, so
    # a refusal creates nothing).
    if req.folders:
        _check_box_folders(workspace_path, req.folders)
        _gate_box_tool_folder_paths(container, "create", req.folders)
    # A box type with its own web app needs a box tool and box image that
    # carry the web-app machinery; both probes run before the history gate
    # (which may start the Gitea), so this refusal starts nothing.
    web_spec = catalog.get(req.preset, {}).get("web")
    if web_spec:
        _gate_box_web(container, want_browser)
    # A trusted browser needs a box tool and a browser image that know trusted
    # browsers (the browser-off refusal ran with the image resolution above).
    # Before the history gate, like the web-app probes.
    if req.trusted_browser:
        _gate_box_trusted_browser(container)
    # Gitea history: every refusal here, before any side effect (the claims
    # that need the Gitea run last, so a cheap refusal never starts it).
    hist_claim = (_gate_box_history(req, catalog, container, workspace_path)
                  if req.history else None)
    # Lazily stand up the box harness. On research this stages rs-sandbox + brings
    # the needed box image in on first use (research create never touches boxes
    # — the frozen lane); where the project holds the image it no-ops. want_browser
    # was resolved in the gate block above, so the image the box will run IS the
    # one delivered (a research project's lazy delivery keys on this).
    progress.step("harness", "ensuring the box harness")
    _ensure_box_harness(container, project_network_for(req.project),
                        workspace_path, want_browser)
    # A box tool from before RS kept its files in the agents' homes would write
    # them into the new box's folder (and set no record), so the project's next
    # start would report files RS had just written: refuse it, before any Gitea
    # work below. A tool that cannot be asked is not judged here.
    _require_home_skills_box_tool(container)
    # The image is in the project now. An image the project already held is
    # the one its last start brought, which may predate trusted browsers on a
    # project not restarted since: ask again, before the history provisioning,
    # the dev wiring and the create.
    if req.trusted_browser and _browser_image_trust(container) != "yes":
        raise ValidationError(_TRUSTED_BROWSER_TOO_OLD_MSG)
    # Editor dist on demand (the staged-catalog Q1-live precedent above): an
    # editor box RO-mounts the supervisor's /opt/editor-dist, and a project
    # created before the host had a cached editor dist never got it staged —
    # without this, such a project can never grow an editor box short of a
    # recreate, silently. ORDER IS LOAD-BEARING: the editor_dist_present()
    # guard must stay BEFORE _stage_editor_dist — that helper die()s naming a
    # CLI verb, and die text is browser-reachable via the op tail; the
    # ValidationError below is the webui-safe refusal for the no-host-cache
    # case. deploy_local stays False: stage the mount source only, never the
    # supervisor's own editor.
    if req.editor and not _editor_dist_staged_in(container):
        if editor_dist_present():
            _stage_editor_dist(container)
        else:
            raise ValidationError(
                "this box requests the editor, but the editor software is not "
                "installed on this host yet — install it from Sandboxes → "
                "Software, then retry")
    # Node seed on demand (the editor-dist precedent above): a project created or
    # last restarted before node was pulled has no seed staged. Stage it only
    # when absent — a re-stage would cost a full stream (see _node_dist_staged_in).
    if needs_node and not node_staged:
        progress.step("node", "staging node into the project")
        _stage_node_dist(container)
    # Dev preset: wire gitea + mint the BOX's own consumer (user + fork +
    # token) BEFORE the box runs — ordering is load-bearing: connect → provision
    # → ledger → staging (the token lands in ~/.dev-tokens for rs-sandbox to
    # read at `docker run`). 4c-a: no project-level fork rides this path.
    box_user = ""
    if catalog.get(req.preset, {}).get("dev"):
        # Before any Gitea work: an older box tool would refuse the create
        # only after the consumer, fork and ledger row below exist.
        _require_share_aware_box_tool(container)
        _resume_gitea(require=True)     # a dev box NEEDS gitea; never create
        network = project_network_for(req.project)
        ip = _connect_gitea_to_project_network(network)
        if not ip:
            die(f"rs-gitea did not attach to {network} (no IP); check docker state")
        box_user = gitea.agent_username(
            gitea.consumer_for(req.project, req.name))
        try:
            gitea.provision_consumer(_gitea_host_port(), req.repo, box_user,
                                     default_branch=effective_branch)
        except gitea.GiteaError as e:
            raise ValidationError(str(e))
        gitea.record_attachment(req.project, "agent", req.repo, ip,
                                box=req.name, user=box_user,
                                branch=effective_branch)
        _stage_dev_gitea(req.project, cfg, gitea_ip=ip)
    # Opt-in rs-fetch wiring (host side): resume gitea (the authority behind
    # the bootstrap floor above), connect it to this project's network, ensure
    # the workspace wiring carries the gitea_ip (rs_sandbox._staged_gitea_ip's
    # source for the box --add-host), then stage the supervisor halves the box
    # run copies in: the rs-fetch tool + read-only operator token
    # (_stage_dev_fetch) and the GLOBAL repo->active-fork wiring
    # (_stage_fetch_wiring). This ordering makes the box-side copy sources
    # present by construction before `rs-sandbox create --fetch` runs below.
    # Mutually exclusive with the dev branch above (fetch is rejected there).
    if req.fetch:
        _resume_gitea(require=True)
        network = project_network_for(req.project)
        ip = _connect_gitea_to_project_network(network)
        if not ip:
            die(f"rs-gitea did not attach to {network} (no IP); check docker state")
        _stage_dev_gitea(req.project, cfg, gitea_ip=ip)
        _stage_dev_fetch(container)
        _stage_fetch_wiring(container)
    # Agent model + effort for this box (STAGE_MODEL_SELECT). Explicit wins;
    # otherwise the project's `box` pair from the marker — which create already
    # wrote CONCRETE and effort-drop-resolved, so it is safe to use as-is. A box
    # does NOT inherit the supervisor's pair: one type, one lookup.
    # The pair is claude's (STAGE_PI_AGENT): resolve the box's EFFECTIVE
    # agent (explicit, else the preset default; the implicit `empty` preset has
    # none) and thread the marker's default pair only for a claude box. (An
    # explicit pair on a non-claude agent was already refused in from_kwargs.)
    eff_agent = req.agent if req.agent is not None else (
        DEFAULT_AGENT if catalog.get(req.preset, {}).get("agent_default") else "none")
    box_pair = (_read_models(workspace_path).get("box") or {}) if eff_agent == DEFAULT_AGENT else {}
    box_model = req.model or box_pair.get("model") or ""
    box_effort = req.effort or box_pair.get("effort") or ""
    if box_model and box_effort:
        # Re-check the RESOLVED pair: an explicit `--model haiku` against a
        # defaulted `max` must drop the effort, not compose an impossible pair.
        # An explicit effort that the resolved model cannot support already died
        # in from_kwargs when both were given; here only the defaulted half can
        # be at fault, so dropping (never raising) is the right move.
        _cat = _model_catalog_checked()
        if not model_catalog.supports_effort(box_model, box_effort, _cat):
            if req.effort:
                raise ValidationError(
                    f"model {box_model!r} does not accept an effort level; "
                    f"remove the effort setting for this box")
            box_effort = ""
    # Preset-field env staging — after every gate (a rejected request must
    # leave no file), before the rs-sandbox exec (cmd_create requires the
    # supervisor-home copy for a fields preset). Values ride the file + stdin
    # ONLY: never this argv, never docker -e, never the workspace.
    if req.field_values:
        env_text = _render_box_env(dict(req.field_values))
        host_dir = BOX_ENV_DIR / req.project
        host_dir.mkdir(parents=True, exist_ok=True)
        os.chmod(BOX_ENV_DIR, 0o700)
        os.chmod(host_dir, 0o700)
        host_file = host_dir / f"{req.name}.env"
        fd = os.open(host_file, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
        with os.fdopen(fd, "w") as fh:
            fh.write(env_text)
        r = run(["docker", "exec", "-i", "-u", "research", container, "sh", "-c",
                 'umask 077 && mkdir -p "$HOME/.rs-box-env" && cat > "$HOME/.rs-box-env/$1"',
                 "sh", f"{req.name}.env"], input=env_text, capture_output=True)
        if r.returncode != 0:
            host_file.unlink(missing_ok=True)
            die(f"failed to stage the box env file into the supervisor: "
                f"{(r.stderr or r.stdout).strip()}")
    # Gitea history provisioning — LAST before the create, so no refusal can
    # follow it. A failure here drops the history record and token, leaves the
    # account as a leftover, and the box is created without history.
    history_line = ""
    history_args: list[str] = []
    if hist_claim is not None:
        progress.step("history", "setting up Gitea history")
        if _provision_box_history(req, hist_claim, container, cfg):
            history_args = [f"--history-user={hist_claim['user']}",
                            f"--history-repo={hist_claim['repo']}"]
        else:
            history_line = _HISTORY_GITEA_FAILED_LINE
    argv = ["docker", "exec", container, "rs-sandbox", "create"]
    if req.name:
        argv.append(req.name)
    argv += ["--preset", req.preset]
    if req.agent is not None:
        argv += ["--agent", req.agent]
    if box_model:
        argv += ["--model", box_model]
    if box_effort:
        argv += ["--effort", box_effort]
    if req.editor:
        argv.append("--editor")
    # Tri-state: thread the flag ONLY when the caller was explicit, so the
    # in-supervisor rs-sandbox applies the preset default itself on None (the
    # two resolvers stay in agreement by construction).
    if req.browser is not None:
        argv.append("--browser" if req.browser else "--no-browser")
    if req.trusted_browser:
        argv.append("--trusted-browser")
    if req.fetch:
        argv.append("--fetch")
    if req.mcps:
        argv += ["--mcps", ",".join(req.mcps)]
    if req.repo:
        argv += ["--repo", req.repo]
    if req.ref:
        argv += ["--ref", req.ref]
    if req.setup:
        argv += ["--setup", req.setup]
    # Always concrete for a dev box (resolved above); empty for every other
    # preset, where the flag is rejected at both gates.
    if effective_branch:
        argv += ["--branch", effective_branch]
    if box_user:
        argv += ["--gitea-user", box_user]
    # One argv word (`--folders=…`): a name may start with "-", which the box
    # tool's parser would read as an option if it stood alone.
    if req.folders:
        argv.append("--folders=" + ",".join(req.folders))
    argv.append("--share" if want_share else "--no-share")
    argv += history_args
    # Only the set ones: a box without them keeps today's exact argv. One argv
    # word each (`--x=value`): a pi model may start with "-" (the --folders case).
    for f, v in harness.items():
        argv.append(f"--{f.replace('_', '-')}={v}")
    progress.step("create-box", "creating the box")
    r = run(argv, capture_output=True)
    if r.returncode != 0:
        # A failed add must not orphan staged secrets (both copies best-effort;
        # the box itself never ran or was rm'd by rs-sandbox's own die path).
        if req.field_values:
            (BOX_ENV_DIR / req.project / f"{req.name}.env").unlink(missing_ok=True)
            run(["docker", "exec", "-u", "research", container, "sh", "-c",
                 'rm -f "$HOME/.rs-box-env/$1"', "sh", f"{req.name}.env"],
                capture_output=True)
        # History wiring made for a box that never got a record: drop it (the
        # account stays as a leftover). A saved record keeps everything for
        # the box's Remove.
        if history_args and not _box_entry_saved(workspace_path, req.name):
            _cleanup_box_history(req.project, req.name, hist_claim["user"],
                                 hist_claim["repo"], container)
        if _is_old_box_tool(r):
            # Every add passes --share/--no-share, so any old tool refuses;
            # name the newest feature it lacks that this add asked for.
            err = (r.stderr or "") + (r.stdout or "")
            if req.folders and "--folders" in err:
                die(_OLD_BOX_TOOL_MSG)
            if history_args and "--history-" in err:
                die(_OLD_BOX_TOOL_HISTORY_MSG)
            if harness and any(f"--{f.replace('_', '-')}" in err for f in harness):
                die(_OLD_BOX_TOOL_HARNESS_MSG)
            if req.trusted_browser and "--trusted-browser" in err:
                die(_OLD_BOX_TOOL_TRUSTED_MSG)
            die(_OLD_BOX_TOOL_SHARE_MSG)
        die(f"failed to add box: {(r.stderr or r.stdout).strip()}")
    try:
        info = json.loads(r.stdout)            # rs-sandbox create prints the entry
    except (json.JSONDecodeError, TypeError):
        die(f"could not parse rs-sandbox output: {r.stdout.strip()!r}")
    # Shape-guard the indexing so a returncode-0-but-wrong-shape output die()s
    # (→ SystemExit, caught by the broker) rather than raising a KeyError/TypeError
    # that would escape dispatch's invariant; box_list is already .get()-defensive.
    if not isinstance(info, dict) or not all(k in info for k in ("name", "ip", "container")):
        die(f"unexpected rs-sandbox output shape: {r.stdout.strip()!r}")
    # Folders the box started without (read tolerantly: an older box tool
    # reports none). One progress line each, built here from validated names.
    raw_warnings = info.get("warnings")
    folder_warnings = _box_folder_warnings(
        # A history warning at the add is said once, by the history line below.
        [w for w in raw_warnings if not (isinstance(w, dict) and w.get("kind") == "history")]
        if (isinstance(raw_warnings, list) and history_args) else raw_warnings,
        info.get("name"))
    for line in folder_warnings:
        progress.step("warning", line)
    # The box's folder holding RS's old files (only a history box is checked
    # at its first run): the add fails at its end, the box kept for Remove.
    create_old = _box_old_items(req.project, info.get("name"), raw_warnings)
    # The box type's own web app: register its tab now, from the publish port
    # the box tool allocated before the box's first run. The label and app
    # port come from this host's catalog copy, never from the tool's output.
    if web_spec:
        _register_box_web_tab(workspace_path, info, web_spec, progress,
                              want_name=req.name)
    # Boot hold: `rs-sandbox create` returns once the box RUNS, but its clone,
    # checkout and setup run afterwards in the entrypoint under `set -e` and
    # --restart unless-stopped — a failing one restarted forever while this
    # add said ready. Wait for the boot's ready line; a restart before it
    # fails the add with the failed boot's own log and stops the box (kept,
    # for Remove). Ahead of the editor wait so a crash-looping editor box
    # fails here instead of burning that wait.
    progress.step("boot", "waiting for the box to start")
    boot, boot_state, boot_finished = _wait_for_box_boot(
        container, info["container"], info["name"])
    if boot == "failed":
        stopped = run(["docker", "exec", container, "rs-sandbox", "stop",
                       info["name"]], capture_output=True).returncode == 0
        secrets = [v for f in (catalog.get(req.preset, {}).get("fields") or [])
                   if isinstance(f, dict) and f.get("secret") is True
                   for v in [req.field_values.get(f.get("name"))] if v]
        # Unlike the history line below (a fixed code → fixed text), this
        # text DOES carry the box's own output: the operator needs the cause
        # in the browser. It is sanitised, secret-redacted and capped as data.
        tail = _box_boot_failure_text(container, info["container"],
                                      info["name"], boot_state, boot_finished,
                                      secrets)
        what = ("it has been stopped" if stopped
                else "it could not be stopped and keeps retrying")
        die(f"box {info['name']!r} failed to start ({boot_state}); {what}. "
            f"The end of its startup log:\n{tail}\n"
            f"Remove the box and add it again once the cause above is fixed "
            f"(for example a repository ref that exists, or a setup command "
            f"that succeeds).")
    boot_timed_out = boot == "timeout"
    if boot_timed_out:
        print(f"warning: box {info['name']!r} still starting after "
              f"{BOX_BOOT_TIMEOUT_S}s — it may still be cloning or installing; "
              f"check the box's tab before starting the agent")
    # Editor readiness gate (create()'s editor-gate shape): the box's stub only
    # listens ~15-30s after `docker run` (in-box extension installs first), and
    # the webui re-fetches the tab set the moment this op completes — without
    # the wait it probes a not-yet-listening port and the Editor tab never
    # renders while the operator is looking. op-done ⇒ tab probeable.
    # Best-effort: a slow editor warns, never fails an otherwise-healthy box.
    if req.editor:
        progress.step("editor", "waiting for the box editor")
        if not _wait_for_box_editor_ready(container, info["container"]):
            print(f"warning: box editor not listening on :{CODE_SERVER_STUB_PORT} "
                  f"after {EDITOR_READY_TIMEOUT_S}s; it should come up shortly")
    # Preset setup hold (the editor-gate class): op-done must mean the box is
    # USABLE — the setup installs the preset's software and the .mcp.json merge
    # runs after it, so returning early invites starting the agent into a box
    # with no MCP config yet (a running session never reloads it).
    # A node preset always has a setup to run (the node step), with or without
    # its own.
    # Skipped after a boot timeout: the sentinel is written before the ready
    # line, so it cannot appear sooner, and a second full wait would push the
    # add past the webui's op window.
    if (not boot_timed_out
            and (catalog.get(req.preset, {}).get("setup") or needs_node
                 or history_args)):
        progress.step("setup", "waiting for the preset setup to finish")
        if not _wait_for_box_setup_done(container, info["container"]):
            # Two causes land here and the wording must carry BOTH: a genuinely
            # slow install, or a FAILING setup (non-zero exit → the box restarts
            # under --restart and retries forever; the sentinel never appears).
            # "Wait for it to settle" alone would misdirect the crash-loop case.
            print(f"warning: preset setup not finished after "
                  f"{BOX_SETUP_READY_TIMEOUT_S}s — it may still be installing, "
                  f"or it may be failing (a failed setup restarts the box and "
                  f"retries); check the box's tab before starting the agent")
    # A box keeping history: its notes came from a clone, so its folder is
    # checked for RS's old files once the setup made it (its record's flag set
    # then); one found fails the add at its end, after the history outcome is
    # reported, the box kept for Remove.
    if history_args and not boot_timed_out:
        create_old += _box_tool_home_skills(req.project, container,
                                            ["--box", info["name"]], progress)
    # The box's own history outcome: a fixed code it wrote, mapped to fixed
    # text here (the box's text never reaches the browser).
    if history_args:
        history_line = _history_status_line(
            _read_history_status(container, info["container"]), hist_claim["repo"])
    if history_line:
        progress.step("note" if history_line.startswith("History: on") else "warning",
                      history_line)
    _raise_old_instructions(create_old)
    progress.step("ready", "box ready")
    return BoxAddResult(project=req.project, name=info["name"], ip=info["ip"],
                        preset=info.get("preset", req.preset),
                        browser=bool(info.get("browser")),
                        agent=info.get("agent", "none"),
                        editor=bool(info.get("editor", req.editor)),
                        container=info["container"],
                        fetch=bool(info.get("fetch", req.fetch)),
                        folders=list(req.folders), warnings=folder_warnings,
                        history=history_line)


def box_remove(req: "BoxRemoveRequest", progress=None) -> BoxRemoveResult:  # type: ignore[name-defined]
    """Discard a sandbox box (container + its workspace) via the in-box
    `rs-sandbox discard`. Step-up re-auth was already enforced by the broker."""
    progress = progress or _NULL_PROGRESS
    progress.step("validate", "checking the project")
    container = _running_dind_supervisor(req.project)
    # Before the registry sweep below, which would drop a reserved entry
    # silently: drop it here and say so.
    _drop_reserved_port_entries(req.project, load_config(), progress)
    progress.step("discard", "discarding the box"
                  + (" (keeping artifacts)" if req.keep_workspace else ""))
    cmd = ["docker", "exec", container, "rs-sandbox", "discard", req.name]
    if req.keep_workspace:
        cmd.append("--keep-workspace")
    r = run(cmd, capture_output=True)
    if r.returncode != 0:
        die(f"failed to remove box {req.name!r}: {(r.stderr or r.stdout).strip()}")
    # A workspace the box tool left in place (a link, a non-folder) is a
    # structured warning; an older box tool prints plain text and reads as none.
    warnings: list[str] = _box_discard_warnings(
        _parse_box_tool_json(r.stdout).get("warnings"), req.name)
    for line in warnings:
        progress.step("warning", line)
    # F3 Slice 2b: sweep the discarded box's exported-port entries — its pub_super
    # publishes went with the box, so a lingering registry entry would be a dead
    # tab. (The box's forwarders died with its container; nothing to reap here.)
    # ONLY write when something actually changes — a normal box discard on a
    # project with no exported ports must not create a spurious registry file.
    ws = workspace_path_for(req.project, load_config())
    if ws.is_dir():
        existing = read_exported_ports(ws)
        remaining = [e for e in existing if e.get("box") != req.name]
        if len(remaining) != len(existing):
            _write_exported_ports(ws, remaining)
    # Retire the box's dev consumer, if it had one: ARCHIVE its fork (history
    # kept, user stays inert), delete its token (host + staged), drop its
    # ledger entry, restage the wiring. Best-effort — the discard already
    # succeeded; a sick gitea must not fail the remove.
    entry = next((e for e in gitea.project_entries(req.project)
                  if e.get("class") == "agent" and e.get("box") == req.name),
                 None)
    if entry is not None:
        if (entry.get("user") and entry.get("repo")
                and container_running(gitea.GITEA_CONTAINER)):
            try:
                gitea.archive_fork(_gitea_host_port(), entry["user"],
                                   entry["repo"])
            except gitea.GiteaError:
                pass
        if entry.get("user"):
            gitea.delete_consumer_token(entry["user"])
            if container_running(container):
                run(["docker", "exec", "-u", "research", container, "sh", "-c",
                     'rm -f "$HOME/.dev-tokens/$1"', "sh",
                     f"{entry['user']}.token"], capture_output=True)
        gitea.prune_entry(req.project, entry.get("repo"), box=req.name)
        _stage_dev_gitea(req.project, load_config())
    # Gitea history: archive the notes repo (read-only, history kept), delete
    # the box's account (with any fork it made) and its token. The Gitea is
    # resumed for it when stopped (the call: a removed box's repo is always
    # archived); nothing here may escape the broker or skip the prune.
    hist = next((e for e in gitea.project_entries(req.project)
                 if e.get("class") == gitea.HISTORY_CLASS
                 and e.get("box") == req.name), None)
    if hist is not None:
        hist_lines = _retire_history_rows(req.project, [hist], container)
        for line in hist_lines:
            progress.step("warning", line)
        warnings.extend(hist_lines)
    # Preset-field env cleanup (best-effort, the dev-token posture): the host
    # store copy AND the supervisor-home copy the box was staged from — a
    # removed box must not leave its key at rest anywhere.
    (BOX_ENV_DIR / req.project / f"{req.name}.env").unlink(missing_ok=True)
    warn = _mcp_drop_rows(req.project, req.name)
    if warn:
        progress.step("warning", warn)
        warnings.append(warn)
    if container_running(container):
        run(["docker", "exec", "-u", "research", container, "sh", "-c",
             'rm -f "$HOME/.rs-box-env/$1"', "sh", f"{req.name}.env"],
            capture_output=True)
    return BoxRemoveResult(project=req.project, name=req.name, warnings=warnings)


def box_list(req: "BoxListRequest", _progress=None) -> BoxListResult:  # type: ignore[name-defined]
    """List a project's sandbox boxes with live container state, via
    `rs-sandbox list --json`. Filters to kind=="sandbox" (the rs-sandbox-owned
    boxes); baked/byo extensions are managed via `research project extension`."""
    container = _running_dind_supervisor(req.project)
    r = run(["docker", "exec", container, "rs-sandbox", "list", "--json"],
            capture_output=True)
    if r.returncode != 0:
        die(f"failed to list boxes: {(r.stderr or r.stdout).strip()}")
    try:
        rows = json.loads(r.stdout)
    except (json.JSONDecodeError, TypeError):
        die(f"could not parse rs-sandbox output: {r.stdout.strip()!r}")
    boxes = [{"name": e.get("name"), "ip": e.get("ip"),
              "agent": e.get("agent", "none"), "browser": bool(e.get("browser")),
              # True only for the literal True the box tool reports.
              "browser_trusted": e.get("browser_trusted") is True,
              "state": e.get("state"),
              # Read tolerantly (an older box tool's rows carry neither) and
              # filtered to valid paths (the record is container-writable).
              "dev": bool(e.get("dev")),
              "folders": [f for f in (e.get("folders") or [])
                          if _valid_box_folder_path(f)]
                         if isinstance(e.get("folders"), list) else [],
              # True only for the literal True the box tool reports.
              "share": e.get("share") is True}
             for e in rows
             if isinstance(e, dict) and e.get("kind") == extension.SANDBOX_KIND]
    choices, choices_error = _box_folder_choices_or_note(
        workspace_path_for(req.project, load_config()))
    return BoxListResult(project=req.project, boxes=boxes,
                         folder_choices=choices,
                         folder_choices_error=choices_error)


def _project_folders_view(project: str, workspace_path: Path,
                          md: dict) -> ProjectFoldersResult:
    """The ⚙ view of one project's folders from its container metadata and
    its record. Names only — never a host path (``data_dir`` aside)."""
    data = rs_data_dir()
    try:
        data_real = data.resolve()
    except (OSError, RuntimeError, ValueError):
        raise ValidationError("RS's data folder could not be resolved")
    _keep, mounted, fixed = _split_folder_binds(md["extra_mounts"], data_real)
    mounted_rel = [str(Path(src).relative_to(data_real)) for src in mounted.values()]
    plan = _folder_plan(workspace_path, md["extra_mounts"])
    saved = plan.record
    return ProjectFoldersResult(
        project=project,
        folders=list(saved) if saved is not None else mounted_rel,
        mounted=mounted_rel,
        fixed=sorted(fixed),
        pending=plan.pending,
        problem=plan.problem,
        rebuilds=md.get("substrate") == Substrate.DOCKER.value,
        data_dir=str(data))


def _project_folders_md(project: str) -> dict:
    container = container_name_for(project)
    if not container_exists(container):
        die(f"project {project!r} has no container right now")
    return _read_supervisor_metadata(container)


def project_folders(req: "ProjectFoldersRequest", _progress=None) -> ProjectFoldersResult:  # type: ignore[name-defined]
    """The ⚙ Sharing box's read: the saved folders (or the mounted ones when
    none were saved), what is mounted now, the folders set at creation that
    the browser cannot change, and whether a saved change waits for the next
    start. A docker inspect plus one small file read."""
    cfg = load_config()
    md = _project_folders_md(req.project)
    return _project_folders_view(req.project, workspace_path_for(req.project, cfg), md)


def project_folders_set(req: "ProjectFoldersSetRequest", _progress=None) -> ProjectFoldersResult:  # type: ignore[name-defined]
    """Record a project's folders (paths relative to RS's data folder) for its
    next start. Nothing restarts here (maintainer, 2026-11-05). The paths pass
    the same gate as create, plus a check against the folders set at creation
    (a shared last name would mount both at one place); a refusal records
    nothing. The record is written beside the workspace, whole."""
    cfg = load_config()
    md = _project_folders_md(req.project)
    workspace_path = workspace_path_for(req.project, cfg)
    sources = resolve_data_mount_paths(req.folders)
    try:
        data_real = rs_data_dir().resolve()
    except (OSError, RuntimeError, ValueError):
        raise ValidationError("RS's data folder could not be resolved")
    _keep, _mounted, fixed = _split_folder_binds(md["extra_mounts"], data_real)
    _check_fixed_names(sources, fixed)
    rel = [str(Path(s).relative_to(data_real)) for s in sources]
    if not workspace_path.parent.is_dir():
        raise ValidationError(f"project {req.project!r} has no folder on disk")
    try:
        _write_folders_record(workspace_path, rel)
    except OSError:
        raise ValidationError("the folders could not be saved")
    return _project_folders_view(req.project, workspace_path, md)


def box_folders(req: "BoxFoldersRequest", _progress=None) -> BoxFoldersResult:  # type: ignore[name-defined]
    """Replace a box's read-only folders via the in-box `rs-sandbox folders`
    (which saves the set and re-runs the box when it changed). The host check
    applies only to names the box does not carry yet: a recorded folder that is
    gone right now stays in the set (the box tool skips it at each run and
    mounts it again once it is back), so saving another change never drops it
    and never refuses on it. Inline like a box port add — it re-runs one box and
    returns once it runs again, without waiting for the box's setup."""
    cfg = load_config()
    container = _running_dind_supervisor(req.project)
    ws = workspace_path_for(req.project, cfg)
    try:
        entries = extension.load(ws)
    except (OSError, ValueError, RecursionError):
        raise ValidationError("could not read this project's boxes")
    entry = entries.get(req.name) if isinstance(entries, dict) else None
    if not isinstance(entry, dict) or entry.get("kind") != extension.SANDBOX_KIND:
        raise ValidationError(f"no box named {req.name!r} in this project")
    if entry.get("dev"):
        raise ValidationError("a dev box does not take read-only folders")
    raw = entry.get("folders")
    recorded = ({f for f in raw if isinstance(f, str)}
                if isinstance(raw, list) else set())
    _check_box_folders(ws, [n for n in req.folders if n not in recorded])
    _gate_box_tool_folder_paths(container, "folders", req.folders)
    # One argv word (`--set=…`; `--set=` clears): a name may start with "-".
    r = run(["docker", "exec", container, "rs-sandbox", "folders", req.name,
             "--set=" + ",".join(req.folders)], capture_output=True)
    if r.returncode != 0:
        if _is_old_box_tool(r):
            die(_OLD_BOX_TOOL_MSG)
        die(f"failed to change the box's folders: "
            f"{(r.stderr or r.stdout).strip()}")
    # Tolerant: the box has already been re-run when this is read.
    info = _parse_box_tool_json(r.stdout)
    warnings = _box_folder_warnings(info.get("warnings"), req.name)
    old_items = _box_old_items(req.project, req.name, info.get("warnings"))
    if old_items:
        # The folders changed and the box runs; RS's old files in its folder
        # kept the new ones from being written: say so as the operation's
        # failure. The other lines of this re-run ride in the error text: this
        # inline verb's reply carries only the error, never its stderr.
        raise ValidationError("\n".join([*(f.text() for f in old_items), *warnings]))
    return BoxFoldersResult(
        project=req.project, name=req.name, folders=list(req.folders),
        changed=info.get("changed") is not False,
        warnings=warnings)


def box_settings(req: "BoxSettingsRequest", _progress=None) -> BoxSettingsResult:  # type: ignore[name-defined]
    """Change a box's agent settings via the in-box `rs-sandbox settings`, which
    saves them and either writes the model into the running box's settings file
    (no restart) or, for a working-mode change, re-runs the box fresh; a box that
    is not running applies them at its next start. Every check runs here first —
    the box tool trusts them, as at box add: the model only on a Claude box (any
    project), the working mode and doer/checker models only on a dev box outside
    a research project, for the box's own agent. The box tool always receives
    the full resolved set (an empty value means none)."""
    cfg = load_config()
    container = _running_dind_supervisor(req.project)
    ws = workspace_path_for(req.project, cfg)
    try:
        entries = extension.load(ws)
    except (OSError, ValueError, RecursionError):
        raise ValidationError("could not read this project's boxes")
    entry = entries.get(req.name) if isinstance(entries, dict) else None
    if not isinstance(entry, dict) or entry.get("kind") != extension.SANDBOX_KIND:
        raise ValidationError(f"no box named {req.name!r} in this project")
    agent = entry.get("agent", "none")
    if not isinstance(agent, str):
        agent = "none"
    reset = set(req.reset)
    model_asked = bool(req.model or req.effort or reset & {"model", "effort"})
    harness_asked = any(getattr(req, f) for f in HARNESS_FIELDS) or bool(reset & set(HARNESS_FIELDS))
    if not (model_asked or harness_asked):
        raise ValidationError("nothing to change")
    if model_asked and agent != "claude":
        raise ValidationError("only a box running Claude takes a model here; "
                              "pi picks its model inside pi")
    research = _container_project_type(container) != PROJECT_TYPE_SANDBOX_DIND
    if harness_asked:
        if research or not entry.get("dev") or agent == "none":
            raise ValidationError("the working mode and the Doer and Checker models are "
                                  "for dev boxes outside research projects")
    # The full resolved set: the entry's values (re-checked — the record is
    # writable from inside the project), with this request's changes applied.
    def _entry_str(k: str) -> str:
        v = entry.get(k)
        return v if isinstance(v, str) else ""
    model = req.model or ("" if "model" in reset else _entry_str("model"))
    effort = req.effort or ("" if "effort" in reset else _entry_str("effort"))
    if model and not CLAUDE_MODEL_RE.match(model):
        model = ""
    dropped = False
    if effort:
        cat = _model_catalog_checked()
        if not _claude_effort_ok(model, effort, cat):
            if req.effort:
                raise ValidationError(f"model {model!r} does not accept an effort level; "
                                      f"leave its effort at the default")
            effort, dropped = "", True
    old_h = entry.get("harness") if isinstance(entry.get("harness"), dict) else {}
    harness: dict[str, str] = {}
    for f in HARNESS_FIELDS:
        v = old_h.get(f)
        if isinstance(v, str) and v:
            try:
                _harness_shape({f: v})
            except Exception:
                v = ""
        else:
            v = ""
        if getattr(req, f):
            v = getattr(req, f)
        elif f in reset:
            v = ""
        if v and not (f == "harness_mode" and v == "none"):
            harness[f] = v
    if harness_asked:
        _validated_harness({f: harness.get(f, "") for f in HARNESS_FIELDS},
                           dev=True, agents=[agent])
    # The groups this change writes; the box tool keeps the others as its
    # record has them — so a model-only change never touches the working mode,
    # and a named model half is written even when the record already holds it
    # (the box's file may differ: a /model pick).
    write = [g for g, asked in (
        ("model", req.model or "model" in reset),
        ("effort", req.effort or "effort" in reset or dropped),
        ("harness", harness_asked)) if asked]
    argv = ["docker", "exec", container, "rs-sandbox", "settings", req.name,
            f"--write={','.join(write)}",
            f"--model={model if agent == 'claude' else ''}",
            f"--effort={effort if agent == 'claude' else ''}",
            *((f"--{f.replace('_', '-')}={harness.get(f, '')}" for f in HARNESS_FIELDS)
              if harness_asked else ())]
    r = run(argv, capture_output=True)
    if r.returncode != 0:
        if _is_old_box_tool(r):
            die(_OLD_BOX_TOOL_SETTINGS_MSG)
        die(f"failed to change the box's settings: {(r.stderr or r.stdout).strip()}")
    info = _parse_box_tool_json(r.stdout)
    warnings = []
    for w in info.get("warnings") or []:
        if isinstance(w, dict) and w.get("kind") == "model" and w.get("reason") == "booting":
            warnings.append(f"box {req.name!r} is still starting — the model is saved; "
                            f"save again in a moment to apply it now, or it is written "
                            f"at the box's next start")
        elif isinstance(w, dict) and w.get("kind") == "model":
            warnings.append(f"the model could not be written into box {req.name!r} yet; "
                            f"it is written at its next start")
        elif isinstance(w, dict):
            warnings += _box_folder_warnings([w], req.name)
    old_items = _box_old_items(req.project, req.name, info.get("warnings"))
    if old_items:
        # The other lines of this re-run ride in the error text: this inline
        # verb's reply carries only the error, never its stderr.
        raise ValidationError("\n".join([*(f.text() for f in old_items), *warnings]))
    return BoxSettingsResult(project=req.project, name=req.name,
                             changed=info.get("changed") is not False,
                             restarted=info.get("restarted") is True,
                             effort_dropped=dropped, warnings=warnings)


def box_presets(req: "BoxPresetsRequest", _progress=None) -> BoxPresetsResult:  # type: ignore[name-defined]
    """The box-preset catalog (built-ins + the operator box-registry) + the
    project's allowed MCP names — drives the webui box window (preset cards + MCP
    picker). Gated on a running dind supervisor (boxes are a dind feature).
    `box_catalog.load_catalog()` can raise `BoxCatalogError` on a malformed
    box-registry.json — map it to ValidationError so it can't escape `dispatch`
    (the verb-fn-raise rule)."""
    _running_dind_supervisor(req.project)
    cfg = load_config()
    try:
        catalog = box_catalog.load_catalog()
    except box_catalog.BoxCatalogError as e:
        raise ValidationError(str(e))
    presets = [{"name": e["name"], "image": e.get("image"),
                "agent_default": bool(e.get("agent_default")),
                "clone": bool(e.get("clone")),
                "editor_default": bool(e.get("editor_default")),
                "repo": e.get("repo") or "",
                "description": e.get("description") or "",
                "source": e.get("source"),
                # Declared input fields (the window renders them; secret ⇒
                # password input) + the visible setup script. Projection, not
                # passthrough — a key missing HERE never reaches the window.
                "fields": [{"name": f.get("name"), "label": f.get("label"),
                            "secret": bool(f.get("secret"))}
                           for f in (e.get("fields") or [])],
                "setup": e.get("setup") or "",
                # Drives the dialog's dev-preset branch (repo picker instead of
                # the BYO fields; MCP group disabled — both S2 gates reject
                # mcps on a dev box).
                "dev": bool(e.get("dev")),
                # Offers the box window's "Keep history on Gitea" switch.
                "gitea_history": bool(e.get("gitea_history")),
                # The type starts its own web app in a tab of its own.
                "web": bool(e.get("web")),
                # Pre-ticks the box window's "Share files" card.
                "share_default": e.get("share_default") is True}
               for e in catalog]
    allowed = sorted(x["name"] for x in load_project_allowlist(req.project, cfg)
                     if x.get("name"))
    folders, folders_error = _box_folder_choices_or_note(
        workspace_path_for(req.project, cfg))
    return BoxPresetsResult(project=req.project, presets=presets,
                            allowed_mcps=allowed, folders=folders,
                            folders_error=folders_error,
                            gitea_enabled=gitea.bootstrap_present())


# --- exported-port registry (STAGE_EXPORTED_PORTS) --------------------------
# A per-project list of {port,label} the webui surfaces as http tabs. The broker
# writes it (the webui mount is RO); project_services_handler reads it off the same
# /projects:ro bind-mount as the box registry. No container action — the tab only
# appears once the PI is actually listening on the port (webui probe-gated).


EXPORTED_PORTS_NAME = "exported-ports.json"


def exported_ports_path(workspace_path: "Path") -> "Path":  # type: ignore[name-defined]
    return workspace_path / ".orchestrator" / EXPORTED_PORTS_NAME


# The registry is broker-written with indent=2: one entry is ~60-150 bytes plus
# its label, so 1 MiB holds several thousand entries — far past any tab strip a
# person can use. At that size one json.loads costs a few ms, which a reader on
# the serial broker thread (port_detect, polled every 15 s per open browser) and
# on the webui event loop (every tab listing / origin request) can afford; at 10x
# it is tens of ms per call per poll on both, and at half it is still thousands
# of entries, so the value is not tight. The file is writable from inside the
# project's container, so the cap is what bounds a forged one. A registry past
# it reads as empty, and the next broker write replaces it — the same as an
# unparseable file. Same magnitude as PORT_DETECT_MAX_OUTPUT_BYTES. Mirrored in
# webui/server.py (that image cannot import this module).
EXPORTED_PORTS_MAX_BYTES = 1 << 20


def _load_port_registry(f, dir_fd=None):
    """The JSON list in the port registry file `f`; [] when `f` is absent;
    None when it is there but unusable: not a regular file (a FIFO, a
    directory, a symlink), larger than EXPORTED_PORTS_MAX_BYTES, not UTF-8,
    not JSON, or not a list. The file is writable from inside the project's
    container, so the open never blocks, never follows a link, and reads at
    most one byte past the cap. MIRRORED in webui/server.py — keep the two
    identical except the `dir_fd` this copy takes: rscore opens `f` relative
    to the settings folder it opened without following a link (orch_files),
    so a container that replaces `.orchestrator` itself redirects nothing;
    the webui copy still opens by path (its reads are B213)."""
    try:
        fd = os.open(f, os.O_RDONLY | os.O_NONBLOCK | os.O_NOFOLLOW | os.O_CLOEXEC,
                     dir_fd=dir_fd)
    except FileNotFoundError:
        return []
    except OSError:
        return None
    try:
        with os.fdopen(fd, "rb") as fh:
            if not stat.S_ISREG(os.fstat(fh.fileno()).st_mode):
                return None
            raw = fh.read(EXPORTED_PORTS_MAX_BYTES + 1)
        if len(raw) > EXPORTED_PORTS_MAX_BYTES:
            return None
        data = json.loads(raw.decode("utf-8"))
    except (OSError, ValueError, RecursionError):
        return None
    return data if isinstance(data, list) else None


def read_exported_ports(workspace_path: "Path") -> list[dict]:  # type: ignore[name-defined]
    """Tolerant read of the exported-port registry → [{port:int, label:str}], plus
    optional {box:str, app_port:int} on an inner-box entry (F3 Slice 2b): `port` is
    the supervisor-netns publish port (pub_super) the resolver dials, `app_port` the
    box's own 127.0.0.1 port, `box` the box name — the pair the unexpose/sweep paths
    need. Such an entry may also carry {web:true}: the box's own web app's tab,
    registered at box create (kept only when exactly True on a valid box entry, so
    every other entry round-trips byte-identically). A top-level entry may carry
    {web:true} too: a docker project's own web app (kept only when exactly True
    and the raw entry has none of box/passthrough/host_port — so a degraded box
    entry or a pass-through claim never turns into a tab nobody can remove).
    Missing/malformed → [], and so are oversize, non-regular and symlinked
    files (_load_port_registry); a plain {port,label} stays a top-level entry.
    A pass-through claim (STAGE_PASSTHROUGH_PORTS) additionally carries
    {passthrough:true, host_port:int, count:int>=1 (absent == 1)} — accepted only
    when ALL of those hold AND both spans, host_port..host_port+count-1 and
    port..port+count-1, are TCP ports (1-65535); else the entry DEGRADES to a
    plain {port,label} (never dropped, never trusted). The span bound exists
    because the file sits in the workspace, which the project container can
    rewrite, and every consumer does arithmetic over these spans: without it a
    hand-written count would be expanded port by port. It is the protocol bound,
    not the configured pass-through block, so every claim the port verb could
    have written under ANY block reads back unchanged whatever the operator
    later does to the block. It is not exactly the verb's set: the verb also
    refuses the reserved project-side ports (_coerce_export_port), which this
    reader does not check — except one: an entry whose port is a reserved
    project-side port (_EXPORT_RESERVED_PORTS: the project's ssh, the editor
    and its password-less upstream, the reader), or an accepted claim whose
    project-side span crosses one, is SKIPPED, box entry or not (RS's own box
    entries sit in 8600-8699). Such an entry was registered before the verb
    refused it, or written by the project itself; nothing may forward it, and
    the start/update/port/box verbs drop it from the file with a warning
    (_drop_reserved_port_entries). The check is a set lookup plus at most four
    comparisons, never an expansion of the span.
    webui/server.py::_read_exported_ports is the MIRROR of this rule (the
    webui image can't import this module) — keep the two acceptance blocks
    and the two skip lines byte-identical. Host-written but webui-read, and
    container-writable, so never trust the shape."""
    try:
        with orch_files.open_folder(workspace_path) as dfd:
            data = _load_port_registry(EXPORTED_PORTS_NAME, dir_fd=dfd)
    except FileNotFoundError:
        data = []
    except OSError:
        data = None             # the settings folder is a link or not a folder
    if not data:
        return []
    out: list[dict] = []
    for e in data:
        if not isinstance(e, dict):
            continue
        port, label = e.get("port"), e.get("label")
        if isinstance(port, int) and not isinstance(port, bool) \
                and isinstance(label, str):
            entry = {"port": port, "label": label}
            box, app_port = e.get("box"), e.get("app_port")
            if isinstance(box, str) and box and isinstance(app_port, int) \
                    and not isinstance(app_port, bool):
                entry["box"], entry["app_port"] = box, app_port
                if e.get("web") is True:
                    entry["web"] = True
            elif e.get("web") is True and not any(
                    k in e for k in ("box", "passthrough", "host_port")):
                entry["web"] = True
            pt, hp, cnt = e.get("passthrough"), e.get("host_port"), e.get("count", 1)
            if (pt is True and isinstance(hp, int) and not isinstance(hp, bool)
                    and isinstance(cnt, int) and not isinstance(cnt, bool)
                    and cnt >= 1 and 1 <= hp and hp + cnt - 1 <= 65535
                    and 1 <= port and port + cnt - 1 <= 65535):
                entry["passthrough"], entry["host_port"] = True, hp
                if cnt > 1:
                    entry["count"] = cnt
            span = entry.get("count", 1)
            if port in _EXPORT_RESERVED_PORTS or (span > 1 and any(
                    port <= r < port + span for r in _EXPORT_RESERVED_PORTS)):
                continue
            out.append(entry)
    return out


def _write_exported_ports(workspace_path: "Path", ports: list[dict]) -> None:  # type: ignore[name-defined]
    """Replace the registry with `ports`, atomically. The directory is
    writable from inside the project's container, so the temp file is a
    fresh, uniquely named one (O_CREAT|O_EXCL|O_NOFOLLOW) — a link
    or file the project planted at any fixed temp path can never redirect or
    block this host-side write. Serialised before the temp exists, so a
    failure to serialise leaves nothing behind; a failed write unlinks its
    own temp by name and re-raises. Mode 0644, as the file always had. The
    settings folder itself is opened without following a link
    (orch_files): a container that replaces `.orchestrator` with a link
    refuses the write (die) instead of redirecting it."""
    try:
        _write_port_registry_text(
            workspace_path, json.dumps(ports, indent=2, sort_keys=True) + "\n")
    except orch_files.Unusable as e:
        die(str(e))


def _write_port_registry_text(workspace_path: "Path", text: str) -> None:  # type: ignore[name-defined]
    """The atomic write behind _write_exported_ports (see there): a fresh
    temp name inside the no-follow settings folder (orch_files.write_text).
    Raises orch_files.Unusable when the folder is a link or not a folder."""
    orch_files.write_text(workspace_path, EXPORTED_PORTS_NAME, text,
                          mode=0o644, create=True)


# What each reserved project-side port is, for the warning that drops an entry
# targeting one. Keys == _EXPORT_RESERVED_PORTS (pytest-pinned).
_RESERVED_PORT_ROLES = {
    22: "the project's ssh",
    8443: "the editor's login front door",
    8444: "the editor without its password",
    8445: "the reader",
}


def _reserved_port_row(e: Any) -> tuple[str, int] | None:
    """(how, reserved port) when the RAW registry row `e` targets a reserved
    project-side port, else None — the rule read_exported_ports skips by,
    applied to the raw row: its `port`, or an ACCEPTED claim's whole span (a
    claim the reader degrades counts as its plain port). `how` is "claim" for
    a pass-through claim, "forwarded" for a top-level entry the readers used
    to forward, and "registered" for a row they never forwarded (a box entry,
    or one without a usable label). Rows with no integer port are not ours to
    judge and stay."""
    if not isinstance(e, dict):
        return None
    port = e.get("port")
    if not isinstance(port, int) or isinstance(port, bool):
        return None
    pt, hp, cnt = e.get("passthrough"), e.get("host_port"), e.get("count", 1)
    claim = (pt is True and isinstance(hp, int) and not isinstance(hp, bool)
             and isinstance(cnt, int) and not isinstance(cnt, bool)
             and cnt >= 1 and 1 <= hp and hp + cnt - 1 <= 65535
             and 1 <= port and port + cnt - 1 <= 65535)
    span = cnt if claim else 1
    hit = next((r for r in sorted(_EXPORT_RESERVED_PORTS)
                if port <= r < port + span), None)
    if hit is None:
        return None
    box, app_port = e.get("box"), e.get("app_port")
    if not isinstance(e.get("label"), str) or (
            isinstance(box, str) and box and isinstance(app_port, int)
            and not isinstance(app_port, bool)):
        return "registered", hit
    return ("claim" if claim else "forwarded"), hit


def _sweep_reserved_port_entries(workspace_path: "Path") -> list[dict]:  # type: ignore[name-defined]
    """Drop every row targeting a reserved project-side port from the RAW
    registry (_reserved_port_row) and return the dropped rows. Every other
    row is written back as it was read, in order. Writes nothing when nothing
    is dropped, when the file is absent, and when it is unusable (the readers
    already treat that as empty). The rows kept are the project's own bytes,
    so they are written compact and as UTF-8: an indented rewrite of a deeply
    nested row can grow many times over and push a readable file past
    EXPORTED_PORTS_MAX_BYTES, where every reader would see an empty list — a
    rewrite still over the cap is refused (ValueError) and the file stays as
    it was. The read and the write are adjacent — no exec between them — so a
    concurrent registry write (the dev-box lane has no busy check against
    this) has the smallest window. Raises what the write raises (OSError,
    ValueError, RecursionError). A settings folder that is a link reads as
    unusable (orch_files), so nothing is written."""
    try:
        with orch_files.open_folder(workspace_path) as dfd:
            raw = _load_port_registry(EXPORTED_PORTS_NAME, dir_fd=dfd)
    except OSError:
        raw = None
    if not raw:
        return []
    keep, dropped = [], []
    for e in raw:
        (dropped if _reserved_port_row(e) else keep).append(e)
    if dropped:
        text = json.dumps(keep, ensure_ascii=False, separators=(",", ":")) + "\n"
        if len(text.encode("utf-8")) > EXPORTED_PORTS_MAX_BYTES:
            raise ValueError("the rewritten port list would exceed its size cap")
        _write_port_registry_text(workspace_path, text)
    return dropped


def _reserved_port_line(project: str, e: dict) -> str:
    how, port = _reserved_port_row(e)  # type: ignore[misc]
    role = _RESERVED_PORT_ROLES.get(port, "a port RS uses itself")
    if how == "claim":
        return (f"pass-through port {e['host_port']} of project {project} was "
                f"forwarded to port {port} although it is reserved ({role}); "
                f"it is no longer forwarded")
    if how == "registered":
        return (f"port {port} of project {project} was registered although it "
                f"is reserved ({role}); it is no longer registered")
    return (f"port {port} of project {project} was forwarded although it is "
            f"reserved ({role}); it is no longer forwarded")


def _drop_reserved_port_entries(project: str, cfg: "Config",  # type: ignore[name-defined]
                                progress=None) -> list[str]:
    """Run the sweep for `project` and report each dropped row once: one
    `warning:` line on stderr each, and a `warning` progress step when the
    verb has a progress sink (the webui's op box). Returns the lines (the port
    verbs carry them in their result's warnings). When something was dropped,
    reconcile the loopback forwarders, so a forwarder already running on a
    reserved port is reaped now (the reconcile self-gates on a running
    container). Best-effort: a failure to rewrite the file is a warning,
    never the end of the verb — the readers skip those rows anyway."""
    ws = workspace_path_for(project, cfg)
    try:
        dropped = _sweep_reserved_port_entries(ws)
    except (OSError, ValueError, RecursionError) as e:
        line = (f"the port list of project {project} names a reserved port "
                f"and could not be rewritten; that port is not forwarded")
        print(f"warning: {line} ({e})", file=sys.stderr)
        if progress is not None:
            progress.step("warning", line)
        return [line]
    lines: list[str] = []
    for e in dropped:
        line = _reserved_port_line(project, e)
        if line not in lines:
            lines.append(line)
    for line in lines:
        print(f"warning: {line}", file=sys.stderr)
        if progress is not None:
            progress.step("warning", line)
    if dropped:
        _reconcile_loopback_bridges(project, cfg)
    return lines


def port_add(req: "PortAddRequest", _progress=None) -> PortAddResult:  # type: ignore[name-defined]
    """Register an exported port for a project (writes the workspace registry).
    Idempotent — a re-add updates the label. THREE shapes:
    - req.box == "" (F3 Slice 1/2a): the top-level supervisor/docker container. The
      port is ASSUMED bound on 127.0.0.1, so registering it stands up an in-box
      forwarder (via _reconcile_loopback_bridges); the tab is on that same `port`.
    - req.box set (F3 Slice 2b): `port` is an inner box's own 127.0.0.1 port. Drive
      `rs-sandbox expose` to allocate a supervisor-netns publish port (pub_super) +
      run the box's forwarder, then register {port: pub_super, box, app_port} — the
      tab lands on pub_super, which the resolver already dials.
    - req.passthrough (STAGE_PASSTHROUGH_PORTS): a raw-TCP claim of
      host_port..host_port+count-1 in the webui's reserved block, relaying to
      port..port+count-1 on this project's container. FAIL-CLOSED global gate: a
      block port is claimable ONCE across ALL projects (walk every workspace
      registry; the one pass is this project re-claiming the IDENTICAL
      (host_port, count, port) triple — the idempotent label update). The result
      `port` is host_port (the claim's identity + the tab key)."""
    cfg = load_config()
    ws = workspace_path_for(req.project, cfg)
    if not ws.is_dir():
        die(f"project {req.project!r} has no workspace; create it first")
    # The registry is written below, after the box tool may have run: refuse
    # a settings folder that is a link before anything happens.
    _require_settings_folder(ws)
    # Before the first read below: the reader hides a reserved row, so every
    # write that follows would drop it silently — say so here, once.
    swept = _drop_reserved_port_entries(req.project, cfg)
    if req.box:
        # A running dind supervisor is required (the box lives in its inner dockerd).
        container = _running_dind_supervisor(req.project)
        r = run(["docker", "exec", container, "rs-sandbox", "expose",
                 req.box, str(req.port)], capture_output=True)
        if r.returncode != 0:
            die(f"failed to expose box port: {(r.stderr or r.stdout).strip()}")
        try:
            info = json.loads(r.stdout)
        except (json.JSONDecodeError, TypeError):
            die(f"could not parse rs-sandbox expose output: {r.stdout.strip()!r}")
        pub = info.get("pub_super") if isinstance(info, dict) else None
        if not isinstance(pub, int) or isinstance(pub, bool):
            die(f"unexpected rs-sandbox expose output shape: {r.stdout.strip()!r}")
        # Register by pub_super (the tab port); keep the app_port + box for
        # unexpose/sweep. Idempotent on (box, app_port) — drop a prior entry.
        # The box's own web-app tab keeps its flag through a re-add (a relabel),
        # so it is still told its address.
        old = read_exported_ports(ws)
        was_web = any(e.get("box") == req.box and e.get("app_port") == req.port
                      and e.get("web") is True for e in old)
        ports = [e for e in old
                 if not (e.get("box") == req.box and e.get("app_port") == req.port)]
        new_entry = {"port": pub, "label": req.label,
                     "box": req.box, "app_port": req.port}
        if was_web:
            new_entry["web"] = True
        ports.append(new_entry)
        ports.sort(key=lambda e: e["port"])
        _write_exported_ports(ws, ports)
        # The expose re-ran the box: report the folders it started without.
        warnings = swept + _box_folder_warnings(info.get("warnings"), req.box)
        old_items = _box_old_items(req.project, req.box, info.get("warnings"))
        if old_items:
            # The port is registered and the box runs; RS's old files are the
            # operation's failure (after the registry write). The other lines
            # of this re-run ride in the error text: this inline verb's reply
            # carries only the error, never its stderr.
            raise ValidationError("\n".join([*(f.text() for f in old_items), *warnings]))
        return PortAddResult(project=req.project, port=pub, label=req.label,
                             ports=ports, warnings=warnings)
    if req.passthrough:
        span_lo, span_hi = req.host_port, req.host_port + req.count - 1
        # GLOBAL fail-closed collision gate over every project's registry.
        # Refusal text is browser-verbatim: it names the holder + the webui
        # surfaces, never a CLI verb or a file (the webui-CLI-mention rule).
        root = Path(cfg.projects_dir).expanduser().resolve()
        if root.is_dir():
            for pdir in sorted(p for p in root.iterdir() if p.is_dir()):
                for e in read_exported_ports(pdir / "workspace"):
                    if not e.get("passthrough"):
                        continue
                    e_lo = e["host_port"]
                    e_hi = e_lo + e.get("count", 1) - 1
                    if e_hi < span_lo or span_hi < e_lo:
                        continue                      # disjoint spans
                    if (pdir.name == req.project and e_lo == req.host_port
                            and e.get("count", 1) == req.count
                            and e.get("port") == req.port):
                        continue                      # identical re-claim
                    die(f"host port {max(span_lo, e_lo)} is already claimed "
                        f"by project {pdir.name!r} — remove that claim from "
                        f"its Ports section (or Sandboxes → Infrastructure → Pass-through "
                        f"ports) first")
        ports = [e for e in read_exported_ports(ws)
                 if not (e.get("passthrough")
                         and e.get("host_port") == req.host_port
                         and e.get("count", 1) == req.count
                         and e.get("port") == req.port)]
        entry: dict = {"port": req.port, "label": req.label,
                       "passthrough": True, "host_port": req.host_port}
        if req.count > 1:
            entry["count"] = req.count
        ports.append(entry)
        ports.sort(key=lambda e: e["port"])
        _write_exported_ports(ws, ports)
        _reconcile_loopback_bridges(req.project, cfg)
        return PortAddResult(project=req.project, port=req.host_port,
                             label=req.label, ports=ports, warnings=swept)
    # Plain (page-tab) entry: dedupe on `port` among NON-passthrough entries
    # only — a pass-through claim targeting the same project-side port is a
    # DIFFERENT registration (identity = host_port) and must survive this add.
    # A project's own web-app tab keeps its flag through a re-add (a relabel),
    # as the box branch does, so it still follows the browser's address.
    old = read_exported_ports(ws)
    was_web = any(e.get("port") == req.port and e.get("web") is True
                  and not e.get("box") and not e.get("passthrough") for e in old)
    ports = [e for e in old
             if not (e.get("port") == req.port and not e.get("passthrough"))]
    new_entry = {"port": req.port, "label": req.label}
    if was_web:
        new_entry["web"] = True
    ports.append(new_entry)
    ports.sort(key=lambda e: e["port"])
    _write_exported_ports(ws, ports)
    _reconcile_loopback_bridges(req.project, cfg)
    return PortAddResult(project=req.project, port=req.port, label=req.label,
                         ports=ports, warnings=swept)


def port_remove(req: "PortRemoveRequest", _progress=None) -> PortRemoveResult:  # type: ignore[name-defined]
    cfg = load_config()
    ws = workspace_path_for(req.project, cfg)
    if not ws.is_dir():
        # Nothing to remove and never auto-create a workspace from a remove.
        return PortRemoveResult(project=req.project, port=req.port, ports=[])
    # Before the read: a reserved row is dropped (and said) here, so removing
    # one succeeds — it is simply gone already.
    swept = _drop_reserved_port_entries(req.project, cfg)
    existing = read_exported_ports(ws)

    # Matcher split by req.passthrough: a pass-through claim's identity is its
    # host_port (its project-side `port` may legitimately equal a page entry's
    # port); everything else keys on `port` and must never match a pass-through
    # entry whose project-side port collides. A box entry (F3 Slice 2b) is keyed
    # on its tab port (pub_super) — the same `port` the webui removes by.
    def _match(e: dict) -> bool:
        if req.passthrough:
            return bool(e.get("passthrough")) and e.get("host_port") == req.port
        return e.get("port") == req.port and not e.get("passthrough")

    gone = next((e for e in existing if _match(e)), None)
    # A box type's own web-app tab belongs to the box (the box keeps running
    # the app); only removing the box removes it. A project's own web-app tab
    # belongs to the project the same way. Fixed texts: the label is free text.
    if gone and gone.get("web") is True:
        if gone.get("box"):
            raise ValidationError("This tab belongs to the box; remove the box "
                                  "to remove it.")
        raise ValidationError("This tab belongs to the project; it goes when "
                              "the project is destroyed.")
    warnings: list[str] = []
    if gone and gone.get("box"):
        container = _running_dind_supervisor(req.project)
        r = run(["docker", "exec", container, "rs-sandbox", "unexpose",
                 gone["box"], str(gone["app_port"])], capture_output=True)
        if r.returncode != 0:
            die(f"failed to unexpose box port: {(r.stderr or r.stdout).strip()}")
        # Tolerant: the box has already been re-run — a parse must never stop
        # the registry write below.
        raw = _parse_box_tool_json(r.stdout).get("warnings")
        warnings = _box_folder_warnings(raw, gone["box"])
        old_items = _box_old_items(req.project, gone["box"], raw)
    else:
        old_items = []
    warnings = swept + warnings
    ports = [e for e in existing if not _match(e)]
    _write_exported_ports(ws, ports)
    # Reap the top-level forwarder for a supervisor/docker entry (a box entry's
    # forwarder died with the box's rm+run in unexpose — the reconcile skips it).
    _reconcile_loopback_bridges(req.project, cfg)
    if old_items:
        # The other lines of this re-run ride in the error text: this inline
        # verb's reply carries only the error, never its stderr.
        raise ValidationError("\n".join([*(f.text() for f in old_items), *warnings]))
    return PortRemoveResult(project=req.project, port=req.port, ports=ports,
                            warnings=warnings)


def box_web_address(req: "BoxWebAddressRequest", _progress=None) -> BoxWebAddressResult:  # type: ignore[name-defined]
    """Hand a web-app box the address its tab is opened at; report whether the
    app answers there. The port must be a box's own web-app tab in THIS
    project's registry — the client names a tab, never a box. Anything short of
    a clean answer from the box reads as not ready: the tab waits and asks
    again."""
    cfg = load_config()
    ws = workspace_path_for(req.project, cfg)
    entry = next((e for e in read_exported_ports(ws)
                  if e.get("port") == req.port and e.get("web") is True),
                 None) if ws.is_dir() else None
    if entry is None:
        raise ValidationError("this tab is not a box's own web app")
    if not entry.get("box"):
        return _project_web_address(req)
    container = _running_dind_supervisor(req.project)
    r = run(["docker", "exec", container, "rs-sandbox", "web-address",
             entry["box"], req.address], capture_output=True)
    info = _parse_box_tool_json(r.stdout) if r.returncode == 0 else {}
    return BoxWebAddressResult(project=req.project, port=req.port,
                               changed=info.get("changed") is True,
                               ready=info.get("ready") is True)


def _project_web_address(req: "BoxWebAddressRequest") -> BoxWebAddressResult:  # type: ignore[name-defined]
    """box_web_address for a docker project's own web app: the same baked
    rs-web-set, run directly in the project container as its user (a docker
    project has no box tool), under the box tool's own timeout."""
    container = container_name_for(req.project)
    if not container_running(container):
        raise ValidationError(_WEB_NOT_RUNNING_MSG)
    if _container_substrate(container) != Substrate.DOCKER.value:
        raise ValidationError("this tab is not a box's own web app")
    r = run(["docker", "exec", "-u", "research", container, "timeout",
             str(WEB_SET_TIMEOUT_S), "rs-web-set", req.address],
            capture_output=True)
    info = {}
    if r.returncode == 0:
        try:
            last = json.loads((r.stdout or "").strip().splitlines()[-1])
            info = last if isinstance(last, dict) else {}
        except (ValueError, IndexError, RecursionError):
            info = {}
    return BoxWebAddressResult(project=req.project, port=req.port,
                               changed=info.get("changed") is True,
                               ready=info.get("ready") is True)


def port_list(req: "PortListRequest", _progress=None) -> PortListResult:  # type: ignore[name-defined]
    cfg = load_config()
    ws = workspace_path_for(req.project, cfg)
    if not ws.is_dir():
        return PortListResult(project=req.project, ports=[])
    return PortListResult(project=req.project, ports=read_exported_ports(ws))


# --- detected ports (STAGE_AUTO_PORTS) --------------------------------------
# The webui asks, on its tab-strip refresh, which web apps are listening in a
# project's own container, so a published app gets a tab without a hand-added
# port. Everything read here comes from inside a container whose agent is root
# there, so every value is parsed as untrusted.

# A healthy detection (one exec reading the socket tables, plus the inner docker
# lookup when the listener set changed) measured ~0.35 s on a privileged dind
# project (2026-10-25). The broker runs every verb on ONE serial thread, so the
# budget is also the most a wedged project costs every other Management action
# per refresh of each browser that has it open: ~10x the measured cost leaves
# headroom for a loaded host, and staying under a third of the webui's 15 s
# refresh keeps a few wedged projects from occupying the broker between ticks.
PORT_DETECT_BUDGET_S = 4.0

# The most bytes kept from one exec. Everything the exec prints is container-
# controlled (the agent can replace `cat` or `docker`), and every later step is
# linear or n·log n in it, so this cap is what bounds the host-side work. Real
# socket tables are fixed-width rows (~150 bytes for tcp, ~180 for tcp6): 1 MiB
# holds ~6000 listeners, two orders of magnitude past any real project, and
# parses in milliseconds. Over the cap the call reports partial.
PORT_DETECT_MAX_OUTPUT_BYTES = 1 << 20

_TCP_LISTEN = "0A"
# Docker container names: [a-zA-Z0-9][a-zA-Z0-9_.-]+ (the daemon's own rule),
# here also at most DETECTED_LABEL_MAX characters. The name becomes a tab label,
# and a label wider than a strip can show is unreadable anyway; a longer name is
# SKIPPED (the tab falls back to the port number), never cut, so a shortened
# name cannot pass for another container. It also bounds the reply, which
# repeats the name in every row the container publishes.
DETECTED_LABEL_MAX = 128
_DOCKER_NAME_RE = re.compile(r"\A[A-Za-z0-9][A-Za-z0-9_.-]{0,%d}\Z" % (DETECTED_LABEL_MAX - 1))
# An inode is a kernel unsigned long: at most 20 decimal digits.
_INODE_RE = re.compile(r"\A[0-9]{1,20}\Z")
_NETNS_RE = re.compile(r"\Anet:\[[0-9]+\]\Z")

# project → {"key": frozenset((port, inode)), "published": {host_port:
# {"name", "container_port", "pid", "netns"}}}. Lives in the broker process
# (serial, so no lock); a CLI caller simply starts cold every time.
_PORT_DETECT_STATE: dict[str, dict] = {}


def parse_proc_net_tcp(text: str, v6: bool) -> list[tuple[Any, int, int]]:
    """LISTEN rows of a /proc/net/tcp{,6} table → [(ip, port, inode)]. Rows that
    do not parse are dropped (the table comes from an untrusted container)."""
    out: list[tuple[Any, int, int]] = []
    hexlen = 32 if v6 else 8
    for line in text.splitlines()[1:]:
        f = line.split()
        if len(f) < 10 or f[3] != _TCP_LISTEN:
            continue
        addr, _, port_hex = f[1].partition(":")
        if len(addr) != hexlen or not port_hex:
            continue
        if len(port_hex) > 4 or not _INODE_RE.match(f[9]):
            continue
        try:
            raw = bytes.fromhex(addr)
            port = int(port_hex, 16)
            inode = int(f[9])
        except ValueError:
            continue
        # The kernel prints each 32-bit word in host (little-endian) order.
        raw = b"".join(raw[i:i + 4][::-1] for i in range(0, len(raw), 4))
        ip = ipaddress.IPv6Address(raw) if v6 else ipaddress.IPv4Address(raw)
        if 1 <= port <= 65535 and inode > 0:
            out.append((ip, port, inode))
    return out


def own_address(hostname_text: str, hosts_text: str) -> Any:
    """The container's project-network address: its /etc/hosts line for its
    own hostname (what gethostbyname(gethostname()) resolves, the address the
    loopback forwarder binds). None when absent or unparseable."""
    name = (hostname_text.split() or [""])[0]
    if not name:
        return None
    for line in hosts_text.splitlines():
        f = line.split("#", 1)[0].split()
        if len(f) >= 2 and name in f[1:]:
            try:
                ip = ipaddress.ip_address(f[0])
            except ValueError:
                continue
            if not ip.is_loopback:
                return ip
    return None


def listen_class(ip: Any, own: Any) -> str:
    """'all' (wildcard), 'own' (the project-network address), 'localhost', or
    'other' (another local address: docker0, rs-inner, a compose gateway)."""
    mapped = getattr(ip, "ipv4_mapped", None)
    if mapped is not None:
        ip = mapped
    if ip.is_unspecified:
        return "all"
    if ip.is_loopback:
        return "localhost"
    if own is not None and ip == own:
        return "own"
    return "other"


def _parse_docker_ps_ports(text: str) -> list[dict]:
    """`docker ps --format '{{.ID}}\\t{{.Names}}\\t{{.Ports}}'` → the published
    tcp ranges, [{"id", "name", "hp", "hp_end", "cp"}] (a single port is a
    one-port range). Kept as ranges, never expanded: the output is
    container-controlled, so a range is not trusted to be small."""
    out: list[dict] = []
    for line in text.splitlines():
        f = line.split("\t")
        if len(f) != 3 or not re.fullmatch(r"[0-9a-f]{12,64}", f[0]):
            continue
        name = f[1].split(",")[0].strip()
        for item in f[2].split(","):
            m = re.fullmatch(r"\s*(?:\[[0-9a-fA-F:]*\]|[0-9.]*):([0-9]{1,5})"
                             r"(?:-([0-9]{1,5}))?->([0-9]{1,5})(?:-([0-9]{1,5}))?/tcp\s*",
                             item)
            if not m:
                continue
            hp, cp = int(m.group(1)), int(m.group(3))
            hp_end = int(m.group(2)) if m.group(2) else hp
            cp_end = int(m.group(4)) if m.group(4) else cp
            # A range (-p 8000-8001:8000-8001) maps port by port; anything
            # else that does not line up is skipped rather than guessed.
            if hp_end - hp != cp_end - cp or hp_end < hp \
                    or not (1 <= hp and hp_end <= 65535 and 1 <= cp and cp_end <= 65535):
                continue
            out.append({"id": f[0], "name": name, "hp": hp, "hp_end": hp_end,
                        "cp": cp})
    return out


def _range_lookup(ranges: list[tuple[int, int, Any]]) -> Callable[[int], Any]:
    """A membership lookup over (lo, hi_inclusive, value) ranges in O(log n) per
    port: `lookup(port)` → the value of a range holding it, or None. Overlaps
    (only forged data has them) resolve to some covering range, never to work
    proportional to their width."""
    rs = sorted(ranges, key=lambda r: r[0])
    los = [r[0] for r in rs]
    # Running maximum of hi, so one bisect finds whether ANY range at or left
    # of the insertion point reaches the port.
    reach, best = [], None
    for r in rs:
        if best is None or r[1] > best[1]:
            best = r
        reach.append(best)

    def lookup(port: int) -> Any:
        i = bisect.bisect_right(los, port) - 1
        if i < 0:
            return None
        r = reach[i]
        return r[2] if r[1] >= port else None
    return lookup


def _sections(text: str, mark: str) -> dict[str, str]:
    """Split exec output on per-call `@@<mark> <section>` lines. The mark is a
    fresh random token per call, so a static file inside the container cannot
    forge a section boundary (a root agent watching the exec can, but it only
    ever forges its own project's view, and every section is parsed as
    untrusted anyway)."""
    out: dict[str, str] = {}
    cur, buf = None, []
    prefix = f"@@{mark} "
    for line in text.splitlines():
        if line.startswith(prefix):
            if cur is not None:
                out[cur] = "\n".join(buf)
            cur, buf = line[len(prefix):].strip(), []
        elif cur is not None:
            buf.append(line)
    if cur is not None:
        out[cur] = "\n".join(buf)
    return out


def _proc_read_script(mark: str, pids: list[int], outer: bool) -> str:
    """One `sh -c` script reading the outer tables (when `outer`) and, per pid,
    its network-namespace link and its own tables. Every value interpolated is a
    validated int or the hex mark; nothing from the container reaches it."""
    parts = []
    if outer:
        for sec, path in (("tcp", "/proc/net/tcp"), ("tcp6", "/proc/net/tcp6"),
                          ("hostname", "/etc/hostname"), ("hosts", "/etc/hosts")):
            parts.append(f"echo '@@{mark} {sec}'; cat {path} 2>/dev/null")
    for pid in pids:
        p = int(pid)
        parts.append(f"echo '@@{mark} ns {p}'; readlink /proc/{p}/ns/net 2>/dev/null")
        parts.append(f"echo '@@{mark} tcp {p}'; cat /proc/{p}/net/tcp 2>/dev/null")
        parts.append(f"echo '@@{mark} tcp6 {p}'; cat /proc/{p}/net/tcp6 2>/dev/null")
    parts.append("true")
    return "; ".join(parts)


def _exec_in(container: str, script: str, timeout_s: float) -> str | None:
    """Run `script` as root in `container` under both an in-container `timeout`
    and a host-side subprocess timeout (the host one alone would leave the inner
    command running). None on any failure or timeout."""
    if timeout_s <= 0:
        return None
    secs = max(1, int(timeout_s))
    try:
        sel = selectors.DefaultSelector()   # not select(): fd numbers past 1024
    except OSError:                         # out of descriptors
        return None
    try:
        proc = subprocess.Popen(_exec_argv(container, secs, script),
                                stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
    except OSError:                     # e.g. an argument past the kernel's limit
        sel.close()
        return None
    deadline = time.monotonic() + timeout_s
    chunks: list[bytes] = []
    size = 0
    rc = None
    try:
        fd = proc.stdout.fileno()
        sel.register(fd, selectors.EVENT_READ)
        while True:
            wait = deadline - time.monotonic()
            if wait <= 0 or not sel.select(wait):
                return None
            chunk = os.read(fd, 65536)
            if not chunk:
                break
            size += len(chunk)
            if size > PORT_DETECT_MAX_OUTPUT_BYTES:
                return None
            chunks.append(chunk)
        rc = proc.wait(timeout=max(0.0, deadline - time.monotonic()))
    except (OSError, subprocess.TimeoutExpired):
        return None
    finally:
        sel.close()
        if proc.poll() is None:
            proc.kill()
            proc.wait()
        proc.stdout.close()
    # errors="replace": the output is container-written (/etc/hosts, the
    # inner docker), and an invalid byte must not escape as an exception.
    return b"".join(chunks).decode("utf-8", "replace") if rc == 0 else None


def _exec_argv(container: str, secs: int, script: str) -> list[str]:
    return ["docker", "exec", "-u", "0", container, "timeout", str(secs),
            "sh", "-c", script]


def _inner_listener(secs: dict[str, str], pid: int, recorded_ns: str,
                    container_port: int,
                    parsed: dict | None = None) -> tuple[bool, str, str]:
    """(readable, inner key, netns) for one inner container: the key is "" while
    nothing inside listens on container_port, else a short digest of that
    listener's socket inodes (it changes when the app restarts inside). A
    digest, not the inode list: one container port reached from many host
    ports would otherwise repeat a container-controlled list in every row.
    Readable only when the namespace link is non-empty, well formed and matches
    the one recorded at lookup (an empty match would let a reused pid read as
    the container), and the table has its header line. `parsed` caches, for
    the call, each pid's table as {port: inodes} and each (pid, port) digest,
    so a container behind many ports is parsed and digested once."""
    ns = secs.get(f"ns {pid}", "").strip()
    table = secs.get(f"tcp {pid}", "")
    if not _NETNS_RE.match(ns) or (recorded_ns and ns != recorded_ns) \
            or not table.strip():
        return False, "", ns
    cache = parsed if parsed is not None else {}
    by_port = cache.get(pid)
    if by_port is None:
        by_port = {}
        for ip, port, i in parse_proc_net_tcp(table, False) + \
                parse_proc_net_tcp(secs.get(f"tcp6 {pid}", ""), True):
            if listen_class(ip, None) != "localhost":
                by_port.setdefault(port, set()).add(i)
        cache[pid] = by_port
    dkey = (pid, container_port)
    if dkey not in cache:
        inodes = sorted(by_port.get(container_port, ()))
        cache[dkey] = hashlib.sha256(",".join(map(str, inodes)).encode()
                                     ).hexdigest()[:16] if inodes else ""
    return True, cache[dkey], ns


def port_detect(req: "PortDetectRequest", _progress=None) -> PortDetectResult:  # type: ignore[name-defined]
    """Web-app candidates listening in `req.project`'s own container.

    One row per port: {port, inodes, label, published, inner_readable,
    inner_key}. Kept: listeners on all interfaces or on the project-network
    address. Dropped: localhost and other local addresses, ports a hand-added
    port could not use (`_coerce_export_port`), hand-added page ports, and
    pass-through spans. For a port the inner docker publishes, `inner_key`
    fingerprints the app's OWN listener inside its container ("" while it
    isn't listening yet) and `inner_readable` says whether that could be read
    at all. An agent can make its own project's reads exceed the output cap
    or the argument limit; that only ever leaves its own view at "partial".
    Writes nothing, launches nothing."""
    budget = min(PORT_DETECT_BUDGET_S, req.deadline - time.time())
    empty = dict(project=req.project, lookup_ran=False, lookup_failed=False,
                 ports=[])
    if budget < PORT_DETECT_BUDGET_S:
        # The caller gives up before a full budget could run (the broker was
        # busy): skip, and let it keep its previous view.
        return PortDetectResult(running=True, partial=True, **empty)
    started = time.monotonic()

    def left() -> float:
        return budget - (time.monotonic() - started)

    cfg = load_config()
    ws = workspace_path_for(req.project, cfg)
    container = container_name_for(req.project)
    gone = PortDetectResult(running=False, partial=False, **empty)
    if not ws.is_dir():
        _PORT_DETECT_STATE.pop(req.project, None)
        return gone
    # One bounded inspect answers "exists", "running" and the substrate: a
    # container wedged on the host daemon must not hold the serial thread.
    try:
        insp = run(["docker", "container", "inspect", "-f",
                    "{{.State.Running}}|{{index .Config.Labels \"%s\"}}"
                    % SUBSTRATE_LABEL, container],
                   capture_output=True, timeout=left(), errors="replace")
    except (subprocess.TimeoutExpired, ValueError, OSError):
        return PortDetectResult(running=True, partial=True, **empty)
    running, _, substrate = insp.stdout.strip().partition("|")
    if insp.returncode != 0 or running != "true":
        _PORT_DETECT_STATE.pop(req.project, None)
        return gone
    dind = (substrate or Substrate.DIND_SYSBOX.value) != Substrate.DOCKER.value
    state = _PORT_DETECT_STATE.get(req.project) or {}
    # Deep enough that recording a namespace below never edits the cache
    # unless this call ends up storing its own state.
    published: dict[int, dict] = {hp: dict(v) for hp, v in
                                  state.get("published", {}).items()}

    mark = secrets.token_hex(8)
    # `published` holds only ports that were listening at the last good
    # lookup, so this set is as small as that listening set.
    cached_pids = sorted({v["pid"] for v in published.values()})
    out = _exec_in(container, _proc_read_script(mark, cached_pids, True), left())
    if out is None:
        return PortDetectResult(running=True, partial=True, **empty)
    secs = _sections(out, mark)

    own = own_address(secs.get("hostname", ""), secs.get("hosts", ""))
    rows = parse_proc_net_tcp(secs.get("tcp", ""), False) + \
        parse_proc_net_tcp(secs.get("tcp6", ""), True)
    try:
        registry = read_exported_ports(ws)
    except Exception:
        # The shared reader returns [] for anything malformed (B149); this is
        # defence in depth, so a future reader regression keeps the old view
        # instead of escaping the verb.
        return PortDetectResult(running=True, partial=True, **empty)
    page_ports = {int(e["port"]) for e in registry if not e.get("passthrough")}
    # Spans as ranges, never expanded: the registry file is writable from
    # inside the container, so a claim's count is not trusted to be small.
    in_span = _range_lookup([(int(e["port"]), int(e["port"]) + int(e.get("count", 1)) - 1, True)
                             for e in registry if e.get("passthrough")])
    by_port: dict[int, set[int]] = {}
    for ip, port, inode in rows:
        if listen_class(ip, own) not in ("all", "own"):
            continue
        if port in page_ports or in_span(port):
            continue
        try:
            _coerce_export_port(port)
        except ValidationError:
            continue
        by_port.setdefault(port, set()).add(inode)
    key = frozenset((p, i) for p, ins in by_port.items() for i in ins)

    # The inner docker lookup: when the listener set changed since the last
    # good lookup, or a cached pid's namespace no longer reads as recorded.
    lookup_ran = lookup_failed = False
    # Only a pid whose namespace was readable can be judged stale: where the
    # inner view is unavailable (recorded "") the outer inode set still
    # catches a container restart, since docker-proxy re-binds on one.
    stale_pid = any(
        v["netns"] and secs.get(f"ns {v['pid']}", "").strip() != v["netns"]
        for hp, v in published.items() if hp in by_port)
    if dind and (key != state.get("key") or stale_pid):
        lookup_ran = True
        ps = _exec_in(container, "docker ps --format "
                      "'{{.ID}}\t{{.Names}}\t{{.Ports}}'", left())
        found = None
        if ps is not None:
            # Map only the ports actually listening; a range is looked up,
            # never walked.
            covering = _range_lookup([(r["hp"], r["hp_end"], r)
                                      for r in _parse_docker_ps_ports(ps)])
            found = {}
            for port in by_port:
                r = covering(port)
                if r is not None:
                    found[port] = {"id": r["id"], "name": r["name"],
                                   "container_port": r["cp"] + (port - r["hp"])}
        pids: dict[str, int] = {}
        if found:
            ids = " ".join(sorted({v["id"] for v in found.values()}))
            insp = _exec_in(container, "docker inspect -f '{{.Id}} {{.State.Pid}}' "
                            + ids, left())
            for line in (insp or "").splitlines():
                f = line.split()
                if len(f) == 2 and re.fullmatch(r"[0-9a-f]{64}", f[0]) \
                        and re.fullmatch(r"[0-9]{1,10}", f[1]) and int(f[1]) > 0:
                    # `docker ps` prints 12-character ids: index by that
                    # prefix, a lookup instead of a scan per port.
                    pids.setdefault(f[0][:12], int(f[1]))
            if insp is None:
                found = None
        if found is None:
            lookup_failed = True        # keep the previous view; retry next call
        else:
            published = {}
            for hp, v in found.items():
                pid = pids.get(v["id"][:12])
                if pid is None or not _DOCKER_NAME_RE.match(v["name"]):
                    continue
                published[hp] = {"name": v["name"],
                                 "container_port": v["container_port"],
                                 "pid": pid, "netns": ""}
            new_pids = sorted({v["pid"] for hp, v in published.items()
                               if hp in by_port})
            more = _exec_in(container, _proc_read_script(mark, new_pids, False),
                            left()) if new_pids else ""
            if more is None:
                # The budget ran out reading the new containers: report
                # partial, so the caller keeps its previous view rather than
                # reading every published port as un-inspectable.
                return PortDetectResult(running=True, partial=True, **empty)
            secs.update(_sections(more, mark))

    ports: list[dict] = []
    parsed: dict = {}   # pid → {port: inodes}; (pid, port) → digest (see _inner_listener)
    for port in sorted(by_port):
        row = {"port": port, "inodes": sorted(by_port[port]), "label": str(port),
               "published": False, "inner_readable": None, "inner_key": ""}
        v = published.get(port)
        if v is not None:
            readable, inner, ns = _inner_listener(secs, v["pid"], v["netns"],
                                                  v["container_port"], parsed)
            if readable and not v["netns"]:
                v["netns"] = ns
            row.update(label=v["name"], published=True,
                       inner_readable=readable, inner_key=inner)
        ports.append(row)
    if not lookup_failed:
        _PORT_DETECT_STATE[req.project] = {"key": key, "published": published}
    return PortDetectResult(project=req.project, running=True, partial=False,
                            lookup_ran=lookup_ran, lookup_failed=lookup_failed,
                            ports=ports)


# ---------------------------------------------------------------------------
# Dev lane verbs (STAGE_DEV_GITEA S1). Every gitea.GiteaError is re-raised as a
# ValidationError so a broker verb fn never lets a foreign exception escape into
# socketserver (the _verb_workflows rule). Secrets (PAT, agent token) never enter
# a message — GiteaError carries only method/path/status by construction.
# ---------------------------------------------------------------------------

def _gitea_host_port() -> str:
    return load_versions().get("GITEA_HOST_PORT", gitea.DEFAULT_GITEA_HOST_PORT)


def dev_repo_add(req: "DevRepoAddRequest", _progress=None) -> DevRepoAddResult:  # type: ignore[name-defined]
    """Mirror a GitHub repo into shared gitea — MIRROR-ONLY (per-consumer
    identities are minted at the point that needs an agent: dev-workflow
    create, the box dev path, an explicit attach). Resumable/idempotent (a
    mid-migrate timeout heals on re-run)."""
    _resume_gitea(require=True)         # resume an enabled gitea; never create
    host_port = _gitea_host_port()
    # Private source ⇔ the caller supplied a per-repo PAT (RS stores no PAT).
    # The PAT is harmless on a public clone; a private repo without one fails
    # loudly at migrate.
    try:
        gitea.add_repo(host_port, req.url, req.repo, pat=req.pat or None)
    except gitea.GiteaError as e:
        raise ValidationError(str(e))
    return DevRepoAddResult(
        repo=req.repo, url=req.url,
        mirror=f"{gitea.ADMIN_USER}/{req.repo}",
        stamp=str(gitea.mirror_stamp_path(req.repo)))


def dev_repo_remove(req: "DevRepoRemoveRequest", progress=None) -> DevRepoRemoveResult:  # type: ignore[name-defined]
    """Delete the mirror + best-effort every consumer fork + the gitea USER
    (and host token) of every fork owner that is FULLY retired — nothing in
    the attachment ledger records it and it owns nothing else once its fork is
    gone — + the mirror stamp. An owner some project still records (the B53
    name-collision edge: two consumers on one gitea username, one shared token
    file) keeps both its token and its user, with a warning. The purge is what
    frees the project/box name: a retired identity is visible on the
    Development page only through an archived fork, so deleting the fork while
    keeping the user used to leave an invisible blocker (B52).

    TWO refusals, in order:
      1. The LEDGER check (a local file read — no gitea needed): a project is
         still attached. Friendly and actionable ("delete that project first"),
         but only as truthful as the record.
      2. The FORK check — the AUTHORITATIVE gate: the mirror still carries a
         LIVE (unarchived) consumer fork, i.e. an agent's work nobody retired.
         It measures ACTUAL gitea state rather than trusting the ledger, and it
         FAILS CLOSED: if the forks can't be enumerated we refuse rather than
         delete (hence gitea.consumer_forks, which raises — NOT list_forks,
         whose []-on-error would read a sick gitea as "no forks, safe to wipe").

    A RETIRED consumer (destroyed project, removed box) leaves its fork
    ARCHIVED, which is not live — so the normal "this repo is finished" path
    passes both gates with no extra step."""
    progress = progress or _NULL_PROGRESS
    attached = gitea.attached_projects(req.repo)
    if attached:
        die(f"repo {req.repo!r} is still worked by: {', '.join(attached)}. "
            f"Delete those dev projects (or their boxes) first — retiring a "
            f"consumer archives its fork and releases the repo.")
    _resume_gitea(require=True)        # resume an enabled gitea to talk to it
    host_port = _gitea_host_port()
    progress.step("forks", "checking for live agent forks")
    try:
        forks = gitea.consumer_forks(host_port, req.repo)
    except gitea.GiteaError as e:
        # Fail CLOSED: an unverifiable fork state is never a licence to delete.
        raise ValidationError(
            f"could not verify {req.repo!r}'s forks ({e}); refusing to delete")
    live = [f["user"] for f in forks if not f.get("archived")]
    if live:
        die(f"repo {req.repo!r} still has live agent fork(s): "
            f"{', '.join(live)}. Delete the dev project or box that owns the "
            f"work first (retiring it archives the fork), or archive the fork "
            f"in the Gitea tab if it is orphaned.")
    # Milestone KEY "delete" is read by the archived remove harness; only the
    # message changed.
    progress.step("delete",
                  "deleting the mirror, its retired forks and their identities")
    try:
        # `or []`: an archived stub returns None here; the CLI joins the list.
        purged = gitea.remove_repo(host_port, req.repo) or []
    except gitea.GiteaError as e:
        raise ValidationError(str(e))
    return DevRepoRemoveResult(repo=req.repo, purged_users=list(purged))


def dev_repo_list(_req: "DevRepoListRequest", _progress=None) -> DevRepoListResult:  # type: ignore[name-defined]
    # A READ — NEVER starts gitea (the dev_status precedent): a stopped/absent
    # gitea lists nothing rather than resuming a backend on a page read.
    if not container_running(gitea.GITEA_CONTAINER):
        return DevRepoListResult(repos=[])
    try:
        repos = gitea.list_repos(_gitea_host_port())
    except gitea.GiteaError as e:
        raise ValidationError(str(e))
    # rs-fetch visibility rides every repo-listing read (the CLI's list surface
    # here; the browser's on dev_status below). A pure host-file read: it adds
    # no docker or network call, so the no-start posture above is untouched.
    # Deliberately the same `fetch_enabled` seam the other two read verbs use
    # rather than a hoisted map read: one function is one place for a test to
    # stub, and the archived pins that drive these verbs stub exactly it.
    for row in repos:
        name = row.get("repo")
        row["fetch_enabled"] = gitea.fetch_enabled(name)
        # The floor every dev-lane WRITE gates on (the host mirror stamp),
        # reported beside the list so a repo gitea holds but this host never
        # added reads as such instead of failing at the first write. A host
        # file stat, so the no-start posture holds; a nameless row is not added.
        row["added"] = bool(name) and gitea.mirror_present(name)
    return DevRepoListResult(repos=repos)


def dev_attach(req: "DevAttachRequest", _progress=None) -> DevAttachResult:  # type: ignore[name-defined]
    """Connect a project's bridge to rs-gitea and record the agent attachment
    (repo + gitea_ip). Requires a RUNNING project (the token staging is a
    docker exec into the live supervisor) and an added repo. A re-attach that
    lands a DIFFERENT gitea IP auto-heals the project's dev boxes (F1). Attach
    never clones into the supervisor — the dev workflow's create step owns
    that; a later-attached extra repo is staged-only (the in-project agent can
    clone it itself with the staged credentials)."""
    container = container_name_for(req.project)
    if not container_exists(container):
        die(f"project {req.project!r} does not exist")
    network = project_network_for(req.project)
    if not network_exists(network):
        die(f"project {req.project!r} has no network; start it first")
    # The repo must have been added (its mirror exists) before an agent
    # attaches — the mirror stamp is the host-side floor.
    if not gitea.mirror_present(req.repo):
        die(f"repo {req.repo!r} not added yet — add it first (the dev "
            f"workflow card and the dev box dialog take its GitHub URL)")
    if not container_running(container):
        die(f"project {req.project!r} is not running; start it first (an "
            f"agent attach stages the gitea token into the live supervisor)")
    # ONE REPO PER DEV CONTAINER (hard invariant): a project's own agent works
    # exactly one repo. Same-repo re-attach (the gitea-IP heal below) is fine; a
    # DIFFERENT repo is the retired multi-repo flow and is refused here — the
    # only door to a second agent repo (create records the one repo directly,
    # box_add provisions box consumers, neither routes through here). Box
    # entries (box != None) are OTHER containers, never this project's 2nd repo.
    existing = {e["repo"] for e in gitea.project_entries(req.project)
                if e.get("class") == "agent" and e.get("box") is None
                and e.get("repo")}
    if existing and existing != {req.repo}:
        die(f"project {req.project!r} already works repo {sorted(existing)[0]!r}; "
            f"a dev container is single-repo — discard and recreate it to work a "
            f"different repo")
    _resume_gitea(require=True)         # resume an enabled gitea; never create
    # Refuse a surviving retired identity BEFORE the network attach below — the
    # first thing here that mutates anything. This is the path most likely to
    # meet one in practice, and until now it was the WORST at saying so: a
    # re-attach against an archived fork used to succeed silently and leave the
    # agent unable to push. Everything above is read-only, and the resume is
    # idempotent, so the refusal costs nothing.
    _refuse_retired_identity(gitea.agent_username(
        gitea.consumer_for(req.project)))
    ip = _connect_gitea_to_project_network(network)
    if not ip:
        die(f"rs-gitea did not attach to {network} (no IP); check docker state")
    # An explicit attach means "this project's OWN agent works this repo" —
    # provision the PROJECT consumer (user + fork + token). Boxes provision
    # their own consumers in box_add, never through here (4c-a).
    dev_user = gitea.agent_username(gitea.consumer_for(req.project))
    # PRESERVE the recorded branch. record_attachment REPLACES on
    # (project, class, repo, box), and the same-repo re-attach is the ONLY live
    # path here — the single-repo guard above hard-refuses a different repo — so
    # this is exactly the entry create recorded. Resolving a fresh default would
    # silently re-point the agent's prompt at the repo default while its clone
    # stays on the chosen branch: no error, just wiring that lies. Resolve ONLY
    # when there is nothing to preserve (a first attach, or a pre-change entry).
    # Resolved BEFORE the provision so the fork's default branch can follow it.
    prior = next((e for e in gitea.project_entries(req.project)
                  if e.get("class") == "agent" and e.get("repo") == req.repo
                  and e.get("box") is None), None)
    branch = (prior or {}).get("branch") or ""
    if not branch:
        branch = _resolve_dev_branch(req.repo, "")
    try:
        gitea.provision_consumer(_gitea_host_port(), req.repo, dev_user,
                                 default_branch=branch)
    except gitea.GiteaError as e:
        raise ValidationError(str(e))
    gitea.record_attachment(req.project, "agent", req.repo, ip,
                            box=None, user=dev_user, branch=branch)
    cfg = load_config()
    _stage_dev_gitea(req.project, cfg, gitea_ip=ip)
    # Unconditional reconcile: change detection lives per-box in
    # _restart_dev_boxes (against actual ExtraHosts) — a record-history
    # comparison cannot work here, detach deletes the prior entry.
    _restart_dev_boxes(req.project, cfg, ip, _progress)
    return DevAttachResult(project=req.project, repo=req.repo, gitea_ip=ip)


def dev_detach(req: "DevDetachRequest", _progress=None) -> DevDetachResult:  # type: ignore[name-defined]
    """Retire consumer entries. repo=<r> detaches the PROJECT consumer's entry
    for that repo (box entries retire via box remove); repo=None detaches ALL
    of the project's entries — detach-to-zero by definition, boxes included.
    Every detached consumer's fork is ARCHIVED (history kept, best-effort —
    skipped when gitea isn't running) and the PROJECT consumer's token — ONE
    file shared across its repos — is deleted ONLY at zero project-consumer
    entries. The staged dev wiring follows the record. The network attachment
    is NOT dropped (S3: fetch is universal; only destroy disconnects).
    Standing dev boxes are NOT auto-discarded — the ALL branch leaves them
    running but unwired (an operator action, documented)."""
    entries = [e for e in gitea.project_entries(req.project)
               if e.get("class") == "agent" and e.get("repo")]
    if req.repo is None:
        targets = list(entries)
        # Dev rows only: the project's Gitea-history rows are not dev wiring.
        gitea.prune_project(req.project, klass="agent")
        remaining = []
    else:
        targets = [e for e in entries
                   if e.get("repo") == req.repo and e.get("box") is None]
        remaining = gitea.prune_entry(req.project, req.repo, box=None,
                                      klass="agent")
    if targets and container_running(gitea.GITEA_CONTAINER):
        host_port = _gitea_host_port()
        for e in targets:
            if e.get("user"):
                try:
                    gitea.archive_fork(host_port, e["user"], e["repo"])
                except gitea.GiteaError:
                    pass
    # Token cleanup (the detach-to-zero rule). Box tokens go with their
    # dropped box entries on the ALL branch.
    drop_users = {e["user"] for e in targets
                  if e.get("user") and e.get("box") is not None}
    proj_user = gitea.agent_username(gitea.consumer_for(req.project))
    still_proj = any(e.get("box") is None for e in remaining
                     if e.get("class") == "agent" and e.get("repo"))
    if not still_proj and (req.repo is None
                           or any(e.get("box") is None for e in targets)):
        drop_users.add(proj_user)
    for user in drop_users:
        gitea.delete_consumer_token(user)
    _stage_dev_gitea(req.project, load_config())
    container = container_name_for(req.project)
    if container_running(container):
        for user in sorted(drop_users):
            run(["docker", "exec", "-u", "research", container, "sh", "-c",
                 'rm -f "$HOME/.dev-tokens/$1"', "sh", f"{user}.token"],
                capture_output=True)
        # B62 detach-to-zero: the consumer's credential store follows its
        # token. Gate = the CONJUNCTION — the project consumer is being
        # dropped AND this detach actually retired an agent (box=None) row.
        # drop_users membership alone over-fires on a box-only project's
        # detach-ALL (the disjunct above adds proj_user with no agent row
        # ever having existed — and ~/.git-credentials there can be the
        # HUMAN's own store); box-None-in-targets alone over-fires on a
        # per-repo detach that leaves the consumer working another repo.
        if proj_user in drop_users and any(e.get("box") is None
                                           for e in targets):
            run(["docker", "exec", "-u", "research", container, "sh", "-c",
                 'rm -f "$HOME/.git-credentials"'],
                capture_output=True)
    return DevDetachResult(project=req.project, repo=req.repo,
                           remaining=len(remaining))


def dev_sync(req: "DevSyncRequest", _progress=None) -> DevSyncResult:  # type: ignore[name-defined]
    _resume_gitea(require=True)         # resume an enabled gitea; never create
    try:
        gitea.sync_repo(_gitea_host_port(), req.repo)
    except gitea.GiteaError as e:
        raise ValidationError(str(e))
    return DevSyncResult(repo=req.repo)


def _dev_gitea_state() -> dict:
    """The gitea dict BOTH Development reads return (dev_status and its
    per-repo sibling dev_repo_status) — one source, so the two cannot drift:
    the per-repo Fetch pane renders through the same held-gitea notice as the
    Development page and needs the same fields. A READ with the verbs'
    no-start posture: docker inspects, host files and a non-blocking shared
    flock probe that creates nothing."""
    exists = container_exists(gitea.GITEA_CONTAINER)
    running = bool(exists and container_running(gitea.GITEA_CONTAINER))
    # The release, the shipped one and any upgrade state ride every reply —
    # pure docker inspects and host files, so the no-start posture holds.
    info = gitea_version_info()
    # While an upgrade or a restore holds gitea, its API is down or answering
    # from a database being migrated: report that, and touch nothing.
    if info["upgrading"]:
        running = False
    return {"exists": exists, "running": running, **info}


def dev_status(_req: "DevStatusRequest", _progress=None) -> DevStatusResult:  # type: ignore[name-defined]
    """The Development-page read: gitea state + per-repo mirror/PR/branch
    status + agent attachments. A READ — never starts gitea, never waits: an
    absent or STOPPED gitea reports running:false with no repos immediately
    (`dev_gitea_start` is the explicit enable verb; `dev_sync`, a user-initiated
    write, resumes an enabled gitea). Deliberately no _provision_gitea/
    _resume_gitea on any path: a page-load read must neither create nor
    docker-start containers, nor sit in a readiness wait on the serial thread."""
    g = _dev_gitea_state()
    repos: list[dict] = []
    if g["running"]:
        host_port = _gitea_host_port()
        try:
            listed = [r["repo"] for r in gitea.list_repos(host_port)
                      if r.get("repo")]
        except gitea.GiteaError as e:
            # No list, no page — the enumeration itself staying page-fatal is
            # deliberate; only the PER-ROW reads degrade below.
            raise ValidationError(str(e))
        for name in listed:
            # Per-repo degradation (B37): one sick repo must never take down
            # the other rows. A raising repo_status becomes a degraded
            # {repo, error} row the page renders inline; GiteaError carries
            # only method/path/status by that class's own contract, so no
            # secret can enter the row.
            try:
                row = gitea.repo_status(host_port, name)
                # The badge feed (S4): pure host-file ledger reads, so the
                # read stays structurally no-start. The ledger holds every
                # verdict ever recorded for the repo — including other forks'
                # and superseded heads — and the selection picks the ONE that
                # may decorate each open-PR row. The full history is not this
                # verb's job; it has its own read (dev_reviews), which is what
                # survives a landing.
                row["reviews"] = gitea.select_pr_verdicts(
                    gitea.load_repo_pr_verdicts(name), row.get("prs") or [],
                    row.get("active") or "", row.get("active_id"))
            except gitea.GiteaError as e:
                row = {"repo": name, "error": str(e)}
            # The visibility preference rides BOTH arms deliberately. A degraded
            # repo is exactly the one an operator reaches for the hide button on,
            # so its row must still carry the state its toggle renders from — and
            # unlike the fields repo_status computes, this one is knowable even
            # when gitea cannot answer for the repo (it is a local file read).
            row["fetch_enabled"] = gitea.fetch_enabled(name)
            # The read reports the same floor the writes gate on: gitea can
            # hold a mirror this host has no stamp for (another RS home sharing
            # the one gitea, or reset dev-lane records), and every stamp-gated
            # write refuses it. Carrying it on BOTH arms lets the page show the
            # disagreement instead of a control that always refuses. A pure
            # host-file stat — the no-start posture holds.
            row["added"] = gitea.mirror_present(name)
            repos.append(row)
    attachments = [{"project": e.get("project"), "repo": e.get("repo")}
                   for e in gitea.load_attachments()
                   if e.get("project") and e.get("repo")
                   and e.get("class") != gitea.HISTORY_CLASS]
    # Reviewer-token state rides OUTSIDE `if running:` — it is orthogonal to
    # gitea's state (a pure local file read; the no-start posture holds).
    return DevStatusResult(gitea=g,
                           repos=repos, attachments=attachments,
                           reviewer=gitea.reviewer_token_state())


def dev_reviews(_req: "DevReviewsRequest", _progress=None) -> DevReviewsResult:  # type: ignore[name-defined]
    """Every review verdict recorded on this host, newest first — the review
    HISTORY, as opposed to dev_status's badge feed.

    A verdict used to be visible only as a decoration on a live gitea row: an
    open PR, or a commit still listed on a branch. Landing the PR (or purging
    the fork, or collecting the repo, which rewrites the shas) took every
    review off the screen while the files sat untouched on disk. This read
    answers from the ledger alone — no gitea call, no docker, nothing to start
    — so the history stands with gitea stopped, with the mirror removed, and
    after any respawn. Entries carry what they reviewed (title/branch/subject,
    the fork and its era) for exactly that reason: the row they came from may
    no longer exist anywhere."""
    return DevReviewsResult(reviews=gitea.load_all_verdicts())


def dev_repo_status(req: "DevRepoStatusRequest", _progress=None) -> DevRepoStatusResult:  # type: ignore[name-defined]
    """ONE repo's Development status — the per-project Fetch-tab read, the
    repo-scoped sibling of dev_status with the SAME posture: a READ that never
    starts gitea and never waits (no _provision_gitea/_resume_gitea on any
    path; absent/stopped -> running:false with an empty row immediately).
    There is no enumeration here, so nothing stays page-fatal: an unknown or
    sick repo degrades to a {repo, error} row (repo_status raises GiteaError
    on the mirror GET's 404), which the pane renders inline (B37 posture).
    The gitea dict is dev_status's own (release, upgrade state, and running
    forced false while an upgrade or a restore holds gitea), so the pane shows
    the held notice instead of reading a Gitea whose data is being moved."""
    g = _dev_gitea_state()
    row: dict = {}
    if g["running"]:
        try:
            row = gitea.repo_status(_gitea_host_port(), req.repo)
            # The badge feed, selected exactly as dev_status does it — the
            # two verbs MUST stay in lockstep: the page renders both through
            # one card renderer that assumes an identical row shape.
            row["reviews"] = gitea.select_pr_verdicts(
                gitea.load_repo_pr_verdicts(req.repo), row.get("prs") or [],
                row.get("active") or "", row.get("active_id"))
        except gitea.GiteaError as e:
            row = {"repo": req.repo, "error": str(e)}
        # Same annotation as dev_status, on both arms, for the same reason.
        row["fetch_enabled"] = gitea.fetch_enabled(req.repo)
        row["added"] = gitea.mirror_present(req.repo)
    attachments = [{"project": e.get("project")}
                   for e in gitea.load_attachments()
                   if e.get("project") and e.get("repo") == req.repo
                   and e.get("class") != gitea.HISTORY_CLASS]
    # Same posture as dev_status: the token state is a local file read,
    # populated outside `if running:`.
    return DevRepoStatusResult(gitea=g,
                               repo=row, attachments=attachments,
                               reviewer=gitea.reviewer_token_state())


def dev_gitea_start(_req: "DevGiteaStartRequest", progress=None) -> DevGiteaStartResult:  # type: ignore[name-defined]
    """DELIBERATELY provision/enable gitea — the Sandboxes page's Infrastructure tab
    "Enable Gitea" button (and `research dev gitea-enable`). The SOLE stand-up
    path (deliberate-create / auto-resume model): it CREATES gitea from nothing
    (pull + run + bootstrap) or resumes a stopped one. Runs as a tailed op
    (PROGRESS_VERBS via _start_op, the 600s op timeout) — the one-time image
    pull streams milestones to the view log; the browser tails to completion."""
    _provision_gitea(progress)
    return DevGiteaStartResult(running=True)


def dev_set_active_fork(req: "DevSetActiveForkRequest", _progress=None) -> DevSetActiveForkResult:  # type: ignore[name-defined]
    """Set the GLOBAL active fork for a repo (the Management dropdown). A
    user-initiated WRITE, so it keeps the dev_sync self-heal posture (resume an
    enabled gitea, never create). Validates the fork is LIVE, persists the map
    entry, and re-stages dev-gitea.json on every attached project so the
    in-container readers (rs-fetch) pick the new owner up without a restart."""
    _resume_gitea(require=True)
    host_port = _gitea_host_port()
    try:
        forks = gitea.list_forks(host_port, req.repo)
    except gitea.GiteaError as e:
        raise ValidationError(str(e))
    live = {f["user"] for f in forks if not f.get("archived")}
    if req.user not in live:
        raise ValidationError(
            f"{req.user!r} is not a live consumer fork of {req.repo!r} "
            f"(live: {sorted(live) or 'none'})")
    active = gitea.load_active_forks()
    active[req.repo] = req.user
    gitea.save_active_forks(active)
    cfg = load_config()
    for project in gitea.attached_projects(req.repo):
        _stage_dev_gitea(project, cfg)
    return DevSetActiveForkResult(repo=req.repo, user=req.user)


def dev_set_fetch_enabled(req: "DevSetFetchEnabledRequest", _progress=None) -> DevSetFetchEnabledResult:  # type: ignore[name-defined]
    """Show or hide one repo on the webui's rs-fetch LISTS (the Development
    page's Repos tab, and its CLI twin).

    The cheapest verb in the dev lane: a single host-file write with NO gitea
    call on any path — so, unlike its sibling dev_set_active_fork, it does not
    resume gitea and cannot wait on one. A stopped or sick gitea is irrelevant
    to it.

    The one gate is the mirror stamp — the same pre-side-effect host-file floor
    dev_attach, box_add's dev gate and CreateRequest.from_kwargs use — so a
    preference can never be minted for a repo that was never added (a stale page
    clicking a repo removed in another tab is the live case). Its refusal text is
    the wording those three already share: it reaches the browser verbatim, so it
    names webui affordances and no CLI command.

    Visibility is a DISPLAY setting, not a permission: nothing here touches the
    in-container fetch wiring, and `rs-fetch <repo>` typed in a terminal keeps
    working on a hidden repo. Nothing in a container enumerates repos, so there
    is no in-container list for this to clean."""
    if not gitea.mirror_present(req.repo):
        raise ValidationError(
            f"repo {req.repo!r} not added yet — add it first (the dev "
            f"workflow card and the dev box dialog take its GitHub URL)")
    gitea.set_fetch_enabled(req.repo, req.enabled)
    return DevSetFetchEnabledResult(repo=req.repo, enabled=req.enabled)


def dev_purge_consumer(req: "DevPurgeConsumerRequest", progress=None) -> DevPurgeConsumerResult:  # type: ignore[name-defined]
    """Delete a RETIRED dev identity — the gitea user and every fork it owns —
    freeing its name for reuse. The recovery half of B41: retirement keeps the
    user (deleting one PURGES its repos, so archiving is the history-preserving
    default), and a kept identity blocks a same-name project or box forever.

    TWO GATES, both FAIL CLOSED, and the order matters:

      0. Absent user -> no-op success, checked FIRST. A stale ledger row naming
         a user that is already gone must not reach a gate that then refuses on
         it, and a double click (or a delete_user that timed out while
         succeeding server-side) must be able to clear the row.
      1. LEDGER — refuse if ANY attachment entry names this user. That is what
         stops a repo-scoped click from purging a consumer still attached
         elsewhere, and it needs no gitea call, so it holds even when gitea is
         half-up. The record is the friendly pre-flight...
      2. GITEA — ...and the LIVE STATE is the authority: refuse if any fork the
         identity owns is unarchived. gitea and the ledger can diverge (B27),
         and this is the arm that catches it. A GiteaError here REFUSES (via
         user_repos, which raises) — an unverifiable state is never a licence
         to delete.

    Only then purge_consumer, which is gate-free by design (retirement calls it
    with LIVE forks; see its docstring)."""
    progress = progress or _NULL_PROGRESS
    _resume_gitea(require=True)         # resume an enabled gitea; never create
    host_port = _gitea_host_port()
    try:
        if not gitea.GiteaClient(gitea.api_base(host_port),
                                 gitea.read_admin_token()
                                 ).user_exists_strict(req.user):
            progress.step("purge", f"{req.user} is already gone")
            return DevPurgeConsumerResult(user=req.user, repos=[], purged=False)
    except gitea.GiteaError as e:
        raise ValidationError(f"could not check {req.user!r} against Gitea: {e}")
    claimed = sorted({e["project"] for e in gitea.load_attachments()
                      if e.get("user") == req.user and e.get("project")})
    if claimed:
        raise ValidationError(
            f"{req.user!r} is still in use by {', '.join(claimed)} — retire "
            f"that project or box first (destroying it archives the fork)")
    try:
        owned = gitea.user_repos(host_port, req.user)
    except gitea.GiteaError as e:
        raise ValidationError(
            f"could not verify what {req.user!r} owns ({e}); refusing to purge")
    live = sorted(r["repo"] for r in owned if not r["archived"])
    if live:
        raise ValidationError(
            f"{req.user!r} still has a live fork ({', '.join(live)}); refusing "
            f"to purge — an identity is only retired once its forks are "
            f"archived")
    progress.step("purge", f"deleting {req.user} and its retired fork(s)")
    try:
        repos = gitea.purge_consumer(host_port, req.user)
    except gitea.GiteaError as e:
        raise ValidationError(str(e))
    # purged=True even when `repos` is empty: the identity existed (checked
    # above) and its user is gone now, which is what frees the name.
    return DevPurgeConsumerResult(user=req.user, repos=repos, purged=True)


def dev_commits(req: "DevCommitsRequest", _progress=None) -> DevCommitsResult:  # type: ignore[name-defined]
    """ONE PAGE of a PR's or a branch's commits, newest-first, for the
    Development page's lazy per-row dropdowns. A READ — the
    dev_status/dev_repo_list posture: NEVER starts gitea on any path (no
    _provision_gitea, no _resume_gitea; a stopped/absent gitea returns empty
    immediately). The try encloses the ENTIRE gitea chain deliberately:
    read_admin_token() raises GiteaError on an un-bootstrapped lane, and an
    escaped GiteaError would leave the broker reply truncated with no envelope.

    `running` is load-bearing for the browser's honesty: a stopped gitea
    returns an empty list inside a normal ok:true envelope, which is
    indistinguishable from "you have reached the end of the history" — and the
    dropdown asserts one of those to the operator. It is free here (the
    no-start guard already performs exactly this check)."""
    if not container_running(gitea.GITEA_CONTAINER):
        return DevCommitsResult(repo=req.repo, commits=[], has_more=False,
                                page=req.page, running=False, reviews={},
                                mirror_head="")
    # Bound on BOTH legs before the branch: the return below reads it either
    # way, and an UnboundLocalError on the PR leg is not in dispatch's catch
    # set — it would escape past the un-wrapped dispatch() call in handle()
    # and truncate the client's reply with no envelope.
    mirror_head = ""
    try:
        if req.pr is not None:
            commits, has_more = gitea.pr_commits(
                _gitea_host_port(), req.repo, req.pr, req.page)
        else:
            commits, has_more = gitea.branch_commits(
                _gitea_host_port(), req.repo, req.branch, req.page)
            # The dropdown's boundary marker. Encloses ONLY the probe: a wider
            # try would leave commits/has_more unbound on the same escape path
            # AND swallow the failure the outer arm exists to convert. A
            # missing marker is exactly today's screen, and the over-fetch it
            # may cost is absorbed by rs-fetch's patch-id walk — so a
            # decoration must never take down a list that loaded fine.
            try:
                mirror_head = gitea.mirror_branch_head(
                    _gitea_host_port(), req.repo, req.branch)
            except gitea.GiteaError:
                mirror_head = ""
    except gitea.GiteaError as e:
        raise ValidationError(str(e))
    # Per-commit review verdicts for the rows' badges: a pure host-file ledger
    # read (the dev_status precedent), so the read stays structurally no-start.
    # The ledger is the repo's FULL sha-keyed map, so every page carries badge
    # data for its own rows with no extra call.
    return DevCommitsResult(repo=req.repo, commits=commits,
                            has_more=has_more, page=req.page, running=True,
                            reviews=gitea.load_repo_commit_verdicts(req.repo),
                            mirror_head=mirror_head)


def dev_board_export(req: "DevBoardExportRequest", progress=None, *,
                     dest: Path | None = None) -> DevBoardExportResult:  # type: ignore[name-defined]
    """Write an encrypted export of the WHOLE dev Gitea instance to ``dest``.

    What the artifact covers, stated plainly because the UI repeats it: the
    entire instance, not one board. Restoring it rolls every repo and every
    project's board back to the moment of export. Recovering a single damaged
    fork without reverting the rest means restoring into a scratch gitea and
    copying across by hand.

    What it does NOT cover: the host-side dev ledger under ~/.research-sandbox/dev
    (which project works which repo, the per-consumer tokens, the mirror stamps,
    the active-fork map) never lived in gitea and is not in a gitea dump. After a
    restore the host still claims forks the rolled-back gitea no longer has, and
    any consumer provisioned SINCE the export has no token row in the restored
    instance — those agents silently lose push authentication until they are
    re-provisioned. The restore surface states this; it is the severest of the
    artifact's gaps and is not a board-rollback-shaped problem.

    ``progress`` is POSITIONAL: the broker's dispatch calls ``fn(args, progress)``
    and the verb wrappers forward it positionally, so a keyword-only parameter
    would raise TypeError — which dispatch does NOT catch (it catches only
    ValidationError, HarnessError and SystemExit), leaving the client with no
    reply envelope at all.

    ``dest`` is KEYWORD-ONLY and deliberately NOT a field on the request: a
    filesystem path must never be relayable from the browser, and keyword-only
    means the broker's ``fn(args, progress)`` call shape structurally cannot
    reach it. ``None`` means the BROWSER path and lands on the one fixed name
    under ``BOARD_EXPORT_DIR``; the CLI always passes its own path and never
    writes into the backups directory the browser path uses (``--out`` is
    required, which is what keeps it out).

    There is deliberately NO sweep of the export directory before writing. It
    would be a pure regression: the on-disk name is FIXED, so ``dump_instance``'s
    verified `.part` → ``replace()`` already IS the one-resident-artifact
    mechanism, and it is atomic. A sweep could only delete the file that
    ``replace()`` is about to overwrite — while every failure arm of the export
    unlinks its part and raises, so a sweep-first export that failed would leave
    the operator with NO backup where they previously had a good one. The cost of
    not sweeping is transient disk: the old artifact and the new `.part` coexist
    for the duration of the export.
    """
    progress = progress or _NULL_PROGRESS
    # The clock starts HERE, not at the dump. `_resume_gitea` can take minutes on
    # the stopped-container arm (docker start + _wait_for_gitea, whose own bound
    # is ~4 min), so a budget that began after it would let the verb run to
    # ~780s — past the 600s window this bound exists to stay under, which is
    # precisely the outcome its comment claims to buy off.
    deadline = time.monotonic() + BOARD_EXPORT_TIMEOUT_S
    # Emitted BEFORE the resume, not after: the stopped-container arm is `docker
    # start` + a readiness wait measured in minutes, and without a step here the
    # browser's checklist shows nothing at all for that whole stretch while the
    # op reads as running. Lockstep with OP_CHECKLISTS.dev_board_export.
    progress.step("gitea", "making sure gitea is running")
    # RESUME an enabled gitea; never create one. A backup verb must not stand up a
    # backend the operator disabled, and `gitea dump` needs it running anyway.
    # Its refusal text is already webui-clean.
    _resume_gitea(require=True)
    progress.step("image", "resolving the gitea image")
    image = _live_gitea_image()
    if dest is None:
        # The browser path. Create the directory 0700 explicitly rather than via
        # mkdir(mode=…), which does nothing to an EXISTING directory — the
        # broker's own serve() uses the same create-then-chmod shape for run/.
        BOARD_EXPORT_DIR.mkdir(parents=True, exist_ok=True)
        try:
            BOARD_EXPORT_DIR.chmod(0o700)
        except OSError:
            pass
        dest = BOARD_EXPORT_DIR / BOARD_EXPORT_NAME
    # Coerce: a caller handing us a string would otherwise reach .stat() as a str.
    dest = Path(dest)
    remaining = int(deadline - time.monotonic())
    if remaining < BOARD_EXPORT_MIN_RUN_S:
        # Bringing gitea up ate the budget. Refuse rather than start an export
        # that is certain to be cut off part-way, which would cost the operator
        # the wait and leave them nothing.
        raise HarnessError(
            "gitea board export had no time budget left",
            f"starting gitea used the export's {BOARD_EXPORT_TIMEOUT_S}s budget; "
            f"retry now that it is running")
    progress.step("dump", "exporting, encrypting and verifying the instance")
    try:
        # ONE call, ONE budget: dump_instance dumps, verifies the .part end to
        # end, and promotes it to `dest` only if it opened. Two separate calls
        # here would each carry the full timeout, so the verb's worst case would
        # be twice the number this bound was reasoned against.
        size, info = gitea.dump_instance(
            container=gitea.GITEA_CONTAINER, passphrase=req.passphrase,
            out_path=dest, image=image, timeout=remaining)
    except gitea.GiteaError as e:
        # HarnessError splits the sinks: log_msg (a STEP NAME, no path, no
        # detail) reaches the durable full log and the mounted view log, while
        # client_detail reaches the error envelope only. Nothing scrubs the
        # passphrase out of the detail because nothing can carry it there: it
        # travels on stdin into a 0600 file inside the container and never enters
        # argv. (dev_passwd DOES scrub, because its secret rides argv into
        # `docker exec` — do not copy that scrub here, and do not read its absence
        # as an oversight.)
        raise HarnessError("gitea board export failed", str(e))
    st = dest.stat()
    return DevBoardExportResult(
        path=str(dest), size=size,
        created_at=datetime.datetime.fromtimestamp(
            st.st_mtime, datetime.timezone.utc).isoformat(timespec="seconds"),
        member_count=info.get("member_count"),      # may be None = unknown
        has_db=bool(info.get("has_db")),
    )


def _docker_start_cause(r: "subprocess.CompletedProcess") -> str:
    """Docker's own reason for a failed `docker start`, as a short parenthesis.

    Empty when docker printed nothing, so a caller never renders "(docker: )".
    Whitespace is collapsed BEFORE the tail is cut, so docker's two-line message
    reads as one line inside the operator's one-line error.
    """
    err = " ".join((r.stderr or r.stdout or "").split())
    return f" (docker: {err[-_GITEA_START_ERR_TAIL_CHARS:]})" if err else ""


def dev_board_import(req: "DevBoardImportRequest",
                     progress=None) -> DevBoardImportResult:  # type: ignore[name-defined]
    """Restore the whole gitea instance from an encrypted backup.

    The destructive one. It stops gitea, replaces its database and every
    repository, and reverts every project's board to the moment the backup was
    taken. There is no broker verb and there will not be one: the ceremony of a
    host-side command is the point.

    THE ORDER IS THE DESIGN. Verification runs before anything else, including
    the safety export, so a wrong passphrase or a damaged file costs nothing but
    the time to find out — not a full dump and an orphaned file on the operator's
    disk. Only then is the safety export taken, and only then is gitea stopped.

    Three things it does NOT restore, printed rather than buried, because each
    one surprises somebody:

      1. The host's own dev ledger — which project works which repo, the
         per-consumer tokens, the mirror stamps — never lived in gitea and is not
         in the archive. After a restore the host still claims forks the
         rolled-back gitea no longer has, and anything provisioned SINCE the
         backup has no token row in the restored instance, so those agents
         silently lose push access until they are re-provisioned. This is the
         severest gap and it is not board-shaped.
      2. Attachments, avatars and LFS objects ARE in the archive and are left
         alone, so rows can point at files this did not bring back.
      3. The decrypted archive and its unpacked tree live in memory for the
         duration, so the whole dump has to fit.
    """
    progress = progress or _NULL_PROGRESS
    src = Path(req.path).expanduser()
    if not src.is_file():
        raise ValidationError(f"no backup file at {src}")
    # ONE budget for the whole verb, spent down across three passes over the
    # artifact rather than handed to each in full. The constant is reasoned as
    # the SUM of those passes, so giving it to each would let the verb run to
    # three times the number it was sized against — the trap dump_instance's own
    # docstring names, at its second site.
    deadline = time.monotonic() + BOARD_IMPORT_TIMEOUT_S

    def _left(step: str, *, floor: int = BOARD_EXPORT_MIN_RUN_S) -> int:
        """What is left of the one budget, refusing if a pass cannot finish.

        The floor differs by pass: a read pass can be re-run, so the export's
        small floor is right for it; the replace cannot be re-run safely once
        started, so it carries its own much larger one.
        """
        remaining = int(deadline - time.monotonic())
        if remaining < floor:
            raise HarnessError(
                f"gitea restore ran out of time before {step}",
                f"the restore's {BOARD_IMPORT_TIMEOUT_S}s budget was spent "
                f"before {step} could start; nothing was replaced and gitea is "
                f"still running")
        return remaining

    # Running: the safety export is a dump of the LIVE instance, and the image
    # has to be read off the container before it is stopped.
    _resume_gitea(require=True)
    # EXCLUSIVE for the whole restore, blocking: an upgrade moving the data at
    # the same moment would copy a half-replaced volume, and a status probe must
    # never make the restore fail. Everything below runs in this process while
    # it holds the lock, so it starts gitea with plain `docker start`s and the
    # wiring pass's own resume finds gitea running (or refuses harmlessly).
    with _gitea_lock(exclusive=True, blocking=True):
        # An interrupted upgrade may have left an unverified release running on
        # a copy that Recover will throw away: a restore into it would be lost.
        try:
            rec = _read_upgrade_record()
        except ValidationError as e:
            raise HarnessError("gitea restore: the upgrade record is damaged", str(e))
        if rec is not None and rec["phase"] != "committed":
            raise HarnessError("gitea restore: an upgrade was interrupted",
                               _gitea_interrupted_msg(rec) + "; nothing was replaced")
        if not container_running(gitea.GITEA_CONTAINER):
            raise HarnessError("gitea restore: Gitea is not running",
                               "Gitea stopped while the restore waited for it; "
                               "nothing was replaced")
        # Read under the lock: an upgrade that finished while this waited has
        # changed both the image and the volume.
        image = _live_gitea_image()
        data_volume = _container_data_volume(gitea.GITEA_CONTAINER)
        if not data_volume:
            raise HarnessError("gitea restore: Gitea's data volume is unknown",
                               "the running Gitea has no named data volume; "
                               "nothing was replaced")

        progress.step("verify", "checking the backup opens")
        try:
            gitea.verify_export(path=src, passphrase=req.passphrase, image=image,
                                timeout=_left("checking the backup"))
        except gitea.GiteaError as e:
            raise HarnessError("gitea restore: the backup did not open", str(e))

        safety = ""
        if req.safety_export:
            progress.step("safety", "backing up what is here now")
            stamp = datetime.datetime.now(
                datetime.timezone.utc).strftime("%Y%m%d-%H%M%S")
            # In a `pre-restore/` subdirectory beside the file being restored, NOT
            # alongside it. The ordinary restore reads the resident backup, so
            # writing next to it would drop full instance dumps — each carrying the
            # server's keys — straight into the directory the page describes as
            # holding exactly one backup. They accumulate (one per restore) and
            # nothing reclaims them, so at minimum they must not make that statement
            # false. Timestamped, so a second attempt cannot overwrite the first
            # attempt's rollback.
            keep = src.parent / "pre-restore"
            try:
                keep.mkdir(parents=True, exist_ok=True)
                keep.chmod(0o700)
            except OSError as e:
                # The mkdir is the half that can genuinely fail — a read-only mount,
                # a directory the operator cannot write — and without this it is a
                # raw traceback on the one destructive command in the lane. Nothing
                # has been touched yet, so this is a clean refusal.
                raise HarnessError(
                    "gitea restore: could not write the safety backup",
                    f"{e} — nothing was changed. Move the backup somewhere "
                    f"writable, or pass --no-safety-export to skip it")
            out = keep / (src.name + f".pre-restore-{stamp}.gpg")
            try:
                gitea.dump_instance(container=gitea.GITEA_CONTAINER,
                                    passphrase=req.passphrase, out_path=out,
                                    image=image, timeout=_left("the safety backup"))
            except gitea.GiteaError as e:
                raise HarnessError("gitea restore: the safety backup failed", str(e))
            safety = str(out)
            # Printed BEFORE the destruction starts, so it is on screen even if
            # everything after this goes wrong.
            print(f"safety backup of the current instance: {safety}")
            print("  (safety backups are kept, one per restore, and are yours to "
                  "remove when you no longer want them)")

        # Resolved BEFORE the stop, deliberately. `_left` raises when the budget is
        # spent, and raising AFTER `docker stop` would leave gitea down over a
        # failure that changed nothing — inverting the very invariant the rest of
        # this function is built around.
        replace_budget = _left("the replace", floor=BOARD_REPLACE_MIN_RUN_S)
        # Read before the stop so BOTH the success and the refusal arms can wait for
        # readiness; it is a file read and cannot fail in a way worth branching on.
        host_port_for_restore = load_versions().get(
            "GITEA_HOST_PORT", gitea.DEFAULT_GITEA_HOST_PORT)
        progress.step("stop", "stopping gitea")
        run_check(["docker", "stop", gitea.GITEA_CONTAINER])
        progress.step("replace", "replacing the database and repositories")
        try:
            gitea.restore_instance(volume=data_volume, image=image,
                                   passphrase=req.passphrase, path=src,
                                   timeout=replace_budget)
        except gitea.RestoreRefused as e:
            # A PRE-FLIGHT refusal, and only that: the volume is provably untouched,
            # so the instance that was running a moment ago should be running again
            # rather than left down by a check that changed nothing.
            #
            # It is brought back the SAME way the success path brings it back, not
            # with a bare `docker start`. This arm is the EXPECTED outcome of the
            # case the Backup page warns about — a backup from a gitea that no
            # longer exists — so it is a path operators will actually take, and a
            # stop/start moves gitea's address on every project network. Without the
            # re-wire each dev box keeps the address baked at its own launch and
            # silently loses push until someone runs a host start.
            started = run(["docker", "start", gitea.GITEA_CONTAINER],
                          capture_output=True)
            if started.returncode == 0:
                try:
                    _wait_for_gitea(host_port_for_restore)
                    wire_gitea_to_projects()
                except SystemExit:
                    # Readiness or wiring failed on top of the refusal. Say both
                    # things rather than replacing the refusal with a vaguer error.
                    raise HarnessError(
                        "gitea restore refused, and gitea did not come back",
                        f"{e} — and gitea did not answer after being started again; "
                        f"check it before using the dev lane")
                raise HarnessError("gitea restore refused", str(e))
            raise HarnessError(
                "gitea restore refused, and gitea could not be started again",
                f"{e} — and starting gitea back up failed, so it is currently DOWN"
                f"{_docker_start_cause(started)}")
        except gitea.GiteaError as e:
            # Anything else: the replace may have got part way, or the container
            # doing it may still be running. Starting gitea here would point it at a
            # half-written database, or add a second writer to the same volume.
            # Leave it stopped and say so — being down is recoverable, a corrupted
            # database started and migrated is not.
            raise HarnessError(
                "gitea restore failed part way",
                f"{e} — gitea has been left STOPPED because its data may be "
                f"partly replaced; restore again from a good backup"
                + (f", or from the safety backup at {safety}" if safety else
                   " (no safety backup was taken, because --no-safety-export was "
                   "given)")
                + " before starting it")

        # From here the DATA IS ALREADY RESTORED. Every failure below is about
        # bringing gitea back, not about the restore — and it must say so, because
        # the operator's next decision (restore again? from what?) depends entirely
        # on which of the two it was. This arm carries HIGHER stakes than the refusal
        # arm above, so it cannot be handled more crudely than it: a bare run_check
        # here would die() with "command failed: docker start" and skip the re-wire,
        # never mentioning that the restore itself succeeded.
        progress.step("start", "starting gitea on the restored data")
        started = run(["docker", "start", gitea.GITEA_CONTAINER], capture_output=True)
        if started.returncode != 0:
            raise HarnessError(
                "gitea restored, but it could not be started again",
                f"the restore COMPLETED and your data is in place — but starting "
                f"gitea failed, so it is currently DOWN"
                f"{_docker_start_cause(started)}. Start it and the dev boxes "
                f"will pick up its address on the next host start.")
        try:
            # The COLD-BOOT budget, explicitly not the resume budget that
            # wire_gitea_to_projects would use on its own. Gitea coming up on a
            # restored database re-applies migrations and rebuilds the search index
            # this restore deliberately deleted, which is minutes of work on a large
            # instance — GITEA_RESUME_WAIT_TRIES is documented as sized for a WARM
            # restart and would time out, and its caller SWALLOWS that timeout and
            # wires from recorded rows. That would let this verb report success
            # against an instance that is not answering.
            _wait_for_gitea(host_port_for_restore)
        except SystemExit:
            raise HarnessError(
                "gitea restored, but it did not come back up",
                f"the restore COMPLETED and your data is in place — but gitea did "
                f"not answer in time after being started. It may still be applying "
                f"migrations on the restored database; check it, then run a host "
                f"start so the dev boxes pick up its address.")
        progress.step("wire", "re-attaching gitea to the projects")
        wire_gitea_to_projects()
        return DevBoardImportResult(restored_from=str(src), safety_export=safety)


def dev_board_status(_req: "DevBoardStatusRequest",
                     progress=None) -> DevBoardStatusResult:  # type: ignore[name-defined]
    """The resident backup's facts, including the HOST PATH the operator copies
    from. Always returns a path — where a backup WOULD be when none is there —
    so the page can tell them where to look either way.

    A pure stat. It touches no container and no network, so it needs no bound and
    cannot be made to hang; and it is the reason the webui asks rather than
    derives, since a container cannot know the operator's home directory.
    """
    target = BOARD_EXPORT_DIR / BOARD_EXPORT_NAME
    try:
        st = target.stat()
    except OSError:                 # absent dir or file: "no backup yet", not an error
        return DevBoardStatusResult(present=False, path=str(target))
    return DevBoardStatusResult(
        present=True, path=str(target), size=st.st_size,
        created_at=datetime.datetime.fromtimestamp(
            st.st_mtime, datetime.timezone.utc).isoformat(timespec="seconds"))


def dev_board_discard(_req: "DevBoardDiscardRequest",
                      progress=None) -> DevBoardDiscardResult:  # type: ignore[name-defined]
    """Remove the resident browser-export artifact (and any stale `.part`).

    Idempotent by design: discarding when nothing is resident is `removed=0`, not
    an error — the browser offers this beside a file whose existence it read a
    moment ago, and a race with a sibling tab must not surface as a failure.
    Touches ONLY the resident backup and a stale `.part` of it. A CLI export's
    `--out` file is the operator's own, and so are the safety copies a restore
    leaves under `pre-restore/` — neither is ever swept.
    """
    progress = progress or _NULL_PROGRESS
    progress.step("discard", "removing the backup")
    removed = 0
    for p in (BOARD_EXPORT_DIR / BOARD_EXPORT_NAME,
              BOARD_EXPORT_DIR / (BOARD_EXPORT_NAME + ".part")):
        try:
            p.unlink()
            removed += 1
        except FileNotFoundError:
            pass
        except OSError as e:
            raise HarnessError("could not discard the gitea backup", str(e))
    return DevBoardDiscardResult(removed=removed)


def _live_gitea_image() -> str:
    """The image the RUNNING gitea container is actually on, as a sha256 ID.

    Not `load_versions()["GITEA_VERSION"]`: that pin is consumed ONLY when the
    container is CREATED (see _provision_gitea) — an existing container is
    `docker start`ed unchanged and _resume_gitea never re-creates — so after a pin
    bump the pin names a version the live instance is not running, and a helper
    container built from it would touch this instance's data with a different
    gitea. Not `.Config.Image` either: that is the TAG as given at `docker run`,
    which drifts the moment a tag is re-pointed or re-pulled. `{{.Image}}` is the
    content-addressed ID and `docker run` accepts it directly.
    """
    r = run(["docker", "container", "inspect", gitea.GITEA_CONTAINER,
             "-f", "{{.Image}}"], capture_output=True)
    ref = (r.stdout or "").strip()
    if r.returncode != 0 or not ref:
        raise HarnessError("could not resolve the running gitea image",
                           "the gitea container is not inspectable")
    return ref


# ---------------------------------------------------------------------------
# Upgrading the shared gitea in place of its data: the new release runs on a
# COPY, the old container and its volume are kept untouched until the operator
# discards them, and a failure puts the old one back. Gitea migrates its
# database forward on first start and an older release refuses a migrated
# database (measured, 1.25.1 against 28.2.0), so a copy taken before the start
# is the only way back.
# ---------------------------------------------------------------------------

# The kept old container, between a successful upgrade and Discard.
GITEA_PREVIOUS_CONTAINER = "rs-gitea-previous"
# The one-shot helper that copies the data. Named, so a copy cut off by a kill
# can be found and removed — an unnamed one would keep the target volume
# mounted and refuse every later removal of it.
GITEA_COPY_CONTAINER = "rs-gitea-upgrade-copy"
# Label on every data volume an upgrade creates; its value is the release the
# volume was made for. The original `rs-gitea-data` carries none.
GITEA_DATA_LABEL = "research.gitea.data"
# What a data volume an upgrade creates is called, for the release it serves.
_GITEA_UPGRADE_VOLUME_PREFIX = gitea.GITEA_DATA_VOLUME + "-"
# The only volume names Discard will ever remove.
_GITEA_DATA_VOLUME_RE = re.compile(
    re.escape(gitea.GITEA_DATA_VOLUME) + r"(?:-\d+(?:\.\d+)*)?")
# The phases an upgrade passes through, in order, then the one going back
# passes through. Only `committed` means the new release proved itself and is
# current; every other phase means the original data is, and Recover puts the
# old release back on it.
GITEA_UPGRADE_PHASES = ("preparing", "copying", "switching", "starting",
                        "committed", "rolling-back")
# The refusal every Gitea-touching action gives while an upgrade or a restore
# holds the instance. Browser-facing.
GITEA_BUSY_MSG = ("Gitea is being upgraded, put back or restored — try again "
                  "when it finishes")
# Bound on the pre-upgrade backup. Reasoned exactly like BOARD_IMPORT_TIMEOUT_S
# and set to it: the upgrade runs in a detached child with no client clock to
# stay under, so the only cost of a generous bound is a longer wait on a wedged
# docker, while a tight one would refuse a large instance's upgrade outright.
# This is ONE dump-and-verify pass of the three that bound was sized for, so it
# is generous by construction, and expiring only refuses — nothing has been
# stopped yet when the backup runs.
GITEA_UPGRADE_DUMP_TIMEOUT_S = BOARD_IMPORT_TIMEOUT_S
# Readiness of the NEW release on the copied data. GITEA_BOOT_WAIT_TRIES is
# sized for a cold boot of an empty database; this start also migrates every
# table forward, which scales with the instance (measured: a small instance
# went from 1.25.1 to 28.2.0 in about four seconds). The two ways to be wrong
# are lopsided. Too short rolls back an upgrade that would have succeeded — safe,
# but the operator pays for the backup and the copy again and may never get
# through on a big instance. Too long only keeps the operator watching a wedged
# start for longer, in a tail that names the step. So it is ten cold-boot
# budgets, about ten minutes.
GITEA_UPGRADE_READY_TRIES = GITEA_BOOT_WAIT_TRIES * 10


GITEA_INTERRUPTED_MSG = ("an earlier Gitea upgrade was interrupted — use Recover "
                         "in Sandboxes → Infrastructure first")


def _gitea_interrupted_msg(rec: dict) -> str:
    """The browser-facing text for an uncommitted record: an upgrade cut off,
    or going back cut off."""
    if rec.get("phase") == "rolling-back":
        return (f"going back to Gitea {rec['from_version']} was interrupted — "
                f"use Recover in Sandboxes → Infrastructure first")
    return GITEA_INTERRUPTED_MSG


def _gitea_held_reason() -> str | None:
    """Why gitea is not available for ordinary work because of an upgrade or a
    restore, or None. Browser-facing text; pure reads."""
    if gitea_upgrading():
        return GITEA_BUSY_MSG
    try:
        rec = _read_upgrade_record()
    except ValidationError as e:
        return str(e)
    if rec is not None and rec["phase"] != "committed":
        return _gitea_interrupted_msg(rec)
    return None


def _gitea_lock_path() -> Path:
    # Derived at CALL time, not import: archived pins redirect gitea.DEV_DIR.
    return gitea.DEV_DIR / "gitea.lock"


def _gitea_upgrade_record_path() -> Path:
    return gitea.DEV_DIR / "gitea-upgrade.json"


class _GiteaLockBusy(Exception):
    """A non-blocking acquisition of the gitea lock found it held."""


@contextlib.contextmanager
def _gitea_lock(*, exclusive: bool, blocking: bool):
    """Hold the gitea lock. EXCLUSIVE is taken by the actions that replace or
    move gitea's data (an upgrade, a restore, Discard, the recovery of an
    interrupted upgrade); SHARED by the arms that start a stopped gitea, so a
    start can never land on data that is being copied or replaced. flock, so
    the kernel releases it when its holder dies — there is no stale state to
    recover. Opened without truncation: the file carries no content."""
    # An OS failure here becomes a die(): every caller is a verb, and a raw
    # OSError would escape the broker's dispatch as a truncated reply.
    try:
        if not gitea.DEV_DIR.is_dir():
            gitea.DEV_DIR.mkdir(parents=True, exist_ok=True)
        fd = os.open(_gitea_lock_path(), os.O_RDWR | os.O_CREAT, 0o600)
    except OSError as e:
        die(f"the Gitea lock could not be opened ({e.strerror or 'I/O error'})")
    try:
        op = fcntl.LOCK_EX if exclusive else fcntl.LOCK_SH
        if not blocking:
            op |= fcntl.LOCK_NB
        try:
            fcntl.flock(fd, op)
        except BlockingIOError:
            raise _GiteaLockBusy()
        yield
    finally:
        os.close(fd)


def gitea_upgrading() -> bool:
    """True while an upgrade or a restore holds gitea. A probe: a non-blocking
    SHARED attempt released at once, so it never blocks and never conflicts with
    another start. A missing lock file means nothing ever held it — and the probe
    creates none, so a host that never enabled gitea stays file-free."""
    try:
        fd = os.open(_gitea_lock_path(), os.O_RDONLY)
    except OSError:
        return False
    try:
        fcntl.flock(fd, fcntl.LOCK_SH | fcntl.LOCK_NB)
        return False
    except BlockingIOError:
        return True
    finally:
        os.close(fd)


def _read_upgrade_record() -> dict | None:
    """The upgrade record, or None when no upgrade is in progress or kept.

    A record that exists but cannot be read is NOT treated as absent: it is
    the one thing that says which volume holds the data, and guessing could
    point a start at the wrong one. It raises, and every caller refuses."""
    path = _gitea_upgrade_record_path()
    try:
        raw = path.read_text()
    except FileNotFoundError:
        return None
    except OSError as e:
        raise ValidationError(f"the Gitea upgrade record cannot be read ({e.strerror})")
    try:
        rec = json.loads(raw)
    except ValueError:
        rec = None
    keys = ("from_version", "to_version", "from_volume", "to_volume", "phase")
    if (not isinstance(rec, dict)
            or not all(isinstance(rec.get(k), str) for k in keys)
            or rec["phase"] not in GITEA_UPGRADE_PHASES):
        raise ValidationError("the Gitea upgrade record is damaged, so it is "
                              "not safe to tell which copy of Gitea's data is "
                              "the live one")
    return rec


def _write_upgrade_record(rec: dict) -> None:
    """Atomically replace the record (a fixed temp name, then rename)."""
    path = _gitea_upgrade_record_path()
    tmp = path.with_name(path.name + ".tmp")
    gitea.DEV_DIR.mkdir(parents=True, exist_ok=True)
    tmp.write_text(json.dumps(rec, indent=2) + "\n")
    os.chmod(tmp, 0o600)
    tmp.replace(path)


def _set_upgrade_phase(rec: dict, phase: str) -> None:
    rec["phase"] = phase
    _write_upgrade_record(rec)


def _clear_upgrade_record() -> None:
    with contextlib.suppress(FileNotFoundError):
        _gitea_upgrade_record_path().unlink()


def _container_data_volume(name: str) -> str | None:
    """The named volume a container mounts at /data, or None (no container, or
    /data is not a named volume)."""
    r = run(["docker", "container", "inspect", name, "-f",
             '{{range .Mounts}}{{if and (eq .Destination "/data") '
             '(eq .Type "volume")}}{{.Name}}{{end}}{{end}}'],
            capture_output=True)
    vol = (r.stdout or "").strip()
    return vol if r.returncode == 0 and vol else None


def _volume_in_use(volume: str) -> bool:
    """Whether any container, running or not, mounts the volume."""
    r = run(["docker", "ps", "-a", "-q", "--filter", f"volume={volume}"],
            capture_output=True)
    return r.returncode != 0 or bool((r.stdout or "").strip())


def _gitea_data_volume_candidates() -> list[str]:
    """Every volume that could hold gitea's data when no record says which:
    the original name plus every volume an upgrade created."""
    out = []
    if volume_exists(gitea.GITEA_DATA_VOLUME):
        out.append(gitea.GITEA_DATA_VOLUME)
    r = run(["docker", "volume", "ls", "-q", "--filter",
             f"label={GITEA_DATA_LABEL}"], capture_output=True)
    for v in (r.stdout or "").split():
        if v not in out:
            out.append(v)
    return out


def _gitea_data_volume() -> str:
    """Which volume holds gitea's data.

    The live container's mount when there is one. Without a container, the
    upgrade record decides: the new copy once the upgrade committed, the
    original before that. Without a record, the one existing candidate, or the
    first-enable name when there is none. More than one candidate and no record
    to choose between them refuses rather than guess — starting gitea on the
    wrong copy would quietly lose everything written since."""
    live = _container_data_volume(gitea.GITEA_CONTAINER)
    if live:
        return live
    rec = _read_upgrade_record()
    if rec is not None:
        return rec["to_volume"] if rec["phase"] == "committed" else rec["from_volume"]
    found = _gitea_data_volume_candidates()
    if len(found) > 1:
        raise ValidationError(
            "more than one copy of Gitea's data exists ("
            + ", ".join(found) + ") and nothing records which one is current, "
            "so Gitea was not started on either")
    return found[0] if found else gitea.GITEA_DATA_VOLUME


def _running_gitea_version(container: str = gitea.GITEA_CONTAINER) -> str:
    """The release a gitea container runs: its label, else its image tag. ""
    when neither reads as a version — the upgrade refuses on that rather than
    compare against something it cannot parse."""
    r = run(["docker", "container", "inspect", container, "-f",
             '{{index .Config.Labels "' + GITEA_VERSION_LABEL + '"}}|'
             '{{.Config.Image}}'], capture_output=True)
    if r.returncode != 0:
        return ""
    label, _, image = (r.stdout or "").strip().partition("|")
    for cand in (label, image.rpartition(":")[2] if ":" in image else ""):
        if cand and _GITEA_VERSION_RE.fullmatch(cand):
            return cand
    return ""


def gitea_version_info() -> dict:
    """What the Infrastructure row shows: the running release, the shipped one,
    any upgrade in progress or kept, and whether one holds gitea right now.
    Pure reads — docker inspects and host files — so a page load can call it."""
    exists = container_exists(gitea.GITEA_CONTAINER)
    try:
        target = _gitea_pinned_version(load_versions())
    except SystemExit:
        target = ""
    upgrade = None
    try:
        rec = _read_upgrade_record()
    except ValidationError:
        rec = {"phase": "damaged", "from_version": "", "to_version": ""}
    if rec is not None:
        upgrade = {"phase": rec["phase"], "from_version": rec["from_version"],
                   "to_version": rec["to_version"],
                   "backup": rec.get("backup") or ""}
    return {
        "version": _running_gitea_version() if exists else "",
        "target": target,
        "upgrade": upgrade,
        "upgrading": gitea_upgrading(),
    }


def _gitea_upgrade_backup_path(to_version: str) -> Path:
    # One file per kept upgrade, at a name derived from the release it went to;
    # a second upgrade cannot start while one is kept, so these never pile up.
    return (BOARD_EXPORT_DIR / "pre-upgrade"
            / f"{Path(BOARD_EXPORT_NAME).stem}-before-{to_version}.gpg")


def gitea_upgrade_refusal() -> str | None:
    """Why an upgrade cannot start right now, or None. Cheap reads only (docker
    inspects and host files), so the broker can ask before it spawns anything;
    the upgrade asks again once it holds the lock. Every text is browser-facing."""
    try:
        rec = _read_upgrade_record()
    except ValidationError as e:
        return str(e)
    if rec is not None and rec["phase"] != "committed":
        return _gitea_interrupted_msg(rec)
    if not container_exists(gitea.GITEA_CONTAINER):
        return "Gitea isn't enabled — enable it in Sandboxes → Infrastructure first"
    if rec is not None:
        return (f"the previous version ({rec['from_version']}) is still kept "
                f"— discard it first")
    if container_exists(GITEA_PREVIOUS_CONTAINER):
        return ("a previous Gitea container is still kept, but nothing records "
                "which upgrade it belongs to, so a second upgrade would not know "
                "what to keep")
    running = _running_gitea_version()
    if not running:
        return "the running Gitea's version cannot be read, so it cannot be compared"
    try:
        target = _gitea_pinned_version(load_versions())
    except SystemExit:
        return "the shipped Gitea version is not a version number"
    if not _version_older(running, target):
        return f"Gitea {running} is already up to date (this software ships {target})"
    if volume_exists(_GITEA_UPGRADE_VOLUME_PREFIX + target) \
            and not _reclaimable_upgrade_volume(target):
        return (f"a data volume for {target} already exists and is not a "
                f"leftover of an earlier attempt, so the upgrade would not "
                f"have a fresh place to copy to")
    return None


def _reclaimable_upgrade_volume(target: str) -> bool:
    """Whether an existing `rs-gitea-data-<target>` is the leftover of an
    upgrade attempt that was rolled back: labelled by an upgrade for exactly
    this release, mounted by no container, and named by no record (a committed
    upgrade's copy always has one). Anything else is refused, never removed."""
    name = _GITEA_UPGRADE_VOLUME_PREFIX + target
    r = run(["docker", "volume", "ls", "-q", "--filter",
             f"label={GITEA_DATA_LABEL}={target}"], capture_output=True)
    if r.returncode != 0 or name not in (r.stdout or "").split():
        return False
    try:
        if _read_upgrade_record() is not None:
            return False
    except ValidationError:
        return False
    return not _volume_in_use(name)


def _measure_kib(image: str, volume: str, script: str) -> int | None:
    """Run a one-line measurement in a throwaway container with the volume
    mounted read-only at /from; the script prints one integer (KiB)."""
    r = run(["docker", "run", "--rm", "--entrypoint", "sh",
             "-v", f"{volume}:/from:ro", image, "-c", script],
            capture_output=True)
    out = (r.stdout or "").strip()
    return int(out) if r.returncode == 0 and out.isdigit() else None


def _start_gitea_unlocked(host_port: str, *, tries: int | None = None) -> None:
    """Start the gitea container and wait until it answers, taking no lock —
    for callers that already hold it EXCLUSIVE (a second open of the lock in
    the same process would refuse itself)."""
    if not container_running(gitea.GITEA_CONTAINER):
        run_check(["docker", "start", gitea.GITEA_CONTAINER])
    _wait_for_gitea(host_port, tries=tries)


def _wait_for_gitea_version(host_port: str, want: str, *, tries: int) -> None:
    """Wait until gitea answers its version endpoint WITH THE ADMIN TOKEN and
    reports ``want``. One call proves three things: the new release is serving,
    it is the release asked for, and the stored token still authenticates
    against the migrated database. die()s when the tries run out."""
    url = f"http://127.0.0.1:{host_port}/api/v1/version"
    token = gitea.read_admin_token()
    seen = ""
    for _ in range(tries):
        # A release that exited (or that docker is restarting after a crash)
        # will not answer however long this waits; stop at once so the
        # rollback starts now rather than after the whole budget.
        st = run(["docker", "container", "inspect", gitea.GITEA_CONTAINER, "-f",
                  "{{.State.Running}} {{.State.Restarting}} {{.RestartCount}}"],
                 capture_output=True)
        state = (st.stdout or "").split()
        if st.returncode != 0 or len(state) != 3 or state[0] != "true" \
                or state[1] != "false" or state[2] != "0":
            die(f"gitea {want} exited instead of starting")
        req = urllib.request.Request(url, headers={"Authorization": f"token {token}"})
        try:
            with urllib.request.urlopen(req, timeout=GITEA_PROBE_MAX_TIME_S) as resp:
                seen = str(json.loads(resp.read().decode() or "{}").get("version") or "")
                if seen == want:
                    return
        except (OSError, ValueError):
            pass
        time.sleep(1)
    die(f"gitea did not answer as {want} in time"
        + (f" (it reported {seen})" if seen else ""))


def _restore_previous_gitea(rec: dict, host_port: str, progress) -> bool:
    """Put the release from before an upgrade back on its untouched data, from
    whatever state an upgrade (or going back) left. Every step tolerates the
    state not being there; each is by name. Returns whether the OLD release
    answers on the ORIGINAL data afterwards. Only then does it clear the record
    and remove the new release's volume — otherwise the record is what lets
    Recover finish the job later, and after a successful upgrade that volume
    holds everything written since. Caller holds the lock EXCLUSIVE."""
    progress.step("rollback", f"putting Gitea {rec['from_version']} back")
    old_image = "gitea/gitea:" + rec["from_version"]
    live = _container_data_volume(gitea.GITEA_CONTAINER)
    if not container_exists(GITEA_PREVIOUS_CONTAINER) and (
            not container_exists(gitea.GITEA_CONTAINER) or live == rec["to_volume"]):
        # The kept container is gone and nothing original remains to restart:
        # the old release will be RECREATED below.
        if not volume_exists(rec["from_volume"]):
            # ...unless its untouched data is gone too: nothing to put back,
            # so leave whatever runs alone.
            return False
        # Have its image BEFORE the new container is taken down, so an
        # offline host keeps what it has. (A rollback from before the rename
        # still has the original rs-gitea and never gets here.)
        if not run_quiet(["docker", "image", "inspect", old_image]):
            if run(["docker", "pull", old_image], capture_output=True).returncode != 0:
                return False
    if _container_data_volume(gitea.GITEA_CONTAINER) == rec["to_volume"]:
        run(["docker", "rm", "-f", gitea.GITEA_CONTAINER], capture_output=True)
        if _container_data_volume(gitea.GITEA_CONTAINER) == rec["to_volume"]:
            # The new release could not be removed. Going on would start IT
            # below and take its answer for the old release's.
            return False
    run(["docker", "rm", "-f", GITEA_COPY_CONTAINER], capture_output=True)
    if container_exists(GITEA_PREVIOUS_CONTAINER):
        if container_exists(gitea.GITEA_CONTAINER):
            # Something else holds the name — never remove a container this
            # code did not make. Leave both; the caller reports Gitea down.
            return False
        run(["docker", "rename", GITEA_PREVIOUS_CONTAINER, gitea.GITEA_CONTAINER],
            capture_output=True)
    elif not container_exists(gitea.GITEA_CONTAINER):
        # The kept container was removed by hand, but the original volume is
        # never written by an upgrade, so the old release can be recreated on
        # it exactly as it ran — its own version, never the shipped pin (which
        # would migrate the only untouched copy forward).
        try:
            _run_gitea_container(old_image, rec["from_volume"],
                                 rec["from_version"], host_port)
        except SystemExit:
            return False
    if not container_exists(gitea.GITEA_CONTAINER):
        return False
    run(["docker", "update", f"--restart={GITEA_RESTART_POLICY}",
         gitea.GITEA_CONTAINER], capture_output=True)
    healthy = True
    try:
        _start_gitea_unlocked(host_port)
    except SystemExit:
        healthy = False
    # Answering is not enough: it must be the old release on the original data
    # that answers, or the record and the new volume are still needed.
    if healthy and (_container_data_volume(gitea.GITEA_CONTAINER) != rec["from_volume"]
                    or _running_gitea_version() != rec["from_version"]):
        healthy = False
    if healthy:
        if (volume_exists(rec["to_volume"]) and not _volume_in_use(rec["to_volume"])
                and rec["to_volume"] != rec["from_volume"]):
            run(["docker", "volume", "rm", rec["to_volume"]], capture_output=True)
        if volume_exists(rec["to_volume"]):
            print(f"warning: {rec['to_volume']} could not be removed; the next "
                  f"upgrade to {rec['to_version']} reclaims it", file=sys.stderr)
        # Cleared even when the copy could not be removed: Gitea is back on its
        # original data, and a leftover copy is reclaimed by the next upgrade
        # (_reclaimable_upgrade_volume), so it cannot block a retry.
        with contextlib.suppress(OSError):
            _clear_upgrade_record()
        progress.step("restored", f"Gitea {rec['from_version']} is back")
    return healthy


def _wire_after_gitea_moved(progress=None) -> None:
    """Reconnect every project to a gitea that was just recreated or renamed
    (its address on each project network may have changed). Best-effort: the
    data question is already settled by the time this runs. `progress` carries
    a box's old-instructions warning to the browser."""
    try:
        wire_gitea_to_projects(progress)
    except SystemExit:
        print("warning: reconnecting the projects to Gitea did not finish; "
              "a host start reconnects them", file=sys.stderr)


def dev_gitea_upgrade(req: "DevGiteaUpgradeRequest", progress=None) -> DevGiteaUpgradeResult:  # type: ignore[name-defined]
    """Upgrade the shared gitea to the shipped release, keeping the old one.

    Order, and why it is the design: everything that can fail without changing
    anything runs first (the checks, the image pull, the space checks, the
    backup), so those failures are plain refusals. Only then is gitea stopped.
    From that point an upgrade record names the phase, and any failure before
    the new release proves itself puts the old release back on its untouched
    volume. The new release runs on a COPY; the old container and volume stay
    as `rs-gitea-previous` until Discard."""
    progress = progress or _NULL_PROGRESS
    host_port = _gitea_host_port()
    progress.step("wait", "waiting for other Gitea work to finish")
    rollback_outcome = None
    with _gitea_lock(exclusive=True, blocking=True):
        refusal = gitea_upgrade_refusal()
        if refusal:
            raise ValidationError(refusal)
        progress.step("gitea", "making sure Gitea is running")
        try:
            _start_gitea_unlocked(host_port)
        except SystemExit:
            raise HarnessError("Gitea is not answering, so it was not upgraded; "
                               "nothing was changed")
        old_image = _live_gitea_image()
        from_version = _running_gitea_version()
        from_volume = _container_data_volume(gitea.GITEA_CONTAINER)
        if not from_volume:
            raise ValidationError("Gitea's data is not on a named volume, so it "
                                  "cannot be copied")
        to_version = _gitea_pinned_version(load_versions())
        to_volume = _GITEA_UPGRADE_VOLUME_PREFIX + to_version
        new_image = "gitea/gitea:" + to_version

        progress.step("pull", f"fetching Gitea {to_version}")
        if not run_quiet(["docker", "image", "inspect", new_image]):
            r = run(["docker", "pull", new_image], capture_output=True)
            if r.returncode != 0:
                raise HarnessError(f"Gitea {to_version} could not be downloaded; "
                                   f"nothing was changed")

        progress.step("space", "checking there is room for a copy")
        need = _measure_kib(old_image, from_volume, "du -sk /from | cut -f1")
        docker_free = _measure_kib(old_image, from_volume,
                                   "df -Pk /from | tail -1 | awk '{print $4}'")
        if need is None or docker_free is None:
            raise HarnessError("the size of Gitea's data could not be measured; "
                               "nothing was changed")
        if docker_free < need:
            raise HarnessError("there is not enough free disk space for a copy "
                               "of Gitea's data; nothing was changed")
        backup = _gitea_upgrade_backup_path(to_version)
        probe_dir = backup.parent
        while not probe_dir.exists() and probe_dir != probe_dir.parent:
            probe_dir = probe_dir.parent
        if shutil.disk_usage(probe_dir).free < need * 1024:
            raise HarnessError("there is not enough free disk space for the "
                               "pre-upgrade backup; nothing was changed")

        progress.step("backup", "backing up the instance before upgrading")
        try:
            backup.parent.mkdir(parents=True, exist_ok=True)
            backup.parent.chmod(0o700)
        except OSError:
            raise HarnessError("the pre-upgrade backup could not be written; "
                               "nothing was changed")
        try:
            gitea.dump_instance(container=gitea.GITEA_CONTAINER,
                                passphrase=req.passphrase, out_path=backup,
                                image=old_image,
                                timeout=GITEA_UPGRADE_DUMP_TIMEOUT_S)
        except gitea.GiteaError:
            raise HarnessError("the pre-upgrade backup failed; nothing was "
                               "changed — try again")

        if volume_exists(to_volume):
            # gitea_upgrade_refusal (re-run under the lock above) only lets this
            # through for a leftover of a rolled-back attempt.
            progress.step("reclaim", "removing the copy a failed attempt left")
            r = run(["docker", "volume", "rm", to_volume], capture_output=True)
            if r.returncode != 0:
                raise HarnessError("a copy left by an earlier attempt could not "
                                   "be removed; nothing was changed")
        rec = {"from_version": from_version, "to_version": to_version,
               "from_volume": from_volume, "to_volume": to_volume,
               "backup": str(backup), "phase": "preparing"}
        try:
            _write_upgrade_record(rec)
        except OSError:
            raise HarnessError("the upgrade record could not be written; "
                               "nothing was changed")
        try:
            progress.step("stop", f"stopping Gitea {from_version}")
            run_check(["docker", "stop", gitea.GITEA_CONTAINER])
            _set_upgrade_phase(rec, "copying")
            progress.step("copy", "copying Gitea's data")
            run_check(["docker", "volume", "create", "--label",
                       f"{GITEA_DATA_LABEL}={to_version}", to_volume])
            run(["docker", "rm", "-f", GITEA_COPY_CONTAINER], capture_output=True)
            # As root: the volume holds files owned by root (the ssh host keys)
            # and by git, and `cp -a` keeps both only when root copies.
            run_check(["docker", "run", "--rm", "--name", GITEA_COPY_CONTAINER,
                       "--entrypoint", "sh",
                       "-v", f"{from_volume}:/from:ro", "-v", f"{to_volume}:/to",
                       old_image, "-c", "cp -a /from/. /to/"])
            # The two settings 28.x deprecated stay in the copied app.ini
            # otherwise: the image only adds and updates entries from the
            # environment, never removes them. Section-scoped, because
            # ALLOWED_HOST_LIST is also the NEW key's name in two other
            # sections. As the file's owner (uid 1000), so the rewritten file
            # stays gitea's.
            run_check(["docker", "run", "--rm", "--entrypoint", "sh",
                       "--user", "1000:1000", "-v", f"{to_volume}:/to",
                       old_image, "-c",
                       "sed -i "
                       "-e '/^\\[migrations\\]/,/^\\[/{/^ALLOWED_DOMAINS[[:space:]]*=/d}' "
                       "-e '/^\\[webhook\\]/,/^\\[/{/^ALLOWED_HOST_LIST[[:space:]]*=/d}' "
                       "/to/gitea/conf/app.ini"])
            progress.step("switch", f"keeping Gitea {from_version} aside")
            run_check(["docker", "rename", gitea.GITEA_CONTAINER,
                       GITEA_PREVIOUS_CONTAINER])
            _set_upgrade_phase(rec, "switching")
            run_check(["docker", "update", "--restart=no", GITEA_PREVIOUS_CONTAINER])
            progress.step("start", f"starting Gitea {to_version} on the copy")
            _run_gitea_container(new_image, to_volume, to_version, host_port)
            _set_upgrade_phase(rec, "starting")
            progress.step("ready", f"waiting for Gitea {to_version} to finish "
                                   f"migrating")
            _wait_for_gitea_version(host_port, to_version,
                                    tries=GITEA_UPGRADE_READY_TRIES)
            _set_upgrade_phase(rec, "committed")
        except (SystemExit, HarnessError, ValidationError, Exception) as e:
            # SystemExit is a BaseException: named explicitly or it escapes.
            print(f"upgrade failed after gitea was stopped: {e!r}", file=sys.stderr)
            rollback_outcome = _restore_previous_gitea(rec, host_port, progress)
    progress.step("wire", "reconnecting the projects to Gitea")
    _wire_after_gitea_moved(progress)
    if rollback_outcome is True:
        raise HarnessError(f"Gitea {to_version} did not start; {from_version} is "
                           f"back on its untouched data")
    if rollback_outcome is False:
        # The put-back can also stop short with the new release still in
        # place (it could not be removed), so say what actually runs.
        new_up = (container_running(gitea.GITEA_CONTAINER)
                  and _container_data_volume(gitea.GITEA_CONTAINER) == to_volume)
        state = (f"{to_version} is still running unverified" if new_up
                 else "Gitea is down")
        raise HarnessError(f"Gitea {to_version} did not start, and {from_version} "
                           f"could not be started again — {state}; use "
                           f"Recover in Sandboxes → Infrastructure")
    return DevGiteaUpgradeResult(from_version=from_version, to_version=to_version,
                                 backup=str(backup))


def _recover_interrupted_upgrade(rec: dict, progress) -> None:
    """Enable's recovery arm: an upgrade record that never reached `committed`
    and nothing holding the lock means the upgrade was cut off. Put the old
    release back exactly as the upgrade's own rollback would have."""
    host_port = _gitea_host_port()
    going_back = rec["phase"] == "rolling-back"
    if (not container_exists(GITEA_PREVIOUS_CONTAINER)
            and not volume_exists(rec["from_volume"])):
        what = ("going back cannot be finished" if going_back
                else "the interrupted upgrade cannot be undone")
        die(f"Gitea {rec['from_version']}'s data is missing, so {what}; "
            f"nothing was changed")
    try:
        with _gitea_lock(exclusive=True, blocking=False):
            ok = _restore_previous_gitea(rec, host_port, progress)
            if ok and going_back:
                _remove_pre_upgrade_backup(rec)
    except _GiteaLockBusy:
        die(GITEA_BUSY_MSG)
    _wire_after_gitea_moved(progress)
    if not ok:
        die(f"Gitea {rec['from_version']} could not be put back"
            + ("" if container_running(gitea.GITEA_CONTAINER) else "; it is down"))


def dev_gitea_discard_previous(_req: "DevGiteaDiscardPreviousRequest",
                               progress=None) -> DevGiteaDiscardPreviousResult:  # type: ignore[name-defined]
    """Remove the release kept after a successful upgrade: its container, its
    data volume, the backup taken just before the upgrade, and the record.
    This deletes the only way back, so it checks that it is removing exactly
    what the record says was kept and never the live data.

    Retryable: each piece already gone counts as removed, so a Discard cut off
    part way (or a kept container removed by hand) is finished by pressing it
    again rather than leaving a record nothing can clear."""
    progress = progress or _NULL_PROGRESS
    try:
        with _gitea_lock(exclusive=True, blocking=False):
            rec = _read_upgrade_record()
            if rec is None or rec["phase"] != "committed":
                raise ValidationError("there is no previous Gitea version kept")
            if not container_running(gitea.GITEA_CONTAINER):
                raise ValidationError("Gitea is not running, so the kept "
                                      "previous version is not discarded — "
                                      "it may still be needed")
            live = _container_data_volume(gitea.GITEA_CONTAINER)
            old = rec["from_volume"]
            if (not old or old == live or old == rec["to_volume"]
                    or not _GITEA_DATA_VOLUME_RE.fullmatch(old)):
                raise ValidationError("the upgrade record does not name a kept "
                                      "copy that is safe to remove, so nothing "
                                      "was removed")
            if container_exists(GITEA_PREVIOUS_CONTAINER):
                if _container_data_volume(GITEA_PREVIOUS_CONTAINER) != old:
                    raise ValidationError("the kept previous Gitea does not "
                                          "match the upgrade record, so nothing "
                                          "was removed")
                progress.step("container", "removing the previous Gitea container")
                run_check(["docker", "rm", GITEA_PREVIOUS_CONTAINER])
            if volume_exists(old):
                progress.step("volume", "removing the previous Gitea's data")
                run_check(["docker", "volume", "rm", old])
            removed_backup = False
            backup = rec.get("backup") or ""
            try:
                if backup and Path(backup) == _gitea_upgrade_backup_path(rec["to_version"]):
                    try:
                        Path(backup).unlink()
                        removed_backup = True
                    except FileNotFoundError:
                        pass
                _clear_upgrade_record()
            except OSError as e:
                raise HarnessError("discarding the previous Gitea did not finish",
                                   f"the previous container and its data are "
                                   f"removed, but a file could not be "
                                   f"({e.strerror or 'I/O error'}); press "
                                   f"Discard again")
    except _GiteaLockBusy:
        raise ValidationError(GITEA_BUSY_MSG)
    return DevGiteaDiscardPreviousResult(version=rec["from_version"],
                                         backup_removed=removed_backup)


def _remove_pre_upgrade_backup(rec: dict) -> bool:
    """Delete the backup taken just before the upgrade, at its derived path
    only. Going back makes it a copy of the data that is live again, and with
    the record cleared nothing would ever show or remove it. Best-effort: Gitea
    is already back when this runs."""
    backup = rec.get("backup") or ""
    if not backup or Path(backup) != _gitea_upgrade_backup_path(rec["to_version"]):
        return False
    try:
        Path(backup).unlink()
        return True
    except FileNotFoundError:
        return False
    except OSError as e:
        print(f"warning: the pre-upgrade backup could not be removed "
              f"({e.strerror or 'I/O error'})", file=sys.stderr)
        return False


def gitea_rollback_refusal() -> str | None:
    """Why going back to the release kept after an upgrade cannot start, or
    None. Going back deletes the volume the record names as the new data and
    runs an image tag built from it, so every part of the record it acts on is
    checked against what an upgrade itself creates. Cheap reads only, so the
    broker can ask before it spawns anything; going back asks again under the
    lock. Every text is browser-facing."""
    try:
        rec = _read_upgrade_record()
    except ValidationError as e:
        return str(e)
    if rec is None:
        return "there is no previous Gitea version kept"
    if rec["phase"] != "committed":
        return _gitea_interrupted_msg(rec)
    frm, to = rec["from_version"], rec["to_version"]
    old, new = rec["from_volume"], rec["to_volume"]
    unsafe = ("the upgrade record does not name copies of Gitea's data that are "
              "safe to switch between, so nothing was changed")
    if not (_GITEA_VERSION_RE.fullmatch(frm) and _GITEA_VERSION_RE.fullmatch(to)):
        return unsafe
    if (new != _GITEA_UPGRADE_VOLUME_PREFIX + to or new == old
            or new == gitea.GITEA_DATA_VOLUME
            or not _GITEA_DATA_VOLUME_RE.fullmatch(new)
            or not _GITEA_DATA_VOLUME_RE.fullmatch(old)):
        return unsafe
    r = run(["docker", "volume", "ls", "-q", "--filter",
             f"label={GITEA_DATA_LABEL}={to}"], capture_output=True)
    if r.returncode != 0 or new not in (r.stdout or "").split():
        return unsafe
    if not container_exists(gitea.GITEA_CONTAINER):
        return "Gitea isn't enabled — enable it in Sandboxes → Infrastructure first"
    if _container_data_volume(gitea.GITEA_CONTAINER) != new:
        return (f"the Gitea container is not the {to} the upgrade started, so "
                f"it is not replaced; nothing was changed")
    if container_exists(GITEA_PREVIOUS_CONTAINER):
        # Its release too: a different one started on the untouched copy
        # would migrate it before the put-back could notice.
        if (_container_data_volume(GITEA_PREVIOUS_CONTAINER) != old
                or _running_gitea_version(GITEA_PREVIOUS_CONTAINER) != frm):
            return ("the kept previous Gitea does not match the upgrade record, "
                    "so nothing was changed")
    elif not volume_exists(old):
        return f"Gitea {frm}'s data is gone, so there is nothing to go back to"
    return None


def dev_gitea_rollback(_req: "DevGiteaRollbackRequest",
                       progress=None) -> DevGiteaRollbackResult:  # type: ignore[name-defined]
    """Go back from a successful upgrade to the release kept beside it: the old
    release returns on its data exactly as it was at the moment of the upgrade,
    and everything written to the new release since is deleted with its volume.

    It never asks the new release for anything, so it works whether that one
    runs, is stopped or keeps crashing. The work is the put-back routine an
    upgrade's own failure path uses. The record goes to `rolling-back` first,
    so a go-back cut off part way is held and finished by Recover exactly like
    a cut-off upgrade."""
    progress = progress or _NULL_PROGRESS
    host_port = _gitea_host_port()
    progress.step("wait", "waiting for other Gitea work to finish")
    with _gitea_lock(exclusive=True, blocking=True):
        refusal = gitea_rollback_refusal()
        if refusal:
            raise ValidationError(refusal)
        rec = _read_upgrade_record()
        frm, to = rec["from_version"], rec["to_version"]
        if not container_exists(GITEA_PREVIOUS_CONTAINER):
            # The old release will be recreated from its image: have it before
            # anything stops, so an offline host refuses instead of ending with
            # Gitea down.
            progress.step("pull", f"making sure Gitea {frm} is available")
            image = "gitea/gitea:" + frm
            if not run_quiet(["docker", "image", "inspect", image]):
                if run(["docker", "pull", image], capture_output=True).returncode != 0:
                    raise HarnessError(f"Gitea {frm} could not be downloaded; "
                                       f"nothing was changed")
        was_running = container_running(gitea.GITEA_CONTAINER)
        try:
            _set_upgrade_phase(rec, "rolling-back")
        except OSError:
            raise HarnessError("the upgrade record could not be written; "
                               "nothing was changed")
        if _restore_previous_gitea(rec, host_port, progress):
            outcome = "back"
            _remove_pre_upgrade_backup(rec)
        elif _container_data_volume(gitea.GITEA_CONTAINER) == rec["to_volume"]:
            # The new release is still in place, so nothing moved: undo the
            # phase. A forced removal that failed part way can have stopped it.
            outcome = "untouched"
            if was_running and not container_running(gitea.GITEA_CONTAINER):
                with contextlib.suppress(SystemExit):
                    _start_gitea_unlocked(host_port)
            try:
                _set_upgrade_phase(rec, "committed")
            except OSError:
                outcome = "changed"
        else:
            outcome = "changed"
        running = container_running(gitea.GITEA_CONTAINER)
    progress.step("wire", "reconnecting the projects to Gitea")
    _wire_after_gitea_moved(progress)
    if outcome == "untouched":
        if running:
            raise HarnessError(f"Gitea {frm} could not be put back; nothing was "
                               f"changed and {to} is still running")
        if was_running:
            raise HarnessError(f"Gitea {frm} could not be put back, and {to} "
                               f"stopped — use Enable in Sandboxes → "
                               f"Infrastructure to start it again")
        raise HarnessError(f"Gitea {frm} could not be put back; nothing was "
                           f"changed ({to} is stopped)")
    if outcome == "changed":
        keep = f"the data written on {to} is kept"
        if running:
            raise HarnessError(f"Gitea {frm} is not back ({keep}) — use "
                               f"Recover in Sandboxes → Infrastructure")
        raise HarnessError(f"Gitea {frm} could not be started — Gitea is down "
                           f"({keep}); use Recover in Sandboxes → Infrastructure")
    return DevGiteaRollbackResult(version=frm, left_version=to)


def dev_passwd(req: "DevPasswdRequest", progress=None) -> DevPasswdResult:  # type: ignore[name-defined]
    """Set the sandbox-admin gitea password (the Sandboxes → Infrastructure
    dialog + `research dev passwd`). Requires an ENABLED gitea — resumes a
    stopped one, never creates (the not-enabled die() carries the enable remedy
    and no secret). The password rides `docker exec` argv into our own gitea
    container — the bootstrap_accounts precedent. Failure raises HarnessError
    (split sinks), never die(): die-text tees to the durable full log, and
    gitea's stderr could echo argv."""
    progress = progress or _NULL_PROGRESS
    _resume_gitea(require=True)
    progress.step("set", "setting the gitea password")
    # --must-change-password=false matches both bootstrap `user create` calls:
    # without it a (version-dependent) forced change at next sign-in defeats
    # the web-UI login this verb exists to enable.
    r = run(["docker", "exec", "-u", "git", gitea.GITEA_CONTAINER,
             "gitea", "admin", "user", "change-password",
             "--username", gitea.ADMIN_USER, "--password", req.password,
             "--must-change-password=false"], capture_output=True)
    if r.returncode != 0:
        # Scrub the password literal from the FULL output BEFORE slicing — a
        # slice-first could truncate the literal at the boundary and the
        # replace would miss the fragment.
        detail = ((r.stderr or "") + (r.stdout or "")).replace(
            req.password, "***").strip()
        raise HarnessError("gitea change-password failed",
                           detail[-200:] if detail else "")
    return DevPasswdResult(user=gitea.ADMIN_USER)


def dev_box_provision(req: "DevBoxProvisionRequest", progress=None) -> dict:  # type: ignore[name-defined]
    """Webui dev-box provision: mirror + box-create as ONE action (the box
    window's dev preset takes a GitHub URL + optional per-repo PAT). A
    COMPOSITION of the shipped verbs so every gate and secret discipline is
    reused, not re-derived: dev_repo_add (mirror-only now; resumes gitea
    require=True — the deliberate-create model; resumable migrate) → box_add
    (preset "dev" — wires gitea and mints the BOX's OWN consumer fork/token).
    Per-consumer forks, 4c-a: the old dev_attach leg is GONE, so no phantom
    project-level fork is minted. Runs in the broker's detached dev-box child
    or inline from a direct rscore caller — never on the broker's accept
    thread. Failure detail streams to the child's full log (die() prints to
    the redirected stderr); the view log gets only run_dev_box's coarse
    tokens."""
    progress = progress or _NULL_PROGRESS
    # A working mode on a research project's box would be refused by box_add —
    # after the mirror below; refuse it before (research boxes get no suite).
    if _harness_set(req):
        _refuse_harness_on_research(_running_dind_supervisor(req.project))
    progress.step("repo", "mirroring the repo")
    dev_repo_add(DevRepoAddRequest.from_kwargs(url=req.url, pat=req.pat))
    # req.name is ALWAYS set here: from_kwargs derived+validated the default
    # PRE-SPAWN (never a post-migrate name failure).
    box = box_add(BoxAddRequest.from_kwargs(
        project=req.project, name=req.name, preset="dev", agent=req.agent,
        editor=req.editor, repo=req.repo, branch=req.branch,
        model=req.model, effort=req.effort, share=req.share,
        **{f: getattr(req, f) for f in HARNESS_FIELDS}), progress)
    return {"project": req.project, "repo": req.repo, "box": box.name,
            "container": box.container}


def dev_project_provision(req: "DevProjectProvisionRequest", progress=None) -> dict:  # type: ignore[name-defined]
    """Webui dev-workflow create: mirror + project-create as ONE action (the
    New Project dev card takes a GitHub URL + optional per-repo PAT). A
    COMPOSITION of the shipped verbs so every gate and secret discipline is
    reused, not re-derived: dev_repo_add (mirror-only; resumes gitea
    require=True — the deliberate-create model; resumable migrate) → create()
    on the dev-flagged workflow (its dev step mints the PROJECT consumer's
    fork/token and clones it — per-consumer forks, no attach leg). The
    CreateRequest is re-derived HERE, with the mirror-stamp floor ON: the
    stamp exists by ordering now (dev_repo_add just wrote it), and no
    pre-spawn-validated value crosses into create unchecked (TOCTOU-safe, the
    preview-vs-apply discipline). Runs in the broker's detached dev-lane
    child or inline from a direct rscore caller — never on the broker's
    accept thread. Failure detail streams to the child's full log; the view
    log gets only run_dev_box's coarse tokens. The reply is secret-free by
    construction: CreateResult (ssh_password) is NOT forwarded — the lane has
    no OP_RUNS retention and the webui sidebar JIT-attaches instead."""
    progress = progress or _NULL_PROGRESS
    progress.step("repo", "mirroring the repo")
    dev_repo_add(DevRepoAddRequest.from_kwargs(url=req.url, pat=req.pat))
    cr = CreateRequest.from_kwargs(
        name=req.name, workflow=req.workflow, dev_repo=req.repo,
        dev_branch=req.branch,
        egress=req.egress, enable=req.enable, disable=req.disable,
        supervisor_model=req.supervisor_model,
        supervisor_effort=req.supervisor_effort,
        pi_model=req.pi_model, pi_thinking=req.pi_thinking,
        **{f: getattr(req, f) for f in HARNESS_FIELDS},
        agents=req.agents, mount=req.mount)
    create(cr, progress=progress)
    return {"project": req.name, "repo": req.repo}


# ---------------------------------------------------------------------------
# Ephemeral sandboxed reviewer (STAGE_DEV_GITEA S4)
#
# Per-PR advisory review in a throwaway rs-minimal-base container on a
# ROUTER-LOCKED bridge: the host pulls the diff from gitea (token stays host
# memory), stages it in as a file, and the container runs a tool-restricted
# `claude -p` under the dedicated reviewer account's creds. The container holds
# NO gitea token and has no route to gitea (no bridge endpoint + the router's
# unconditional RFC1918 drop). Verdicts land in the HOST ledger only (gitea.
# REVIEWS_DIR) — never in gitea, never in a container (invariant 4). Reviews
# run in PARALLEL (per-run unique container names; the broker side is the
# lockless review lane, the CLI runs inline) — the review is advisory, the
# human diff-read is the gate.
# ---------------------------------------------------------------------------

# Diff cap for one review. A diff near the model's context (~800 KB of text)
# leaves no room to reason and burns the dedicated account on garbage; real PRs
# sit far below 100 KB. At half, a legitimately-large-but-reviewable PR could
# false-fail; at 10x the review reads past any useful context. Overflow is a
# LOUD failed ledger entry ("diff too large"), never a silent truncation.
REVIEW_DIFF_MAX_BYTES = 512 * 1024
# Wall bound on one reviewer container (docker-wait timeout host-side; the
# in-container route-gate self-terminates on the same bound so a hard host
# kill can't leave an orphan spinning — A2). At half, a deep tool-using review
# of a big diff can false-fail; at 10x a wedged claude holds a container + the
# account's tokens for hours.
REVIEW_MAX_TIME_S = 900
# Route-gate poll cadence inside the container (seconds). Derived iterations =
# REVIEW_MAX_TIME_S / this, so the gate and the wall bound expire together.
_REVIEW_GATE_POLL_S = 0.2
# The PR body is agent-authored metadata embedded in the prompt as untrusted
# context; the DIFF is the review subject. Uncapped, a long PR body competes
# with the diff for context; at 10x this it would dominate it. Truncation is
# marked in the prompt. The same cap bounds a COMMIT review's full message, and
# it cuts the TAIL — git trailers ARE the tail, so a >4000-char agent message
# hides an attribution / session-link trailer from the reviewer's attribution
# criterion (the second net; the rs-fetch collection scrub, the first net, is
# unaffected). Accepted: raising it is a deliberate edit, not a bug.
REVIEW_PR_BODY_MAX_CHARS = 4000
# Bounded tail of the reviewer's raw stdout/stderr printed to the HOST-ONLY
# full log on failure. Not a new magic number: it NAMES the literal the
# stderr-tail read already shipped with; the raw-output tail (the fix for the
# unparseable-output diagnostic dead-end) reuses it. At half, a long auth/
# usage message could truncate mid-explanation; at 10x a runaway output would
# bloat the full log for no diagnostic gain.
_REVIEW_OUTPUT_TAIL_CHARS = 2000
# Cap on the free-text "risk" label at parse time. The label renders in a
# ONE-LINE badge inside a table row; the prompt-pinned vocabulary maxes at 7
# chars and a future enriched label ("DANGER: supply-chain tampering") runs
# ~30-45. At half, enrichment already truncates; at 10x, a prompt-injected
# label wrecks the row layout the badge lives in. Layout is the whole
# exposure — the webui renders verdict strings as text nodes, so markup
# injection is moot.
_VERDICT_RISK_MAX_CHARS = 48

REVIEWER_NETWORK = "rs-reviewer"
REVIEWER_RUN_PREFIX = "rs-reviewer-run-"
# Serializes the SHARED lane setup (_ensure_reviewer_network) across the
# parallel detached review children — separate processes, so a kernel file
# lock is the right primitive (released on fd close/process death; no stale-
# lock recovery path, the pid-file weakness this avoids). Host-only home-dir
# state, deliberately NOT under the webui-mounted run/ dir. Reviews themselves
# stay N-at-a-time; only the ~1s setup critical section serializes.
REVIEWER_NET_LOCK = Path.home() / ".research-sandbox" / "reviewer-net.lock"

# Shared in-container deploy fragment (root): the agent dist -> the research
# user's own writable ~/.local + the dist's bypass settings (no-clobber), the
# docker-box boot pattern. Fixed strings only — nothing user-supplied.
_REVIEWER_DEPLOY = (
    "mkdir -p /home/research/.local && "
    "cp -a /opt/agent-dist/claude/local/. /home/research/.local/ && "
    "mkdir -p /home/research/.claude && "
    "cp -n /opt/agent-dist/claude/claude/settings.json "
    "/home/research/.claude/settings.json && "
    "chown -R research:research /home/research/.local /home/research/.claude"
)

# docker exec / su -c contexts don't guarantee ~/.local/bin on PATH, so the
# reviewer surfaces invoke the deployed launcher by absolute path (a relative
# symlink into ../share/, resolves once the tree is copied — the dist shape).
_REVIEWER_CLAUDE = "/home/research/.local/bin/claude"

# The reviewer's tool restriction: managed-settings deny — the highest-
# precedence permission scope (the websearcher browser_evaluate precedent),
# not overridable by the dist's bypassPermissions. Read/Grep/Glob stay usable
# so the reviewer navigates the staged diff; everything that can execute,
# write, or reach the network is denied.
_REVIEWER_MANAGED_SETTINGS = json.dumps({"permissions": {"deny": [
    "Bash", "Write", "Edit", "NotebookEdit", "WebFetch", "WebSearch", "Task",
]}})

# The reviewer prompts live OUTSIDE the code, in container/reviewer/
# prompts.json ({"pr": [...lines...], "commit": [...lines...]}, joined with
# newlines at load). Host-read per review, never image-baked — a prompt edit
# applies to the very next run with no restart and no rebuild. {title}/{body}
# placeholders are filled by _render_reviewer_prompt.
_REVIEWER_PROMPTS_PATH = SCRIPT_DIR / "container" / "reviewer" / "prompts.json"


def _load_reviewer_prompt(kind: str) -> str:
    """One prompt template ("pr" | "commit") from the prompts file, joined.
    Read per call — always fresh, one small read per review. Any defect is a
    die() naming the file: pre-side-effect in review_pr (the load is its
    first floor), and on the detached lane run_review's SystemExit arm routes
    the detail to the host-only full log. Reads the module global (never a
    default parameter) so tests can repoint the path."""
    path = _REVIEWER_PROMPTS_PATH
    try:
        data = json.loads(path.read_text())
    except OSError as e:
        die(f"reviewer prompts file unreadable: {path} ({e})")
    except json.JSONDecodeError as e:
        die(f"reviewer prompts file is not valid JSON: {path} ({e})")
    if not isinstance(data, dict):
        die(f"reviewer prompts file must be a JSON object: {path}")
    lines = data.get(kind)
    if (not isinstance(lines, list)
            or not all(isinstance(ln, str) for ln in lines)):
        die(f"reviewer prompts file: {kind!r} must be a list of strings: "
            f"{path}")
    text = "\n".join(lines)
    if "{title}" not in text or "{body}" not in text:
        die(f"reviewer prompts file: the {kind!r} template must carry the "
            f"{{title}} and {{body}} placeholders: {path}")
    return text


def _render_reviewer_prompt(template: str, title: str, body: str) -> str:
    """Fill {title}/{body}. The replacement is a CALLABLE, never a string:
    re.sub processes backslash escapes in string replacements, so ordinary
    metadata (a Windows path, a trailing backslash) would raise re.error.
    A callable's return is inserted literally, and replacement text is never
    rescanned — adversarial metadata containing a placeholder token stays
    literal."""
    values = {"title": title, "body": body}
    return re.sub(r"\{(title|body)\}", lambda m: values[m.group(1)], template)


def _ensure_reviewer_network() -> str:
    """Idempotent rs-reviewer bridge: create if absent, connect the router,
    (re-)assert the LOCKED rules, return the router's IP on it. Rules are
    re-asserted on EVERY call (apply-rules.sh is remove-then-apply), so a
    router RECREATE heals at the next review; a plain router restart already
    self-heals via the router's own rules persist (/etc/sandbox/rules).

    The whole setup runs under a host file lock (B45/B46): the parallel
    detached review children otherwise race the check-then-create (2 of 3
    died "network already exists" on the first live 3-wide bulk fire) and
    interleave the remove-then-apply rule re-assert. The lock's flock blocks
    INDEFINITELY by design — a sibling wedged inside the section means docker
    itself is wedged and a timeout constant would only rename that failure;
    a dead holder releases via the kernel. Reviews stay parallel; only this
    ~1s section serializes."""
    if not container_running(ROUTER_CONTAINER):
        die(f"{ROUTER_CONTAINER} is not running. Run `research start` first.")
    REVIEWER_NET_LOCK.parent.mkdir(parents=True, exist_ok=True)
    with open(REVIEWER_NET_LOCK, "w") as lockf:
        fcntl.flock(lockf, fcntl.LOCK_EX)
        if not network_exists(REVIEWER_NETWORK):
            # Tolerant create (belt-and-braces under the lock): proceed iff
            # the network exists afterwards — a non-rscore creator winning a
            # race is tolerable, a daemon-down create failure stays fail-loud.
            r = run(network_create_args(REVIEWER_NETWORK), capture_output=True)
            if r.returncode != 0 and not network_exists(REVIEWER_NETWORK):
                die(f"command failed: docker network create "
                    f"{REVIEWER_NETWORK}\n{(r.stderr or '').strip()}")
        run(["docker", "network", "connect", REVIEWER_NETWORK,
             ROUTER_CONTAINER], capture_output=True)
        apply_firewall_rules(REVIEWER_NETWORK, "locked")
        # Proactive sweep of crashed reviews' leftovers (PI decision): a child
        # hard-killed between its docker run and its finally leaves a STOPPED
        # container; clear exited ones at the next review instead of letting
        # them accumulate until pid reuse. Anchored on the RUN prefix (the
        # name filter is substring-by-default — keep it anchored so only the
        # per-run containers ever match) and status=exited ONLY (a running
        # sibling is never touched; verdict capture reads host-side tmp
        # files, never the container).
        r = run(["docker", "ps", "-aq",
                 "--filter", f"name=^{REVIEWER_RUN_PREFIX}",
                 "--filter", "status=exited"], capture_output=True)
        for cid in (r.stdout or "").split():
            run(["docker", "rm", "-f", cid], capture_output=True)
    return get_router_ip(REVIEWER_NETWORK)


def reviewer_token_set(token: str) -> dict:
    """Store the dedicated reviewer account's long-lived setup-token — the
    one-time host bootstrap step (mint it with `claude setup-token` in any
    terminal logged into that account). Host-CLI-only by PI ruling: never a
    broker verb, no Request class, absent from every *_WEBUI_FIELDS — the
    browser structurally cannot reach it. The token arrives via stdin/getpass
    (never argv) and is validated only for shape: non-empty, single line —
    an opaque secret gets no content sniffing; a bad token fails loud at the
    next review with the raw-output tail in the full log."""
    token = (token or "").strip()
    if not token:
        raise ValidationError("empty reviewer token")
    if any(c in token for c in "\r\n"):
        raise ValidationError("the reviewer token must be a single line")
    gitea.REVIEWER_CRED_DIR.mkdir(parents=True, exist_ok=True)
    os.chmod(gitea.REVIEWER_CRED_DIR, 0o700)
    gitea._write_secret(gitea.REVIEWER_TOKEN_PATH, token + "\n")
    print(f"reviewer token stored at {gitea.REVIEWER_TOKEN_PATH}")
    return {"stored": str(gitea.REVIEWER_TOKEN_PATH)}


def _parse_verdict(text: str) -> dict | None:
    """Tolerant model-output parse: the first {...} JSON object, fields picked
    by name and shape-coerced. None -> unparseable."""
    start, end = text.find("{"), text.rfind("}")
    if start < 0 or end <= start:
        return None
    try:
        data = json.loads(text[start:end + 1])
    except json.JSONDecodeError:
        return None
    if not isinstance(data, dict):
        return None
    out: dict = {"summary": str(data.get("summary") or "")}
    risk = data.get("risk")
    if isinstance(risk, str) and risk.strip():
        label = " ".join(risk.split())   # one line: the badge is a table cell
        if len(label) > _VERDICT_RISK_MAX_CHARS:
            label = label[:_VERDICT_RISK_MAX_CHARS - 1] + "…"
        out["risk"] = label
    outcome = data.get("outcome")
    if isinstance(outcome, str) and outcome.strip().lower() in ("pass", "fail"):
        out["outcome"] = outcome.strip().lower()
    findings = []
    for f in data.get("findings") or []:
        if isinstance(f, dict):
            findings.append({"file": str(f.get("file") or ""),
                             "note": str(f.get("note") or "")})
    out["findings"] = findings
    return out


def _review_container_script(model: str, effort: str) -> str:
    """The reviewer container's root script. Fixed strings only — the repo/pr
    never enter it (diff + prompt arrive as staged files); the model/effort
    argv tokens are catalog-validated aliases re-guarded here against the same
    charset, because they interpolate into a shell string (only validated
    values are ever interpolated). An empty effort emits no --effort (the
    effort-less-tier rule). Steps: bounded
    route-gate (no egress until the host pointed the default route at the
    router; self-terminates on the wall bound so a hard host kill can't leave
    an orphan), managed-settings tool deny, token + dist deploy, the claude -p
    run as research against a container-LOCAL /work copy (no host-uid coupling
    on the mount), then results — and ONLY results — copied back out by root
    (root writes the mount regardless of the host uid)."""
    if not re.fullmatch(r"[a-z][a-z0-9-]*", model):
        die(f"invalid reviewer model token: {model!r}")
    if effort and not re.fullmatch(r"[a-z][a-z0-9-]*", effort):
        die(f"invalid reviewer effort token: {effort!r}")
    model_flags = f"--model {model}" + (f" --effort {effort}" if effort else "")
    gate_iters = int(REVIEW_MAX_TIME_S / _REVIEW_GATE_POLL_S)
    return (
        "set -e\n"
        f"for i in $(seq 1 {gate_iters}); do\n"
        "  [ -f /review/route-ok ] && break\n"
        f"  sleep {_REVIEW_GATE_POLL_S}\n"
        "done\n"
        "[ -f /review/route-ok ] || exit 90\n"
        "mkdir -p /etc/claude-code\n"
        "cat > /etc/claude-code/managed-settings.json <<'RSEOF'\n"
        + _REVIEWER_MANAGED_SETTINGS + "\n"
        "RSEOF\n"
        + _REVIEWER_DEPLOY + "\n"
        # Auth = the long-lived setup-token, exported inside su's child shell
        # from a root-installed research-owned copy: the value never rides an
        # argv (the $(cat …) below is LITERAL text in every /proc cmdline and
        # expands only in-shell) and never lands in docker inspect. NOTHING
        # credential-shaped is copied back out — the token never rotates, and
        # nothing from the untrusted container may touch durable host auth
        # state (PI ruling; the old capture-back is retired).
        "install -m 400 -o research -g research /review/token "
        "/home/research/.reviewer-token\n"
        "install -d -m 755 -o research -g research /work\n"
        "install -m 644 -o research -g research /review/diff.patch /work/diff.patch\n"
        "install -m 644 -o research -g research /review/prompt.md /work/prompt.md\n"
        "su - research -c 'cd /work && "
        "CLAUDE_CODE_OAUTH_TOKEN=\"$(cat /home/research/.reviewer-token)\" "
        + _REVIEWER_CLAUDE
        + " " + model_flags + " -p \"$(cat /work/prompt.md)\" "
        "> /work/raw.txt 2> /work/err.txt' || true\n"
        "mkdir -p /review/out\n"
        "cp /work/raw.txt /review/out/raw.txt 2>/dev/null || true\n"
        "cp /work/err.txt /review/out/err.txt 2>/dev/null || true\n"
    )


def _write_failed_verdict(repo: str, pr: int, head_sha: str, reason: str,
                          stamp: dict | None = None) -> None:
    """Failed ledger entry (COARSE reason token only — a review error can carry
    host paths; raw detail belongs to the host-only full log / CLI terminal).
    `stamp` carries the same what-was-reviewed fields an ok entry gets (fork,
    fork_id, title, head): a failure is history too, and the Reviews tab has to
    name what the attempt was about once the PR row is gone."""
    gitea.save_verdict(repo, pr, {
        "repo": repo, "pr": pr, "head_sha": head_sha,
        **(stamp or {}),
        "status": "failed", "reason": reason,
        "reviewed_at": datetime.datetime.now(
            datetime.timezone.utc).isoformat()})


def _write_failed_commit_verdict(repo: str, sha: str, reason: str,
                                 stamp: dict | None = None) -> None:
    """The COMMIT twin of _write_failed_verdict (same coarse-token discipline;
    no head_sha/pr — the sha itself is the immutable subject)."""
    gitea.save_commit_verdict(repo, sha, {
        "repo": repo, "commit": sha,
        **(stamp or {}),
        "status": "failed", "reason": reason,
        "reviewed_at": datetime.datetime.now(
            datetime.timezone.utc).isoformat()})


def review_pr(req: "ReviewRequest", progress=None) -> dict:  # type: ignore[name-defined]
    """One review — a whole PR (req.pr) or a single commit (req.commit) —
    start to ledger. Runs in the broker's DETACHED review child (parallel
    lane) or inline on the CLI — never on the broker's accept thread. stdout
    here is the child's host-only full log (or the operator's own terminal);
    the view-log gets only run_review's coarse tokens."""
    progress = progress or _NULL_PROGRESS
    repo, pr = req.repo, req.pr
    # First floor: a missing/broken prompts file refuses before ANY side
    # effect (no docker/network/gitea yet), independent of token/gitea state.
    prompt_tmpl = _load_reviewer_prompt("commit" if req.commit else "pr")
    if not gitea.REVIEWER_TOKEN_PATH.is_file():
        die("no reviewer token — mint one with `claude setup-token` (any "
            "project terminal, logged into the dedicated reviewer account) "
            "and store it with `research dev reviewer-token` (one-time setup)")
    if not dist_present(DEFAULT_AGENT):
        die(f"no cached {DEFAULT_AGENT} dist — pull it under Sandboxes → Software first")
    # The reviewer's (model, effort) — the fifth model_catalog type, resolved
    # LIVE per run (never marker-frozen: this runs in a fresh detached child
    # or a fresh CLI process, so a Management-page default change applies to
    # the very next review). A bad operator override refuses HERE, before any
    # docker/network side effect; stdout is the host-only full log / the
    # operator's own terminal, never the mounted view log. The token-state
    # line beside it is diagnostic only — a stale/bad token fails loud at the
    # run with the raw-output tail below, never a silent dead-end.
    rev_model, rev_effort = _resolve_model_pair("reviewer")
    print(f"reviewer model: {rev_model}"
          + (f" effort {rev_effort}" if rev_effort else ""))
    tstate = gitea.reviewer_token_state()
    print("reviewer token: "
          + (f"present (set {tstate['set_at']})" if tstate["present"]
             else "absent"))
    router_ip = _ensure_reviewer_network()
    _resume_gitea(require=True)         # tracks dev_sync: resume, never create
    host_port = _gitea_host_port()
    # Per-consumer forks: the review targets the repo's ACTIVE fork (the
    # Management-steered global selector; no cross-fork aggregation).
    owner = gitea.active_fork_for(host_port, repo)
    if not owner:
        die(f"repo {repo!r} has no live consumer fork to review "
            f"(create a dev project or dev box on it first)")
    client = gitea.GiteaClient(gitea.api_base(host_port),
                               gitea.read_admin_token())

    # The locator branch: everything below diverges only in WHAT is fetched
    # and WHICH ledger file the postures write; the container run is shared.
    target = f"{repo}@{req.commit[:9]}" if req.commit else f"{repo}#{pr}"
    head_sha = ""
    # What this review is ABOUT, stamped into whichever entry gets written.
    # Filled in by the locator branch as soon as the target resolves — BEFORE
    # each leg's diff fetch, whose failure writes an entry that would otherwise
    # be unlabelled. Empty only where the resolve itself dies, which writes no
    # entry at all. _fail reads it from the enclosing scope at CALL time (hence
    # the assignment order above being load-bearing) and hands it to the ledger
    # writers as one argument, so an ok entry and a failed entry for the same
    # review can never carry different stamps.
    stamp: dict = {}

    def _fail(reason: str) -> None:
        # Coarse-token failed entry into the matching ledger (commit entries
        # never touch the PR ledger and vice versa).
        if req.commit:
            _write_failed_commit_verdict(repo, req.commit, reason, stamp)
        else:
            _write_failed_verdict(repo, pr, head_sha, reason, stamp)

    if req.commit:
        progress.step("resolve-commit", "resolving the commit")
        try:
            cinfo = client.commit_info(owner, repo, req.commit)
        except gitea.GiteaError as e:
            die(str(e))                 # pre-diff: no ledger write (PR parity)
        stamp = {"fork": owner, "subject": cinfo["subject"]}
        progress.step("fetch-diff", "fetching the diff")
        try:
            diff = client.commit_diff(owner, repo, req.commit,
                                      REVIEW_DIFF_MAX_BYTES)
        except gitea.GiteaError as e:
            _fail("diff too large" if "review cap" in str(e)
                  else "diff fetch failed")
            die(str(e))
        body = cinfo["message"]
        if len(body) > REVIEW_PR_BODY_MAX_CHARS:
            body = body[:REVIEW_PR_BODY_MAX_CHARS] + "\n[... truncated]"
        prompt = _render_reviewer_prompt(prompt_tmpl, cinfo["subject"], body)
    else:
        progress.step("resolve-pr", "resolving the PR")
        try:
            info = client.pull_info(owner, repo, pr)
        except gitea.GiteaError as e:
            die(str(e))
        if info["merged"] or info["state"] != "open":
            die(f"PR #{pr} on {owner}/{repo} is not open "
                f"({'merged' if info['merged'] else info['state']}); "
                f"only open PRs are reviewed")
        head_sha = info["head_sha"]
        stamp = {"fork": owner, "fork_id": info["fork_id"],
                 "title": info["title"], "head": info["head"]}

        progress.step("fetch-diff", "fetching the diff")
        try:
            diff = client.pull_diff(owner, repo, pr, REVIEW_DIFF_MAX_BYTES)
        except gitea.GiteaError as e:
            _fail("diff too large" if "review cap" in str(e)
                  else "diff fetch failed")
            die(str(e))

        body = info["body"]
        if len(body) > REVIEW_PR_BODY_MAX_CHARS:
            body = body[:REVIEW_PR_BODY_MAX_CHARS] + "\n[... truncated]"
        prompt = _render_reviewer_prompt(prompt_tmpl, info["title"], body)

    name = f"{REVIEWER_RUN_PREFIX}{os.getpid()}"
    tmp = Path(tempfile.mkdtemp(prefix="rs-review-"))     # 0700 (holds creds)
    progress.step("run-review", "running the sandboxed reviewer")
    try:
        (tmp / "diff.patch").write_text(diff)
        (tmp / "prompt.md").write_text(prompt)
        shutil.copyfile(gitea.REVIEWER_TOKEN_PATH, tmp / "token")
        os.chmod(tmp / "token", 0o600)
        (tmp / "out").mkdir()
        # No --rm: auto-remove raced our own finally rm -f, leaving Dead
        # husks that squat the name (B47) — the finally is the SINGLE removal
        # path now, and docker wait below is reliable again (the S4 --rm
        # caveat). The tolerant PRE-run rm clears a same-pid leftover from a
        # hard-killed prior child (two LIVE children can never share a pid,
        # so the name it clears is dead by construction); a hard-killed
        # child's stopped container otherwise lingers visibly until this or
        # the lane sweep removes it (accepted).
        run(["docker", "rm", "-f", name], capture_output=True)
        # The reviewer resolves through the configured resolvers like every
        # project container: without `--dns`, its embedded resolver forwards to
        # the operator host's resolvers, which the locked rules on rs-reviewer
        # drop (DNS is open to the configured resolvers only).
        dns_args = [a for s in load_config().sandbox_dns for a in ("--dns", s)]
        run_check(["docker", "run", "-d", "--name", name,
                   "--network", REVIEWER_NETWORK, *dns_args,
                   "-v", f"{tmp}:/review",
                   "-v", f"{agent_dist_path(DEFAULT_AGENT)}:/opt/agent-dist/claude:ro",
                   MINIMAL_BASE_IMAGE, "sh", "-lc",
                   _review_container_script(rev_model, rev_effort)])
        inject_route(name, router_ip)
        (tmp / "route-ok").write_text("ok\n")
        try:
            run(["docker", "wait", name], capture_output=True,
                timeout=REVIEW_MAX_TIME_S)
        except subprocess.TimeoutExpired:
            run(["docker", "rm", "-f", name], capture_output=True)
            _fail("review timed out")
            die(f"review of {target} exceeded {REVIEW_MAX_TIME_S}s and was "
                f"killed")

        err_path = tmp / "out" / "err.txt"
        if err_path.is_file():
            tail = err_path.read_text(errors="replace")[-_REVIEW_OUTPUT_TAIL_CHARS:]
            if tail.strip():
                print(f"reviewer stderr tail:\n{tail}")   # full log / terminal only

        raw_path = tmp / "out" / "raw.txt"
        raw = raw_path.read_text(errors="replace") if raw_path.is_file() else ""
        if not raw.strip():
            # Distinguish "claude wrote nothing" from "the copy-out never ran/
            # the container died pre-launch" — full log / terminal only; the
            # ledger reason stays coarse.
            print("reviewer out-file state: raw.txt "
                  + (f"{raw_path.stat().st_size}B" if raw_path.is_file()
                     else "missing")
                  + ", err.txt "
                  + (f"{err_path.stat().st_size}B" if err_path.is_file()
                     else "missing"))
            _fail("reviewer run failed")
            die(f"review of {target} produced no output (see the full log)")
        verdict = _parse_verdict(raw)
        if verdict is None:
            # The raw output IS the diagnosis (an auth/usage message arrives
            # on stdout and used to vanish here) — bounded, full log only.
            print("reviewer raw output tail:\n"
                  + raw[-_REVIEW_OUTPUT_TAIL_CHARS:])
            _fail("unparseable verdict")
            die(f"review of {target} returned unparseable output "
                f"(see the full log)")
        reviewed_at = datetime.datetime.now(
            datetime.timezone.utc).isoformat()
        # Display-ready record of what actually RAN (the resolved pair, not
        # the defaults at render time); empty effort -> no trailing word.
        # _parse_verdict emits a FIXED key set (summary/risk/outcome/
        # findings), so the **verdict spread can never carry a "model" key
        # over this one.
        rev_desc = f"{DEFAULT_AGENT} {rev_model}" + (
            f" {rev_effort}" if rev_effort else "")
        if req.commit:
            entry = {"repo": repo, "commit": req.commit, **stamp,
                     "status": "ok",
                     "reviewed_at": reviewed_at, "model": rev_desc, **verdict}
            ledger = gitea.save_commit_verdict(repo, req.commit, entry)
        else:
            entry = {"repo": repo, "pr": pr, "head_sha": head_sha, **stamp,
                     "status": "ok", "reviewed_at": reviewed_at,
                     "model": rev_desc, **verdict}
            ledger = gitea.save_verdict(repo, pr, entry)
        progress.step("verdict", "verdict recorded")

        # No capture-back, deliberately (PI ruling): the long-lived setup
        # token never rotates, and nothing produced inside the untrusted
        # container may touch durable host auth state — the container is
        # disposable in BOTH directions. The token store changes only via
        # `research dev reviewer-token`.
        return {"repo": repo,
                **({"commit": req.commit} if req.commit else {"pr": pr}),
                "status": "ok",
                "summary": verdict.get("summary", ""),
                "risk": verdict.get("risk", ""),
                "outcome": verdict.get("outcome", ""),
                "model": rev_desc,
                "ledger": str(ledger)}
    finally:
        run(["docker", "rm", "-f", name], capture_output=True)
        shutil.rmtree(tmp, ignore_errors=True)


# Sentinels for _gateway_priority: the container does not exist at all, or it
# exists without an endpoint on the network (a half-done heal, or a hand
# `docker network disconnect`). Only the second is something to repair.
GATEWAY_CONTAINER_ABSENT = "container-absent"
GATEWAY_ENDPOINT_ABSENT = "endpoint-absent"


def _gateway_priority(container: str, network: str) -> int | str:
    """The gateway priority of ``container``'s endpoint on ``network``,
    GATEWAY_CONTAINER_ABSENT when there is no such container, or
    GATEWAY_ENDPOINT_ABSENT when the container exists but has no endpoint
    there (a stopped container keeps its endpoints in inspect, so it is
    healed where it stands)."""
    r = run(["docker", "container", "inspect", "-f",
             "{{json .NetworkSettings.Networks}}", container],
            capture_output=True)
    if r.returncode != 0:
        # Absence is the one failure that means "nothing to pin"; anything
        # else (daemon hiccup, permission) must not read as absence — a shared
        # container left unpinned loses its egress under the operator's
        # host-hardening rules, so the heal fails loudly like the floor does.
        err = r.stderr or ""
        if "No such container" in err or "No such object" in err:
            return GATEWAY_CONTAINER_ABSENT
        die(f"could not inspect {container} to pin its default gateway: "
            f"{(err or r.stdout or '').strip()[-200:]}")
    try:
        nets = json.loads((r.stdout or "").strip() or "null") or {}
    except json.JSONDecodeError as e:
        die(f"could not read {container}'s network settings: {e}")
    ep = nets.get(network)
    if not isinstance(ep, dict):
        return GATEWAY_ENDPOINT_ABSENT
    return int(ep.get("GwPriority") or 0)


def pin_shared_gateway(container: str) -> bool:
    """Make rs-sandbox the default-gateway network of one shared container,
    persistently: disconnect its rs-sandbox endpoint and reconnect it with the
    gateway priority. Docker recomputes the default route from endpoint
    priorities at every container start, so an in-place route edit would
    expire at the next restart while this survives it (measured). Works on
    running and stopped containers alike; published ports follow the gateway
    endpoint. A container that exists but has NO rs-sandbox endpoint — a heal
    whose reconnect failed, or a hand disconnect — is connected with the
    priority (connect only), so the heal repairs its own half-done state
    instead of skipping it forever. No-op (False) when the container is absent
    or already pinned; True when it re-wired."""
    state = _gateway_priority(container, ROUTER_NETWORK)
    if state in (GATEWAY_CONTAINER_ABSENT, GATEWAY_PRIORITY):
        return False
    # The webui binds its listeners on its rs-sandbox address at process start
    # (B156); a reconnect can hand that endpoint a different address (when a
    # lower one is free), which would leave a RUNNING webui listening on a dead
    # address. Read by name first: nothing else here may issue another inspect.
    restart_webui = container == WEBUI_CONTAINER and container_running(container)
    if state != GATEWAY_ENDPOINT_ABSENT:
        run_check(["docker", "network", "disconnect", ROUTER_NETWORK, container])
    run_check(["docker", "network", "connect", "--gw-priority",
               str(GATEWAY_PRIORITY), ROUTER_NETWORK, container])
    if restart_webui:
        run_check(["docker", "restart", container])
    return True


def shared_gateway_containers() -> list[str]:
    """Every shared container RS connects to project networks — the set whose
    default route must stay on rs-sandbox. The kept-aside previous gitea is
    included so a rollback starts pinned."""
    return [ROUTER_CONTAINER, WEBUI_CONTAINER, REGISTRY_CONTAINER,
            REGISTRY_PUSH_CONTAINER, gitea.GITEA_CONTAINER, GITEA_PREVIOUS_CONTAINER,
            MCP_GATEWAY_CONTAINER]


def pin_shared_gateways() -> list[str]:
    """Heal every existing shared container created before gateway pinning
    (or resumed by a plain `docker start`); returns the ones re-wired. Runs at
    `research start` right after the router is up, before anything else, so a
    later step that dies cannot skip it."""
    return [c for c in shared_gateway_containers() if pin_shared_gateway(c)]


def _version_from_output(r: subprocess.CompletedProcess) -> str | None:
    """The leading dotted-numeric version in a command's stdout, or None when
    the command failed or printed nothing numeric — the floor refuses both."""
    if r.returncode != 0:
        return None
    m = _VERSION_NUMERIC_RE.match((r.stdout or "").strip())
    return m.group(1) if m else None


def check_engine_floor() -> None:
    """Refuse `research start` below the Engine / compose versions that honour
    gateway priority (see GATEWAY_PRIORITY). Fail-closed: an unreadable
    version refuses too — `_version_older` alone reads "not older" for a
    missing compose plugin, which is the right posture for a warning and the
    wrong one for a floor whose absence breaks every shared container's egress
    once the operator's host-hardening rules are in place."""
    checks = [
        ("docker client", ["docker", "version", "-f", "{{.Client.Version}}"],
         ENGINE_VERSION_FLOOR),
        ("docker engine", ["docker", "version", "-f", "{{.Server.Version}}"],
         ENGINE_VERSION_FLOOR),
        ("docker compose", ["docker", "compose", "version", "--short"],
         COMPOSE_VERSION_FLOOR),
    ]
    for what, cmd, floor in checks:
        got = _version_from_output(run(cmd, capture_output=True))
        if got is None:
            die(f"could not read the {what} version ({' '.join(cmd)}); "
                f"research-sandbox needs {what} >= {floor} (gateway priority "
                f"for the shared containers).")
        if _version_older(got, floor):
            die(f"{what} {got} is too old; research-sandbox needs {what} >= "
                f"{floor} (gateway priority keeps the shared containers' "
                f"default route on {ROUTER_NETWORK}).")


def wire_webui_to_projects() -> None:
    """Connect rs-webui to every existing per-project network. Idempotent;
    no-op when there is no webui container. Called at webui start and after
    every `project create` so the webui sees fresh projects without a
    restart."""
    if not _container_present(WEBUI_CONTAINER):
        return
    r = run(["docker", "network", "ls",
             "--filter", f"name=^{PROJECT_NETWORK_PREFIX}",
             "--format", "{{.Name}}"],
            capture_output=True)
    for net in r.stdout.strip().splitlines():
        if net:
            run(["docker", "network", "connect", net, WEBUI_CONTAINER],
                capture_output=True)


def wire_router_to_projects() -> None:
    """Connect rs-router to every existing per-project network. Idempotent;
    no-op when the router isn't running.

    `cmd_project_create` is the original wire-er (via ensure_project_network).
    This re-wirer exists for the case where the router container was rebuilt
    or recreated — compose's `up -d --build router` does `rm` + `run`, which
    drops every `docker network connect` to rs-net-<project> that prior
    creates set up. Without this, the next `project update` against an
    existing project dies at `get_router_ip` because the recreated rs-router
    isn't attached to that project's network.

    iptables state on the router IS recovered on its own: the router's
    entrypoint replays `/etc/sandbox/rules/*` on startup, and that directory
    lives on the named volume `rs-router-rules` which survives `docker rm`.
    So this helper only handles the network-attachment side of the recreate;
    the firewall side is self-healing."""
    if not container_running(ROUTER_CONTAINER):
        return
    r = run(["docker", "network", "ls",
             "--filter", f"name=^{PROJECT_NETWORK_PREFIX}",
             "--format", "{{.Name}}"],
            capture_output=True)
    for net in r.stdout.strip().splitlines():
        if net:
            run(["docker", "network", "connect", net, ROUTER_CONTAINER],
                capture_output=True)


def wire_registry_to_projects() -> None:
    """Re-attach rs-registry to every per-project network after a host
    `start` / registry recreate (mirror of wire_router_to_projects). LAZY: if the
    registry has never been created (no extension enabled yet) do nothing — it is
    stood up on first `enable`, not at `start`. If it exists but is stopped, start
    it, then re-attach. Without this, a `start` that recreated the registry would
    leave existing projects' inner dockerds unable to pull their extensions."""
    if not (container_exists(REGISTRY_CONTAINER)
            or container_exists(REGISTRY_PUSH_CONTAINER)):
        return
    # Both instances resumed — and an older single writable registry converted
    # to the read-only pair here, at the first start after the upgrade, not at
    # the next box delivery. A pair that will not come back must not abort the
    # rest of `research start` (the webui, the MCPs and gitea follow): warn.
    try:
        _ensure_registry_running()
    except RegistryUnavailable as e:
        print(f"warning: box-image registry not fully up ({e.reason}); "
              "start continues", file=sys.stderr)
    if not container_running(REGISTRY_CONTAINER):
        return
    _attach_registry_to_all_projects()


def _detect_tailscale_fqdn() -> str | None:
    """Read the host's tailnet FQDN from `tailscale status --json`. Returns
    None if tailscale isn't installed, the daemon isn't running, or the
    host hasn't joined a tailnet."""
    if shutil.which("tailscale") is None:
        return None
    r = run(["tailscale", "status", "--json"], capture_output=True)
    if r.returncode != 0:
        return None
    try:
        data = json.loads(r.stdout)
    except json.JSONDecodeError:
        return None
    fqdn = (data.get("Self") or {}).get("DNSName", "")
    return fqdn.rstrip(".") or None


def _detect_tailscale_ipv4() -> str | None:
    """Read the host's tailnet IPv4 from `tailscale ip -4` (one bare
    address per line). Returns the first line that parses as an IPv4
    address, or None if tailscale isn't installed, the command fails, or
    no line parses. No range check: a tailnet can use a custom IP pool."""
    if shutil.which("tailscale") is None:
        return None
    r = run(["tailscale", "ip", "-4"], capture_output=True)
    if r.returncode != 0:
        return None
    for line in (r.stdout or "").splitlines():
        try:
            return str(ipaddress.IPv4Address(line.strip()))
        except ValueError:
            continue
    return None


def _webui_tls_volume() -> str:
    """Resolve the docker volume name actually mounted at /app/tls in
    rs-webui. Falls back to the literal name pinned in docker-compose.yml
    when rs-webui isn't running yet. This avoids a previous bug where the
    helper wrote to a bare `rs-webui-tls` volume while compose mounted a
    project-prefixed one (`research-sandbox_rs-webui-tls`)."""
    if _container_present(WEBUI_CONTAINER):
        r = run(["docker", "inspect", WEBUI_CONTAINER, "-f",
                 "{{range .Mounts}}{{if eq .Destination \"/app/tls\"}}"
                 "{{.Name}}{{end}}{{end}}"], capture_output=True)
        if r.returncode == 0 and r.stdout.strip():
            return r.stdout.strip()
    return "rs-webui-tls"


def _stage_webui_cert(cert_pem: bytes, key_pem: bytes,
                      provider: str) -> None:
    """Write cert+key+`.custom` marker into the webui's TLS volume. The
    marker tells the in-container ensure_tls() to skip its auto-regenerate-
    self-signed path so the user-provided cert sticks even when WEBUI_BIND
    doesn't appear in the cert's SAN."""
    volume = _webui_tls_volume()
    if not run_quiet(["docker", "volume", "inspect", volume]):
        run_check(["docker", "volume", "create", volume])
    with tempfile.TemporaryDirectory() as td:
        td_path = Path(td)
        (td_path / "cert.pem").write_bytes(cert_pem)
        (td_path / "key.pem").write_bytes(key_pem)
        (td_path / ".custom").write_text(f"{provider}\n")
        # chown to UID 1000 — the in-container webui user. Without this
        # the written files are root-owned, and any regen attempt (e.g.
        # server.py falling back to self-signed when the marker is absent)
        # hits Permission denied on the cert.pem write and the container
        # restart-loops. chmod 644/600 then matches what the auto-generated
        # cert flow uses.
        if run_quiet(["docker", "image", "inspect", WEBUI_IMAGE]):
            # The volume is writable by the webui, and the renewal at start
            # stages here unattended: the stager never opens or follows an
            # object it finds there (a planted FIFO would block a `cp`).
            r = run([
                "docker", "run", "--rm", "--network", "none", "-u", "0",
                "--entrypoint", "python",
                "-v", f"{volume}:/tls",
                "-v", f"{td_path}:/src:ro",
                WEBUI_IMAGE, "-I", "-c", _WEBUI_TLS_STAGE_PY,
                "/tls", "/src", str(WEBUI_IMAGE_UID), str(WEBUI_IMAGE_UID),
            ], capture_output=True, errors="replace")
            if r.returncode != 0:
                last = next((ln.strip() for ln in reversed((r.stderr or "").splitlines())
                             if ln.strip()), f"exit {r.returncode}")
                die(f"could not stage the webui certificate into its TLS volume: {last}")
        else:
            run_check([
                "docker", "run", "--rm",
                "-v", f"{volume}:/tls",
                "-v", f"{td_path}:/src:ro",
                "busybox", "sh", "-c",
                "cp /src/cert.pem /tls/cert.pem && "
                "cp /src/key.pem  /tls/key.pem && "
                "cp /src/.custom  /tls/.custom && "
                "chown 1000:1000 /tls/cert.pem /tls/key.pem /tls/.custom && "
                "chmod 644 /tls/cert.pem /tls/.custom && "
                "chmod 600 /tls/key.pem"
            ])
    _record_webui_tls_provider(provider, cert_pem)


WEBUI_IMAGE_UID = 1000   # baked uid in webui/Dockerfile (USER webui)


def _ensure_webui_volume_ownership(uid: int, gid: int) -> None:
    """The rs-webui-tls / rs-webui-state named volumes initialize owned by the
    image's baked uid (1000). When the webui runs as a different uid (the
    uid-equality contract on a non-1000 host), it can't write its TLS cert or
    persist the origin-port map there — chown both volumes to the runtime uid
    first. No-op on the common uid==1000 host."""
    if (uid, gid) == (WEBUI_IMAGE_UID, WEBUI_IMAGE_UID):
        return
    run(["docker", "run", "--rm", "-u", "0",
         "-v", "rs-webui-tls:/app/tls", "-v", "rs-webui-state:/app/state",
         WEBUI_IMAGE,
         "chown", "-R", f"{uid}:{gid}", "/app/tls", "/app/state"],
        capture_output=True)


# The webui TLS renewal (B58). The TLS volume is mounted read-write into the
# webui, so the host trusts nothing it finds there: the tailnet name comes only
# from this HOST-side record of what RS last staged (written by
# `_stage_webui_cert`, i.e. by `research webui cert-tailscale` and by the
# renewal), JSON {"provider": "tailscale:<fqdn>", "cert_sha256": "<hex>"}.
WEBUI_TLS_RECORD_PATH = Path.home() / ".research-sandbox" / "webui-tls-provider"

# RFC 1035: a name is at most 255 octets on the wire, 253 characters in dotted
# text. A longer "name" cannot have come from `tailscale status`, so it is
# rejected like a malformed one. Derived, not a tuning knob.
DNS_NAME_MAX_CHARS = 253

# A DNS host name of two or more labels, ASCII letters/digits/hyphens, no label
# starting or ending with a hyphen. With fullmatch this excludes every
# argv-option shape (a leading "-") and every control or space character, which
# is the property that matters before the name reaches `tailscale cert`.
_TAILSCALE_FQDN_RE = re.compile(
    r"[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?"
    r"(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?)+", re.ASCII)

# The marker is only ever compared for equality with a record whose name passed
# the 253-character check; the longest marker RS writes is
# "tailscale:<253 chars>\n". A larger file cannot equal any record, so reading
# past this bound can never change the verdict (mismatch); half of it would turn
# legitimate long names into a mismatch, ten times only lets more hostile bytes
# into the host process.
WEBUI_TLS_MARKER_MAX_BYTES = len("tailscale:") + DNS_NAME_MAX_CHARS + 1

# Marks the throwaway that reads the webui's TLS marker, so an observer (the
# acceptance harness's event count) can tell the bounded read apart from every
# other container run from the same image; it carries no behaviour.
WEBUI_TLS_READER_LABEL = "research.webui-tls-reader=1"

# Runs inside a throwaway rs-webui container on a read-only mount of the TLS
# volume. Never follows a symlink, never blocks on a FIFO (O_NONBLOCK; S_ISREG
# refuses it before any read), reads at most cap+1 bytes, and emits hex so the
# host never decodes webui bytes as text.
_WEBUI_TLS_MARKER_READ_PY = """\
import os, stat, sys
path, cap = sys.argv[1], int(sys.argv[2])
fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
st = os.fstat(fd)
if not stat.S_ISREG(st.st_mode) or st.st_size > cap:
    sys.exit(4)
data = os.read(fd, cap + 1)
if len(data) > cap:
    sys.exit(4)
sys.stdout.write(data.hex())
"""

# Runs as root inside a throwaway rs-webui container: argv <dst> <src> <uid>
# <gid>. Each file is created fresh under a random temp name (O_EXCL|O_NOFOLLOW:
# never opens an existing object), owned and moded on its descriptor, and only
# then renamed onto its name through the directory descriptor (a rename neither
# opens nor follows the target). A directory squatting a name aborts before any
# rename; temps this run created are removed on every exit.
_WEBUI_TLS_STAGE_PY = """\
import os, secrets, stat, sys
dst, src, uid, gid = sys.argv[1], sys.argv[2], int(sys.argv[3]), int(sys.argv[4])
files = (("cert.pem", 0o644), ("key.pem", 0o600), (".custom", 0o644))
d = os.open(dst, os.O_RDONLY | os.O_DIRECTORY)
for name, _ in files:
    try:
        if stat.S_ISDIR(os.lstat(name, dir_fd=d).st_mode):
            sys.exit(name + " is a directory")
    except FileNotFoundError:
        pass
staged = []
try:
    for name, mode in files:
        with open(os.path.join(src, name), "rb") as f:
            data = f.read()
        tmp = ".rs-stage-" + secrets.token_hex(8)
        fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
                     0o600, dir_fd=d)
        staged.append(tmp)
        with os.fdopen(fd, "wb") as w:
            w.write(data)
            os.fchown(w.fileno(), uid, gid)
            os.fchmod(w.fileno(), mode)
    for i, (name, _) in enumerate(files):
        os.replace(staged[i], name, src_dir_fd=d, dst_dir_fd=d)
        staged[i] = None
finally:
    for tmp in staged:
        if tmp is not None:
            try:
                os.unlink(tmp, dir_fd=d)
            except OSError:
                pass
"""


def _record_webui_tls_provider(provider: str, cert_pem: bytes) -> None:
    """Record, host-side, what `_stage_webui_cert` just staged. The old record
    is removed first, so a failed write leaves renewal OFF rather than a stale
    certificate hash that would restage at every start. Never dies."""
    path = WEBUI_TLS_RECORD_PATH
    tmp = path.with_name(path.name + ".tmp")
    try:
        path.unlink(missing_ok=True)
    except OSError as e:
        print(f"warning: could not remove the old webui certificate record {path} "
              f"({e}); remove that file by hand — until then each start acts on "
              f"that old record (it restages the certificate, or warns that the "
              f"webui's certificate no longer matches it)", file=sys.stderr)
        return
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp.write_text(json.dumps({
            "provider": provider,
            "cert_sha256": hashlib.sha256(cert_pem).hexdigest(),
        }) + "\n", encoding="ascii")
        os.chmod(tmp, 0o644)
        os.replace(tmp, path)
    except OSError as e:
        print(f"warning: could not record the webui certificate's provider at "
              f"{path} ({e}); renewal at start stays off", file=sys.stderr)
        try:
            tmp.unlink(missing_ok=True)
        except OSError:
            pass


def _read_webui_tls_record() -> dict | None:
    """The host-side record: None when absent; {} when present but not a
    record RS wrote (unreadable, not ASCII, not JSON, wrong shape)."""
    path = WEBUI_TLS_RECORD_PATH
    try:
        text = path.read_text(encoding="ascii")
    except FileNotFoundError:
        return None
    except (OSError, ValueError):
        return {}
    try:
        rec = json.loads(text)
    except ValueError:
        return {}
    if (isinstance(rec, dict) and isinstance(rec.get("provider"), str)
            and isinstance(rec.get("cert_sha256"), str)):
        return rec
    return {}


def _valid_tailscale_fqdn(fqdn: str) -> bool:
    return (len(fqdn) <= DNS_NAME_MAX_CHARS
            and _TAILSCALE_FQDN_RE.fullmatch(fqdn) is not None)


def _read_webui_tls_marker(volume: str) -> str | None:
    """The webui's `.custom` marker, read through the bounded reader in a
    throwaway container on a read-only mount; None on any failure (absent, a
    symlink, a FIFO, a directory, too large, not ASCII, a failed run)."""
    try:
        r = run(["docker", "run", "--rm", "--network", "none",
                 "--label", WEBUI_TLS_READER_LABEL,
                 "--entrypoint", "python",
                 "-v", f"{volume}:/app/tls:ro", WEBUI_IMAGE,
                 "-I", "-c", _WEBUI_TLS_MARKER_READ_PY,
                 "/app/tls/.custom", str(WEBUI_TLS_MARKER_MAX_BYTES)],
                capture_output=True, errors="replace")
    except OSError:
        return None
    if r.returncode != 0:
        return None
    try:
        return bytes.fromhex((r.stdout or "").strip()).decode("ascii")
    except ValueError:
        return None


def _fetch_tailscale_cert(fqdn: str) -> tuple[bytes | None, bytes | None, str]:
    """`tailscale cert` for `fqdn` into a temp dir: (cert, key, "") or
    (None, None, the error). The same invocation `research webui
    cert-tailscale` makes; never raises for a missing binary or file."""
    with tempfile.TemporaryDirectory() as td:
        cert_path = Path(td) / "cert.pem"
        key_path = Path(td) / "key.pem"
        try:
            r = run(["tailscale", "cert",
                     "--cert-file", str(cert_path),
                     "--key-file", str(key_path),
                     fqdn], capture_output=True)
            if r.returncode != 0:
                return None, None, ((r.stderr or r.stdout or "").strip()
                                    or f"exit {r.returncode}")
            return cert_path.read_bytes(), key_path.read_bytes(), ""
        except OSError as e:
            return None, None, f"{type(e).__name__}: {e}"


def _webui_container_ids() -> tuple[int, int] | None:
    """The uid:gid the existing webui container runs as; None when there is no
    webui container. No recorded user, or a user NAME, is the image's uid."""
    u = webui_container_user()
    if u is None:
        return None
    uid_s, _, gid_s = u.partition(":")
    if not gid_s:
        gid_s = uid_s
    if uid_s.isdigit() and gid_s.isdigit():
        return int(uid_s), int(gid_s)
    return WEBUI_IMAGE_UID, WEBUI_IMAGE_UID


def refresh_webui_tailscale_cert() -> bool:
    """Ask Tailscale for the current certificate of the name the operator
    staged with `research webui cert-tailscale`, and install it when it is a
    different one. True only when a new certificate was staged. Warns on
    stderr and returns False on every failure; never aborts the caller."""
    rec = _read_webui_tls_record()
    if rec is None:
        return False
    if not run_quiet(["docker", "image", "inspect", WEBUI_IMAGE]):
        return False
    volume = _webui_tls_volume()
    if not run_quiet(["docker", "volume", "inspect", volume]):
        return False
    path = WEBUI_TLS_RECORD_PATH
    if not rec:
        print(f"warning: {path} is not a record RS wrote; renewal skipped "
              f"(run 'research webui cert-tailscale' to rewrite it)", file=sys.stderr)
        return False
    provider = rec["provider"]
    if not provider.startswith("tailscale:"):
        return False
    fqdn = provider[len("tailscale:"):]
    if not _valid_tailscale_fqdn(fqdn):
        print(f"warning: {path} does not hold a valid Tailscale host name; renewal "
              f"skipped (run 'research webui cert-tailscale' to rewrite it)",
              file=sys.stderr)
        return False
    marker = _read_webui_tls_marker(volume)
    if (marker or "").strip() != provider:
        print(f"warning: the webui's certificate is no longer the Tailscale "
              f"certificate RS staged for {fqdn}; renewal skipped. Run 'research "
              f"webui cert-tailscale' to restage it, or delete {path} to stop "
              f"renewing", file=sys.stderr)
        return False
    if shutil.which("tailscale") is None:
        print(f"warning: the tailscale CLI is not on PATH, so the webui's "
              f"certificate for {fqdn} is not renewed; browsers refuse it once it "
              f"expires (run 'research webui cert-tailscale' once tailscale is "
              f"back)", file=sys.stderr)
        return False
    cert, key, err = _fetch_tailscale_cert(fqdn)
    if cert is None or key is None:
        print(f"warning: could not renew the webui's Tailscale certificate for "
              f"{fqdn}: {err} (run 'research webui cert-tailscale' to retry)",
              file=sys.stderr)
        return False
    if hashlib.sha256(cert).hexdigest() == rec["cert_sha256"]:
        return False
    try:
        _stage_webui_cert(cert, key, provider=provider)
        ids = _webui_container_ids()
        if ids is not None:
            _ensure_webui_volume_ownership(*ids)
    except (SystemExit, OSError) as e:
        detail = f" ({e})" if isinstance(e, OSError) else " (see the error above)"
        print(f"warning: could not install the renewed Tailscale certificate for "
              f"{fqdn}{detail}; the webui keeps the one it has", file=sys.stderr)
        return False
    print(f"renewed the webui's Tailscale certificate for {fqdn}")
    return True


def renew_webui_cert_at_start() -> None:
    """`research start`'s renewal: nothing when no Tailscale certificate was
    ever staged (no host record — the default self-signed install, checked
    first so it makes no docker call), and nothing when the webui container is
    absent (`research webui stop` removed it — the operator's "no UI" signal).
    After a renewal, a running webui with the listen contract is restarted onto
    the new files (a restart re-reads the volume); a stopped one reads them at
    its next start. Never dies."""
    if _read_webui_tls_record() is None:
        return
    if not _container_present(WEBUI_CONTAINER):
        return
    if not refresh_webui_tailscale_cert():
        return
    if container_running(WEBUI_CONTAINER) and webui_container_has_listen_contract():
        r = run(["docker", "restart", WEBUI_CONTAINER], capture_output=True)
        if r.returncode != 0:
            err = (r.stderr or r.stdout or "").strip()
            print(f"warning: could not restart {WEBUI_CONTAINER} onto the renewed "
                  f"certificate: {err[-200:]}; it serves the new one after its next "
                  f"restart", file=sys.stderr)


def webui_listen_subnet() -> str:
    """The router network's IPv4 subnet, which the webui binds inside (B156).
    Dies with a one-line remedy when the network is absent (the router brings
    it up) or carries no IPv4 subnet — never with docker's raw error."""
    r = run(["docker", "network", "inspect", ROUTER_NETWORK,
             "-f", "{{json .IPAM.Config}}"], capture_output=True)
    if r.returncode != 0:
        die(f"the router network {ROUTER_NETWORK} does not exist yet; run "
            f"`research start` first")
    try:
        entries = json.loads(r.stdout or "null") or []
    except json.JSONDecodeError:
        entries = []
    for e in entries:
        sub = e.get("Subnet") if isinstance(e, dict) else None
        try:
            if sub and ipaddress.ip_network(sub).version == 4:
                return str(ipaddress.ip_network(sub))
        except ValueError:
            continue
    die(f"the router network {ROUTER_NETWORK} has no IPv4 subnet; the webui "
        f"cannot choose its listen address")


def webui_image_has_listen_contract() -> bool:
    """Does the webui image bind inside the passed subnet (its label)? An image
    without the label binds every address."""
    r = run(["docker", "image", "inspect", WEBUI_IMAGE, "-f",
             f'{{{{index .Config.Labels "{WEBUI_LISTEN_LABEL}"}}}}'],
            capture_output=True)
    return r.returncode == 0 and r.stdout.strip() == WEBUI_LISTEN_LABEL_VALUE


def webui_container_has_listen_contract() -> bool:
    """Was the existing webui CONTAINER created from an image with the listen
    contract? Docker copies image labels onto the container, so this reads the
    image the container actually runs, not what the tag points at now."""
    r = run(["docker", "container", "inspect", WEBUI_CONTAINER, "-f",
             f'{{{{index .Config.Labels "{WEBUI_LISTEN_LABEL}"}}}}'],
            capture_output=True)
    return r.returncode == 0 and r.stdout.strip() == WEBUI_LISTEN_LABEL_VALUE


def webui_container_subnet() -> str:
    """The WEBUI_LISTEN_SUBNET the existing webui container was created with
    ("" when absent or when the container does not exist)."""
    r = run(["docker", "container", "inspect", WEBUI_CONTAINER,
             "-f", "{{json .Config.Env}}"], capture_output=True)
    if r.returncode != 0:
        return ""
    try:
        env = json.loads(r.stdout or "null") or []
    except json.JSONDecodeError:
        return ""
    for kv in env:
        if isinstance(kv, str) and kv.startswith("WEBUI_LISTEN_SUBNET="):
            return kv.split("=", 1)[1]
    return ""


def webui_container_user() -> str | None:
    """The `uid:gid` the existing webui container runs as (its Config.User).

    None when the container-scoped inspect fails, i.e. there is no webui
    container (a bare inspect would also answer for the rs-webui IMAGE); ""
    when the container carries no user (it then runs as the image's baked
    uid). The None/str split IS the presence read, so callers need no second
    inspect."""
    r = run(["docker", "container", "inspect", WEBUI_CONTAINER,
             "-f", "{{.Config.User}}"], capture_output=True)
    if r.returncode != 0:
        return None
    return (r.stdout or "").strip()


# A webui published on every host address is reachable from every project at
# its own bridge gateway (Docker's port forwarding DNATs any local address onto
# the webui's router-network listener), so no path brings one up (B162). One
# sentence, shared by `research webui start`'s refusal and `research start`'s
# warning; the remedy names --bind because a plain `webui start` over a
# wildcard .env refuses too.
WEBUI_WILDCARD_REFUSAL = (
    "the webui must not listen on every address, because every project could "
    "then reach it at its own bridge gateway; run `research webui start --bind "
    "<address>` with 127.0.0.1, this host's LAN address or its tailnet address "
    "(it rewrites WEBUI_BIND in .env)")

# webui_container_bind()'s answer when the container exists but the address it
# publishes 7777 on cannot be read: distinct from None (no container) and from
# "" (docker's spelling of every address).
WEBUI_BIND_UNREADABLE = object()


def _parse_webui_address(value: str):
    """`value` as one IP address (an IPv6 literal may be bracketed;
    `localhost` reads as 127.0.0.1), or None when it is not one."""
    v = (value or "").strip()
    if v == "localhost":
        v = "127.0.0.1"
    if v.startswith("[") and v.endswith("]"):
        v = v[1:-1]
    try:
        return ipaddress.ip_address(v)
    except ValueError:
        return None


def webui_bind_literal(value: str) -> str:
    """The bind as compose must receive it: a published host address is an IP
    literal only (docker rejects `localhost` there), so `localhost` becomes
    127.0.0.1; anything else is returned stripped. Call after
    webui_bind_address has accepted the value."""
    v = (value or "").strip()
    return "127.0.0.1" if v == "localhost" else v


def _is_wildcard_address(addr) -> bool:
    """0.0.0.0, ::, and ::ffff:0.0.0.0 in every spelling (ipv4_mapped exists
    on IPv6 addresses only; Python 3.9 does not fold it into is_unspecified)."""
    if addr.is_unspecified:
        return True
    mapped = getattr(addr, "ipv4_mapped", None)
    return mapped is not None and mapped.is_unspecified


def webui_bind_address(value: str):
    """Validate the webui bind in effect (`--bind`, else .env's WEBUI_BIND) and
    return it as an address. Raises ValidationError when it is not one IP
    address, or when it is every address (B162) — callers check it before they
    write .env or remove anything."""
    addr = _parse_webui_address(value)
    if addr is None:
        raise ValidationError(
            f"WEBUI_BIND must be one IP address (got {value!r}); set it in .env, or "
            f"pass --bind <address>, to 127.0.0.1, this host's LAN address or its "
            f"tailnet address")
    if _is_wildcard_address(addr):
        raise ValidationError(f"refusing WEBUI_BIND={value}: {WEBUI_WILDCARD_REFUSAL}")
    return addr


def webui_published_address(host_ip):
    """A container HostIp (webui_container_bind's string answer) as an address:
    "" is docker's every-address, so it reads as 0.0.0.0. None for anything that
    does not parse (and for the unreadable sentinel)."""
    if not isinstance(host_ip, str):
        return None
    if host_ip == "":
        return ipaddress.ip_address("0.0.0.0")
    return _parse_webui_address(host_ip)


def webui_container_bind():
    """The host address the existing webui CONTAINER publishes its UI port on,
    read from the container's own port bindings (they survive a stop, and are
    what the container will bind again on `docker start` — .env may have
    changed since). One key suffices: compose publishes the UI port, the origin
    range and the pass-through block from the one WEBUI_BIND.

    None: no webui container (the container-scoped inspect is itself the
    presence read). WEBUI_BIND_UNREADABLE: the container exists but carries no
    readable binding for 7777/tcp. Otherwise the HostIp string, "" meaning
    every address."""
    r = run(["docker", "container", "inspect", WEBUI_CONTAINER,
             "-f", "{{json .HostConfig.PortBindings}}"], capture_output=True)
    if r.returncode != 0:
        return None
    try:
        bindings = json.loads(r.stdout or "null")
        host_ip = bindings["7777/tcp"][0]["HostIp"]
    except (json.JSONDecodeError, TypeError, KeyError, IndexError):
        return WEBUI_BIND_UNREADABLE
    return host_ip if isinstance(host_ip, str) else WEBUI_BIND_UNREADABLE


def webui_bind_state() -> str:
    """"absent" (no webui container), "ok" (published on one address),
    "wildcard" (published on every address, B162) or "unreadable" (the
    container's binding cannot be read — treated like a wildcard: never
    resumed, stopped when running)."""
    host_ip = webui_container_bind()
    if host_ip is None:
        return "absent"
    addr = webui_published_address(host_ip)
    if addr is None:
        return "unreadable"
    return "wildcard" if _is_wildcard_address(addr) else "ok"


def webui_compose_env(bind: str, port: str, listen_subnet: str,
                      broker_run_dir: Path) -> dict[str, str]:
    """Every variable the webui's compose service takes from the caller, so
    each path that brings the webui up (`research webui start`, the in-place
    recreate) passes the same set: the listen subnet, bind and port, the
    origin and pass-through port ranges from .env, the operator's uid/gid
    (the webui must run as the operator to reach the broker's 0700 run dir
    and pass its SO_PEERCRED check; compose would fall back to 1000) and the
    broker's run dir, mounted read-only as the socket's parent.

    PROJECTS_DIR and HOME are not in the set: compose reads PROJECTS_DIR from
    .env itself and HOME is the operator's own. `broker_run_dir` is passed in
    because this module cannot import the broker (it imports this module).

    Side effect, after every read has succeeded: the broker run dir is
    created, operator-owned, so the bind-mount source exists before `up` —
    otherwise docker creates it root-owned and the broker (running as the
    operator) cannot bind its socket there. A malformed origin range dies; a
    malformed pass-through block raises ValidationError (the caller adds the
    .env remedy); neither leaves anything behind."""
    origin_lo, origin_hi = _webui_origin_port_range()
    pt_lo, pt_hi = webui_passthrough_port_range()
    env = {
        "WEBUI_LISTEN_SUBNET": listen_subnet,
        "WEBUI_BIND": bind,
        "WEBUI_PORT": port,
        "WEBUI_ORIGIN_PORT_LO": str(origin_lo),
        "WEBUI_ORIGIN_PORT_HI": str(origin_hi),
        "WEBUI_PASSTHROUGH_PORT_LO": str(pt_lo),
        "WEBUI_PASSTHROUGH_PORT_HI": str(pt_hi),
        "WEBUI_UID": str(os.getuid()),
        "WEBUI_GID": str(os.getgid()),
        "RS_BROKER_DIR": str(broker_run_dir),
    }
    broker_run_dir.mkdir(parents=True, exist_ok=True)
    return env


def _webui_recreate_in_place(broker_run_dir: Path) -> None:
    """Tear down + bring up the webui container so it re-reads the TLS
    volume on next start. No image rebuild; passes the same compose
    environment `research webui start` does (webui_compose_env: bind, port,
    the router network's subnet the webui binds inside (B156), the port
    ranges, the operator's uid/gid and the broker run dir), and gives the
    TLS/state volumes to the operator's uid before `up` (the cert staging
    writes them as 1000). Every refusal comes before anything is touched,
    the bind first: a wildcard or non-address WEBUI_BIND would bring the
    webui back on every address (B162)."""
    bind = read_env_value("WEBUI_BIND") or "127.0.0.1"
    try:
        webui_bind_address(bind)
    except ValidationError as e:
        die(str(e))
    port = read_env_value("WEBUI_PORT") or "7777"
    if not webui_image_has_listen_contract():
        # recreating an older image would reopen the webui to every project
        # (B156) while the subnet in its environment reads as satisfied
        die("the webui image predates the narrowed listen address; run "
            "`research webui start`, which rebuilds it and picks up the staged "
            "certificate")
    try:
        env = webui_compose_env(webui_bind_literal(bind), port, webui_listen_subnet(),
                                broker_run_dir)
    except ValidationError as e:
        die(f"{e} — fix WEBUI_PASSTHROUGH_PORT_LO/HI in .env")
    os.environ.update(env)
    if _container_present(WEBUI_CONTAINER):
        run(["docker", "rm", "-f", WEBUI_CONTAINER], capture_output=True)
    _ensure_webui_volume_ownership(os.getuid(), os.getgid())
    docker_compose("--profile", "webui", "up", "-d", "webui")
    wire_webui_to_projects()


# Re-export every module-level name (incl. _underscore helpers) so
# research.py's existing cmd_* call sites resolve via `from rscore import *`.
__all__ = [_n for _n in list(globals()) if not _n.startswith('__')]
